    'single choice (radio buttons)' => 'Einfachauswahl (Radiobuttons)',
    'choice from a list' => 'Auswahl aus einer Liste',
    'Confirmation: %s' => 'Bestätigung: %s',
    'New enquiry webhook' => 'Webhook für neue Anfragen',
    'Where to send every new enquiry from a form (CRM, Make, Zapier, n8n, Slack). It receives the form name, the filled-in fields and the sender\'s e-mail.' => 'Wohin jede neue Anfrage aus einem Formular gesendet werden soll (CRM, Make, Zapier, n8n, Slack). Er erhält den Formularnamen, die ausgefüllten Felder und die E-Mail-Adresse des Absenders.',
    'This policy explains how [COMPANY NAME], company ID [ID], registered at [ADDRESS], processes the personal data you entrust to us.' => 'Diese Erklärung beschreibt, wie [FIRMENNAME], Handelsregisternummer [NUMMER], mit Sitz in [ADRESSE], die personenbezogenen Daten verarbeitet, die Sie uns anvertrauen.',
    'What data we process' => 'Welche Daten wir verarbeiten',
    'Your name, e-mail, phone and the content of the message you fill in the enquiry form.' => 'Ihren Namen, Ihre E-Mail-Adresse, Ihre Telefonnummer und den Inhalt der Nachricht, die Sie im Anfrageformular eingeben.',
    'Why and on what basis' => 'Warum und auf welcher Grundlage',
    'So that we can reply and prepare an offer – these are steps prior to entering into a contract and our legitimate interest in answering your enquiry.' => 'Damit wir antworten und ein Angebot erstellen können – das sind Schritte vor Abschluss eines Vertrags und unser berechtigtes Interesse, Ihre Anfrage zu beantworten.',
    'How long' => 'Wie lange',
    'We delete enquiries automatically after [NUMBER] months unless they lead to a contract.' => 'Anfragen löschen wir automatisch nach [ANZAHL] Monaten, sofern daraus kein Vertrag entsteht.',
    'Who has access to the data' => 'Wer Zugriff auf die Daten hat',
    'Only us and our hosting provider [HOSTING NAME], who runs the website for us.' => 'Nur wir und unser Hosting-Anbieter [HOSTING-NAME], der die Website für uns betreibt.',
    'Cookies and analytics' => 'Cookies und Analyse',
    'The website measures traffic without cookies. It uses third-party cookies only with your consent.' => 'Die Website misst den Besucherverkehr ohne Cookies. Cookies von Drittanbietern verwendet sie nur mit Ihrer Einwilligung.',
    'Your rights' => 'Ihre Rechte',
    'You have the right to access, rectify and erase your data, to restrict processing and to object. You can lodge a complaint with the data protection authority.' => 'Sie haben das Recht auf Auskunft, Berichtigung und Löschung Ihrer Daten, auf Einschränkung der Verarbeitung und auf Widerspruch. Sie können sich bei der Datenschutzbehörde beschweren.',
    'Write to us at [E-MAIL] or call [PHONE].' => 'Schreiben Sie uns an [E-MAIL] oder rufen Sie uns unter [TELEFON] an.',
    'Start from a template' => 'Mit einer Vorlage beginnen',
    'blank page (text)' => 'leere Seite (Text)',
