    'Click in the preview on what must stay visible when the photo is cropped to another shape (card, section background).' => 'Klicken Sie in der Vorschau auf die Stelle, die sichtbar bleiben muss, wenn das Foto auf eine andere Form zugeschnitten wird (Karte, Abschnittshintergrund).',
    'Replace file' => 'Datei ersetzen',
    'The new photo appears everywhere the old one is used – the file address does not change.' => 'Das neue Foto erscheint überall dort, wo das alte verwendet wird – die Adresse der Datei ändert sich nicht.',
    'Replace' => 'Ersetzen',
    'Anyone who must have it and has not turned it on yet can only reach My account after signing in until they set it up.' => 'Wer sie aktivieren muss und noch nicht aktiviert hat, kann nach der Anmeldung nur auf „Mein Konto“ zugreifen, bis er sie eingerichtet hat.',
    'Search (name, e-mail, text):' => 'Suche (Name, E-Mail, Text):',
    'No enquiry matches the filter.' => 'Keine Anfrage entspricht dem Filter.',
    'Try another word or status.' => 'Versuchen Sie ein anderes Wort oder einen anderen Status.',
    'Delete the selected enquiries including attachments? This cannot be undone.' => 'Die ausgewählten Anfragen samt Anhängen löschen? Das kann nicht rückgängig gemacht werden.',
    'Handled by' => 'Bearbeitet von',
    'Internal note' => 'Interne Notiz',
    'Only administration users see it – e.g. what you offered the customer.' => 'Nur Benutzer der Administration sehen sie – z. B. was Sie dem Kunden angeboten haben.',
    'Save note' => 'Notiz speichern',
    'Most visited pages' => 'Meistbesuchte Seiten',
    'Instead of a password, send an e-mail invitation – the user sets their own password' => 'Statt eines Passworts eine Einladung per E-Mail senden – der Benutzer legt sein Passwort selbst fest',
    'Send the user an e-mail link to set a new password?' => 'Dem Benutzer per E-Mail einen Link zum Festlegen eines neuen Passworts senden?',
