    'Where:' => 'Wo:',
    'Detail contains:' => 'Detail enthält:',
    'The log is kept for six months.' => 'Das Protokoll wird sechs Monate lang aufbewahrt.',
    'custom font' => 'eigene Schriftart',
    'System fonts download nothing. A custom font is stored on your own server – it does not need visitor consent either.' => 'Systemschriften laden nichts herunter. Eine eigene Schriftart wird auf Ihrem eigenen Server gespeichert – auch dafür ist keine Einwilligung der Besucher nötig.',
    'Brand fonts (WOFF2)' => 'Markenschriften (WOFF2)',
    'Upload the font files (.woff2) to Media and paste their address here. One variable font file is enough, or a regular and a bold weight. After saving, choose the font above.' => 'Laden Sie die Schriftdateien (.woff2) in die Medien hoch und fügen Sie hier deren Adresse ein. Eine variable Schriftdatei genügt, oder eine normale und eine fette Ausführung. Wählen Sie die Schriftart nach dem Speichern oben aus.',
