    'Up to %d MB: PDF, image, document or ZIP.' => 'Bis zu %d MB: PDF, Bild, Dokument oder ZIP.',
    'Sample item' => 'Beispieleintrag',
    'attachment (file)' => 'Anhang (Datei)',
    'Two-factor sign-in' => 'Zwei-Faktor-Anmeldung',
    'required for administrators' => 'für Administratoren erforderlich',
    'required for all users' => 'für alle Benutzer erforderlich',
    'Save changes' => 'Änderungen speichern',
    'Mine' => 'Meine',
    'Edit' => 'Bearbeiten',
    'The SVG file could not be read (max. 2 MB, valid SVG).' => 'Die SVG-Datei konnte nicht gelesen werden (max. 2 MB, gültiges SVG).',
    'Only a JPG, PNG or WebP image can be replaced.' => 'Nur ein JPG-, PNG- oder WebP-Bild kann ersetzt werden.',
    'An invitation needs an e-mail.' => 'Für eine Einladung wird eine E-Mail-Adresse benötigt.',
    'The new name must be unused and written in lowercase without accents (e.g. card-large).' => 'Der neue Name darf noch nicht vergeben sein und muss in Kleinbuchstaben ohne Akzente geschrieben werden (z. B. card-large).',
    'A few short steps and your website is running. Everything can be changed later in the administration.' => 'Ein paar kurze Schritte, und Ihre Website läuft. Alles lässt sich später in der Administration ändern.',
    'What you want switched on' => 'Was Sie aktivieren möchten',
    'Extensions can be switched on or off at any time in the administration (Extensions). Switching off deletes nothing.' => 'Erweiterungen können Sie jederzeit in der Administration (Erweiterungen) ein- oder ausschalten. Durch das Ausschalten wird nichts gelöscht.',
    'News and blog: the %s listing with categories and tags, RSS, the News element in the builder and a link in the automatic menu.' => 'News und Blog: die Übersicht %s mit Kategorien und Schlagwörtern, RSS, das Element „News“ im Builder und ein Link im automatischen Menü.',
    'Forms and enquiries' => 'Formulare und Anfragen',
    'The Form element in the builder and the Enquiries inbox: submitted enquiries are stored, arrive by e-mail and can be passed to a colleague or a CRM.' => 'Das Element „Formular“ im Builder und der Posteingang „Anfragen“: Gesendete Anfragen werden gespeichert, kommen per E-Mail an und können an einen Kollegen oder ein CRM weitergegeben werden.',
    '%s – the feature is switched off and will not appear on the website.' => '%s – die Funktion ist ausgeschaltet und erscheint nicht auf der Website.',
    'News is switched off on this website.' => 'News sind auf dieser Website ausgeschaltet.',
    'Search the website…' => 'Website durchsuchen …',
