    'out of 5 · 120 reviews' => 'von 5 · 120 Bewertungen',
    'Back-to-top button (bottom right on the website)' => 'Button „Nach oben“ (unten rechts auf der Website)',
    'Back to top' => 'Nach oben',
    'Subscribe' => 'Abonnieren',
    'We only send news and offers. You can unsubscribe with one click in every e-mail.' => 'Wir senden nur News und Angebote. Sie können sich mit einem Klick in jeder E-Mail abmelden.',
    'Thank you! We have sent you an e-mail with a link – click it to confirm your subscription.' => 'Vielen Dank! Wir haben Ihnen eine E-Mail mit einem Link gesendet – klicken Sie darauf, um Ihr Abonnement zu bestätigen.',
    'Please check the e-mail address.' => 'Bitte überprüfen Sie die E-Mail-Adresse.',
    'Too many attempts in a row. Please try again in a moment.' => 'Zu viele Versuche hintereinander. Bitte versuchen Sie es gleich noch einmal.',
    'Your e-mail' => 'Ihre E-Mail-Adresse',
    'you@example.com' => 'sie@beispiel.de',
    'The event is on now.' => 'Die Veranstaltung läuft gerade.',
    'Enter the date as YYYY-MM-DD HH:MM.' => 'Geben Sie das Datum im Format JJJJ-MM-TT HH:MM ein.',
    'days' => 'Tage',
    'minutes' => 'Minuten',
    'seconds' => 'Sekunden',
    'Projects delivered on time' => 'Pünktlich abgeschlossene Projekte',
    'Returning customers' => 'Stammkunden',
    'Rated %s out of 5' => 'Bewertet mit %s von 5',
    'Confirm your subscription – %s' => 'Bestätigen Sie Ihr Abonnement – %s',
    'to confirm your subscription to news from %s, click the link:' => 'um Ihr Abonnement der News von %s zu bestätigen, klicken Sie auf den Link:',
    'If you did not ask to subscribe, ignore this e-mail – without confirmation we will not send you anything.' => 'Wenn Sie kein Abonnement angefordert haben, ignorieren Sie diese E-Mail – ohne Bestätigung senden wir Ihnen nichts.',
    'Subscription confirmed' => 'Abonnement bestätigt',
    'Thank you, we will send news to %s. You can unsubscribe using the link in every e-mail.' => 'Vielen Dank, wir senden News an %s. Sie können sich über den Link in jeder E-Mail abmelden.',
    'Unsubscribed' => 'Abgemeldet',
    'We have removed %s from the subscriber list.' => 'Wir haben %s aus der Abonnentenliste entfernt.',
    'The link is invalid or has already been used. If you want to receive news, please subscribe again.' => 'Der Link ist ungültig oder wurde bereits verwendet. Wenn Sie News erhalten möchten, abonnieren Sie bitte erneut.',
    'Preview size' => 'Vorschaugröße',
    'Fit' => 'Anpassen',
    'Wide monitor (1920 px)' => 'Breiter Monitor (1920 px)',
    'Help and keyboard shortcuts (?)' => 'Hilfe und Tastenkürzel (?)',
    'Help' => 'Hilfe',
    'Text “%s” has low contrast against its background (%d : 1) – it is hard to read.' => 'Der Text „%s“ hat einen geringen Kontrast zum Hintergrund (%d : 1) – er ist schwer lesbar.',
    'Save draft' => 'Entwurf speichern',
    'Undo / redo' => 'Rückgängig / Wiederholen',
