    'Move within Structure' => 'In der Struktur verschieben',
    'This help' => 'Diese Hilfe',
    'Keyboard shortcuts' => 'Tastenkürzel',
    'Editor tour' => 'Rundgang durch den Editor',
    'Elements and ready-made sections' => 'Elemente und fertige Abschnitte',
    'On the left you pick an element or a whole ready-made section. Click to insert it after the selected element, drag it anywhere on the page. The Structure tab shows the page as a tree.' => 'Links wählen Sie ein Element oder einen ganzen fertigen Abschnitt aus. Mit einem Klick fügen Sie ihn nach dem ausgewählten Element ein, per Drag-and-drop ziehen Sie ihn an eine beliebige Stelle der Seite. Der Tab „Struktur“ zeigt die Seite als Baum.',
    'The page as visitors will see it' => 'Die Seite, wie Besucher sie sehen',
    'Click to select an element, double-click to edit text. At the top you switch the preview to tablet and mobile – the style then changes only for that width.' => 'Klicken Sie, um ein Element auszuwählen, doppelklicken Sie, um Text zu bearbeiten. Oben schalten Sie die Vorschau auf Tablet und Smartphone um – der Stil ändert sich dann nur für diese Breite.',
    'Content, style and advanced' => 'Inhalt, Stil und Erweitert',
    'On the right you change the text, links, colours, spacing and behaviour of the selected element. Take colours and sizes from the list – they keep the website consistent.' => 'Rechts ändern Sie Text, Links, Farben, Abstände und Verhalten des ausgewählten Elements. Übernehmen Sie Farben und Größen aus der Liste – so bleibt die Website einheitlich.',
    'Saving and publishing' => 'Speichern und Veröffentlichen',
    'Changes save automatically as a draft. Visitors see them only after Publish – before that we warn you about missing links, descriptions and low contrast.' => 'Änderungen werden automatisch als Entwurf gespeichert. Besucher sehen sie erst nach dem Veröffentlichen – zuvor warnen wir Sie vor fehlenden Links, Beschreibungen und geringem Kontrast.',
    'Skip' => 'Überspringen',
    'Done' => 'Fertig',
    'Style copied.' => 'Stil kopiert.',
    'Copy style' => 'Stil kopieren',
    'Paste style' => 'Stil einfügen',
    'Display conditions' => 'Anzeigebedingungen',
    'visitors only (not signed in)' => 'nur Besucher (nicht angemeldet)',
    'only people signed in to the administration' => 'nur in der Administration angemeldete Personen',
    'Show from' => 'Anzeigen ab',
    'Show until (inclusive)' => 'Anzeigen bis (einschließlich)',
    'On the canvas the element is always visible. On the website it appears only when the conditions are met – for example a promotional banner for a week.' => 'Auf der Arbeitsfläche ist das Element immer sichtbar. Auf der Website erscheint es nur, wenn die Bedingungen erfüllt sind – zum Beispiel ein Aktionsbanner für eine Woche.',
    'Counter' => 'Zähler',
    'Progress bars' => 'Fortschrittsbalken',
    'Countdown' => 'Countdown',
    'Back-to-top button' => 'Button „Nach oben“',
    'A big number with a label that counts up when shown (years of experience, customers, projects).' => 'Eine große Zahl mit Beschriftung, die beim Einblenden hochzählt (Jahre Erfahrung, Kunden, Projekte).',
    'Bars with percentages – goal progress, share, skill level.' => 'Balken mit Prozentwerten – Zielfortschritt, Anteil, Kenntnisstand.',
    'Stars with a score and number of reviews (e.g. from Google).' => 'Sterne mit Bewertung und Anzahl der Rezensionen (z. B. von Google).',
    'Time remaining until a date – an event, an opening, a registration deadline.' => 'Verbleibende Zeit bis zu einem Datum – eine Veranstaltung, eine Eröffnung, eine Anmeldefrist.',
    'Icons linking to the company profiles (addresses from Settings).' => 'Symbole mit Links zu den Firmenprofilen (Adressen aus den Einstellungen).',
    'A website search field – for the header, the 404 page or a listing.' => 'Ein Suchfeld für die Website – für den Kopfbereich, die 404-Seite oder eine Übersicht.',
    'An e-mail field with subscription confirmation – you will find the addresses under Subscribers in the administration.' => 'Ein E-Mail-Feld mit Bestätigung des Abonnements – die Adressen finden Sie in der Administration unter Abonnenten.',
    'A floating arrow back to the top of the page – put it in the footer.' => 'Ein schwebender Pfeil zurück zum Seitenanfang – setzen Sie ihn in den Fußbereich.',
    'Background video (MP4 or WebM from Media, no sound)' => 'Hintergrundvideo (MP4 oder WebM aus den Medien, ohne Ton)',
    'Poster (image before playing)' => 'Vorschaubild (Bild vor dem Abspielen)',
    'once a week' => 'einmal pro Woche',
    'Number' => 'Zahl',
    'Before the number (e.g. “+”)' => 'Vor der Zahl (z. B. „+“)',
    'After the number (e.g. “ %”, “+”, “ years”)' => 'Nach der Zahl (z. B. „ %“, „+“, „ Jahre“)',
    'Label' => 'Beschriftung',
    'Bars' => 'Balken',
    'Percent' => 'Prozent',
    'Rating (0–5, e.g. 4.8)' => 'Bewertung (0–5, z. B. 4,8)',
    'Text next to the stars' => 'Text neben den Sternen',
    'Until (YYYY-MM-DD HH:MM)' => 'Bis (JJJJ-MM-TT HH:MM)',
    'Text when finished' => 'Text nach Ablauf',
    'Show network names too' => 'Auch Netzwerknamen anzeigen',
    'Placeholder text' => 'Platzhaltertext',
    'Button' => 'Button',
    'Text below the field' => 'Text unter dem Feld',
    'Submenu as a wide panel (mega menu)' => 'Untermenü als breites Panel (Mega-Menü)',
    'Background image on scroll' => 'Hintergrundbild beim Scrollen',
    'stays fixed (parallax)' => 'bleibt fixiert (Parallax)',
    'scrolls with content' => 'scrollt mit dem Inhalt',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). The site sends confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or you export them to CSV.' => 'Das Element „Newsletter-Anmeldung“ im Builder: Besucher geben eine E-Mail-Adresse ein und bestätigen sie per Link (Double-Opt-in). Die Website übergibt bestätigte Abonnenten an Ihren Mailing-Dienst (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, Webhook), oder Sie exportieren sie als CSV.',
    'Subscribers' => 'Abonnenten',
    'The subscriber has been deleted.' => 'Der Abonnent wurde gelöscht.',
    'Subscribed' => 'Abonniert',
    'Confirmed' => 'Bestätigt',
    'Unsubscribe link' => 'Abmelde-Link',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send with your own tool – the export includes the unsubscribe link.' => 'Adressen aus dem Element „Newsletter-Anmeldung“. Als Abonnenten zählen nur Personen, die über den Link in der E-Mail bestätigt haben. Versenden Sie mit Ihrem eigenen Tool – der Export enthält den Abmelde-Link.',
    'Search e-mail' => 'E-Mail suchen',
    'Export confirmed (CSV)' => 'Bestätigte exportieren (CSV)',
    'No subscribers yet.' => 'Noch keine Abonnenten.',
    'Nothing found.' => 'Nichts gefunden.',
    'Put the Newsletter sign-up element on the website – for example in the footer.' => 'Platzieren Sie das Element „Newsletter-Anmeldung“ auf der Website – zum Beispiel im Fußbereich.',
    'confirmed' => 'bestätigt',
    'awaiting confirmation' => 'wartet auf Bestätigung',
    'Remove the address from the subscriber list?' => 'Die Adresse aus der Abonnentenliste entfernen?',
    'Only an editor or administrator can publish. Your changes stay saved as a draft.' => 'Nur ein Redakteur oder Administrator kann veröffentlichen. Ihre Änderungen bleiben als Entwurf gespeichert.',
    'Only an administrator edits a shared class – a change applies to the whole website at once. Set the look of a single element in its style.' => 'Nur ein Administrator bearbeitet eine gemeinsame Klasse – eine Änderung gilt sofort für die gesamte Website. Das Aussehen eines einzelnen Elements legen Sie in dessen Stil fest.',
    'Only an editor or administrator edits, publishes and deletes published pages. You can prepare a new hidden page.' => 'Nur ein Redakteur oder Administrator bearbeitet, veröffentlicht und löscht veröffentlichte Seiten. Sie können eine neue verborgene Seite vorbereiten.',
    'This news item is published – only an editor or administrator can save changes to it. Ask them to edit it.' => 'Dieser News-Beitrag ist veröffentlicht – nur ein Redakteur oder Administrator kann Änderungen daran speichern. Bitten Sie ihn, ihn zu bearbeiten.',
    'The website requires two-step sign-in – you can create a token once you turn it on.' => 'Die Website erfordert die Zwei-Faktor-Anmeldung – Sie können ein Token erstellen, sobald Sie sie aktiviert haben.',
    'These fields have an invalid format and were not saved: %s. Please correct them (they are highlighted); the other settings are saved.' => 'Diese Felder haben ein ungültiges Format und wurden nicht gespeichert: %s. Bitte korrigieren Sie sie (sie sind markiert); die übrigen Einstellungen sind gespeichert.',
    'Enquiries older than the given number of months will be permanently deleted right away – including attachments. Save anyway?' => 'Anfragen, die älter sind als die angegebene Anzahl an Monaten, werden sofort endgültig gelöscht – samt Anhängen. Trotzdem speichern?',
    'The database is back in its state before the restore.' => 'Die Datenbank befindet sich wieder in ihrem Zustand vor der Wiederherstellung.',
    'The state before the restore is in backup %s – please restore it.' => 'Der Zustand vor der Wiederherstellung befindet sich im Backup %s – bitte stellen Sie es wieder her.',
    'The backup is incomplete or damaged (the end of the file is missing) – the restore was stopped.' => 'Das Backup ist unvollständig oder beschädigt (das Dateiende fehlt) – die Wiederherstellung wurde abgebrochen.',
    'The website files have been returned to their state before the update.' => 'Die Dateien der Website wurden in den Zustand vor dem Update zurückversetzt.',
    'The server cannot use encrypted FTP (FTPS). Send backups to S3 storage, or download them manually.' => 'Der Server kann kein verschlüsseltes FTP (FTPS) verwenden. Senden Sie Backups an einen S3-Speicher oder laden Sie sie manuell herunter.',
    'to an FTP server with FTPS encryption (another host, home NAS)' => 'an einen FTP-Server mit FTPS-Verschlüsselung (anderer Host, NAS zu Hause)',
    'The builder needs a larger screen.' => 'Der Builder benötigt einen größeren Bildschirm.',
    'Build pages on a computer or tablet. On a phone, edit texts with the “Edit here” button right on the website.' => 'Erstellen Sie Seiten an einem Computer oder Tablet. Auf dem Smartphone bearbeiten Sie Texte mit dem Button „Hier bearbeiten“ direkt auf der Website.',
    'Back to the administration' => 'Zurück zur Administration',
    'Please confirm that you want to receive news at %s.' => 'Bitte bestätigen Sie, dass Sie News an %s erhalten möchten.',
    'Do you really no longer want to receive news at %s?' => 'Möchten Sie wirklich keine News mehr an %s erhalten?',
    'tag' => 'Schlagwort',
    'category' => 'Kategorie',
    'my section' => 'mein Bereich',
    'user' => 'Benutzer',
    'Invalid sign-in request' => 'Ungültige Anmeldeanfrage',
    'The application did not register correctly with this website (unknown client or return address). Please connect it again.' => 'Die Anwendung hat sich nicht korrekt bei dieser Website registriert (unbekannter Client oder Rücksprungadresse). Bitte verbinden Sie sie erneut.',
    'Connect an application' => 'Anwendung verbinden',
    'The request to connect the application has expired or does not exist. Start connecting again in the application.' => 'Die Anfrage zum Verbinden der Anwendung ist abgelaufen oder existiert nicht. Starten Sie die Verbindung in der Anwendung erneut.',
    'wants to work with the website %s.' => 'möchte mit der Website %s arbeiten.',
    'It will act with the permissions of your account %s (%s): read and edit pages, news, site parts and appearance – just like you in the administration. Builds and news are saved as drafts.' => 'Sie handelt mit den Berechtigungen Ihres Kontos %s (%s): Seiten, News, Seitenbereiche und das Erscheinungsbild lesen und bearbeiten – genau wie Sie in der Administration. Builds und News werden als Entwurf gespeichert.',
    'After allowing it you return to the application at %s. You can revoke the connection at any time in My account → Connected applications.' => 'Nach der Freigabe kehren Sie zur Anwendung unter %s zurück. Sie können die Verbindung jederzeit unter Mein Konto → Verbundene Anwendungen widerrufen.',
    'Allow access' => 'Zugriff erlauben',
    'Deny' => 'Ablehnen',
    'The easiest way is to add a custom connector in the Claude app with the address %s – Claude sends you here to sign in and confirm access, no token to copy. The token below is for Claude Code and other tools without sign-in.' => 'Am einfachsten fügen Sie in der Claude-App einen benutzerdefinierten Connector mit der Adresse %s hinzu – Claude leitet Sie zur Anmeldung und Bestätigung des Zugriffs hierher, ohne dass Sie ein Token kopieren müssen. Das Token unten ist für Claude Code und andere Tools ohne Anmeldung gedacht.',
    'Connected applications' => 'Verbundene Anwendungen',
    'connected %s' => 'verbunden am %s',
    'Disconnect the application? It will not get into the website until you allow it again.' => 'Die Anwendung trennen? Sie erhält keinen Zugriff auf die Website, bis Sie sie erneut erlauben.',
    'Disconnect' => 'Trennen',
    'The application is disconnected – it will not get into the website until you allow it again.' => 'Die Anwendung ist getrennt – sie erhält keinen Zugriff auf die Website, bis Sie sie erneut erlauben.',
    'Found: %s' => 'Gefunden: %s',
