    'Campaign' => 'Kampagne',
    'Imprint' => 'Impressum',
    'Who runs the site: company, registered office, identification numbers, register entry and contact from Business details.' => 'Wer die Website betreibt: Firma, Sitz, Kennnummern, Registereintrag und Kontakt aus Firmendaten.',
