    'Who you are, how long you have been doing it and why customers trust you.' => 'Wer Sie sind, wie lange Sie es schon tun und warum Kunden Ihnen vertrauen.',
    'What you offer – each service briefly and clearly.' => 'Was Sie anbieten – jede Leistung kurz und klar.',
