    'Features are optional parts of Kaleta. All of them are part of the system and maintained by the Kaleta team – nothing is downloaded or installed. A switched-off feature disappears from the menu and the site; its data stays and returns when you switch it on again.' => 'Funktionen sind optionale Bestandteile von Kaleta. Alle gehören zum System und werden vom Kaleta-Team gepflegt – es wird nichts heruntergeladen oder installiert. Eine ausgeschaltete Funktion verschwindet aus dem Menü und von der Website; ihre Daten bleiben erhalten und sind wieder da, sobald Sie sie erneut einschalten.',
