    'The assistant\'s reply could not be read. Please try again.' => 'Die Antwort des Assistenten konnte nicht gelesen werden. Bitte versuchen Sie es erneut.',
    'Unknown translation language.' => 'Unbekannte Übersetzungssprache.',
    'The assistant returned an incomplete translation. Please try again.' => 'Der Assistent hat eine unvollständige Übersetzung geliefert. Bitte versuchen Sie es erneut.',
    'Revoke token' => 'Token widerrufen',
    'An update is already running. Try again in a moment.' => 'Ein Update läuft bereits. Versuchen Sie es in einem Moment erneut.',
    'Import and export' => 'Import und Export',
    'Import from WordPress' => 'Import aus WordPress',
    'File %s – site “%s” (%s). Nothing has been imported yet; this is only an overview of what the file contains.' => 'Datei %s – Website „%s“ (%s). Es wurde noch nichts importiert; dies ist nur eine Übersicht darüber, was die Datei enthält.',
    'Posts' => 'Beiträge',
    'Files in the media library' => 'Dateien in der Mediathek',
    'images in texts: %s' => 'Bilder in Texten: %s',
    'What will not be converted' => 'Was nicht konvertiert wird',
    'Private posts, trash, revisions and auto-drafts. A password-protected post is imported as a draft.' => 'Private Beiträge, Papierkorb, Revisionen und automatische Entwürfe. Ein passwortgeschützter Beitrag wird als Entwurf importiert.',
    'Custom content types:' => 'Eigene Inhaltstypen:',
    'Plug-in shortcodes (forms, page builders…) – the tag disappears, the text inside stays:' => 'Plug-in-Shortcodes (Formulare, Page-Builder …) – das Tag verschwindet, der Text darin bleibt erhalten:',
    'Images stay on the old site for now; after the import you can download them to your site with one button.' => 'Die Bilder bleiben vorerst auf der alten Website; nach dem Import können Sie sie mit einem Klick auf Ihre Website herunterladen.',
    'Import options' => 'Importoptionen',
    'default site language' => 'Standardsprache der Website',
    'What to import' => 'Was importiert werden soll',
    'drafts and posts pending review (%s)' => 'Entwürfe und Beiträge, die auf Freigabe warten (%s)',
    'pages (%s)' => 'Seiten (%s)',
    'redirects from old addresses to new ones' => 'Weiterleitungen von alten Adressen auf neue',
    'The redirects will be saved but only take effect once you turn on the Redirects feature.' => 'Die Weiterleitungen werden gespeichert, greifen aber erst, wenn Sie die Funktion Weiterleitungen einschalten.',
    'Start import' => 'Import starten',
    'pending review' => 'Freigabe ausstehend',
    'in trash' => 'im Papierkorb',
    'auto-drafts' => 'automatische Entwürfe',
    'The import has stopped:' => 'Der Import wurde angehalten:',
    'Back to Import and export' => 'Zurück zu Import und Export',
    'Reading file %s: %s items processed. Keep this page open.' => 'Datei %s wird gelesen: %s Elemente verarbeitet. Lassen Sie diese Seite geöffnet.',
    'Importing: %s of %s items. Keep this page open, it continues by itself.' => 'Import läuft: %s von %s Elementen. Lassen Sie diese Seite geöffnet, er läuft von selbst weiter.',
    'The content import is finished.' => 'Der Import der Inhalte ist abgeschlossen.',
    'New pages' => 'Neue Seiten',
    'Redirects from old addresses' => 'Weiterleitungen von alten Adressen',
    'Skipped (already imported earlier)' => 'Übersprungen (bereits früher importiert)',
    'Images from the old site' => 'Bilder von der alten Website',
    '%s images downloaded, %s failed.' => '%s Bilder heruntergeladen, %s fehlgeschlagen.',
    'Latest images that could not be downloaded' => 'Neueste Bilder, die nicht heruntergeladen werden konnten',
    'This server cannot download files from other sites (both curl and allow_url_fopen are missing, or the GD extension). Move the images manually: upload them to Media and replace them in the articles.' => 'Dieser Server kann keine Dateien von anderen Websites herunterladen (sowohl curl als auch allow_url_fopen fehlen, oder die GD-Erweiterung). Verschieben Sie die Bilder manuell: Laden Sie sie in die Medien hoch und ersetzen Sie sie in den Artikeln.',
    'The file does not contain the address of the old site, so the images cannot be downloaded.' => 'Die Datei enthält nicht die Adresse der alten Website, daher können die Bilder nicht heruntergeladen werden.',
    'Try downloading again' => 'Erneut herunterladen',
    'Download images from the old site' => 'Bilder von der alten Website herunterladen',
    'The PHP extension xmlreader or dom is missing on the server – a WordPress export cannot be read without them.' => 'Auf dem Server fehlt die PHP-Erweiterung xmlreader oder dom – ohne sie kann ein WordPress-Export nicht gelesen werden.',
    'WordPress export' => 'WordPress-Export',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/ folder – it will appear in the list below.' => 'Der Server erlaubt Uploads von höchstens %s. Kopieren Sie eine größere Datei per FTP in den Ordner storage/import/ – sie erscheint in der Liste unten.',
    'Upload and show preview' => 'Hochladen und Vorschau anzeigen',
    'Uploaded' => 'Hochgeladen',
    'Delete the file %s? Content that has already been imported stays on the site.' => 'Die Datei %s löschen? Bereits importierte Inhalte bleiben auf der Website erhalten.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors and commenters from the old site.' => 'Sie können dieselbe Datei wiederholt importieren – was bereits importiert wurde, wird übersprungen. Löschen Sie die Datei, wenn der Import abgeschlossen ist; sie enthält E-Mail-Adressen von Autoren und Kommentatoren der alten Website.',
    'Export of the whole site' => 'Export der gesamten Website',
    'The PHP zip extension is missing on the server, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Auf dem Server fehlt die PHP-Erweiterung zip, daher enthält der Export nur Daten (JSON). Laden Sie den Ordner media/ per FTP herunter.',
    'Create export' => 'Export erstellen',
    'Delete the export %s?' => 'Den Export %s löschen?',
    'The last three exports are kept. To restore this site, use the database backup in Settings → Backups and updates.' => 'Die letzten drei Exporte werden aufbewahrt. Um diese Website wiederherzustellen, verwenden Sie das Datenbank-Backup unter Einstellungen → Backups und Updates.',
    'being read' => 'wird gelesen',
    'ready to import' => 'bereit zum Import',
    'import in progress' => 'Import läuft',
    'content imported' => 'Inhalte importiert',
    'downloading images' => 'Bilder werden heruntergeladen',
    'imported including images' => 'einschließlich Bildern importiert',
    'Result' => 'Ergebnis',
    'Show preview' => 'Vorschau anzeigen',
    'Read again' => 'Erneut lesen',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/ folder.' => 'Die Datei konnte nicht hochgeladen werden. Wenn sie größer ist, als der Server erlaubt, laden Sie sie per FTP in den Ordner storage/import/ hoch.',
    'The file must have the .xml extension – it is an export from WordPress (Tools → Export).' => 'Die Datei muss die Endung .xml haben – es ist ein Export aus WordPress (Werkzeuge → Exportieren).',
    'The file could not be saved – check write permissions for storage/import.' => 'Die Datei konnte nicht gespeichert werden – prüfen Sie die Schreibrechte für storage/import.',
    'The file does not exist.' => 'Die Datei existiert nicht.',
    'The file has been deleted. The imported content stays on the site.' => 'Die Datei wurde gelöscht. Die importierten Inhalte bleiben auf der Website erhalten.',
    'The export is ready – download it from the list below.' => 'Der Export ist fertig – laden Sie ihn aus der Liste unten herunter.',
    'The export does not exist.' => 'Der Export existiert nicht.',
    'The export has been deleted.' => 'Der Export wurde gelöscht.',
    'Cannot create the storage/import folder – check write permissions.' => 'Der Ordner storage/import kann nicht erstellt werden – prüfen Sie die Schreibrechte.',
    'The file is empty or larger than 1 GB. Export a large site from WordPress in parts (by date).' => 'Die Datei ist leer oder größer als 1 GB. Exportieren Sie eine große Website aus WordPress in Teilen (nach Datum).',
    'The file could not be opened.' => 'Die Datei konnte nicht geöffnet werden.',
    'This is not a WordPress export. In WordPress open Tools → Export, choose “All content” and download the .xml file.' => 'Das ist kein WordPress-Export. Öffnen Sie in WordPress Werkzeuge → Exportieren, wählen Sie „Alle Inhalte“ und laden Sie die .xml-Datei herunter.',
    'The file contains no site content (the channel element is missing).' => 'Die Datei enthält keine Website-Inhalte (das Element channel fehlt).',
    'The file contains a DOCTYPE or custom entities. A WordPress export never has them – the file was rejected for security reasons.' => 'Die Datei enthält ein DOCTYPE oder eigene Entitäten. Ein WordPress-Export hat diese nie – die Datei wurde aus Sicherheitsgründen abgelehnt.',
    'The file is not valid XML – it is damaged or incomplete. Download the export from WordPress again. The error is on line:' => 'Die Datei ist kein gültiges XML – sie ist beschädigt oder unvollständig. Laden Sie den Export erneut aus WordPress herunter. Der Fehler befindet sich in Zeile:',
    '(untitled)' => '(ohne Titel)',
    'The address does not belong to the old site.' => 'Die Adresse gehört nicht zur alten Website.',
    'The domain of the old site does not exist or points to an internal network.' => 'Die Domain der alten Website existiert nicht oder verweist auf ein internes Netzwerk.',
    'The old site did not return the image, it responded with error' => 'Die alte Website hat das Bild nicht geliefert, sie antwortete mit dem Fehler',
    'The file is not a JPG, PNG, GIF or WebP image.' => 'Die Datei ist kein JPG-, PNG-, GIF- oder WebP-Bild.',
    'Too many redirects.' => 'Zu viele Weiterleitungen.',
    'The image is larger than 15 MB.' => 'Das Bild ist größer als 15 MB.',
    'The old site is not responding.' => 'Die alte Website antwortet nicht.',
    'The old site responds too slowly.' => 'Die alte Website antwortet zu langsam.',
    'The media exceed 1 GB, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Die Medien überschreiten 1 GB, daher enthält der Export nur Daten (JSON). Laden Sie den Ordner media/ per FTP herunter.',
    'There is not enough disk space for an archive with media, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Für ein Archiv mit Medien ist nicht genug Speicherplatz vorhanden, daher enthält der Export nur Daten (JSON). Laden Sie den Ordner media/ per FTP herunter.',
    'The archive could not be created – check write permissions for storage/zalohy.' => 'Das Archiv konnte nicht erstellt werden – prüfen Sie die Schreibrechte für storage/zalohy.',
    'The archive could not be finished – the disk is probably full.' => 'Das Archiv konnte nicht fertiggestellt werden – wahrscheinlich ist der Datenträger voll.',
    'Cannot write to storage/zalohy – check write permissions.' => 'In storage/zalohy kann nicht geschrieben werden – prüfen Sie die Schreibrechte.',
    'Button text' => 'Text der Schaltfläche',
    'Turn off' => 'Ausschalten',
    'Turn on' => 'Einschalten',
    'edited directly on the site' => 'direkt auf der Website bearbeitet',
    'Writing assistant (your own key)' => 'Schreibassistent (eigener Schlüssel)',
    'Language:' => 'Sprache:',
