    'Video address' => 'Adresse des Videos',
    'Video title (for screen readers)' => 'Titel des Videos (für Screenreader)',
    'A thin horizontal line between parts of the content.' => 'Eine dünne waagerechte Linie zwischen Teilen des Inhalts.',
    'Latest news as cards – they update themselves.' => 'Die neuesten News als Karten – sie aktualisieren sich von selbst.',
    'Dynamic' => 'Dynamisch',
    'Number of news items' => 'Anzahl der News-Beiträge',
    'Only from category (address, optional)' => 'Nur aus Kategorie (Adresse, optional)',
    'Show images' => 'Bilder anzeigen',
    'Cards from a collection (testimonials, team, products…) – the inside is the template for one item, {{fields}} fill in automatically.' => 'Karten aus einer Sammlung (Kundenstimmen, Team, Produkte …) – der Inhalt ist die Vorlage für einen Eintrag, {{fields}} werden automatisch eingesetzt.',
    'Maximum items' => 'Maximale Anzahl Einträge',
    'by order in the administration' => 'nach Reihenfolge in der Administration',
    'by name' => 'nach Name',
    'newest first' => 'neueste zuerst',
    'Text when the collection has no items' => 'Text, wenn die Sammlung keine Einträge hat',
    'An enquiry or question – submitted messages are in Enquiries and arrive by email.' => 'Eine Anfrage oder Frage – abgesendete Nachrichten finden Sie unter Anfragen, sie kommen auch per E-Mail an.',
    'checkbox (consent)' => 'Kontrollkästchen (Einwilligung)',
    'Custom HTML' => 'Eigenes HTML',
    'Embedded code of another service (map, booking). Administrators only.' => 'Eingebetteter Code eines anderen Dienstes (Karte, Buchung). Nur für Administratoren.',
    'The site logo from Appearance, otherwise the site name – a link to the home page.' => 'Das Logo der Website aus dem Erscheinungsbild, sonst der Name der Website – ein Link zur Startseite.',
    'Address, phone, email, company ID, opening hours, map, copyright or social networks from Settings.' => 'Adresse, Telefonnummer, E-Mail, USt-IdNr., Öffnungszeiten, Karte, Copyright oder soziale Netzwerke aus den Einstellungen.',
    '© year and site name' => '© Jahr und Name der Website',
    'RSS link' => 'RSS-Link',
    'The system inserts the news item, news list or 404 message here. Use it exactly once in a wrapper.' => 'Das System fügt hier den News-Beitrag, die News-Liste oder die 404-Meldung ein. In einem Rahmen gehört es genau einmal hin.',
    'flex (row / column)' => 'Flex (Zeile / Spalte)',
    'Direction' => 'Richtung',
