    'normal (anchor for nested)' => 'normal (Anker für Verschachteltes)',
    'sticky on scroll' => 'beim Scrollen fixieren',
    'Spacing' => 'Abstände',
    'Typography' => 'Typografie',
    'Background and border' => 'Hintergrund und Rahmen',
    'Component' => 'Komponente',
    'A reusable block – editing the component updates it everywhere it is used.' => 'Ein wiederverwendbarer Block – eine Änderung an der Komponente wirkt sich überall aus, wo sie verwendet wird.',
    'Properties' => 'Eigenschaften',
    'Components' => 'Komponenten',
    'New component' => 'Neue Komponente',
    'No components yet.' => 'Noch keine Komponenten.',
    'A component is a block you use in several places – a service card, a contact strip, a call to action. In the builder, select an element and choose “Save as component”; when you edit it later, it changes everywhere at once.' => 'Eine Komponente ist ein Block, den Sie an mehreren Stellen verwenden – eine Leistungskarte, ein Kontaktstreifen, eine Handlungsaufforderung. Wählen Sie im Builder ein Element aus und wählen Sie „Als Komponente speichern“; wenn Sie sie später ändern, ändert sie sich überall auf einmal.',
    'Create a component' => 'Komponente anlegen',
    'Name and properties' => 'Name und Eigenschaften',
    'Really delete this component?' => 'Diese Komponente wirklich löschen?',
    'Component name' => 'Name der Komponente',
    'e.g. Service card' => 'z. B. Leistungskarte',
    'What can differ between uses of the component – heading, text, image, link. In the builder you insert them into the component with a {{key}} tag, then fill in a value for each use (empty = default).' => 'Was sich bei jeder Verwendung der Komponente unterscheiden kann – Überschrift, Text, Bild, Link. Im Builder fügen Sie sie mit einem {{key}}-Tag in die Komponente ein, bei der Verwendung tragen Sie dann einen Wert ein (leer = Standard).',
    'Default value' => 'Standardwert',
    'Save component' => 'Komponente speichern',
    'The component needs a name.' => 'Die Komponente braucht einen Namen.',
    'The component does not exist.' => 'Die Komponente existiert nicht.',
    'The component was saved.' => 'Die Komponente wurde gespeichert.',
    'The component was deleted. Places where it was used will be empty.' => 'Die Komponente wurde gelöscht. Stellen, an denen sie verwendet wurde, bleiben leer.',
    'Name or element is missing.' => 'Name oder Element fehlt.',
    'A component cannot be created from this element.' => 'Aus diesem Element kann keine Komponente erstellt werden.',
    'Component: %s' => 'Komponente: %s',
    'Services and content' => 'Leistungen und Inhalt',
    'Trust' => 'Vertrauen',
    'About the company' => 'Über das Unternehmen',
    'Contact and calls to action' => 'Kontakt und Handlungsaufforderungen',
    'Writing assistant – provider, your key and model' => 'Schreibassistent – Anbieter, Ihr Schlüssel und Modell',
    'Provider' => 'Anbieter',
    'Create a key with the provider:' => 'Einen Schlüssel erstellen Sie beim Anbieter:',
    'Mistral AI (Europe)' => 'Mistral AI (Europa)',
    'You pay only for actual use; one suggestion costs a fraction of a cent. The key is stored only on your site.' => 'Sie zahlen nur für die tatsächliche Nutzung; ein Vorschlag kostet nur den Bruchteil eines Cents. Der Schlüssel wird nur auf Ihrer Website gespeichert.',
    'API key' => 'API-Schlüssel',
    'For Claude, choose from the list (Sonnet is recommended). For other providers, enter the exact model name from their documentation – their model line-up changes often.' => 'Für Claude wählen Sie aus der Liste (empfohlen wird Sonnet). Bei anderen Anbietern geben Sie den genauen Modellnamen aus deren Dokumentation ein – das Modellangebot ändert sich dort oft.',
    'The assistant only suggests – a person decides on every change. When used, the text is sent to the chosen provider; nothing is sent anywhere without clicking an assistant button.' => 'Der Assistent macht nur Vorschläge – über jede Änderung entscheidet ein Mensch. Bei der Nutzung wird der Text an den gewählten Anbieter gesendet; ohne Klick auf eine Assistenten-Schaltfläche wird nirgendwohin etwas gesendet.',
    'The writing assistant is not enabled (Features).' => 'Der Schreibassistent ist nicht aktiviert (Funktionen).',
    'Enter the model name of the chosen provider under Features (Writing assistant).' => 'Geben Sie unter Funktionen (Schreibassistent) den Modellnamen des gewählten Anbieters ein.',
    'The API key is missing – an administrator enters it under Features (Writing assistant).' => 'Der API-Schlüssel fehlt – ein Administrator trägt ihn unter Funktionen (Schreibassistent) ein.',
    'Could not reach %s. Check that the server may make outgoing connections.' => '%s ist nicht erreichbar. Prüfen Sie, ob der Server ausgehende Verbindungen aufbauen darf.',
    'The %s API key is not valid. Check it under Features.' => 'Der API-Schlüssel für %s ist ungültig. Prüfen Sie ihn unter Funktionen.',
    '%s is busy right now or the key\'s limit is used up. Try again shortly.' => '%s ist gerade ausgelastet oder das Limit des Schlüssels ist erschöpft. Versuchen Sie es in Kürze erneut.',
    'The %s account has run out of credit.' => 'Das Guthaben des %s-Kontos ist aufgebraucht.',
    '%s does not know the model. Check its name under Features.' => '%s kennt das Modell nicht. Prüfen Sie den Namen unter Funktionen.',
    '%s is down. Try again shortly.' => '%s ist ausgefallen. Versuchen Sie es in Kürze erneut.',
    'Describe the section in at least one sentence – what it should contain and for whom.' => 'Beschreiben Sie den Abschnitt in mindestens einem Satz – was er enthalten soll und für wen.',
    'The assistant did not return a usable section. Try refining the description.' => 'Der Assistent hat keinen brauchbaren Abschnitt geliefert. Versuchen Sie, die Beschreibung zu präzisieren.',
    'The element has no text to rewrite.' => 'Das Element enthält keinen Text, der umgeschrieben werden könnte.',
    'Add variant' => 'Variante hinzufügen',
    'not on any page yet' => 'noch auf keiner Seite',
    'on pages: %s' => 'auf den Seiten: %s',
    'variant' => 'Variante',
    'Delete the variant? The selected pages will get the default version.' => 'Die Variante löschen? Die ausgewählten Seiten erhalten die Standardversion.',
    'A variant applies only to the selected pages; elsewhere the default stays. For example a landing page with a simpler header. If you leave the variant empty in the builder, the page will have no header (footer).' => 'Eine Variante gilt nur für die ausgewählten Seiten, anderswo bleibt die Standardversion. Zum Beispiel eine Landingpage mit einem einfacheren Kopfbereich. Wenn Sie die Variante im Builder leer lassen, hat die Seite keinen Kopfbereich (Fußbereich).',
    'Variant name' => 'Name der Variante',
    'e.g. Landing page' => 'z. B. Landingpage',
    'Only the header and footer can have variants.' => 'Nur Kopfbereich und Fußbereich können Varianten haben.',
    'Variant: %s' => 'Variante: %s',
    'The variant needs a name.' => 'Die Variante braucht einen Namen.',
    'The variant was deleted – the selected pages have the default version again.' => 'Die Variante wurde gelöscht – die ausgewählten Seiten haben wieder die Standardversion.',
    'by field – ascending' => 'nach Feld – aufsteigend',
    'by field – descending' => 'nach Feld – absteigend',
    'Sort field (key, e.g. price)' => 'Feld zum Sortieren (Schlüssel, z. B. price)',
    'Filter by field (key, optional)' => 'Nach Feld filtern (Schlüssel, optional)',
    'Filter buttons for visitors (by the field above)' => 'Filter-Buttons für Besucher (nach dem Feld oben)',
    'Paginate (by “Maximum items”)' => 'Seitenweise anzeigen (nach „Maximale Anzahl Einträge“)',
    'In the builder, new sections from a description and text rewrites; in news, headlines, intro, SEO description, tags, proofreading, image descriptions and translation. Needs your own Claude, OpenAI, Google or Mistral key (below); text is sent only when you click an assistant button.' => 'Im Builder neue Abschnitte nach Beschreibung und Umformulierungen von Texten; bei News Überschriften, Teaser, SEO-Beschreibung, Schlagwörter, Korrekturlesen, Bildbeschreibungen und Übersetzung. Benötigt Ihren eigenen Schlüssel von Claude, OpenAI, Google oder Mistral (unten); Text wird nur gesendet, wenn Sie auf eine Assistenten-Schaltfläche klicken.',
    'MCP server at /mcp: Claude builds pages in the builder with your account\'s permissions, edits the header, footer, collections and look, and writes news. Pages and news are saved as drafts that you publish, the menu and look go into the draft look; settings apply straight away. Everyone creates their access token under My account.' => 'MCP-Server unter /mcp: Claude baut mit den Rechten Ihres Kontos Seiten im Builder, bearbeitet Kopfbereich, Fußbereich, Sammlungen und Erscheinungsbild und schreibt News. Seiten und News speichert es als Entwürfe, die Sie veröffentlichen, Menü und Erscheinungsbild gehen in den Entwurf des Erscheinungsbilds; Einstellungen gelten sofort. Den Zugriffs-Token erstellt jeder selbst unter Mein Konto.',
    'Someone else has edited this page in the meantime (or you opened it in another window).' => 'Jemand anderes hat diese Seite in der Zwischenzeit bearbeitet (oder Sie haben sie in einem anderen Fenster geöffnet).',
    '%d files in use were not deleted – remove them from the site first (the list shows where they are used).' => '%d verwendete Dateien wurden nicht gelöscht – entfernen Sie sie zuerst von der Website (die Liste zeigt, wo sie verwendet werden).',
    'page' => 'Seite',
    'site part' => 'Seitenbereich',
    'collection' => 'Sammlung',
    'collection item' => 'Sammlungseintrag',
    'component' => 'Komponente',
    'class' => 'Klasse',
    'settings' => 'Einstellungen',
    'Unused' => 'Nicht verwendet',
    'Used in: %s' => 'Verwendet in: %s',
    'Shown under a news item\'s main photo unless it has its own photo credit.' => 'Wird unter dem Hauptfoto eines News-Beitrags angezeigt, sofern er keinen eigenen Fotonachweis hat.',
    'Site menu (Appearance → Menu) with submenus and the language switcher; collapsible on phones.' => 'Menü der Website (Erscheinungsbild → Menü) mit Untermenüs und Sprachumschalter; auf Smartphones aufklappbar.',
    'Main menu' => 'Hauptmenü',
    'Footer menu' => 'Menü im Fußbereich',
    'Link to news (in the automatic menu)' => 'Link zu den News (beim automatischen Menü)',
    'Language version:' => 'Sprachversion:',
    'The menu is currently built automatically from pages ticked “in navigation”. Once you edit and save it here, this version applies.' => 'Das Menü wird derzeit automatisch aus den Seiten zusammengestellt, die mit „In der Navigation“ markiert sind. Sobald Sie es hier bearbeiten und speichern, gilt diese Version.',
    'Reorder by dragging or with the arrows. The right arrow moves an item into the submenu of the one above.' => 'Die Reihenfolge ändern Sie per Ziehen oder mit den Pfeilen. Mit dem Pfeil nach rechts ordnen Sie einen Eintrag dem Untermenü des darüberliegenden zu.',
    'Links in the site footer (privacy policy, contact, careers…). Used by the default footer and by a Navigation element set to the footer menu.' => 'Links im Fußbereich der Website (Datenschutzerklärung, Kontakt, Karriere …). Sie werden vom Standard-Fußbereich und von einem Navigationselement verwendet, das auf das Menü im Fußbereich eingestellt ist.',
    'The menu is empty – add the first item.' => 'Das Menü ist leer – fügen Sie den ersten Eintrag hinzu.',
    'Add page' => 'Seite hinzufügen',
    'Custom link' => 'Eigener Link',
    'Group' => 'Gruppe',
    'An item without a link that only opens a submenu' => 'Ein Eintrag ohne Link, der nur ein Untermenü öffnet',
    'Save menu' => 'Menü speichern',
    'Return the menu to being built automatically from pages? Your changes will be discarded.' => 'Das Menü wieder automatisch aus den Seiten zusammenstellen lassen? Ihre Änderungen werden verworfen.',
    'Empty the footer menu?' => 'Das Menü im Fußbereich leeren?',
    'Back to automatic menu' => 'Zurück zum automatischen Menü',
    'Empty the menu' => 'Menü leeren',
    'The menu has been saved.' => 'Das Menü wurde gespeichert.',
    'The menu could not be saved – please try again.' => 'Das Menü konnte nicht gespeichert werden – bitte versuchen Sie es erneut.',
    'The menu is again built automatically from pages in the navigation.' => 'Das Menü wird wieder automatisch aus den Seiten der Navigation zusammengestellt.',
    'The footer menu is empty.' => 'Das Menü im Fußbereich ist leer.',
    'The site has a custom menu – the page is added to its end. Change the order and submenus in Appearance → Menu.' => 'Die Website hat ein individuell zusammengestelltes Menü – die Seite wird an dessen Ende angehängt. Reihenfolge und Untermenüs ändern Sie unter Erscheinungsbild → Menü.',
    'Lower number = earlier in the page list and in the automatic menu.' => 'Kleinere Zahl = weiter oben in der Seitenliste und im automatischen Menü.',
    'Which menu' => 'Welches Menü',
    'First fill in the Site e-mail on the General tab.' => 'Füllen Sie zuerst die Website-E-Mail im Tab „Allgemein“ aus.',
    'The page is in the trash. You can restore it for %d days.' => 'Die Seite befindet sich im Papierkorb. Sie können sie %d Tage lang wiederherstellen.',
    '%s (copy)' => '%s (Kopie)',
    'The page shows the text from the editor (the build\'s content without the layout). You will find the build in versions when you open the builder.' => 'Die Seite zeigt den Text aus dem Editor (den Inhalt des Builder-Entwurfs ohne das Layout). Den Builder-Entwurf finden Sie in den Versionen, wenn Sie den Builder öffnen.',
    'The home page cannot be deleted. First choose another home page in Settings → General.' => 'Die Startseite kann nicht gelöscht werden. Wählen Sie zuerst unter Einstellungen → Allgemein eine andere Startseite.',
    'The home page cannot be hidden. First choose another home page in Settings → General.' => 'Die Startseite kann nicht verborgen werden. Wählen Sie zuerst unter Einstellungen → Allgemein eine andere Startseite.',
    'A page in the trash uses this address – restore it or delete it permanently.' => 'Diese Adresse hat eine Seite im Papierkorb – stellen Sie sie wieder her oder löschen Sie sie endgültig.',
    'The page has been restored as hidden – publish it in its settings.' => 'Die Seite wurde als verborgen wiederhergestellt – veröffentlichen Sie sie in ihren Einstellungen.',
    'The page has been permanently deleted.' => 'Die Seite wurde endgültig gelöscht.',
    'The copy of the page is hidden – edit it and publish it.' => 'Die Kopie der Seite ist verborgen – bearbeiten und veröffentlichen Sie sie.',
    'Tag deleted. The news items remain, they just no longer carry it.' => 'Schlagwort gelöscht. Die News-Beiträge bleiben erhalten, sie tragen es nur nicht mehr.',
    'Page' => 'Seite',
    'The editor now contains the version from %s. It takes effect once you save the news item.' => 'Im Editor ist jetzt die Version vom %s. Sie gilt, sobald Sie den News-Beitrag speichern.',
    'News items moved to the trash: %d. They can be restored for 30 days (News → Trash).' => 'In den Papierkorb verschobene News-Beiträge: %d. Sie können 30 Tage lang wiederhergestellt werden (News → Papierkorb).',
    'News items restored: %d. They are back as drafts.' => 'Wiederhergestellte News-Beiträge: %d. Sie sind als Entwürfe zurück.',
    'News items permanently deleted: %d.' => 'Endgültig gelöschte News-Beiträge: %d.',
    'The news item does not exist or you do not have access to it.' => 'Der News-Beitrag existiert nicht oder Sie haben keinen Zugriff darauf.',
    'Only an editor or administrator can edit a published news item.' => 'Nur ein Redakteur oder Administrator kann einen veröffentlichten News-Beitrag bearbeiten.',
    'Save the news item first, then it can be translated.' => 'Speichern Sie den News-Beitrag zuerst, dann kann er übersetzt werden.',
    'This version of the news item does not exist.' => 'Diese Version des News-Beitrags existiert nicht.',
    'The news item will be checked again within a few minutes.' => 'Der News-Beitrag wird in einigen Minuten erneut geprüft.',
    'Categories' => 'Kategorien',
    'The category does not exist.' => 'Die Kategorie existiert nicht.',
    'Category saved.' => 'Kategorie gespeichert.',
    'The category cannot be deleted while it contains news items (including those in the trash). Move them elsewhere first.' => 'Die Kategorie kann nicht gelöscht werden, solange sie News-Beiträge enthält (auch im Papierkorb). Verschieben Sie diese zuerst woandershin.',
    'Category deleted.' => 'Kategorie gelöscht.',
    'Fill in the category name.' => 'Füllen Sie den Namen der Kategorie aus.',
    'Site appearance' => 'Erscheinungsbild der Website',
    'The site appearance has been saved.' => 'Das Erscheinungsbild der Website wurde gespeichert.',
    'Does not write news' => 'Schreibt keine News',
    'Writes, edits and publishes news by all authors' => 'Schreibt, bearbeitet und veröffentlicht News aller Autoren',
    'Writes and edits their own news; an editor publishes it' => 'Schreibt und bearbeitet eigene News; ein Redakteur veröffentlicht sie',
    'The user has been deleted. Their news items remain, without an author.' => 'Der Benutzer wurde gelöscht. Seine News-Beiträge bleiben ohne Autor erhalten.',
    'The build is not valid JSON.' => 'Der Builder-Entwurf ist kein gültiges JSON.',
    'There is nothing to publish.' => 'Es gibt nichts zu veröffentlichen.',
    'The section is not in the library.' => 'Der Abschnitt ist nicht in der Bibliothek.',
    'Class name: lowercase letters without accents, digits and hyphens (e.g. card, card--highlighted).' => 'Klassenname: Kleinbuchstaben ohne Akzente, Ziffern und Bindestriche (z. B. card, card--highlighted).',
    'Declaration not allowed: %s' => 'Deklaration nicht erlaubt: %s',
    'The version does not exist.' => 'Die Version existiert nicht.',
    '/new-address or https://…' => '/neue-adresse oder https://…',
    'A redirect is only used when nothing exists at the old address. It is created automatically when the address of a page, news item or category changes.' => 'Eine Weiterleitung wird nur verwendet, wenn unter der alten Adresse nichts vorhanden ist. Sie wird automatisch angelegt, wenn sich die Adresse einer Seite, eines News-Beitrags oder einer Kategorie ändert.',
    'Nothing to do – when you change the address of a page or news item, a redirect is created automatically.' => 'Sie müssen nichts tun – wenn Sie die Adresse einer Seite oder eines News-Beitrags ändern, wird automatisch eine Weiterleitung angelegt.',
    'Addresses visitors could not find (404)' => 'Adressen, die Besucher nicht gefunden haben (404)',
    'Write a news item' => 'News-Beitrag schreiben',
    'Images used in the news item “%s”.' => 'Bilder, die im News-Beitrag „%s“ verwendet werden.',
    'Upload your first photos with the form above – or drag them straight into the text in the editor.' => 'Laden Sie Ihre ersten Fotos mit dem Formular oben hoch – oder ziehen Sie sie direkt in den Text im Editor.',
    'Really delete the selected files? Files the site still uses are skipped.' => 'Die ausgewählten Dateien wirklich löschen? Dateien, die die Website noch verwendet, werden übersprungen.',
    'Image credit' => 'Bildnachweis',
    'Scheduled news is published and dates are shown according to it. It is now %s.' => 'Danach werden geplante News veröffentlicht und Datumsangaben angezeigt. Jetzt ist es %s.',
    'The site texts (Search, News, Read more…) are in this language, and the site declares it to search engines.' => 'In dieser Sprache sind die Texte der Website (Suchen, News, Weiterlesen …), und die Website meldet sie so den Suchmaschinen.',
    'Each version has its own pages, categories and news. A news item\'s language is set by its category. Link translations in the editor.' => 'Jede Version hat eigene Seiten, Kategorien und News. Die Sprache eines News-Beitrags bestimmt seine Kategorie. Übersetzungen verknüpfen Sie im Editor.',
    'Home page and news' => 'Startseite und News',
    'Site home page' => 'Startseite der Website',
    '– news list –' => '– News-Liste –',
    'The page shown at the site address. News is always at %s.' => 'Die Seite, die unter der Adresse der Website angezeigt wird. Die News sind immer unter %s.',
    'The site sends password reset links and system notifications, and enquiries from forms. With your own SMTP server, messages go out from a verified mailbox and do not end up in spam.' => 'Die Website sendet Links zum Zurücksetzen des Passworts und Systembenachrichtigungen, mit Formularen kommen auch Anfragen hinzu. Über Ihren eigenen SMTP-Server werden Nachrichten von einem verifizierten Postfach versendet und landen nicht im Spam.',
    'Send a test e-mail to the site address' => 'Test-E-Mail an die Adresse der Website senden',
    'Scheduled news, notifications and outgoing mail run on site visits. A low-traffic site makes them more precise by calling this address every 5 minutes from your hosting\'s cron:' => 'Geplante News, Benachrichtigungen und der Versand von E-Mails werden bei Besuchen der Website ausgelöst. Eine Website mit geringem Besucheraufkommen macht sie präziser, wenn Sie diese Adresse alle 5 Minuten per Cron Ihres Hostings aufrufen:',
    'Restore the database from this backup? Everything added to the site since it was created (pages, news, enquiries, settings) will be lost. The current state is saved to a new backup first.' => 'Die Datenbank aus diesem Backup wiederherstellen? Alles, was seit seiner Erstellung auf der Website hinzugekommen ist (Seiten, News, Anfragen, Einstellungen), geht verloren. Der aktuelle Stand wird vorher in einem neuen Backup gesichert.',
    'The database backup contains pages, news, settings and users; uploaded images are in the media backup. Backups are stored in the backups folder storage/zalohy/, which is not accessible from the web – download copies off the server too.' => 'Das Datenbank-Backup enthält Seiten, News, Einstellungen und Benutzer; hochgeladene Bilder sind im Medien-Backup. Backups liegen im Ordner storage/zalohy/, der über das Web nicht erreichbar ist – laden Sie sie auch außerhalb des Servers herunter.',
    'Language' => 'Sprache',
    'unpublished changes' => 'nicht veröffentlichte Änderungen',
    'Category name' => 'Name der Kategorie',
    'The part of the address after %s.' => 'Der Teil der Adresse nach %s.',
    'Shown above the category\'s news list and used as the description for search engines.' => 'Wird über der News-Liste der Kategorie angezeigt und als Beschreibung für Suchmaschinen verwendet.',
    'Higher number = higher in the list.' => 'Höhere Zahl = weiter oben in der Liste.',
    'News in this category belongs to this language version of the site.' => 'News in dieser Kategorie gehören zu dieser Sprachversion der Website.',
    'New category' => 'Neue Kategorie',
    'Back to news' => 'Zurück zu den News',
    'No category has been created yet.' => 'Es wurde noch keine Kategorie angelegt.',
    'Every news item belongs to one category – without it, the news item cannot be saved.' => 'Jeder News-Beitrag gehört zu einer Kategorie – ohne sie kann der News-Beitrag nicht gespeichert werden.',
    'Create the first category' => 'Erste Kategorie anlegen',
    'News items' => 'News-Beiträge',
    'Really delete the category?' => 'Die Kategorie wirklich löschen?',
    'Open the builder' => 'Builder öffnen',
    'This page\'s content is built in the builder.' => 'Der Inhalt dieser Seite wird im Builder zusammengestellt.',
    'Want to build the page from sections, columns and buttons?' => 'Möchten Sie die Seite aus Abschnitten, Spalten und Buttons zusammenbauen?',
    'Open in the builder' => 'Im Builder öffnen',
    'Search engines and sharing' => 'Suchmaschinen und Teilen',
    'empty = page name' => 'leer = Name der Seite',
    'One or two sentences on what visitors will find on the page (up to 160 characters).' => 'Ein bis zwei Sätze dazu, was Besucher auf der Seite finden (bis zu 160 Zeichen).',
    'empty = default image from Settings' => 'leer = Standardbild aus den Einstellungen',
    'Shown when the link is shared on Facebook, LinkedIn or Teams (ideally 1200 × 630 px).' => 'Wird angezeigt, wenn der Link auf Facebook, LinkedIn oder in Teams geteilt wird (ideal 1200 × 630 px).',
    'site home page' => 'Startseite der Website',
    'Show in the site\'s main navigation' => 'In der Hauptnavigation der Website anzeigen',
    'Save and open in the builder' => 'Speichern und im Builder öffnen',
    'Duplicate page' => 'Seite duplizieren',
    'Return the page to plain text? The build stays in versions and you can go back to it.' => 'Die Seite wieder auf einfachen Text zurücksetzen? Der Builder-Entwurf bleibt in den Versionen erhalten und Sie können zu ihm zurückkehren.',
    'Return page to text' => 'Seite auf Text zurücksetzen',
    'The builder needs JavaScript. The page content can also be edited without it in the page form.' => 'Der Builder benötigt JavaScript. Der Inhalt der Seite lässt sich auch ohne ihn im Seitenformular bearbeiten.',
    'Name or address contains:' => 'Name oder Adresse enthält:',
    'Deleted pages stay here for 30 days, then they are deleted permanently.' => 'Gelöschte Seiten bleiben hier 30 Tage, danach werden sie endgültig gelöscht.',
    'Back to pages' => 'Zurück zu den Seiten',
    'No page matches the search.' => 'Keine Seite entspricht der Suche.',
    'Try another word.' => 'Versuchen Sie ein anderes Wort.',
    'Clear search' => 'Suche zurücksetzen',
    'A business website usually consists of Home, About us, Services and Contact.' => 'Eine Unternehmenswebsite besteht üblicherweise aus Startseite, Über uns, Leistungen und Kontakt.',
    'Pages in the trash are not on the site. A restored page comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Seiten im Papierkorb sind nicht auf der Website. Eine wiederhergestellte Seite kommt als verborgen zurück; nach 30 Tagen wird sie endgültig aus dem Papierkorb gelöscht.',
    'Delete the page permanently? This cannot be undone.' => 'Die Seite endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'home' => 'Startseite',
    'The builder has changes that are not on the site yet.' => 'Im Builder gibt es Änderungen, die noch nicht auf der Website sind.',
    'The builder has work-in-progress changes that are not on the site yet.' => 'Im Builder gibt es Änderungen in Bearbeitung, die noch nicht auf der Website sind.',
    'You are building this page in the builder. The site still shows the text below – once you publish in the builder, the build replaces it.' => 'Sie bauen diese Seite im Builder. Auf der Website steht vorerst der Text unten – sobald Sie im Builder veröffentlichen, ersetzt der Builder-Entwurf ihn.',
    'Preview hidden page' => 'Vorschau der verborgenen Seite',
    'Duplicate' => 'Duplizieren',
    'Move the page to the trash? It disappears from the site; you can restore it for 30 days.' => 'Die Seite in den Papierkorb verschieben? Sie verschwindet von der Website, Sie können sie 30 Tage lang wiederherstellen.',
    'Most read news' => 'Meistgelesene News',
    'Where visitors come from' => 'Woher die Besucher kommen',
    'You cannot remove administrator rights from your own account.' => 'Sie können Ihrem eigenen Konto die Administratorrechte nicht entziehen.',
    'Really delete the user? Their news items will remain, without an author.' => 'Den Benutzer wirklich löschen? Seine News-Beiträge bleiben ohne Autor erhalten.',
    'Categories (those with posts are created)' => 'Kategorien (angelegt werden die, die Beiträge haben)',
    'User accounts and passwords – the news items will belong to you. Comments are not transferred.' => 'Benutzerkonten und Passwörter – die News-Beiträge gehören dann Ihnen. Kommentare werden nicht übertragen.',
    'Menus, widgets, appearance and plugin settings – you will rebuild the navigation on the new site.' => 'Menüs, Widgets, Erscheinungsbild und Einstellungen von Plugins – die Navigation bauen Sie auf der neuen Website neu auf.',
    'Which language version of the site the new categories and pages belong to.' => 'Zu welcher Sprachversion der Website die neuen Kategorien und Seiten gehören.',
    'Put posts without a category into' => 'Beiträge ohne Kategorie ablegen in',
    'a new “Uncategorised” category' => 'einer neuen Kategorie „Nicht zugeordnet“',
    'Imported news is not announced: no webhook or IndexNow. Before a larger import, create a database backup in Settings → Backups and updates.' => 'Importierte News werden nicht bekannt gegeben: kein Webhook und kein IndexNow. Erstellen Sie vor einem größeren Import unter Einstellungen → Backups und Updates ein Datenbank-Backup.',
    'Downloading images from the old site: %s of %s news items and pages done, %s images downloaded. Keep this page open, I will continue automatically.' => 'Bilder von der alten Website werden heruntergeladen: %s von %s News-Beiträgen und Seiten erledigt, %s Bilder heruntergeladen. Lassen Sie diese Seite geöffnet, ich mache automatisch weiter.',
    'New news items' => 'Neue News-Beiträge',
    'New categories' => 'Neue Kategorien',
    'Show news' => 'News anzeigen',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded only from the domain %s, and the old site must still be available.' => 'News und Seiten zeigen noch Bilder von der alten Website. Beim Herunterladen werden die Hauptbilder der News-Beiträge und die Bilder in den Texten in den Medien gespeichert (verkleinert, mit Vorschaubildern und WebP) und die Links in den Texten umgeschrieben. Heruntergeladen wird ausschließlich von der Domain %s, und die alte Website muss noch erreichbar sein.',
    'In WordPress, open Tools → Export, choose “All content” and download the .xml file. Then upload it here. Pages, posts (as news), categories and tags are converted and redirects from the old addresses are created; nothing changes on the site until you confirm the import in the next step.' => 'Öffnen Sie in WordPress Werkzeuge → Export, wählen Sie „Alle Inhalte“ und laden Sie die .xml-Datei herunter. Diese laden Sie dann hier hoch. Seiten, Beiträge (als News), Kategorien und Schlagwörter werden umgewandelt, und es werden Weiterleitungen von den alten Adressen angelegt; auf der Website ändert sich nichts, bis Sie den Import im nächsten Schritt bestätigen.',
    'One archive gives you the whole site in an open format (JSON): pages, news, categories, tags, redirects, menus, collections, pop-ups, site parts, components, shared classes and uploaded files – as a content backup or for moving elsewhere. Enquiries, passwords, keys and accounts are not included.' => 'Ein Archiv liefert Ihnen die gesamte Website in einem offenen Format (JSON): Seiten, News, Kategorien, Schlagwörter, Weiterleitungen, Menüs, Sammlungen, Pop-ups, Seitenbereiche, Komponenten, gemeinsame Klassen und hochgeladene Dateien – als Inhalts-Backup oder für den Umzug woandershin. Anfragen, Passwörter, Schlüssel und Konten sind nicht enthalten.',
    'Back to the news list' => 'Zurück zur News-Übersicht',
    'Shown in lists and at the start of the news item – do not repeat it in the text.' => 'Wird in Listen und am Anfang des News-Beitrags angezeigt – wiederholen Sie es nicht im Text.',
    'To embed a video, put its address (YouTube, Vimeo) on a line of its own. It loads for the visitor only after a click.' => 'Ein Video binden Sie ein, indem Sie seine Adresse (YouTube, Vimeo) in eine eigene Zeile setzen. Es wird für den Besucher erst nach einem Klick geladen.',
    'Draft' => 'Entwurf',
    'An editor or site administrator publishes the news item.' => 'Ein Redakteur oder der Administrator der Website veröffentlicht den News-Beitrag.',
    'A future date = the news item is published automatically at that time.' => 'Ein zukünftiges Datum = der News-Beitrag wird zu diesem Zeitpunkt automatisch veröffentlicht.',
    'Mark as updated (with today\'s date)' => 'Als aktualisiert markieren (mit heutigem Datum)',
    'Comma-separated. Visitors can use a tag to see related news.' => 'Durch Kommas getrennt. Über ein Schlagwort sehen Besucher verwandte News.',
    'Image caption' => 'Bildunterschrift',
    'Empty field = caption and credit from the Media library.' => 'Leeres Feld = Bildunterschrift und Nachweis aus der Medienbibliothek.',
    'Translation' => 'Übersetzung',
    'Language versions' => 'Sprachversionen',
    'Translate the saved version with the assistant? A draft is created for you to read before publishing. Translation can take up to a minute.' => 'Die gespeicherte Version mit dem Assistenten übersetzen? Es entsteht ein Entwurf, den Sie vor der Veröffentlichung durchlesen. Die Übersetzung kann bis zu einer Minute dauern.',
    'address or number of the original news item' => 'Adresse oder Nummer des ursprünglichen News-Beitrags',
    'Fill in only for a news item in another language version (the category sets the language).' => 'Nur bei einem News-Beitrag in einer anderen Sprachversion ausfüllen (die Sprache bestimmt die Kategorie).',
    'SEO and more settings' => 'SEO und weitere Einstellungen',
    'The part of the address after %s. If you change it after publishing, the old address redirects automatically.' => 'Der Teil der Adresse nach %s. Wenn Sie ihn nach der Veröffentlichung ändern, wird die alte Adresse automatisch weitergeleitet.',
    'empty = news item title' => 'leer = Titel des News-Beitrags',
    'Question on one line, the answer below it, an empty line between pairs. Shown below the text and in structured data (FAQ).' => 'Frage in einer Zeile, die Antwort darunter, zwischen den Paaren eine Leerzeile. Wird unter dem Text und in strukturierten Daten (FAQ) angezeigt.',
    'In the background, the system goes through published news – one every five minutes, each once a month – and checks whether its links still work. News items checked: %s of %s.' => 'Im Hintergrund geht das System die veröffentlichten News durch – eine alle fünf Minuten, jede einmal im Monat – und prüft, ob die Links darin noch funktionieren. Geprüfte News-Beiträge: %s von %s.',
    'New news item' => 'Neuer News-Beitrag',
    'News status' => 'Status der News',
    'Category:' => 'Kategorie:',
    'Total:' => 'Gesamt:',
    'Deleted news items stay here for 30 days, then they are deleted permanently.' => 'Gelöschte News-Beiträge bleiben hier 30 Tage, danach werden sie endgültig gelöscht.',
    'No news item matches the filter.' => 'Kein News-Beitrag entspricht dem Filter.',
    'Try another word, category or status.' => 'Versuchen Sie ein anderes Wort, eine andere Kategorie oder einen anderen Status.',
    'There are no news items yet.' => 'Es gibt noch keine News-Beiträge.',
    'Until you publish a news item, it stays a draft that nobody sees on the site.' => 'Bis Sie einen News-Beitrag veröffentlichen, bleibt er ein Entwurf, den auf der Website niemand sieht.',
    'Write the first news item' => 'Ersten News-Beitrag schreiben',
    'News items in the trash are not on the site. A restored news item comes back as a draft; after 30 days it is permanently deleted from the trash.' => 'News-Beiträge im Papierkorb sind nicht auf der Website. Ein wiederhergestellter News-Beitrag kommt als Entwurf zurück; nach 30 Tagen wird er endgültig aus dem Papierkorb gelöscht.',
    'Delete the selected news items permanently? This cannot be undone.' => 'Die ausgewählten News-Beiträge endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'Back to the news item' => 'Zurück zum News-Beitrag',
    'Tags are created automatically as you write news. When you add a description to a tag, its page becomes a topic – an introduction to a field or project with all its news in one place.' => 'Schlagwörter entstehen von selbst, während Sie News schreiben. Wenn Sie einem Schlagwort eine Beschreibung hinzufügen, wird seine Seite zu einem Thema – eine Einführung in ein Fachgebiet oder Projekt mit allen News an einem Ort.',
    'Optional. Shown above the news list and as the description for search engines.' => 'Optional. Wird über der News-Liste und als Beschreibung für Suchmaschinen angezeigt.',
    'The news items get the selected tag, this one is removed and its address redirects. Useful for typos and duplicate spellings.' => 'Die News-Beiträge erhalten das ausgewählte Schlagwort, dieses wird entfernt und seine Adresse weitergeleitet. Praktisch bei Tippfehlern und doppelten Schreibweisen.',
    'Add them in the news editor in the Tags field. Here you can then merge them and turn them into topic pages.' => 'Fügen Sie sie im News-Editor im Feld „Schlagwörter“ hinzu. Hier können Sie sie dann zusammenführen und in Themenseiten umwandeln.',
    'Delete the tag? The news items stay, they just lose this tag.' => 'Das Schlagwort löschen? Die News-Beiträge bleiben erhalten, sie verlieren nur dieses Schlagwort.',
    'Changed by an administrator in Users.' => 'Wird von einem Administrator unter Benutzer geändert.',
    'Shown with news items on the site.' => 'Wird bei News-Beiträgen auf der Website angezeigt.',
    'Position in the company' => 'Position im Unternehmen',
    'e.g. head of sales' => 'z. B. Vertriebsleiter',
    'Shown as a short profile under your news items. What you do in the company and your background.' => 'Wird als kurzes Profil unter Ihren News-Beiträgen angezeigt. Was Sie im Unternehmen tun und welchen Hintergrund Sie haben.',
    'It creates new news items as drafts and new pages as hidden. All its changes are in the Change log. Protect the token like a password.' => 'Neue News-Beiträge legt er als Entwürfe an und neue Seiten als verborgen. Alle seine Eingriffe finden Sie im Änderungsprotokoll. Schützen Sie den Token wie ein Passwort.',
    'Colours' => 'Farben',
    'Shades (muted text, lines, soft primary colour) and the button text colour are derived automatically.' => 'Farbtöne (gedämpfter Text, Linien, sanfte Primärfarbe) und die Textfarbe auf Buttons werden automatisch berechnet.',
    'Readability' => 'Lesbarkeit',
    'according to the visitor\'s device' => 'je nach Gerät des Besuchers',
    'Check your logo: a dark logo on a transparent background would disappear on a dark site.' => 'Prüfen Sie Ihr Logo: Ein dunkles Logo auf transparentem Hintergrund würde auf einer dunklen Website verschwinden.',
    'Sizes' => 'Größen',
    'Type and spacing grow smoothly with the window width – from phone to large monitor. Headings are multiples of the base font size.' => 'Schrift und Abstände wachsen stufenlos mit der Fensterbreite – vom Smartphone bis zum großen Monitor. Überschriften sind Vielfache der Basisschriftgröße.',
    'Base font size on phones' => 'Basisschriftgröße auf Smartphones',
    'Base font size on monitors' => 'Basisschriftgröße auf Monitoren',
    'Text width (news and text pages)' => 'Textbreite (News und Textseiten)',
    'Logo and icon' => 'Logo und Icon',
    'Save appearance' => 'Erscheinungsbild speichern',
    'The preview shows unsaved changes.' => 'Die Vorschau zeigt nicht gespeicherte Änderungen.',
    'Home page preview' => 'Vorschau der Startseite',
    'Desktop' => 'Desktop',
    'Business website' => 'Unternehmenswebsite',
    'Crafts and services' => 'Handwerk und Dienstleistungen',
    'Consulting and agency' => 'Beratung und Agentur',
    '%s, news items: %d' => '%s, News-Beiträge: %d',
    'Where do you want to go? Type the name of a section, action, page or news item…' => 'Wohin möchten Sie? Geben Sie den Namen eines Bereichs, einer Aktion, Seite oder eines News-Beitrags ein …',
    'automatic menu' => 'automatisches Menü',
    'variant saved' => 'Variante gespeichert',
