    'Named text styles you pick for an element in the builder (Style → Typography). A change here applies everywhere the style is used.' => 'Benannte Textstile, die Sie im Builder bei einem Element auswählen (Stil → Typografie). Eine Änderung hier wirkt sich überall aus, wo der Stil verwendet wird.',
    'Size (scale step)' => 'Größe (Skalenstufe)',
