    'All devices' => 'Alle Geräte',
    'Computer and tablet only' => 'Nur Computer und Tablet',
    'Phone only' => 'Nur Smartphone',
    'A heading, a short text and an e-mail field with confirmed sign-up.' => 'Eine Überschrift, ein kurzer Text und ein E-Mail-Feld mit bestätigter Anmeldung.',
    'Download for an e-mail' => 'Download gegen E-Mail-Adresse',
    'A guide or price list in exchange for contact details – the form goes to Enquiries.' => 'Ein Leitfaden oder eine Preisliste im Austausch gegen Kontaktdaten – das Formular landet in den Anfragen.',
    'Announcement bar' => 'Ankündigungsleiste',
    'A slim bar at the top with a short message and a link.' => 'Eine schmale Leiste oben mit einer kurzen Nachricht und einem Link.',
    'Discount or offer' => 'Rabatt oder Angebot',
    'A bold offer with a code and a button.' => 'Ein auffälliges Angebot mit Code und Button.',
    'Event invitation' => 'Einladung zu einer Veranstaltung',
    'A corner panel with the date, the place and a registration link.' => 'Ein Eckfeld mit Datum, Ort und Anmeldelink.',
    'Blank pop-up' => 'Leeres Pop-up',
    'A heading and a text – build the rest in the builder.' => 'Eine Überschrift und ein Text – den Rest bauen Sie im Builder.',
    'Pop-up settings (when and where it shows)' => 'Pop-up-Einstellungen (wann und wo es erscheint)',
    'Collection fields and settings' => 'Felder und Einstellungen der Sammlung',
    '%d%%' => '%d%%',
    '%d subscribers are going to the mailing service; the site sends the rest gradually in the background.' => '%d Abonnenten werden an den Mailing-Dienst übertragen; die Website sendet den Rest nach und nach im Hintergrund.',
    'The failed transfers were tried again – see the result in the Service column.' => 'Die fehlgeschlagenen Übertragungen wurden erneut versucht – das Ergebnis sehen Sie in der Spalte „Dienst“.',
    'Confirmed subscribers go to %s automatically; those who unsubscribe are removed from it.' => 'Bestätigte Abonnenten werden automatisch an %s übertragen; wer sich abmeldet, wird daraus entfernt.',
    'Waiting to be sent: %d.' => 'Wartet auf Versand: %d.',
    'Failed: %d.' => 'Fehlgeschlagen: %d.',
    'Send all confirmed subscribers to the service' => 'Alle bestätigten Abonnenten an den Dienst senden',
    'Try the failed ones again' => 'Fehlgeschlagene erneut versuchen',
    'Service settings' => 'Diensteinstellungen',
    'Using Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing? Once connected in Features, the site sends confirmed subscribers straight to your list.' => 'Sie nutzen Brevo, MailerLite, Mailchimp, Ecomail oder SmartEmailing? Sobald Sie den Dienst unter „Funktionen“ verbunden haben, sendet die Website bestätigte Abonnenten direkt an Ihre Liste.',
    'Connect a service' => 'Dienst verbinden',
    'Service' => 'Dienst',
    'waiting' => 'wartet',
    'The service did not respond.' => 'Der Dienst hat nicht geantwortet.',
    'Newsletter – connection to a mailing service' => 'Newsletter – Anbindung an einen Mailing-Dienst',
    'Connection to a mailing service' => 'Anbindung an einen Mailing-Dienst',
    'After a sign-up is confirmed (double opt-in), the site adds the address to the list in your service and removes it after unsubscribing. Sending, deliverability and unsubscribing from e-mails stay with the service. The transfer runs in the background – visitors do not wait.' => 'Nachdem eine Anmeldung bestätigt wurde (Double-Opt-in), fügt die Website die Adresse zur Liste in Ihrem Dienst hinzu und entfernt sie nach der Abmeldung. Versand, Zustellbarkeit und Abmeldung von E-Mails bleiben beim Dienst. Die Übertragung läuft im Hintergrund – Besucher müssen nicht warten.',
    'none – you export subscribers to CSV' => 'keiner – Sie exportieren Abonnenten als CSV',
    'Create the key in your service account (API, integrations). For SmartEmailing, enter the user name and the key separated by a colon. The key is stored only on your site and is never shown over MCP.' => 'Erstellen Sie den Schlüssel in Ihrem Dienstkonto (API, Integrationen). Bei SmartEmailing geben Sie Benutzername und Schlüssel durch einen Doppelpunkt getrennt ein. Der Schlüssel wird nur auf Ihrer Website gespeichert und nie über MCP angezeigt.',
    'The ID of the list (Brevo, Ecomail, SmartEmailing), group (MailerLite) or audience (Mailchimp) – you find it in the list settings in the service.' => 'Die ID der Liste (Brevo, Ecomail, SmartEmailing), der Gruppe (MailerLite) oder der Audience (Mailchimp) – Sie finden sie in den Listeneinstellungen im Dienst.',
    'Webhook URL' => 'Webhook-URL',
    'Only for “Another service via a webhook”: the site sends JSON with the event novy_odberatel or odhlaseni_odberu and the e-mail.' => 'Nur für „Anderer Dienst per Webhook“: Die Website sendet JSON mit dem Ereignis novy_odberatel oder odhlaseni_odberu und der E-Mail-Adresse.',
    'Another service via a webhook (Make, Zapier, n8n)' => 'Anderer Dienst per Webhook (Make, Zapier, n8n)',
    'Parts of the appearance' => 'Teile des Erscheinungsbilds',
    'Styles' => 'Stile',
    'A style is a ready set of colours, fonts, sizes and corner radius. Pick one with a click and fine-tune it in the other tabs – the content of the site does not change.' => 'Ein Stil ist ein fertiges Set aus Farben, Schriften, Größen und Eckenradius. Wählen Sie einen per Klick aus und passen Sie ihn in den anderen Tabs an – der Inhalt der Website ändert sich nicht.',
    'current' => 'aktuell',
    'You do not have to put a look for your brand together by hand: connect Claude and write, for example, “Set the look of the site to our brand – primary colour #0E6E6E, serif headings, subtle rounding”. It saves the colours and fonts to the design system, and you see the result here.' => 'Sie müssen das Erscheinungsbild Ihrer Marke nicht von Hand zusammenstellen: Verbinden Sie Claude und schreiben Sie zum Beispiel „Stelle das Erscheinungsbild der Website auf unsere Marke ein – Primärfarbe #0E6E6E, Serifen-Überschriften, dezente Rundung“. Claude speichert die Farben und Schriften im Designsystem, und Sie sehen das Ergebnis hier.',
    'Buttons, cards, images and form fields across the site get this radius.' => 'Buttons, Karten, Bilder und Formularfelder auf der gesamten Website erhalten diesen Radius.',
    'Fonts and sizes' => 'Schriften und Größen',
    'Shapes' => 'Formen',
    'Kaleta installation' => 'Kaleta-Installation',
    'Server check' => 'Serverprüfung',
    'The server does not meet the requirements. Fix the items marked with a cross and reload the page.' => 'Der Server erfüllt die Anforderungen nicht. Beheben Sie die mit einem Kreuz markierten Punkte und laden Sie die Seite neu.',
    'The installation could not be completed – check the highlighted fields.' => 'Die Installation konnte nicht abgeschlossen werden – prüfen Sie die markierten Felder.',
    'MySQL or MariaDB. Create an empty database beforehand – in your hosting control panel.' => 'MySQL oder MariaDB. Legen Sie vorher eine leere Datenbank an – im Kontrollpanel Ihres Hostings.',
