    'Table prefix' => 'Tabellenpräfix',
    'Site and administrator' => 'Website und Administrator',
    'The account you will first sign in to the administration with.' => 'Das Konto, mit dem Sie sich zuerst in der Verwaltung anmelden.',
    'Scheduled news posts are published and dates are shown according to it.' => 'Geplante News-Beiträge werden danach veröffentlicht und Datumsangaben danach angezeigt.',
    'Install Kaleta' => 'Kaleta installieren',
    'Creates the database tables and the config.php file.' => 'Erstellt die Datenbanktabellen und die Datei config.php.',
    'Kaleta is already installed' => 'Kaleta ist bereits installiert',
    'The config.php file exists, so the installer changes nothing.' => 'Die Datei config.php existiert, daher ändert das Installationsprogramm nichts.',
    'Done, your website is running' => 'Fertig, Ihre Website läuft',
    'The database is ready and the configuration has been written.' => 'Die Datenbank ist bereit und die Konfiguration wurde geschrieben.',
    'For security reasons install.php has deleted itself – there is nothing else you need to do.' => 'Aus Sicherheitsgründen hat sich install.php selbst gelöscht – Sie müssen nichts weiter tun.',
    'For security reasons, now delete this file from the server:' => 'Aus Sicherheitsgründen löschen Sie jetzt diese Datei vom Server:',
    'Go to the administration' => 'Zur Verwaltung',
