    'A component is a shared template: editing it under Components changes it everywhere it is used. The element on this page is replaced by the component.' => 'Eine Komponente ist eine gemeinsame Vorlage: Wenn Sie sie unter „Komponenten“ bearbeiten, ändert sie sich überall, wo sie verwendet wird. Das Element auf dieser Seite wird durch die Komponente ersetzt.',
    'More actions' => 'Weitere Aktionen',
    'Cancel move by tapping' => 'Verschieben durch Tippen abbrechen',
    'Choose a video in MP4 or WebM format.' => 'Wählen Sie ein Video im Format MP4 oder WebM.',
    'Share a link to the draft preview' => 'Einen Link zur Entwurfsvorschau teilen',
    'Link validity' => 'Gültigkeit des Links',
    '1 day' => '1 Tag',
    '3 days' => '3 Tage',
    '7 days' => '7 Tage',
    'The draft could not be saved.' => 'Der Entwurf konnte nicht gespeichert werden.',
    'The link could not be created.' => 'Der Link konnte nicht erstellt werden.',
    'Preview link' => 'Vorschau-Link',
    'Copy' => 'Kopieren',
    'Valid until %s.' => 'Gültig bis %s.',
    'Create link' => 'Link erstellen',
    'Share preview' => 'Vorschau teilen',
    'Anyone with the link can see the draft without signing in – including changes you make later. Search engines do not index it.' => 'Jeder mit dem Link kann den Entwurf ohne Anmeldung sehen – auch spätere Änderungen. Suchmaschinen indexieren ihn nicht.',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). Send them your latest news in an e-mail styled by the design system (through an SMTP server, while cron runs), pass confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or export them to CSV.' => 'Das Element „Newsletter-Anmeldung“ im Builder: Besucher geben eine E-Mail-Adresse ein und bestätigen sie per Link (Double-Opt-in). Senden Sie ihnen Ihre neuesten News in einer E-Mail im Stil des Designsystems (über einen SMTP-Server, solange Cron läuft), übergeben Sie bestätigte Abonnenten an Ihren Mailing-Dienst (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, Webhook) oder exportieren Sie sie als CSV.',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send them news under Newsletters, or with your own tool – the export includes the unsubscribe link.' => 'Adressen aus dem Element „Newsletter-Anmeldung“. Als Abonnenten zählen nur Personen, die den Link in der E-Mail bestätigt haben. Senden Sie ihnen News unter „Newsletter“ oder mit Ihrem eigenen Tool – der Export enthält den Abmeldelink.',
    'Newsletters' => 'Newsletter',
    'New newsletter' => 'Neuer Newsletter',
