    'Cancel scheduling' => 'Planung abbrechen',
    'Sending to subscribers needs the publishing permission – ask an editor or an administrator.' => 'Zum Senden an Abonnenten ist die Berechtigung zum Veröffentlichen erforderlich – fragen Sie einen Redakteur oder Administrator.',
    'Send the newsletter to %d confirmed subscribers? Save your changes first – the saved version goes out.' => 'Den Newsletter an %d bestätigte Abonnenten senden? Speichern Sie zuerst Ihre Änderungen – die gespeicherte Version wird versendet.',
    'now' => 'jetzt',
    'at' => 'am',
    'Date and time of sending' => 'Datum und Uhrzeit des Versands',
    'Send to %d subscribers' => 'An %d Abonnenten senden',
    'The newsletter needs a subject.' => 'Der Newsletter benötigt einen Betreff.',
    'Choose at least one news item, or send the latest news.' => 'Wählen Sie mindestens einen News-Beitrag aus oder senden Sie die neuesten News.',
    'The button link must be an https:// address or a path on the site starting with /.' => 'Der Button-Link muss eine https://-Adresse oder ein Pfad auf der Website sein, der mit / beginnt.',
    'The newsletter does not exist.' => 'Der Newsletter existiert nicht.',
    'A newsletter that is being sent or was sent cannot be changed.' => 'Ein Newsletter, der gerade gesendet wird oder bereits gesendet wurde, kann nicht geändert werden.',
    'The newsletter is being sent right now – it cannot be deleted until it finishes.' => 'Der Newsletter wird gerade gesendet – er kann erst nach Abschluss gelöscht werden.',
    'The newsletter has already been sent.' => 'Der Newsletter wurde bereits gesendet.',
    'There are no confirmed subscribers yet.' => 'Es gibt noch keine bestätigten Abonnenten.',
    'The newsletter has no news items to send – publish a news item or choose No news.' => 'Der Newsletter hat keine News-Beiträge zum Senden – veröffentlichen Sie einen News-Beitrag oder wählen Sie „Keine News“.',
    'The time must be in the future, as YYYY-MM-DD HH:MM.' => 'Die Zeit muss in der Zukunft liegen, im Format JJJJ-MM-TT HH:MM.',
    'The test address is not a valid e-mail.' => 'Die Testadresse ist keine gültige E-Mail-Adresse.',
    'Newsletters are sent only through an SMTP server (Brevo, Amazon SES, Mailgun, your mailbox…) – set it up in Settings → Mail.' => 'Newsletter werden nur über einen SMTP-Server versendet (Brevo, Amazon SES, Mailgun, Ihr Postfach …) – richten Sie ihn unter Einstellungen → E-Mail ein.',
    'Cron has not called the tasks address in the last 30 minutes – newsletters go out in batches only while it runs. Set it up with the address in System status.' => 'Cron hat die Aufgabenadresse in den letzten 30 Minuten nicht aufgerufen – Newsletter gehen nur in Paketen hinaus, solange es läuft. Richten Sie es mit der Adresse unter Einstellungen → Zustand ein.',
    'The newsletter was saved.' => 'Der Newsletter wurde gespeichert.',
    'Sending to subscribers needs the publishing permission.' => 'Zum Senden an Abonnenten ist die Berechtigung zum Veröffentlichen erforderlich.',
    'The newsletter is scheduled for %s.' => 'Der Newsletter ist für %s geplant.',
    'Sending has started: %d subscribers. The e-mails go out in batches each time cron runs.' => 'Der Versand hat begonnen: %d Abonnenten. Die E-Mails gehen bei jedem Cron-Lauf in Paketen hinaus.',
    'Scheduling was cancelled – the newsletter is a draft again.' => 'Die Planung wurde abgebrochen – der Newsletter ist wieder ein Entwurf.',
    'The newsletter was deleted.' => 'Der Newsletter wurde gelöscht.',
    'Your account has no e-mail address – add one under My account.' => 'Ihr Konto hat keine E-Mail-Adresse – fügen Sie unter „Mein Konto“ eine hinzu.',
