    'The test e-mail could not be sent: %s' => 'Die Test-E-Mail konnte nicht gesendet werden: %s',
    'Cron' => 'Cron',
    'not set up – scheduled work waits for visits, and newsletters cannot be sent; you will find the address further down this page' => 'nicht eingerichtet – geplante Aufgaben warten auf Besuche, und Newsletter können nicht gesendet werden; die Adresse finden Sie weiter unten auf dieser Seite',
    'last run %s – newsletters are not being sent until cron runs again' => 'letzter Lauf %s – Newsletter werden erst wieder gesendet, wenn Cron erneut läuft',
    'Newsletters: e-mails per hour' => 'Newsletter: E-Mails pro Stunde',
    'Newsletters go out in batches while cron runs. Keep to the sending limit of your SMTP service – free plans often allow only a few hundred e-mails a day.' => 'Newsletter gehen in Paketen hinaus, solange Cron läuft. Halten Sie das Versandlimit Ihres SMTP-Dienstes ein – kostenlose Tarife erlauben oft nur einige hundert E-Mails pro Tag.',
    'Test' => 'Test',
    'Deleted items stay here for 30 days, then they are deleted permanently.' => 'Gelöschte Einträge bleiben hier 30 Tage lang erhalten und werden dann endgültig gelöscht.',
    'Back to items' => 'Zurück zu den Einträgen',
    'Items in the trash are not on the site. A restored item comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Einträge im Papierkorb sind nicht auf der Website. Ein wiederhergestellter Eintrag kommt verborgen zurück; nach 30 Tagen wird er endgültig aus dem Papierkorb gelöscht.',
    'Delete the item permanently? This cannot be undone.' => 'Den Eintrag endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'Move the item to the trash? It disappears from the site; you can restore it for 30 days.' => 'Den Eintrag in den Papierkorb verschieben? Er verschwindet von der Website; Sie können ihn 30 Tage lang wiederherstellen.',
    'The item is in the trash – it is no longer on the site; you can restore it for 30 days.' => 'Der Eintrag liegt im Papierkorb – er ist nicht mehr auf der Website; Sie können ihn 30 Tage lang wiederherstellen.',
    'The item was restored as hidden.' => 'Der Eintrag wurde als verborgen wiederhergestellt.',
    'The item was deleted permanently.' => 'Der Eintrag wurde endgültig gelöscht.',
    '%d enquiries read' => '%d Anfragen gelesen',
    'Custom layout' => 'Eigenes Layout',
    '%s in the layout/ folder is no longer used – since 1.6 the look comes only from Site appearance and the builder. Move what you need into shared classes and site parts, then delete the folder.' => '%s im Ordner layout/ wird nicht mehr verwendet – seit 1.6 stammt das Erscheinungsbild nur noch aus dem Erscheinungsbild der Website und dem Builder. Übertragen Sie, was Sie benötigen, in gemeinsame Klassen und Seitenbereiche und löschen Sie dann den Ordner.',
    'Unpublished look changes' => 'Nicht veröffentlichte Änderungen am Erscheinungsbild',
    'visitors still see the published look.' => 'Besucher sehen weiterhin das veröffentlichte Erscheinungsbild.',
    'Preview the whole site' => 'Die ganze Website in der Vorschau ansehen',
    'Publish the look' => 'Erscheinungsbild veröffentlichen',
