    'Menus: %s' => 'Menüs: %s',
    'automatic' => 'automatisch',
    'Saved to the draft look – preview the whole site, then publish it.' => 'Im Entwurf des Erscheinungsbilds gespeichert – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'There was nothing to publish.' => 'Es gab nichts zu veröffentlichen.',
    'The look is published: %s' => 'Das Erscheinungsbild ist veröffentlicht: %s',
    'The unpublished look changes were discarded.' => 'Die nicht veröffentlichten Änderungen am Erscheinungsbild wurden verworfen.',
    'The earlier look is in the draft – preview the whole site, then publish it.' => 'Das frühere Erscheinungsbild liegt im Entwurf – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'The look version does not exist.' => 'Die Version des Erscheinungsbilds existiert nicht.',
    'Design tokens have been loaded into the draft look – preview the whole site, then publish it.' => 'Die Design-Tokens wurden in den Entwurf des Erscheinungsbilds geladen – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'Colours, fonts, sizes and shapes go to the draft look first – with changes of shared classes and menus. Visitors see them once you publish the look.' => 'Farben, Schriften, Größen und Formen gehen zuerst in den Entwurf des Erscheinungsbilds – zusammen mit Änderungen an gemeinsamen Klassen und Menüs. Besucher sehen sie, sobald Sie das Erscheinungsbild veröffentlichen.',
    'Earlier looks' => 'Frühere Erscheinungsbilder',
    'Each time you publish the look, the one before is kept here (the last 20).' => 'Jedes Mal, wenn Sie das Erscheinungsbild veröffentlichen, wird das vorherige hier aufbewahrt (die letzten 20).',
