    'Use this template' => 'Diese Vorlage verwenden',
    'All site parts' => 'Alle Seitenbereiche',
    'A template is a clean skeleton – colours, fonts and spacing come from your design system. It goes into the draft of the part: adjust it in the builder and publish it; until then visitors see the published version.' => 'Eine Vorlage ist ein sauberes Grundgerüst – Farben, Schriften und Abstände stammen aus Ihrem Designsystem. Sie kommt in den Entwurf des Bereichs: Passen Sie sie im Builder an und veröffentlichen Sie sie; bis dahin sehen Besucher die veröffentlichte Version.',
    'The template could not be used.' => 'Die Vorlage konnte nicht verwendet werden.',
    'The template is in the draft – adjust it and publish; until then visitors see the published version.' => 'Die Vorlage liegt im Entwurf – passen Sie sie an und veröffentlichen Sie sie; bis dahin sehen Besucher die veröffentlichte Version.',
    'Webhooks' => 'Webhooks',
    'A webhook sends data to another service the moment something happens on the site – a new enquiry to a CRM or Slack, a published news item to Make, Zapier or n8n, which then share it on social networks.' => 'Ein Webhook sendet Daten an einen anderen Dienst, sobald auf der Website etwas passiert – eine neue Anfrage an ein CRM oder Slack, ein veröffentlichter News-Beitrag an Make, Zapier oder n8n, die ihn dann in sozialen Netzwerken teilen.',
    'Addresses' => 'Adressen',
    'Signature' => 'Signatur',
    'Signing secret' => 'Signaturschlüssel',
    'Every call carries the headers X-Kaleta-Timestamp and X-Kaleta-Signature (sha256=HMAC-SHA256 of “timestamp.body” with this secret). A receiver that checks the signature knows the call came from your site and was not changed. Keep the secret private.' => 'Jeder Aufruf enthält die Header X-Kaleta-Timestamp und X-Kaleta-Signature (sha256=HMAC-SHA256 von „timestamp.body“ mit diesem Schlüssel). Ein Empfänger, der die Signatur prüft, weiß, dass der Aufruf von Ihrer Website kam und nicht verändert wurde. Halten Sie den Schlüssel geheim.',
    'Create a new secret? Receivers that check the signature will reject calls until you give them the new one.' => 'Einen neuen Schlüssel erstellen? Empfänger, die die Signatur prüfen, lehnen Aufrufe ab, bis Sie ihnen den neuen Schlüssel geben.',
    'Create a new secret' => 'Neuen Schlüssel erstellen',
    'How to check the signature' => 'So prüfen Sie die Signatur',
    'Send a test call' => 'Testaufruf senden',
    'Delivery log' => 'Zustellprotokoll',
    'No webhook has been sent yet.' => 'Es wurde noch kein Webhook gesendet.',
    'Event' => 'Ereignis',
    'Address' => 'Adresse',
    'delivered' => 'zugestellt',
    'not delivered' => 'nicht zugestellt',
    'Send again' => 'Erneut senden',
    'A call that fails is retried after 1, 5 and 30 minutes and after 2 and 12 hours. Records are deleted after 30 days; the content of a delivered call is not kept.' => 'Ein fehlgeschlagener Aufruf wird nach 1, 5 und 30 Minuten sowie nach 2 und 12 Stunden erneut versucht. Einträge werden nach 30 Tagen gelöscht; der Inhalt eines zugestellten Aufrufs wird nicht aufbewahrt.',
    'First fill in and save at least one webhook address (https://).' => 'Tragen Sie zuerst mindestens eine Webhook-Adresse (https://) ein und speichern Sie sie.',
    'The test call has been delivered.' => 'Der Testaufruf wurde zugestellt.',
    'The test call was not delivered – the reason is in the delivery log. It will be retried automatically.' => 'Der Testaufruf wurde nicht zugestellt – den Grund finden Sie im Zustellprotokoll. Er wird automatisch erneut versucht.',
    'A new secret has been created. Paste it into every receiver that checks the signature.' => 'Ein neuer Schlüssel wurde erstellt. Fügen Sie ihn in jeden Empfänger ein, der die Signatur prüft.',
    'Only https:// addresses are allowed.' => 'Es sind nur https://-Adressen erlaubt.',
    'The receiver did not respond.' => 'Der Empfänger hat nicht geantwortet.',
    'Its classes and components were not imported – only an administrator can add them.' => 'Seine Klassen und Komponenten wurden nicht importiert – nur ein Administrator kann sie hinzufügen.',
    'New classes: %d, new components: %d (those the site already had were kept).' => 'Neue Klassen: %d, neue Komponenten: %d (die, die die Website schon hatte, wurden beibehalten).',
    'all calls of the last 7 days delivered' => 'alle Aufrufe der letzten 7 Tage zugestellt',
    '%d call(s) of the last 7 days not delivered – see Settings → Webhooks' => '%d Aufruf(e) der letzten 7 Tage nicht zugestellt – siehe Einstellungen → Webhooks',
    'Import from Kaleta' => 'Import aus Kaleta',
    'Moving a site from another Kaleta installation: upload its export (the .zip archive from Export of the whole site). Everything is imported – pages, news, collections, components, menus, the look and the media – into a new, empty site; user accounts and secrets are never part of an export.' => 'Eine Website aus einer anderen Kaleta-Installation übernehmen: Laden Sie deren Export hoch (das ZIP-Archiv aus „Export der gesamten Website“). Alles wird importiert – Seiten, News, Sammlungen, Komponenten, Menüs, das Erscheinungsbild und die Medien – in eine neue, leere Website; Benutzerkonten und Geheimnisse sind nie Teil eines Exports.',
    'This site already has its own content, so an export cannot be imported here. Install Kaleta again and choose “Start from an export”.' => 'Diese Website hat bereits eigene Inhalte, daher kann hier kein Export importiert werden. Installieren Sie Kaleta erneut und wählen Sie „Mit einem Export starten“.',
    'Kaleta export' => 'Kaleta-Export',
    'imported' => 'importiert',
    'Export of the site “%s” from Kaleta %s, created %s.' => 'Export der Website „%s“ aus Kaleta %s, erstellt am %s.',
    'Files in media/' => 'Dateien in media/',
    'The export has no files – copy the media/ folder from the old site over FTP before or after the import.' => 'Der Export enthält keine Dateien – kopieren Sie den Ordner media/ der alten Website per FTP vor oder nach dem Import.',
    'The import replaces all content of this site: pages, news, collections, components, menus, site parts, pop-ups, redirects and the media library, and takes over the site name, company details, languages and the look. User accounts, passwords, keys and the settings of mail and backups stay as they are on this site – the export never contains them. Imported news will be yours.' => 'Der Import ersetzt alle Inhalte dieser Website: Seiten, News, Sammlungen, Komponenten, Menüs, Seitenbereiche, Pop-ups, Weiterleitungen und die Medienbibliothek, und übernimmt den Namen der Website, die Unternehmensangaben, Sprachen und das Erscheinungsbild. Benutzerkonten, Passwörter, Schlüssel sowie die Einstellungen für E-Mail und Backups bleiben auf dieser Website unverändert – der Export enthält sie nie. Importierte News-Beiträge gehören dann Ihnen.',
    'This site already has its own content (pages: %d, news: %d, collection items: %d, media: %d). A Kaleta export can be imported only into a new, empty site – install Kaleta again and choose “Start from an export”.' => 'Diese Website hat bereits eigene Inhalte (Seiten: %d, News: %d, Sammlungseinträge: %d, Medien: %d). Ein Kaleta-Export kann nur in eine neue, leere Website importiert werden – installieren Sie Kaleta erneut und wählen Sie „Mit einem Export starten“.',
    'Replace the content of this site with the export. A database backup is made first.' => 'Ersetzen Sie den Inhalt dieser Website durch den Export. Zuvor wird ein Datenbank-Backup erstellt.',
    'Import' => 'Importieren',
    'Copying files into media/: %s of %s. Keep this page open, it continues by itself.' => 'Dateien werden nach media/ kopiert: %s von %s. Lassen Sie diese Seite geöffnet, es geht von selbst weiter.',
    'The site has been imported.' => 'Die Website wurde importiert.',
    '%d skipped' => '%d übersprungen',
    'Files that could not be saved' => 'Dateien, die nicht gespeichert werden konnten',
    'The state before the import is in backup %s (Settings → Backups and updates). Check the site, then delete the export file – it is no longer needed.' => 'Der Zustand vor dem Import befindet sich im Backup %s (Einstellungen → Backups und Updates). Prüfen Sie die Website und löschen Sie dann die Exportdatei – sie wird nicht mehr benötigt.',
    'The state before the import is in backup %s (Settings → Backups and updates).' => 'Der Zustand vor dem Import befindet sich im Backup %s (Einstellungen → Backups und Updates).',
    'Confirm that the content of this site will be replaced.' => 'Bestätigen Sie, dass der Inhalt dieser Website ersetzt wird.',
    'The site already has its own content. A Kaleta export can be imported only into a new, empty site.' => 'Die Website hat bereits eigene Inhalte. Ein Kaleta-Export kann nur in eine neue, leere Website importiert werden.',
    'The file is not a Kaleta export.' => 'Die Datei ist kein Kaleta-Export.',
    'The file is not a Kaleta export (obsah.json is missing in the archive).' => 'Die Datei ist kein Kaleta-Export (obsah.json fehlt im Archiv).',
    'The export comes from a newer version of Kaleta – update this site first (Settings → Backups and updates).' => 'Der Export stammt aus einer neueren Version von Kaleta – aktualisieren Sie zuerst diese Website (Einstellungen → Backups und Updates).',
    'The PHP zip extension is missing on the server – upload obsah.json from the archive instead.' => 'Die PHP-Erweiterung zip fehlt auf dem Server – laden Sie stattdessen obsah.json aus dem Archiv hoch.',
    'Collection items' => 'Sammlungseinträge',
    'Shared classes' => 'Gemeinsame Klassen',
    'Menus' => 'Menüs',
    'News' => 'News',
    'Backup %s is ready, but the media could not be copied: %s' => 'Das Backup %s ist bereit, aber die Medien konnten nicht kopiert werden: %s',
    'A backup on the same server as the site does not help if you lose the hosting. Each new database backup therefore uploads itself elsewhere, and the media/ folder is copied to the same place – only new and changed files, in the background.' => 'Ein Backup auf demselben Server wie die Website hilft nicht, wenn Sie das Hosting verlieren. Deshalb lädt sich jedes neue Datenbank-Backup an einen anderen Ort hoch, und der Ordner media/ wird an dieselbe Stelle kopiert – nur neue und geänderte Dateien, im Hintergrund.',
    'Copy the media too' => 'Medien auch kopieren',
    'Uploaded images and files go to the folder media/ of the same target. A file deleted on the site stays in the copy.' => 'Hochgeladene Bilder und Dateien kommen in den Ordner media/ desselben Ziels. Eine auf der Website gelöschte Datei bleibt in der Kopie erhalten.',
    'Media: the last attempt %s failed: %s' => 'Medien: Der letzte Versuch %s ist fehlgeschlagen: %s',
    'Media: the copy is complete (checked %s).' => 'Medien: Die Kopie ist vollständig (geprüft %s).',
    'Media: %d files are still waiting – the copy continues in the background.' => 'Medien: %d Dateien warten noch – das Kopieren wird im Hintergrund fortgesetzt.',
    'Automatic backups' => 'Automatische Backups',
    'Every day something changed on the site, otherwise once a week – while an administrator works in the administration or cron runs. The last 10 backups are kept.' => 'An jedem Tag, an dem sich etwas auf der Website geändert hat, sonst einmal pro Woche – während ein Administrator in der Verwaltung arbeitet oder Cron läuft. Die letzten 10 Backups werden aufbewahrt.',
    'How to restore the site after losing the hosting' => 'So stellen Sie die Website nach dem Verlust des Hostings wieder her',
    'Install Kaleta on the new hosting with the same table prefix (ka_ unless you changed it) and any starter site.' => 'Installieren Sie Kaleta beim neuen Hosting mit demselben Tabellenpräfix (ka_, sofern Sie es nicht geändert haben) und einer beliebigen Startwebsite.',
    'Upload the latest database backup (kaleta-….sql.gz from your FTP or S3 copy, or a downloaded one) over FTP into storage/zalohy/.' => 'Laden Sie das neueste Datenbank-Backup (kaleta-….sql.gz aus Ihrer FTP- oder S3-Kopie oder ein heruntergeladenes) per FTP in storage/zalohy/ hoch.',
    'Copy the media/ folder from the same place into the root of the site.' => 'Kopieren Sie den Ordner media/ von derselben Stelle in das Hauptverzeichnis der Website.',
    'Here in Backups, click Restore at that backup. Then sign in with the accounts from the backup.' => 'Klicken Sie hier unter „Backups“ bei diesem Backup auf „Wiederherstellen“. Melden Sie sich danach mit den Konten aus dem Backup an.',
    'Moving a site to another Kaleta installation without accounts and secrets is simpler with Export of the whole site and Import from Kaleta (Import and export).' => 'Eine Website ohne Konten und Geheimnisse in eine andere Kaleta-Installation zu übertragen, ist mit „Export der gesamten Website“ und „Import aus Kaleta“ (Import und Export) einfacher.',
    '%d visits in the last 30 days ended with “page not found” – add a redirect to the right page.' => '%d Besuche der letzten 30 Tage endeten mit „Seite nicht gefunden“ – fügen Sie eine Weiterleitung auf die richtige Seite hinzu.',
    'An item points at a page that no longer exists.' => 'Ein Eintrag verweist auf eine Seite, die nicht mehr existiert.',
    'Component “%s”' => 'Komponente „%s“',
    'Item template of “%s”' => 'Eintragsvorlage von „%s“',
    'Item “%s” (%s)' => 'Eintrag „%s“ (%s)',
    'Menu “%s”' => 'Menü „%s“',
    'News item “%s”' => 'News-Beitrag „%s“',
    'No description for search engines and no longer text to take one from.' => 'Keine Beschreibung für Suchmaschinen und kein längerer Text, aus dem eine übernommen werden könnte.',
    'No description for search engines – they then make up their own from the page text.' => 'Keine Beschreibung für Suchmaschinen – sie erstellen dann selbst eine aus dem Text der Seite.',
    'Page “%s”' => 'Seite „%s“',
    'Pop-up “%s”' => 'Pop-up „%s“',
    'Site part “%s”' => 'Seitenbereich „%s“',
    'The item “%s” points at a hidden page – visitors do not see it in the menu.' => 'Der Eintrag „%s“ verweist auf eine verborgene Seite – Besucher sehen ihn nicht im Menü.',
    'The item “%s” points at a page in the trash.' => 'Der Eintrag „%s“ verweist auf eine Seite im Papierkorb.',
    'The link %s does not work (%s).' => 'Der Link %s funktioniert nicht (%s).',
    'The link %s leads to a page that does not exist.' => 'Der Link %s führt zu einer Seite, die nicht existiert.',
    'The title “%s” is used %d times – search engines cannot tell the pages apart.' => 'Der Titel „%s“ wird %d-mal verwendet – Suchmaschinen können die Seiten nicht voneinander unterscheiden.',
    'no response' => 'keine Antwort',
    'External links are checked in the background, one news item every five minutes. The audit runs each time you open this page.' => 'Externe Links werden im Hintergrund geprüft, ein News-Beitrag alle fünf Minuten. Das Audit läuft jedes Mal, wenn Sie diese Seite öffnen.',
    'Found %d things to fix. Each one links to where you fix it; Claude can go through them too (site_audit).' => '%d Punkte zu beheben gefunden. Jeder verlinkt dorthin, wo Sie ihn beheben; Claude kann sie ebenfalls durchgehen (site_audit).',
    'No problems found – links lead where they should, pages have descriptions and the builder checks pass.' => 'Keine Probleme gefunden – Links führen dorthin, wohin sie sollen, Seiten haben Beschreibungen und die Builder-Prüfungen sind bestanden.',
    'Show on the site' => 'Auf der Website anzeigen',
    'A three-letter code (EUR, CZK, USD). Without it the price is not passed on.' => 'Ein dreistelliger Code (EUR, CZK, USD). Ohne ihn wird der Preis nicht weitergegeben.',
    'Currency of the price' => 'Währung des Preises',
    'Items are' => 'Die Einträge sind',
    'Structured data for search engines' => 'Strukturierte Daten für Suchmaschinen',
    'Tell search engines what the items are. Item pages then carry the schema.org data; the name, address, description and image come from the item itself. Save new fields first – then you can pick them here.' => 'Teilen Sie Suchmaschinen mit, worum es sich bei den Einträgen handelt. Die Eintragsseiten enthalten dann die schema.org-Daten; Name, Adresse, Beschreibung und Bild stammen aus dem Eintrag selbst. Speichern Sie neue Felder zuerst – dann können Sie sie hier auswählen.',
    'nothing specific (no structured data)' => 'nichts Bestimmtes (keine strukturierten Daten)',
    '– none –' => '– keine –',
    'Item history (%s)' => 'Verlauf des Eintrags (%s)',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the first longer text field.' => 'Ein oder zwei Sätze für Suchergebnisse (bis zu 160 Zeichen). Leer = der Anfang des ersten längeren Textfelds.',
    'Publish the hidden item automatically at:' => 'Den verborgenen Eintrag automatisch veröffentlichen am:',
    'Restore this version of the item? The current version stays in the history.' => 'Diese Version des Eintrags wiederherstellen? Die aktuelle Version bleibt im Verlauf erhalten.',
    'The item page stays reachable, but it is left out of search engines, the sitemap, llms.txt and site search.' => 'Die Eintragsseite bleibt erreichbar, wird aber von Suchmaschinen, der Sitemap, llms.txt und der Website-Suche ausgenommen.',
    'empty = the first image field' => 'leer = das erste Bildfeld',
    'empty = the item name' => 'leer = der Name des Eintrags',
    'Missing descriptions' => 'Fehlende Beschreibungen',
    'Duplicate titles' => 'Doppelte Titel',
    'Buttons, images and headings' => 'Buttons, Bilder und Überschriften',
    'Frequent 404 errors' => 'Häufige 404-Fehler',
    'Product' => 'Produkt',
    'Question and answer' => 'Frage und Antwort',
    'Kind of service' => 'Art der Dienstleistung',
    'Area served' => 'Einzugsgebiet',
    'Price' => 'Preis',
    'Job title' => 'Berufsbezeichnung',
    'Profile link' => 'Profillink',
    'Brand' => 'Marke',
    'Product code (SKU)' => 'Produktcode (SKU)',
    'Start' => 'Beginn',
    'End' => 'Ende',
    'Place' => 'Ort',
    'Site audit' => 'Website-Audit',
    'The earlier version of the item is back; the one before it is in the history.' => 'Die frühere Version des Eintrags ist wieder da; die davor liegende befindet sich im Verlauf.',
    'The media are too large to pack in one go. Turn on the off-site copy (it copies the media bit by bit) or download the media/ folder over FTP.' => 'Die Medien sind zu groß, um sie auf einmal zu packen. Aktivieren Sie die externe Kopie (sie kopiert die Medien Stück für Stück) oder laden Sie den Ordner media/ per FTP herunter.',
    'The item is in the trash. Bring it back with restore_from_trash first.' => 'Der Eintrag liegt im Papierkorb. Holen Sie ihn zuerst mit restore_from_trash zurück.',
    'Addresses on your site that repeatedly ended with “page not found” this week: %d. Visitors came from an old link or a typo – send each one to the right page with a redirect, or ignore it.' => 'Adressen Ihrer Website, die diese Woche wiederholt mit „Seite nicht gefunden“ endeten: %d. Besucher kamen über einen alten Link oder einen Tippfehler – leiten Sie jede per Weiterleitung auf die richtige Seite um oder ignorieren Sie sie.',
    'Review the addresses' => 'Adressen prüfen',
    'Ignore all' => 'Alle ignorieren',
    'Ignore' => 'Ignorieren',
    '%d addresses ignored. A new address that visitors cannot find will show up again.' => '%d Adressen ignoriert. Eine neue Adresse, die Besucher nicht finden, erscheint wieder.',
    'Nothing to do – no address ended with “page not found” repeatedly in the last 60 days.' => 'Nichts zu tun – in den letzten 60 Tagen endete keine Adresse wiederholt mit „Seite nicht gefunden“.',
    'Visitors came to these addresses and found nothing – usually an old link from another site, a search engine or a typo. For each one choose:' => 'Besucher kamen auf diese Adressen und fanden nichts – meist ein alter Link von einer anderen Website, einer Suchmaschine oder ein Tippfehler. Wählen Sie für jede:',
    'Redirect – the old address leads to the page that replaced it (the form above is filled in, add the target).' => 'Weiterleitung – die alte Adresse führt zur Seite, die sie ersetzt hat (das Formular oben ist ausgefüllt, ergänzen Sie das Ziel).',
    'Ignore – nothing replaces it, or it is a bot probing for other systems. It will not come back.' => 'Ignorieren – nichts ersetzt sie, oder es ist ein Bot, der nach anderen Systemen sucht. Sie kommt nicht wieder.',
    'Ignore all these addresses? The warning on the start screen goes away until a new address appears.' => 'Alle diese Adressen ignorieren? Die Warnung auf der Startseite verschwindet, bis eine neue Adresse auftaucht.',
    'Security contact' => 'Sicherheitskontakt',
    'An e-mail address or an https:// page where people report security problems of this site. It is published at /.well-known/security.txt (RFC 9116); empty = no file.' => 'Eine E-Mail-Adresse oder eine https://-Seite, an die Personen Sicherheitsprobleme dieser Website melden. Sie wird unter /.well-known/security.txt veröffentlicht (RFC 9116); leer = keine Datei.',
    'What may Claude do?' => 'Was darf Claude tun?',
    'Everything your account may do' => 'Alles, was Ihr Konto darf',
    'Build, edit and publish with the permissions of your role (%s). The menu and the look still wait in the draft look until they are published.' => 'Erstellen, bearbeiten und veröffentlichen mit den Berechtigungen Ihrer Rolle (%s). Das Menü und das Erscheinungsbild warten bis zur Veröffentlichung weiterhin im Entwurf des Erscheinungsbilds.',
    'Drafts only' => 'Nur Entwürfe',
    'Claude builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'Claude baut Seiten, schreibt Nachrichtenentwürfe, fügt versteckte Sammlungseinträge hinzu, schlägt Ausnahmen von den Öffnungszeiten vor, sortiert Anfragen und bereitet Änderungen am Aussehen vor – Sie prüfen und veröffentlichen sie. Ohne Sie ändert sich auf der Live-Website nichts.',
    'Read only' => 'Nur lesen',
    'Claude reads pages, settings, the audit and the change log, and suggests changes. It changes nothing.' => 'Claude liest Seiten, Einstellungen, das Audit und das Änderungsprotokoll und schlägt Änderungen vor. Es ändert nichts.',
    'It will act with your account %s (%s) – never with more than your role allows.' => 'Claude handelt mit Ihrem Konto %s (%s) – nie mit mehr Rechten, als Ihre Rolle erlaubt.',
    'full access' => 'voller Zugriff',
    'drafts only' => 'nur Entwürfe',
    'read only' => 'nur lesen',
    'Made by:' => 'Erstellt von:',
    'people and Claude' => 'Personen und Claude',
    'people in the admin' => 'Personen in der Verwaltung',
    'Made by Claude through the connection %s' => 'Von Claude über die Anbindung %s erstellt',
    'Connect Claude' => 'Claude anbinden',
    'Build and edit the site by talking to Claude. In the Claude app, add a custom connector with your site address followed by /mcp – My account shows the exact address.' => 'Bauen und bearbeiten Sie die Website im Gespräch mit Claude. Fügen Sie in der Claude-App einen benutzerdefinierten Connector mit Ihrer Website-Adresse gefolgt von /mcp hinzu – unter „Mein Konto“ sehen Sie die genaue Adresse.',
    'Claude sends you here to sign in. You choose what it may do: everything your account may, only save drafts, or only read.' => 'Claude leitet Sie zur Anmeldung hierher weiter. Sie legen fest, was es darf: alles, was Ihr Konto darf, nur Entwürfe speichern oder nur lesen.',
    'The connector needs the site on HTTPS. In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'Der Connector benötigt die Website über HTTPS. In einem Unterordner findet die Claude-App die Anmeldung selbst; für ein Tool, das dies nicht kann, verwenden Sie ein persönliches Token.',
    'Instructions for Claude' => 'Anweisungen für Claude',
    'e.g. We address customers informally. Say “renovation”, never “reconstruction”. Keep headings short. Always offer a free visit.' => 'z. B. Wir sprechen Kunden mit „Sie“ an. Sagen Sie „Renovierung“, nie „Rekonstruktion“. Überschriften kurz halten. Immer einen kostenlosen Besuch anbieten.',
    'Brand voice, words to use or avoid, house rules. Every Claude connection gets them when it connects, and they are its resource kaleta://instructions.' => 'Markenstimme, zu verwendende oder zu meidende Wörter, Hausregeln. Jede Claude-Anbindung erhält sie beim Verbinden, und sie sind deren Ressource kaleta://instructions.',
    'Remember where leads came from' => 'Merken, woher Leads kamen',
    'The first page of a visit, its campaign and the site that sent the visitor go with enquiries and newsletter sign-ups (Statistics → Campaigns and pages). Only for visitors who allow marketing in the cookie bar – turning it on adds that choice to the bar.' => 'Die erste Seite eines Besuchs, seine Kampagne und die Website, die den Besucher geschickt hat, werden zu Anfragen und Newsletter-Anmeldungen gespeichert (Statistik → Kampagnen und Seiten). Nur für Besucher, die im Cookie-Banner Marketing erlauben – beim Einschalten wird diese Auswahl dem Banner hinzugefügt.',
    'Leads (enquiries and sign-ups)' => 'Leads (Anfragen und Anmeldungen)',
    'Visits that became a lead' => 'Besuche, die zu einem Lead wurden',
    '%s leads' => '%s Leads',
    'Pages that bring leads' => 'Seiten, die Leads bringen',
    'Enquiries / sign-ups' => 'Anfragen / Anmeldungen',
    'Conversion' => 'Conversion',
    'Campaigns' => 'Kampagnen',
    'Campaign (source / medium / name)' => 'Kampagne (Quelle / Medium / Name)',
    'No visits from links with utm parameters yet.' => 'Noch keine Besuche über Links mit utm-Parametern.',
    'First pages of visits that brought a lead' => 'Erste Seiten von Besuchen, die einen Lead gebracht haben',
    'Known only for visitors who allowed marketing cookies in the cookie bar.' => 'Nur bei Besuchern bekannt, die im Cookie-Banner Marketing-Cookies erlaubt haben.',
    'Site' => 'Website',
    'Devices' => 'Geräte',
    'Device' => 'Gerät',
    'Computer' => 'Computer',
    'The site has no pop-ups.' => 'Die Website hat keine Pop-ups.',
    'News item' => 'News-Beitrag',
    'Pop-up counters run since the pop-up was made or reset. Claude reads the same report with get_stats.' => 'Die Pop-up-Zähler laufen seit der Erstellung oder dem Zurücksetzen des Pop-ups. Claude liest denselben Bericht mit get_stats.',
    'inactive' => 'inaktiv',
