    'Paste the address of a Calendly or Google booking page, a Google, Microsoft, Tally, Typeform or Airtable form, or a Spotify or SoundCloud track.' => 'Fügen Sie die Adresse einer Calendly- oder Google-Buchungsseite, eines Google-, Microsoft-, Tally-, Typeform- oder Airtable-Formulars oder eines Spotify- oder SoundCloud-Titels ein.',
    'Embed' => 'Einbettung',
    'A booking calendar, form or player from Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify or SoundCloud – loads after a click.' => 'Ein Buchungskalender, Formular oder Player von Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify oder SoundCloud – lädt nach einem Klick.',
