    'Player' => 'Player',
    'Code in the head of this page' => 'Code im Head dieser Seite',
    'Only for this page, after the code for the whole site (Settings → Analytics) – e.g. the conversion tag of a landing page. Mind the cookie consent: code that tracks visitors belongs in the marketing code.' => 'Nur für diese Seite, nach dem Code für die gesamte Website (Einstellungen → Analyse) – z. B. das Conversion-Tag einer Landingpage. Beachten Sie die Cookie-Einwilligung: Code, der Besucher verfolgt, gehört in den Marketing-Code.',
    'Code in the head of a page can be set only by an administrator, through a connection with full access.' => 'Code im Head einer Seite kann nur ein Administrator über eine Anbindung mit vollem Zugriff festlegen.',
    'Accessibility' => 'Barrierefreiheit',
    ' (dark mode)' => ' (Dunkelmodus)',
    '%s has a contrast of %s : 1 – text needs at least 4.5 : 1.' => '%s hat ein Kontrastverhältnis von %s : 1 – Text benötigt mindestens 4,5 : 1.',
    'The whole site' => 'Die gesamte Website',
    'No accessibility statement – the European Accessibility Act expects a service to say how accessible it is and whom to contact about barriers. Add a page such as /accessibility.' => 'Keine Erklärung zur Barrierefreiheit – der European Accessibility Act erwartet, dass ein Dienst angibt, wie barrierefrei er ist und an wen man sich bei Barrieren wenden kann. Fügen Sie eine Seite wie /accessibility hinzu.',
    'The button “%s” does not say what it does – screen readers read buttons and links on their own.' => 'Der Button „%s“ sagt nicht, was er bewirkt – Screenreader lesen Buttons und Links einzeln vor.',
    'An image in the text has no description for blind visitors (alt).' => 'Ein Bild im Text hat keine Beschreibung für blinde Besucher (alt).',
    'A link has no text – a screen reader has nothing to read.' => 'Ein Link hat keinen Text – ein Screenreader hat nichts vorzulesen.',
    'The link “%s” does not say where it leads – screen readers read links on their own.' => 'Der Link „%s“ sagt nicht, wohin er führt – Screenreader lesen Links einzeln vor.',
    'A table has no header cells (th) – screen readers cannot tell what the columns mean.' => 'Eine Tabelle hat keine Kopfzellen (th) – Screenreader können nicht erkennen, was die Spalten bedeuten.',
    'An embedded frame (iframe) has no title.' => 'Ein eingebetteter Frame (iframe) hat keinen Titel.',
