    'Edits pages, news and collection items, answers enquiries, sees the statistics and asks Claude for changes – the look, settings and users stay with the agency.' => 'Bearbeitet Seiten, Neuigkeiten und Sammlungseinträge, beantwortet Anfragen, sieht die Statistik und gibt Claude Aufträge – Design, Einstellungen und Benutzer bleiben bei der Agentur.',
    'Writer' => 'Redakteur',
    'Writes news for someone else to publish.' => 'Schreibt Neuigkeiten, die jemand anderes veröffentlicht.',
    'Enquiries only' => 'Nur Anfragen',
    'Handles enquiries from the site forms and the newsletter subscribers, and asks Claude for changes.' => 'Bearbeitet Anfragen aus den Formularen der Website und die Newsletter-Abonnenten und gibt Claude Aufträge.',
    'Built and looked after by' => 'Erstellt und betreut von',
    'The agency or freelancer who looks after the site. The sign-in screen and the foot of the admin show whom to ask for help.' => 'Die Agentur oder der Freelancer, die die Website betreuen. Die Anmeldeseite und der Fuß der Verwaltung zeigen, an wen man sich bei Fragen wendet.',
    'E-mail for help' => 'E-Mail für Hilfe',
    'Phone for help' => 'Telefon für Hilfe',
    'A path from Media, e.g. media/2026/10/agency.svg – click the file in Media to open it, its address starts with media/.' => 'Ein Pfad aus den Medien, z. B. media/2026/10/agency.svg – klicken Sie in den Medien auf die Datei, um sie zu öffnen; ihre Adresse beginnt mit media/.',
    'Website by %s' => 'Website von %s',
    'help: %s' => 'Hilfe: %s',
    'Before handing over' => 'Vor der Übergabe',
    'No site e-mail: enquiries and password resets have nowhere to go.' => 'Keine E-Mail-Adresse der Website: Anfragen und das Zurücksetzen von Passwörtern kommen nirgends an.',
    'E-mail goes out through the host’s mail() – set an SMTP server so enquiries and newsletters do not end up in spam.' => 'E-Mails gehen über mail() des Hostings hinaus – richten Sie einen SMTP-Server ein, damit Anfragen und Newsletter nicht im Spam landen.',
    'Backups stay on the same server – add an off-site copy (FTPS or S3) in case the hosting is lost.' => 'Sicherungen bleiben auf demselben Server – fügen Sie eine externe Kopie hinzu (FTPS oder S3), falls das Hosting verloren geht.',
    'Company details are missing – the footer, the imprint and search engines use them.' => 'Die Unternehmensangaben fehlen – die Fußzeile, das Impressum und Suchmaschinen verwenden sie.',
    'Search engines are blocked – switch indexing on when the site goes live.' => 'Suchmaschinen sind gesperrt – schalten Sie die Indexierung ein, wenn die Website live geht.',
    'No site icon (favicon) – browsers and phones show a blank one.' => 'Kein Website-Symbol (Favicon) – Browser und Telefone zeigen ein leeres an.',
    'Analytics or marketing codes run without a cookie bar – visitors in the EU must consent first.' => 'Analyse- oder Marketing-Codes laufen ohne Cookie-Leiste – Besucher in der EU müssen zuerst einwilligen.',
    'No security contact – add who takes reports of security problems (published as security.txt).' => 'Kein Sicherheitskontakt – geben Sie an, wer Meldungen zu Sicherheitsproblemen entgegennimmt (veröffentlicht als security.txt).',
    'The administrator %s signs in without two-step sign-in or a passkey.' => 'Der Administrator %s meldet sich ohne Zwei-Schritt-Anmeldung oder Passkey an.',
    'The client has no account of their own yet – create one with the Client role (Users → Roles).' => 'Der Kunde hat noch kein eigenes Konto – legen Sie eines mit der Rolle Kunde an (Benutzer → Rollen).',
    'Your contact is not set – the client will not see whom to ask (Settings → General → Built and looked after by).' => 'Ihr Kontakt ist nicht eingetragen – der Kunde sieht nicht, an wen er sich wenden kann (Einstellungen → Allgemein → Erstellt und betreut von).',
    'Background tasks have never run – newsletters are sent only while they do. Add the cron line from System status.' => 'Hintergrundaufgaben sind noch nie gelaufen – Newsletter werden nur versendet, während sie laufen. Fügen Sie die Cron-Zeile aus dem Systemstatus hinzu.',
    'How to use this' => 'So funktioniert es',
    'guide, opens in a new tab' => 'Anleitung, öffnet sich in einem neuen Tab',
    'Could not connect to the SMTP server %s. Check the address, port and encryption; some hosts block outgoing SMTP.' => 'Keine Verbindung zum SMTP-Server %s. Prüfen Sie Adresse, Port und Verschlüsselung; manche Hoster sperren ausgehendes SMTP.',
    'The SMTP server refused the sign-in – check the user name and password (Gmail and Seznam need an app password).' => 'Der SMTP-Server hat die Anmeldung abgelehnt – prüfen Sie Benutzername und Passwort (Gmail und Seznam brauchen ein App-Passwort).',
    'SMTP server reply to %s: %s' => 'Antwort des SMTP-Servers auf %s: %s',
    'A scheduled newsletter can be changed only by someone who may send newsletters – unschedule it first.' => 'Einen geplanten Newsletter kann nur ändern, wer Newsletter versenden darf – heben Sie zuerst die Planung auf.',
    'Without the extra spam check (CAPTCHA from Settings → Privacy and cookies)' => 'Ohne zusätzliche Spamprüfung (CAPTCHA aus Einstellungen → Datenschutz und Cookies)',
    'Spam check for forms' => 'Spamprüfung für Formulare',
    'Forms are protected without one: a signed time, a hidden trap field and a limit per address. Add a CAPTCHA only if spam still gets through. The provider receives the visitor’s address and browser details – name it in your privacy policy.' => 'Formulare sind auch ohne sie geschützt: eine signierte Zeit, ein verstecktes Fallenfeld und ein Limit pro Adresse. Fügen Sie ein CAPTCHA nur hinzu, wenn trotzdem Spam durchkommt. Der Anbieter erhält die Adresse und Browserdaten des Besuchers – nennen Sie ihn in Ihrer Datenschutzerklärung.',
    'Extra spam check' => 'Zusätzliche Spamprüfung',
    'none – the built-in protection only' => 'keine – nur der integrierte Schutz',
    'hCaptcha and Cloudflare Turnstile suit EU sites; reCAPTCHA v3 is invisible and scores every visit.' => 'hCaptcha und Cloudflare Turnstile passen zu Websites in der EU; reCAPTCHA v3 ist unsichtbar und bewertet jeden Besuch.',
    'Site key' => 'Website-Schlüssel',
    'From the provider’s dashboard, for this site’s domain.' => 'Aus dem Dashboard des Anbieters, für die Domain dieser Website.',
    'Secret key' => 'Geheimer Schlüssel',
    'the key is saved – enter a new one only to change it' => 'der Schlüssel ist gespeichert – geben Sie nur zum Ändern einen neuen ein',
    'Stays on your site; Claude cannot read it.' => 'Bleibt auf Ihrer Website; Claude kann ihn nicht lesen.',
    'Remove the saved key' => 'Gespeicherten Schlüssel entfernen',
    'Accept forms when the provider is down' => 'Formulare annehmen, wenn der Anbieter ausfällt',
    'The built-in protection still applies. Off = such forms are refused until the provider answers again.' => 'Der integrierte Schutz gilt weiterhin. Aus = solche Formulare werden abgelehnt, bis der Anbieter wieder antwortet.',
    'The container ID in the form GTM-XXXXXXX. Consent mode is built in: with the built-in cookie bar the container starts after the visitor allows analytics or marketing.' => 'Die Container-ID in der Form GTM-XXXXXXX. Der Einwilligungsmodus ist integriert: Mit dem integrierten Cookie-Banner startet der Container, sobald der Besucher Analyse oder Marketing erlaubt.',
    'Google Analytics is set here and probably also in your Tag Manager container – visits would be counted twice. Keep it in one place.' => 'Google Analytics ist hier und vermutlich auch in Ihrem Tag-Manager-Container eingerichtet – Besuche würden doppelt gezählt. Behalten Sie es an einer Stelle.',
    'Kaleta sends these events to the data layer for your tags: generate_lead (a form was sent), sign_up (newsletter), popup_conversion, click_phone, click_email and file_download.' => 'Kaleta sendet diese Ereignisse für Ihre Tags in den Data Layer: generate_lead (Formular gesendet), sign_up (Newsletter), popup_conversion, click_phone, click_email und file_download.',
    'Download a container template with these triggers' => 'Container-Vorlage mit diesen Triggern herunterladen',
    'This is switched off in the public demo. Install Kaleta to try it.' => 'In der öffentlichen Demo ist das ausgeschaltet. Installieren Sie Kaleta, um es auszuprobieren.',
    'This is the public demo of Kaleta. Sign in as %s with the password %s. Everything you change disappears at the next hourly reset.' => 'Das ist die öffentliche Demo von Kaleta. Melden Sie sich als %s mit dem Passwort %s an. Alles, was Sie ändern, verschwindet beim nächsten stündlichen Zurücksetzen.',
    'Public demo: everything you change here is reset in %s minutes. E-mail, imports, updates, users and the Claude connection are switched off.' => 'Öffentliche Demo: Alles, was Sie hier ändern, wird in %s Minuten zurückgesetzt. E-Mail, Importe, Updates, Benutzer und die Claude-Anbindung sind ausgeschaltet.',
    'Sending e-mail is switched off in the public demo.' => 'In der öffentlichen Demo werden keine E-Mails versendet.',
    'Downloading from other sites is switched off in the public demo.' => 'In der öffentlichen Demo wird nichts von anderen Websites heruntergeladen.',
    'Import from a website' => 'Import von einer Website',
    'Enter the address of a site on any platform – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal or WordPress without an export. Its pages become builder pages with their images, and the old addresses redirect to the new ones. The pages stay hidden until you check and publish them; the design is not copied – the pages take this site’s look.' => 'Geben Sie die Adresse einer Website auf einer beliebigen Plattform ein – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal oder WordPress ohne Export. Ihre Seiten werden mit ihren Bildern zu Builder-Seiten, und die alten Adressen leiten auf die neuen weiter. Die Seiten bleiben verborgen, bis Sie sie prüfen und veröffentlichen; das Design wird nicht kopiert – die Seiten übernehmen das Aussehen dieser Website.',
    'This server cannot download from other sites (both curl and allow_url_fopen are missing, or the GD extension).' => 'Dieser Server kann nicht von anderen Websites herunterladen (curl und allow_url_fopen fehlen beide, oder die GD-Erweiterung).',
    'Address of the site' => 'Adresse der Website',
    'Kaleta reads the sitemap, or follows the site’s links when there is none – at most %s pages.' => 'Kaleta liest die Sitemap oder folgt, wenn es keine gibt, den Links der Website – höchstens %s Seiten.',
    'the main language' => 'die Hauptsprache',
    'Download the images into Media' => 'Bilder in die Medien herunterladen',
    'Redirect the old addresses to the new pages' => 'Alte Adressen auf die neuen Seiten weiterleiten',
    'Import blog posts as news (addresses like /blog/…, or with a publication date)' => 'Blogbeiträge als News importieren (Adressen wie /blog/… oder mit Veröffentlichungsdatum)',
    'Find the pages' => 'Seiten finden',
    'finding pages' => 'Seiten werden gesucht',
    'Remove from the list' => 'Aus der Liste entfernen',
    'Enter the address of the site, e.g. https://www.example.com.' => 'Geben Sie die Adresse der Website ein, z. B. https://www.example.com.',
    'The import does not exist any more.' => 'Dieser Import existiert nicht mehr.',
    'Site: %s' => 'Website: %s',
    'Finding pages: %s found so far. Keep this page open, it continues by itself.' => 'Seiten werden gesucht: bisher %s gefunden. Lassen Sie diese Seite offen, es geht von selbst weiter.',
    'No pages were found. Check the address – the site has to be reachable from this server.' => 'Es wurden keine Seiten gefunden. Prüfen Sie die Adresse – die Website muss von diesem Server aus erreichbar sein.',
    '%s pages found. They will be imported as hidden pages; nothing changes for visitors until you publish them.' => '%s Seiten gefunden. Sie werden als verborgene Seiten importiert; für Besucher ändert sich nichts, bis Sie sie veröffentlichen.',
    '… and %s more.' => '… und %s weitere.',
    'Import %s pages' => '%s Seiten importieren',
    'Importing: %s of %s pages. Keep this page open, it continues by itself.' => 'Import: %s von %s Seiten. Lassen Sie diese Seite offen, es geht von selbst weiter.',
    'The import is finished. The pages are hidden until you check and publish them.' => 'Der Import ist abgeschlossen. Die Seiten bleiben verborgen, bis Sie sie prüfen und veröffentlichen.',
    'Images in Media' => 'Bilder in den Medien',
    '%s pages could not be imported' => '%s Seiten konnten nicht importiert werden',
    'Next: check the pages, put the ones you keep into the menu and publish them. Claude can match their look to the design system and tidy the texts through the connection.' => 'Weiter: Prüfen Sie die Seiten, nehmen Sie die behaltenen ins Menü auf und veröffentlichen Sie sie. Claude kann über die Anbindung ihr Aussehen ans Designsystem anpassen und die Texte überarbeiten.',
    'Show pages' => 'Seiten anzeigen',
    'The page could not be downloaded.' => 'Die Seite konnte nicht heruntergeladen werden.',
    'The page has no content to import.' => 'Die Seite hat keinen Inhalt zum Importieren.',
    'Address of the old site' => 'Adresse der alten Website',
    'Before you point the domain to this site, check the old site against it: every old address must lead somewhere, and no page may lose its search engine description, its form or most of its images. Nothing is changed – the check only reads.' => 'Bevor Sie die Domain auf diese Website richten, vergleichen Sie die alte Website damit: Jede alte Adresse muss irgendwohin führen, und keine Seite darf ihre Beschreibung für Suchmaschinen, ihr Formular oder die meisten ihrer Bilder verlieren. Es wird nichts geändert – die Prüfung liest nur.',
    'Check the move' => 'Umzug prüfen',
    'Check the move before going live' => 'Umzug vor dem Livegang prüfen',
    'Checking: %s of %s addresses. Keep this page open, it continues by itself.' => 'Prüfe: %s von %s Adressen. Lassen Sie diese Seite offen, es geht von selbst weiter.',
    'Everything moved: every old address leads to a published page and nothing was lost.' => 'Alles ist umgezogen: Jede alte Adresse führt zu einer veröffentlichten Seite, und nichts ist verloren gegangen.',
    'Finding the pages of the old site. Keep this page open, it continues by itself.' => 'Suche die Seiten der alten Website. Lassen Sie diese Seite offen, es geht von selbst weiter.',
    'Fix what is missing – redirects in Redirects, descriptions and forms on the pages – and check again. Claude can do it through the connection (migration_report).' => 'Ergänzen Sie, was fehlt – Weiterleitungen unter Weiterleitungen, Beschreibungen und Formulare auf den Seiten – und prüfen Sie erneut. Claude kann das über die Anbindung erledigen (migration_report).',
    'Missing' => 'Fehlt',
    'Nearly ready: check the warnings below.' => 'Fast fertig: Prüfen Sie die Hinweise unten.',
    'Not published yet' => 'Noch nicht veröffentlicht',
    'Not ready to go live: %s problems would cost visitors or search engines something.' => 'Noch nicht bereit für den Livegang: %s Probleme würden Besucher oder Suchmaschinen etwas kosten.',
    'Nothing at this address and no redirect – it will end in 404.' => 'Unter dieser Adresse gibt es nichts und keine Weiterleitung – sie endet mit 404.',
    'Old addresses' => 'Alte Adressen',
    'Old site: %s' => 'Alte Website: %s',
    'On this site' => 'Auf dieser Website',
    'Problems' => 'Probleme',
    'Redirected' => 'Weitergeleitet',
    'Redirected more than once – point the redirect straight at the final page.' => 'Mehrfach weitergeleitet – richten Sie die Weiterleitung direkt auf die Zielseite.',
    'Redirected to another site.' => 'Auf eine andere Website weitergeleitet.',
    'Same address' => 'Gleiche Adresse',
    'The Redirects feature is off: no redirect from an old address works.' => 'Die Funktion Weiterleitungen ist ausgeschaltet: Keine Weiterleitung von einer alten Adresse funktioniert.',
    'The new page has less than half of the old page’s images.' => 'Die neue Seite hat weniger als die Hälfte der Bilder der alten Seite.',
    'The old page could not be read, so only the address was checked.' => 'Die alte Seite ließ sich nicht lesen, daher wurde nur die Adresse geprüft.',
    'The old page had a form, the new one has none.' => 'Die alte Seite hatte ein Formular, die neue hat keines.',
    'The old page had a search engine description, the new one has none.' => 'Die alte Seite hatte eine Beschreibung für Suchmaschinen, die neue hat keine.',
    'The page is here but not published yet.' => 'Die Seite ist da, aber noch nicht veröffentlicht.',
    'The report does not exist any more.' => 'Die Prüfung existiert nicht mehr.',
    'check in progress' => 'Prüfung läuft',
    'Note' => 'Hinweis',
    'slide in from the left' => 'von links einfahren',
    'slide in from the right' => 'von rechts einfahren',
    'from a blur' => 'aus der Unschärfe',
    'Motion while scrolling' => 'Bewegung beim Scrollen',
    'parallax (slower than the page)' => 'Parallaxe (langsamer als die Seite)',
    'stronger parallax' => 'stärkere Parallaxe',
    'slight rotation' => 'leichte Drehung',
    'grows into view' => 'wächst ins Bild',
    'Effect on hover' => 'Effekt beim Überfahren',
    'lift with a shadow' => 'mit Schatten anheben',
    'grow slightly' => 'leicht vergrößern',
    'nudge to the side' => 'zur Seite schieben',
    'fade a little' => 'etwas transparenter',
    'OK' => 'In Ordnung',
    'SEO plugin %s: %s custom titles, %s meta descriptions, %s noindex – they go into the SEO fields of the news items and pages. A title made only of the plugin’s variables is skipped; the site builds it itself.' => 'SEO-Plugin %s: %s eigene Titel, %s Meta-Beschreibungen, %s noindex – sie wandern in die SEO-Felder der Nachrichten und Seiten. Ein Titel nur aus Variablen des Plugins wird übersprungen; die Website bildet ihn selbst.',
    'Canonical URLs (%s) are not transferred.' => 'Kanonische URLs (%s) werden nicht übernommen.',
    'Redirects managed by SEO plugins (SmartCrawl, Yoast SEO, Rank Math) are not part of the export – they come over separately.' => 'Weiterleitungen aus SEO-Plugins (SmartCrawl, Yoast SEO, Rank Math) sind nicht Teil des Exports – sie werden separat übernommen.',
    'With an SEO title, description or noindex from a plugin' => 'Mit SEO-Titel, Beschreibung oder noindex aus einem Plugin',
    'Custom post type “%s”: %s items become a collection with item pages at /%s/…, with the fields %s.' => 'Eigener Inhaltstyp „%s“: %s Einträge werden zu einer Sammlung mit Eintragsseiten unter /%s/…, mit den Feldern %s.',
    'Left out (repeaters, galleries or relationships – Claude can move them by hand): %s.' => 'Ausgelassen (Repeater, Galerien oder Beziehungen – Claude kann sie von Hand übernehmen): %s.',
    'custom post types as collections (%s)' => 'eigene Inhaltstypen als Sammlungen (%s)',
    'Collection items (custom post types), in %s new collections' => 'Sammlungseinträge (eigene Inhaltstypen), in %s neuen Sammlungen',
    'Excerpt' => 'Auszug',
    'none' => 'keine',
    'Header on scroll (header part only)' => 'Kopfzeile beim Scrollen (nur Website-Teil Kopfzeile)',
    'transparent at the top, solid after scrolling' => 'oben transparent, nach dem Scrollen gefüllt',
    'smaller after scrolling' => 'nach dem Scrollen kleiner',
    'transparent at the top and smaller after scrolling' => 'oben transparent und nach dem Scrollen kleiner',
    'Text colour while the header is transparent' => 'Textfarbe, solange die Kopfzeile transparent ist',
    'as normal' => 'wie sonst',
    'light (over a dark photo)' => 'hell (über einem dunklen Foto)',
    'dark (over a light photo)' => 'dunkel (über einem hellen Foto)',
    'An icon shows before the text. The description and group columns (a group inside a submenu with its own items) appear in a mega menu – the Navigation element with “Submenu as a wide panel”.' => 'Ein Symbol erscheint vor dem Text. Die Beschreibung und Gruppenspalten (eine Gruppe innerhalb eines Untermenüs mit eigenen Einträgen) erscheinen im Mega-Menü – Element Navigation mit „Untermenü als breites Panel“.',
    'Description (mega menu)' => 'Beschreibung (Mega-Menü)',
    'Into the group above (a column of the mega menu)' => 'In die Gruppe darüber (eine Spalte des Mega-Menüs)',
    '%s (default language)' => '%s (Standardsprache)',
    'Nothing to copy.' => 'Nichts zu kopieren.',
    'The clipboard does not contain Kaleta elements.' => 'Die Zwischenablage enthält keine Kaleta-Elemente.',
    'None of the elements could be inserted.' => 'Keines der Elemente konnte eingefügt werden.',
    '%d images still load from %s – replace them with files from this site’s Media.' => '%d Bilder werden weiterhin von %s geladen – ersetzen Sie sie durch Dateien aus den Medien dieser Website.',
    '%d images were left out – the media of the other site are not available here.' => '%d Bilder wurden ausgelassen – die Medien der anderen Website sind hier nicht verfügbar.',
    '%d h' => '%d Std.',
    '%d min' => '%d Min.',
    '%s ends with error %d' => '%s endet mit Fehler %d',
    '%s failed %d× in a row: %s' => '%s ist %d× nacheinander fehlgeschlagen: %s',
    '%s: %d problem(s) on the site' => '%s: %d Problem(e) auf der Website',
    '/%s was requested %d times and there is no page or redirect.' => '/%s wurde %d-mal aufgerufen, aber dort gibt es weder eine Seite noch eine Weiterleitung.',
    'Alert e-mails' => 'Warn-E-Mails',
    'Alerts' => 'Warnungen',
    'Automatic backup %s' => 'Automatisches Backup %s',
    'Background jobs' => 'Hintergrundaufgaben',
    'Checking links' => 'Links prüfen',
    'Deleting old personal data and events' => 'Alte personenbezogene Daten und Ereignisse löschen',
    'Details are in System status:' => 'Details finden Sie unter Systemstatus:',
    'E-mail “%s” could not be sent: %s' => 'Die E-Mail „%s“ konnte nicht gesendet werden: %s',
    'Form “%s” sent from %s' => 'Formular „%s“ gesendet von %s',
    'Installing version %s failed: %s' => 'Die Installation von Version %s ist fehlgeschlagen: %s',
    'Job' => 'Aufgabe',
    'Kaleta noticed something that needs your attention:' => 'Kaleta ist etwas aufgefallen, das Ihre Aufmerksamkeit braucht:',
    'Last run' => 'Zuletzt',
    'Off-site copy of the media' => 'Kopie der Medien außerhalb des Servers',
    'Problems in the last 7 days' => 'Probleme der letzten 7 Tage',
    'Published: %s' => 'Veröffentlicht: %s',
    'Runs' => 'Läuft',
    'Scheduled publishing and announcements' => 'Geplantes Veröffentlichen und Benachrichtigungen',
    'Sending e-mail' => 'E-Mails senden',
    'Sending newsletters' => 'Newsletter senden',
    'Subscribers to the mailing service' => 'Abonnenten an den Mailing-Dienst',
    'The automatic backup failed: %s' => 'Das automatische Backup ist fehlgeschlagen: %s',
    'The background job “%s” failed %d times in a row: %s' => 'Die Hintergrundaufgabe „%s“ ist %d-mal nacheinander fehlgeschlagen: %s',
    'The background job “%s” works again.' => 'Die Hintergrundaufgabe „%s“ funktioniert wieder.',
    'The look was published: %s' => 'Das Aussehen wurde veröffentlicht: %s',
    'The off-site copy of the backup failed: %s' => 'Die Kopie des Backups außerhalb des Servers ist fehlgeschlagen: %s',
    'Version %s did not work (%s), so the site went back to version %s.' => 'Version %s funktionierte nicht (%s), daher ist die Website zu Version %s zurückgekehrt.',
    'Version %s was installed (from %s).' => 'Version %s wurde installiert (von %s).',
    'Version %s was installed but the site did not work afterwards (%s). The website files have been returned to their state before the update.' => 'Version %s wurde installiert, aber die Website funktionierte danach nicht (%s). Die Dateien der Website wurden auf den Stand vor dem Update zurückgesetzt.',
    'Webhook %s could not be delivered: %s' => 'Webhook %s konnte nicht zugestellt werden: %s',
    'Webhook deliveries' => 'Webhook-Zustellungen',
    'When a backup, an update, e-mail, a webhook or a background job fails, the site sends one e-mail – at most one an hour, with everything that happened.' => 'Wenn ein Backup, ein Update, eine E-Mail, ein Webhook oder eine Hintergrundaufgabe fehlschlägt, sendet die Website eine E-Mail – höchstens eine pro Stunde, mit allem, was passiert ist.',
    'You get at most one such e-mail an hour. Change the address or switch the alerts off in System status.' => 'Sie erhalten höchstens eine solche E-Mail pro Stunde. Die Adresse ändern oder die Warnungen ausschalten können Sie im Systemstatus.',
    'cron and visits' => 'Cron und Besuche',
    'every %s' => 'alle %s',
    'every job worked the last time it ran' => 'jede Aufgabe hat beim letzten Lauf funktioniert',
    'failed %d×' => '%d× fehlgeschlagen',
    'not run yet' => 'noch nicht gelaufen',
    'ok' => 'in Ordnung',
    'only from cron' => 'nur über Cron',
    'the administration' => 'die Administration',
    'the home page' => 'die Startseite',
    'the site does not start' => 'die Website startet nicht',
    'Send alert e-mails' => 'Warn-E-Mails senden',
    'Send them to' => 'Senden an',
    'Empty = the site e-mail (Settings → General).' => 'Leer = die E-Mail-Adresse der Website (Einstellungen → Allgemein).',
    '%s was blocked for %d hours after probing for other systems (%s).' => '%s wurde für %d Stunden gesperrt, weil sie Adressen anderer Systeme ausprobiert hat (%s).',
    '0 = no limit. 120 is plenty for people; it stops aggressive scrapers.' => '0 = keine Grenze. 120 reicht Menschen; es stoppt aggressive Scraper.',
    'An address that asks for /wp-login.php, /.env and similar addresses of other systems 5 times in an hour is blocked for 24 hours.' => 'Eine Adresse, die innerhalb einer Stunde fünfmal /wp-login.php, /.env und ähnliche Adressen anderer Systeme abfragt, wird für 24 Stunden gesperrt.',
    'Block probing' => 'Ausprobieren sperren',
    'Blocked addresses and networks' => 'Gesperrte Adressen und Netze',
    'Blocked countries' => 'Gesperrte Länder',
    'Blocked for a while' => 'Vorübergehend gesperrt',
    'Country: %s.' => 'Land: %s.',
    'Firewall on' => 'Firewall eingeschaltet',
    'No address is blocked right now.' => 'Derzeit ist keine Adresse gesperrt.',
    'Nothing refused yet.' => 'Noch nichts abgewiesen.',
    'One per line, e.g. 203.0.113.7 or 198.51.100.0/24; a comment after #.' => 'Eine pro Zeile, z. B. 203.0.113.7 oder 198.51.100.0/24; ein Kommentar nach #.',
    'Refused requests' => 'Abgewiesene Anfragen',
    'Requests per minute from one address' => 'Anfragen pro Minute von einer Adresse',
    'The address is no longer blocked.' => 'Die Adresse ist nicht mehr gesperrt.',
    'The country of visitors is not known here – blocking countries works only behind Cloudflare or when the hosting sends the country.' => 'Das Land der Besucher ist hier nicht bekannt – Länder sperren funktioniert nur hinter Cloudflare oder wenn das Hosting das Land mitsendet.',
    'The firewall guards the public site and the Claude connection – never the administration, so you cannot lock yourself out. Addresses of your local network are never blocked.' => 'Die Firewall schützt die öffentliche Website und die Claude-Anbindung – nie die Administration, Sie können sich also nicht aussperren. Adressen Ihres lokalen Netzes werden nie gesperrt.',
    'The last 50; the log keeps 30 days.' => 'Die letzten 50; das Protokoll wird 30 Tage aufbewahrt.',
    'The site runs behind' => 'Die Website läuft hinter',
    'These lines are not addresses and are ignored: %s' => 'Diese Zeilen sind keine Adressen und werden ignoriert: %s',
    'Two-letter codes separated by commas, e.g. RU, CN. Only when the country is known (see above).' => 'Zweibuchstabige Codes, durch Kommas getrennt, z. B. RU, CN. Nur wenn das Land bekannt ist (siehe oben).',
    'Unblock' => 'Entsperren',
    'Until' => 'Bis',
    'Why' => 'Warum',
    'Your address as the site sees it: %s.' => 'Ihre Adresse, wie die Website sie sieht: %s.',
    'blocked address' => 'gesperrte Adresse',
    'blocked country' => 'gesperrtes Land',
    'blocked for a while' => 'vorübergehend gesperrt',
    'nothing – visitors connect directly' => 'nichts – Besucher verbinden sich direkt',
    'probing for other systems' => 'Ausprobieren anderer Systeme',
    'too many requests' => 'zu viele Anfragen',
    'Domain and mail' => 'Domain und E-Mail',
    'Checks' => 'Prüfungen',
    'switched off in the public demo – no request leaves it' => 'in der öffentlichen Demo abgeschaltet – keine Anfrage verlässt sie',
    'not checked yet – the background jobs check it once a day, or use Check now below' => 'noch nicht geprüft – die Hintergrundaufgaben prüfen es einmal täglich, oder nutzen Sie unten „Jetzt prüfen“',
    'the site runs on a local address (%s) – the certificate, the domain registration and the mail DNS records are checked once it has its public address' => 'die Website läuft auf einer lokalen Adresse (%s) – Zertifikat, Domain-Registrierung und die DNS-Einträge für E-Mail werden geprüft, sobald sie ihre öffentliche Adresse hat',
    'Sending domain' => 'Absenderdomain',
    'no sender address – fill in the site e-mail (Settings → General) so the mail records can be checked' => 'keine Absenderadresse – tragen Sie die E-Mail der Website ein (Einstellungen → Allgemein), damit die E-Mail-Einträge geprüft werden können',
    'the DNS records of %s could not be read (the server did not get an answer from its resolver)' => 'die DNS-Einträge von %s konnten nicht gelesen werden (der Server bekam keine Antwort von seinem Resolver)',
    'SPF record' => 'SPF-Eintrag',
    '%s has no SPF record – receiving servers cannot tell that its mail is legitimate and often file it as spam. Add a TXT record on %s: %s' => '%s hat keinen SPF-Eintrag – empfangende Server können nicht erkennen, dass die E-Mail echt ist, und sortieren sie oft als Spam ein. Legen Sie einen TXT-Eintrag auf %s an: %s',
    'includes the SMTP server %s' => 'schließt den SMTP-Server %s ein',
    'does not seem to include the SMTP server %s; add %s (or the value your mail provider publishes)' => 'scheint den SMTP-Server %s nicht einzuschließen; ergänzen Sie %s (oder den Wert, den Ihr E-Mail-Anbieter veröffentlicht)',
    'DMARC record' => 'DMARC-Eintrag',
    '%s has no DMARC record – Gmail and Microsoft require it from senders. Add a TXT record on %s: %s' => '%s hat keinen DMARC-Eintrag – Gmail und Microsoft verlangen ihn von Absendern. Legen Sie einen TXT-Eintrag auf %s an: %s',
    'policy p=none only reports; once the reports look right, move to p=quarantine' => 'die Richtlinie p=none meldet nur; sobald die Berichte stimmen, wechseln Sie zu p=quarantine',
    'DKIM signature' => 'DKIM-Signatur',
    'no DKIM key found under the common selectors (%s). If your mail provider signs with another selector, all is well; otherwise turn DKIM signing on with the provider and publish its key in DNS' => 'unter den gängigen Selektoren (%s) wurde kein DKIM-Schlüssel gefunden. Signiert Ihr E-Mail-Anbieter mit einem anderen Selektor, ist alles in Ordnung; sonst schalten Sie die DKIM-Signierung beim Anbieter ein und veröffentlichen seinen Schlüssel im DNS',
    'key published under the selector %s' => 'Schlüssel unter dem Selektor %s veröffentlicht',
    'Certificate' => 'Zertifikat',
    'could not be read from %s: %s' => 'konnte von %s nicht gelesen werden: %s',
    'expires in %d days (%s)' => 'läuft in %d Tagen ab (%s)',
    'expired %d days ago (%s) – browsers warn visitors away from the site' => 'vor %d Tagen abgelaufen (%s) – Browser warnen Besucher vor der Website',
    'renew it, or check that the automatic renewal (Let’s Encrypt) still works' => 'erneuern Sie es oder prüfen Sie, ob die automatische Erneuerung (Let’s Encrypt) noch funktioniert',
    'Domain registration' => 'Domain-Registrierung',
    'the expiry of %s could not be checked: %s' => 'das Ablaufdatum von %s konnte nicht geprüft werden: %s',
    '%s – the registry does not publish the expiry date; check it with your registrar' => '%s – die Registry veröffentlicht das Ablaufdatum nicht; prüfen Sie es bei Ihrem Registrar',
    '%s expires in %d days (%s)' => '%s läuft in %d Tagen ab (%s)',
    '%s expired %d days ago (%s)' => '%s ist vor %d Tagen abgelaufen (%s)',
    'renew the domain with your registrar – an expired domain takes the site and its mail down' => 'verlängern Sie die Domain bei Ihrem Registrar – mit einer abgelaufenen Domain fallen Website und E-Mail aus',
    'The sending domain %s has no SPF record – mail from the forms will land in spam. Add a TXT record: %s' => 'Die Absenderdomain %s hat keinen SPF-Eintrag – E-Mails aus den Formularen landen im Spam. Legen Sie einen TXT-Eintrag an: %s',
    'The sending domain %s has no DMARC record – Gmail and Microsoft require it. Add a TXT record on %s: %s' => 'Die Absenderdomain %s hat keinen DMARC-Eintrag – Gmail und Microsoft verlangen ihn. Legen Sie einen TXT-Eintrag auf %s an: %s',
    'The site certificate expires in %d days – check that it renews.' => 'Das Zertifikat der Website läuft in %d Tagen ab – prüfen Sie, ob es erneuert wird.',
    'The site certificate has expired – browsers warn visitors away from the site.' => 'Das Zertifikat der Website ist abgelaufen – Browser warnen Besucher vor der Website.',
    'The domain %s expires in %d days – renew it with the registrar.' => 'Die Domain %s läuft in %d Tagen ab – verlängern Sie sie beim Registrar.',
    'The domain %s has expired – renew it with the registrar before someone else takes it.' => 'Die Domain %s ist abgelaufen – verlängern Sie sie beim Registrar, bevor sie jemand anderes übernimmt.',
    'The site runs on a local address – the certificate, the domain and the mail records are checked once it has its public address.' => 'Die Website läuft auf einer lokalen Adresse – Zertifikat, Domain und E-Mail-Einträge werden geprüft, sobald sie ihre öffentliche Adresse hat.',
    'The domain and mail check has run – the results are in the table above.' => 'Die Prüfung von Domain und E-Mail ist gelaufen – die Ergebnisse stehen in der Tabelle oben.',
    'The mail DNS records (SPF, DMARC, DKIM), the site certificate and the domain registration have not been checked yet. The check runs once a day on its own; the results appear in the table above.' => 'Die DNS-Einträge für E-Mail (SPF, DMARC, DKIM), das Zertifikat der Website und die Domain-Registrierung wurden noch nicht geprüft. Die Prüfung läuft einmal täglich von selbst; die Ergebnisse erscheinen in der Tabelle oben.',
    'Last checked %s. The check runs once a day on its own; the results are in the table above.' => 'Zuletzt geprüft %s. Die Prüfung läuft einmal täglich von selbst; die Ergebnisse stehen in der Tabelle oben.',
    'Domain, certificate and mail records' => 'Domain, Zertifikat und Mail-Einträge',
    'Real-user speed (Core Web Vitals)' => 'Geschwindigkeit bei Besuchern (Core Web Vitals)',
    'Measurements' => 'Messungen',
    'good' => 'gut',
    'needs improvement' => 'verbesserungswürdig',
    'poor' => 'schlecht',
    'No measurements yet – they arrive from visitors’ browsers while the statistics are on.' => 'Noch keine Messungen – sie kommen aus den Browsern der Besucher, solange die Statistik eingeschaltet ist.',
    'Speed: the 75th percentile of what real visitors experienced – loading of the main content (LCP, good up to 2.5 s), layout shifts (CLS, good up to 0.1) and the response to interaction (INP, good up to 200 ms); values are the upper edge of a histogram bucket, so they never flatter.' => 'Geschwindigkeit: das 75. Perzentil dessen, was echte Besucher erlebt haben – Laden des Hauptinhalts (LCP, gut bis 2,5 s), Layoutverschiebungen (CLS, gut bis 0,1) und Reaktion auf Interaktion (INP, gut bis 200 ms); die Werte sind die Obergrenze eines Histogramm-Intervalls und schmeicheln daher nie.',
    'Loading got slower: visitors wait %s s for the main content (p75 LCP) in the last 30 days, %s s in the 30 days before (%d measurements) – check the images, fonts and embeds above the fold.' => 'Das Laden wurde langsamer: Besucher warten in den letzten 30 Tagen %s s auf den Hauptinhalt (p75 LCP), in den 30 Tagen davor %s s (%d Messungen) – prüfen Sie Bilder, Schriften und eingebettete Inhalte im oberen Seitenbereich.',
    'Suspend automatically' => 'Automatisch aussetzen',
    'block accounts nobody has used for %d days (never the last administrator)' => 'Konten sperren, die %d Tage lang niemand benutzt hat (niemals den letzten Administrator)',
    'revoke Claude connections nobody has used for %d days' => 'Claude-Verbindungen widerrufen, die %d Tage lang niemand benutzt hat',
    'Checked once a day. While this is off, System status and the site audit only report unused accounts and connections. A blocked account shows the reason in Users and an administrator can reactivate it; a revoked connection has to be connected again.' => 'Wird einmal täglich geprüft. Solange dies aus ist, melden Systemstatus und Website-Audit unbenutzte Konten und Verbindungen nur. Ein gesperrtes Konto zeigt den Grund unter Benutzer und ein Administrator kann es wieder aktivieren; eine widerrufene Verbindung muss neu verbunden werden.',
    'Accounts and access' => 'Konten und Zugriff',
    'Two-step sign-in for administrators' => 'Zweistufige Anmeldung der Administratoren',
    '%d administrator(s) sign in without two-step sign-in or a passkey – it is turned on under My account (avatar at the top right)' => '%d Administrator(en) melden sich ohne zweistufige Anmeldung oder Passkey an – eingeschaltet wird sie unter Mein Konto (Avatar oben rechts)',
    'Unused accounts' => 'Unbenutzte Konten',
    'every account has been used in the last %d days' => 'jedes Konto wurde in den letzten %d Tagen benutzt',
    '%d account(s) unused for %d days – the automatic suspension blocks them on its next daily run' => '%d Konto/Konten seit %d Tagen unbenutzt – die automatische Aussetzung sperrt sie beim nächsten täglichen Lauf',
    '%d account(s) unused for %d days – block them in Users, or switch on the automatic suspension in Settings → General' => '%d Konto/Konten seit %d Tagen unbenutzt – sperren Sie sie unter Benutzer oder schalten Sie die automatische Aussetzung unter Einstellungen → Allgemein ein',
    'last activity %s' => 'letzte Aktivität %s',
    'Unused Claude connections' => 'Unbenutzte Claude-Verbindungen',
    'every connection has been used in the last %d days' => 'jede Verbindung wurde in den letzten %d Tagen benutzt',
    '%d connection(s) unused for %d days – the automatic suspension revokes them on its next daily run' => '%d Verbindung(en) seit %d Tagen unbenutzt – die automatische Aussetzung widerruft sie beim nächsten täglichen Lauf',
    '%d connection(s) unused for %d days – revoke them in the user’s account, or switch on the automatic suspension in Settings → General' => '%d Verbindung(en) seit %d Tagen unbenutzt – widerrufen Sie sie im Konto des Benutzers oder schalten Sie die automatische Aussetzung unter Einstellungen → Allgemein ein',
    'Connections without an expiry' => 'Verbindungen ohne Ablaufdatum',
    'every personal token has an expiry date' => 'jedes persönliche Token hat ein Ablaufdatum',
    '%d personal token(s) never expire – a token works until it is revoked; revoke those that are not needed, or create them again with an expiry' => '%d persönliche(s) Token laufen nie ab – ein Token funktioniert, bis es widerrufen wird; widerrufen Sie nicht benötigte oder erstellen Sie sie neu mit Ablaufdatum',
    '%d – blocked by an administrator or by the automatic suspension; you can reactivate them in Users' => '%d – gesperrt von einem Administrator oder der automatischen Aussetzung; unter Benutzer können Sie sie wieder aktivieren',
    'Automatic suspension' => 'Automatische Aussetzung',
    'off – unused accounts and connections are only reported (Settings → General)' => 'aus – unbenutzte Konten und Verbindungen werden nur gemeldet (Einstellungen → Allgemein)',
    'accounts after %d days' => 'Konten nach %d Tagen',
    'Claude connections after %d days' => 'Claude-Verbindungen nach %d Tagen',
    'The account %s has not been used for %d days (last activity %s) – block it, or let the automatic suspension do it.' => 'Das Konto %s wurde seit %d Tagen nicht benutzt (letzte Aktivität %s) – sperren Sie es oder überlassen Sie es der automatischen Aussetzung.',
    'The Claude connection “%s” of %s has not been used for %d days – revoke it, or let the automatic suspension do it.' => 'Die Claude-Verbindung „%s“ von %s wurde seit %d Tagen nicht benutzt – widerrufen Sie sie oder überlassen Sie es der automatischen Aussetzung.',
    'Unused accounts and Claude connections are only reported – switch on the automatic suspension (Settings → General) so that leftover access closes itself.' => 'Unbenutzte Konten und Claude-Verbindungen werden nur gemeldet – schalten Sie die automatische Aussetzung ein (Einstellungen → Allgemein), damit vergessener Zugriff sich von selbst schließt.',
    'The account is not blocked.' => 'Das Konto ist nicht gesperrt.',
    'The account has been reactivated – the user can sign in again.' => 'Das Konto ist wieder aktiv – der Benutzer kann sich wieder anmelden.',
    'The connection has been revoked – Claude can no longer sign in with it.' => 'Die Verbindung wurde widerrufen – Claude kann sich damit nicht mehr anmelden.',
    'The connection no longer exists.' => 'Die Verbindung existiert nicht mehr.',
    'Blocked automatically on %s – nobody had used the account for %d days. An administrator can reactivate it.' => 'Automatisch gesperrt am %s – niemand hatte das Konto %d Tage lang benutzt. Ein Administrator kann es wieder aktivieren.',
    'blocked automatically' => 'automatisch gesperrt',
    'Reactivate' => 'Wieder aktivieren',
    'Blocked automatically on %s – nobody had used the account for %d days. Untick the box and save to reactivate the account.' => 'Automatisch gesperrt am %s – niemand hatte das Konto %d Tage lang benutzt. Haken entfernen und speichern, dann ist das Konto wieder aktiv.',
    'Claude connections' => 'Claude-Verbindungen',
    'Personal tokens and connected applications of this account. A connection nobody has used for %d days is reported in System status; revoke what is not needed any more.' => 'Persönliche Token und verbundene Anwendungen dieses Kontos. Eine Verbindung, die %d Tage lang niemand benutzt hat, meldet der Systemstatus; widerrufen Sie, was nicht mehr gebraucht wird.',
    'Revoke the connection? Claude will no longer be able to sign in with it.' => 'Verbindung widerrufen? Claude kann sich damit nicht mehr anmelden.',
    'personal token' => 'persönliches Token',
    'connected application' => 'verbundene Anwendung',
    'last used %s' => 'zuletzt benutzt %s',
    'never used' => 'noch nicht benutzt',
    'valid until %s' => 'gültig bis %s',
    'no expiry' => 'ohne Ablaufdatum',
    'Revoke' => 'Widerrufen',
    'expired %s' => 'abgelaufen am %s',
    'Valid for' => 'Gültig für',
    '1 year' => '1 Jahr',
    '%d days' => '%d Tage',
    'An expired token stops working on its own; you then create a new one. A token nobody uses for %d days is reported in System status.' => 'Ein abgelaufenes Token hört von selbst auf zu funktionieren; dann erstellen Sie ein neues. Ein Token, das %d Tage lang niemand benutzt, meldet der Systemstatus.',
    'connection revoked automatically' => 'Verbindung automatisch widerrufen',
    'account reactivated' => 'Konto wieder aktiviert',
    'connection revoked' => 'Verbindung widerrufen',
    'An account not used for %d days was suspended (user #%d).' => 'Ein seit %d Tagen nicht genutztes Konto wurde gesperrt (Benutzer Nr. %d).',
    'A Claude connection not used for %d days was revoked (user #%d).' => 'Eine seit %d Tagen nicht genutzte Claude-Anbindung wurde widerrufen (Benutzer Nr. %d).',
    'Suspending unused accounts and connections' => 'Sperren ungenutzter Konten und Anbindungen',
    'Fleet console' => 'Website-Konsole',
    'Makes this installation the console of your other Kaleta sites: they report to it every hour, it shows all of them on one screen sorted by what needs attention, checks that they are up and decides when they install a new version – test sites first, the rest two days later. It never gets into the sites.' => 'Macht diese Installation zur Konsole Ihrer anderen Kaleta-Websites: Sie melden sich stündlich bei ihr, sie zeigt alle auf einem Bildschirm, sortiert nach dem, was Aufmerksamkeit braucht, prüft, ob sie erreichbar sind, und entscheidet, wann sie eine neue Version installieren – zuerst Test-Websites, die übrigen zwei Tage später. In die Websites selbst gelangt sie nie.',
    '%s was paired with the console.' => '%s wurde mit der Konsole gekoppelt.',
    '%s runs version %s.' => '%s läuft mit Version %s.',
    '%s is no longer in the console.' => '%s ist nicht mehr in der Konsole.',
    '%s answers again.' => '%s antwortet wieder.',
    '%s does not answer (%s).' => '%s antwortet nicht (%s).',
    'no answer' => 'keine Antwort',
    '%s has not sent its heartbeat for more than a day.' => '%s hat seit mehr als einem Tag keinen Bericht gesendet.',
    'This is not a pairing key of a Kaleta console (it starts with kaleta-console:).' => 'Das ist kein Kopplungsschlüssel einer Kaleta-Konsole (er beginnt mit kaleta-console:).',
    'Fill in the site address in Settings → General first.' => 'Tragen Sie zuerst die Adresse der Website unter Einstellungen → Allgemein ein.',
    'The console refused the pairing: %s' => 'Die Konsole hat die Kopplung abgelehnt: %s',
    'The site was paired with the fleet console %s.' => 'Die Website wurde mit der Website-Konsole %s gekoppelt.',
    'The new version is allowed on %d sites; each installs it with its next report (within an hour).' => 'Die neue Version ist auf %d Websites freigegeben; jede installiert sie mit ihrem nächsten Bericht (innerhalb einer Stunde).',
    'The site is not in the console.' => 'Die Website ist nicht in der Konsole.',
    'Saved.' => 'Gespeichert.',
    'Checked.' => 'Geprüft.',
    'The site was removed from the console. It stops reporting with its next report; pair it again to bring it back.' => 'Die Website wurde aus der Konsole entfernt. Ihren nächsten Bericht lehnt die Konsole ab; koppeln Sie sie erneut, um sie zurückzuholen.',
    'A fleet console is another Kaleta installation that shows all your sites on one screen. This site sends it a signed report every hour – version, health, background jobs, backups, enquiries waiting and visits, never names or the content of enquiries. The console cannot get into this site.' => 'Eine Website-Konsole ist eine andere Kaleta-Installation, die alle Ihre Websites auf einem Bildschirm zeigt. Diese Website sendet ihr stündlich einen signierten Bericht – Version, Zustand, Hintergrundaufgaben, Sicherungen, wartende Anfragen und Besuche, nie Namen oder den Inhalt von Anfragen. Die Konsole kann nicht in diese Website gelangen.',
    'Pair with a console' => 'Mit einer Konsole koppeln',
    'Pairing key' => 'Kopplungsschlüssel',
    'On the console: Fleet → Add a site. The key is valid for 24 hours and only once.' => 'In der Konsole: Website-Konsole → Website hinzufügen. Der Schlüssel gilt 24 Stunden und nur einmal.',
    'The console decides when new versions install here' => 'Die Konsole entscheidet, wann neue Versionen hier installiert werden',
    'Test sites first, the rest two days later when nothing broke. Only versions signed by the Kaleta publisher install, as always.' => 'Zuerst Test-Websites, die übrigen zwei Tage später, wenn nichts kaputtging. Installiert werden wie immer nur vom Kaleta-Herausgeber signierte Versionen.',
    'Pair' => 'Koppeln',
    'Console' => 'Konsole',
    'Key fingerprints' => 'Schlüssel-Fingerabdrücke',
    'console %s, this site %s' => 'Konsole %s, diese Website %s',
    'Last report' => 'Letzter Bericht',
    'not sent yet' => 'noch nicht gesendet',
    'Allowed update' => 'Freigegebenes Update',
    'Version %s – it installs with the next background run.' => 'Version %s – sie wird beim nächsten Lauf der Hintergrundaufgaben installiert.',
    'Without it, updates work as before: security releases install themselves when that is on in Backups and updates, others you install yourself.' => 'Ohne das funktionieren Updates wie bisher: Sicherheitsversionen installieren sich selbst, wenn das unter Sicherungen und Updates eingeschaltet ist, andere installieren Sie selbst.',
    'Save the choice about updates' => 'Update-Auswahl speichern',
    'Send a report now' => 'Bericht jetzt senden',
    'The site will stop reporting to the console. Continue?' => 'Die Website sendet der Konsole keine Berichte mehr. Fortfahren?',
    'Disconnect from the console' => 'Von der Konsole trennen',
    'Paste this pairing key on the site in Settings → Fleet console. It is valid for 24 hours and only once; it is not shown again.' => 'Fügen Sie diesen Kopplungsschlüssel auf der Website unter Einstellungen → Website-Konsole ein. Er gilt 24 Stunden und nur einmal; er wird nicht noch einmal angezeigt.',
    'No site reports to this console yet. Make a pairing key and paste it on the site.' => 'Dieser Konsole meldet sich noch keine Website. Erstellen Sie einen Kopplungsschlüssel und fügen Sie ihn auf der Website ein.',
    'All %d sites are fine.' => 'Alle %d Websites sind in Ordnung.',
    '%d of %d sites need attention.' => '%d von %d Websites brauchen Aufmerksamkeit.',
    'The newest version: %s.' => 'Neueste Version: %s.',
    'Add a site' => 'Website hinzufügen',
    'Check all now' => 'Alle jetzt prüfen',
    'Every site that lets the console decide installs version %s within an hour, without waiting for the test sites. Continue?' => 'Jede Website, die die Konsole entscheiden lässt, installiert Version %s innerhalb einer Stunde, ohne auf die Test-Websites zu warten. Fortfahren?',
    'Allow the new version everywhere now' => 'Neue Version jetzt überall freigeben',
    'Which sites' => 'Welche Websites',
    'Need attention' => 'Brauchen Aufmerksamkeit',
    'All sites' => 'Alle Websites',
    'Nothing needs attention.' => 'Nichts braucht Aufmerksamkeit.',
    'What needs attention' => 'Was Aufmerksamkeit braucht',
    'Enquiries waiting' => 'Wartende Anfragen',
    'test site' => 'Test-Website',
    'allowed %s' => 'freigegeben %s',
    'Sites report every hour; the console checks every 5 minutes that each home page answers. Problems reach you by the alert e-mail (System status → Alerts).' => 'Websites melden sich stündlich; die Konsole prüft alle 5 Minuten, ob jede Startseite antwortet. Probleme erreichen Sie per Warn-E-Mail (Systemstatus → Warnungen).',
    'Administration of the site' => 'Administration der Website',
    'Needs attention:' => 'Braucht Aufmerksamkeit:',
    'not checked yet' => 'noch nicht geprüft',
    'no report yet' => 'noch kein Bericht',
    '%s is available' => '%s ist verfügbar',
    'Last update' => 'Letztes Update',
    'failed' => 'fehlgeschlagen',
    'Health' => 'Zustand',
    'Last backup' => 'Letzte Sicherung',
    'off-site copy: %s' => 'Kopie außerhalb des Servers: %s',
    'Cron last called' => 'Cron zuletzt aufgerufen',
    'Visits in 7 days' => 'Besuche in 7 Tagen',
    '%d in 7 days, %d waiting for an answer' => '%d in 7 Tagen, %d warten auf Antwort',
    'no findings' => 'keine Befunde',
    'Problems the site reports' => 'Probleme, die die Website meldet',
    'The site reports its problems in English; fix them in its administration.' => 'Die Website meldet ihre Probleme auf Englisch; beheben Sie sie in ihrer Administration.',
    'Background jobs that fail: %s' => 'Fehlschlagende Hintergrundaufgaben: %s',
    'This site decides about its updates itself (Settings → Fleet console on the site).' => 'Diese Website entscheidet selbst über ihre Updates (auf der Website unter Einstellungen → Website-Konsole).',
    'normal – after the test sites ran the version for 48 hours without problems' => 'normal – nachdem die Test-Websites die Version 48 Stunden ohne Probleme betrieben haben',
    'test site – gets a new version first' => 'Test-Website – bekommt eine neue Version zuerst',
    'Security releases go to every site at once.' => 'Sicherheitsversionen gehen sofort an alle Websites.',
    'Save' => 'Speichern',
    'Allow version %s now' => 'Version %s jetzt freigeben',
    'Remove the site from the console? Its reports will be refused until it is paired again.' => 'Website aus der Konsole entfernen? Ihre Berichte werden abgelehnt, bis sie erneut gekoppelt wird.',
    'Remove from the console' => 'Aus der Konsole entfernen',
    'Events' => 'Ereignisse',
    'Paired %s.' => 'Gekoppelt %s.',
    'Score %d (higher = more urgent).' => 'Wert %d (höher = dringender).',
    'does not answer' => 'antwortet nicht',
    'stopped reporting' => 'meldet sich nicht mehr',
    'errors' => 'Fehler',
    'an update failed' => 'ein Update ist fehlgeschlagen',
    'background jobs fail' => 'Hintergrundaufgaben schlagen fehl',
    'no recent backup' => 'keine aktuelle Sicherung',
    'warnings' => 'Warnungen',
    'cron not set up' => 'Cron nicht eingerichtet',
    'enquiries waiting' => 'Anfragen warten',
    'a new version is available' => 'eine neue Version ist verfügbar',
    'audit findings' => 'Audit-Befunde',
    'The site is paired with the console and has sent its first report.' => 'Die Website ist mit der Konsole gekoppelt und hat ihren ersten Bericht gesendet.',
    'The report has been sent to the console.' => 'Der Bericht wurde an die Konsole gesendet.',
    'The choice about updates is saved.' => 'Die Update-Auswahl ist gespeichert.',
    'The site no longer reports to the console.' => 'Die Website meldet sich nicht mehr bei der Konsole.',
    'Report to the fleet console' => 'Bericht an die Website-Konsole',
    'Fleet console: are the sites up' => 'Website-Konsole: laufen die Websites?',
    'Fleet' => 'Website-Konsole',
    'The console did not confirm the report.' => 'Die Konsole hat den Bericht nicht bestätigt.',
    'The console does not know this site any more – pair it again.' => 'Die Konsole kennt diese Website nicht mehr – koppeln Sie sie erneut.',
    'Version' => 'Versionsstand',
    'Ring' => 'Update-Ring',
    'Monthly report' => 'Monatsbericht',
    'In the first days of each month the site e-mails a short report about the previous month: traffic, enquiries and sign-ups, updates, backups, changes made by people and by Claude, the problems right now and what needs your decision. Counts and page addresses only – never names, e-mail addresses or the contents of enquiries, so the report can be forwarded. With the agency details from the General tab it carries the agency’s branding.' => 'In den ersten Tagen jedes Monats schickt die Website per E-Mail einen kurzen Bericht über den Vormonat: Zugriffe, Anfragen und Anmeldungen, Updates, Backups, Änderungen durch Menschen und durch Claude, die aktuellen Probleme und was Ihre Entscheidung braucht. Nur Zahlen und Seitenadressen – nie Namen, E-Mail-Adressen oder Inhalte von Anfragen, der Bericht kann also weitergeleitet werden. Mit den Agenturangaben aus dem Reiter Allgemein trägt er das Branding der Agentur.',
    'Send a monthly report by e-mail' => 'Monatsbericht per E-Mail senden',
    'One address per line or separated by commas, at most 10. Empty = the site e-mail (Settings → General).' => 'Eine Adresse pro Zeile oder durch Kommas getrennt, höchstens 10. Leer = die E-Mail-Adresse der Website (Einstellungen → Allgemein).',
    'Preview last month' => 'Vorschau für den letzten Monat',
    'Send last month’s report now' => 'Bericht für den letzten Monat jetzt senden',
    'Save the settings first – sending uses the saved recipients.' => 'Speichern Sie zuerst die Einstellungen – der Versand verwendet die gespeicherten Empfänger.',
    'There is nobody to send the report to – fill in the recipients, or the site e-mail on the General tab.' => 'Es gibt niemanden, an den der Bericht gehen könnte – tragen Sie Empfänger ein oder die E-Mail-Adresse der Website im Reiter Allgemein.',
    'The report has been handed over for delivery to %d recipient(s).' => 'Der Bericht wurde zur Zustellung an %d Empfänger übergeben.',
    'Monthly report by e-mail' => 'Monatsbericht per E-Mail',
    'The monthly report for %s went to %d recipient(s).' => 'Der Monatsbericht für %s ging an %d Empfänger.',
    'January' => 'Januar',
    'February' => 'Februar',
    'March' => 'März',
    'May' => 'Mai',
    'June' => 'Juni',
    'July' => 'Juli',
    'October' => 'Oktober',
    'December' => 'Dezember',
    'Website report – %s – %s' => 'Website-Bericht – %s – %s',
    'Website report – %s' => 'Website-Bericht – %s',
    '%d enquiry(ies) nobody has opened yet' => '%d Anfrage(n), die noch niemand geöffnet hat',
    '%d problem(s) in System status need fixing' => '%d Problem(e) im Systemstatus müssen behoben werden',
    'Needs your decision' => 'Braucht Ihre Entscheidung',
    'Most read pages' => 'Meistgelesene Seiten',
    'Visitors came from' => 'Besucher kamen von',
    'Compared with the month before.' => 'Im Vergleich zum Vormonat.',
    'The built-in statistics are off (Settings → Analytics), so there are no traffic figures.' => 'Die eingebaute Statistik ist aus (Einstellungen → Analyse), daher gibt es keine Zugriffszahlen.',
    'Enquiries received' => 'Eingegangene Anfragen',
    'from page %s' => 'von der Seite %s',
    'Newsletter sign-ups' => 'Newsletter-Anmeldungen',
    'Enquiries and sign-ups' => 'Anfragen und Anmeldungen',
    'none this month' => 'diesen Monat keine',
    '%d made, %d failed' => '%d erstellt, %d fehlgeschlagen',
    'the last one %s' => 'das letzte %s',
    '%d by people, %d by Claude' => '%d von Menschen, %d von Claude',
    'Changes in the administration' => 'Änderungen in der Verwaltung',
    'Care of the site' => 'Pflege der Website',
    'Problems right now' => 'Aktuelle Probleme',
    'None – every check in System status is fine.' => 'Keine – jede Prüfung im Systemstatus ist in Ordnung.',
    'Details are in System status' => 'Details stehen unter Systemstatus',
    'Sent once a month by the website %s. Switch it off or change the recipients in Settings → Mail.' => 'Einmal im Monat von der Website %s gesendet. Abschalten oder die Empfänger ändern können Sie unter Einstellungen → E-Mail.',
    'The monthly report by e-mail went out (the month and how many recipients).' => 'Der Monatsbericht per E-Mail ging hinaus (der Monat und wie viele Empfänger).',
    'April' => 'April',
    'August' => 'August',
    'September' => 'September',
    'November' => 'November',
    'Backups' => 'Backups',
    'The fact %s changed.' => 'Der Fakt %s hat sich geändert.',
    'The key may contain lowercase letters, digits and _ and must start with a letter (2–40 characters).' => 'Der Schlüssel darf Kleinbuchstaben, Ziffern und _ enthalten und muss mit einem Buchstaben beginnen (2–40 Zeichen).',
    'This fact comes from the settings (Business details) – change it there.' => 'Dieser Fakt stammt aus den Einstellungen (Firmendaten) – ändern Sie ihn dort.',
    'Create the fact in the default language first.' => 'Legen Sie den Fakt zuerst in der Standardsprache an.',
    'amount of money' => 'Geldbetrag',
    'web address' => 'Webadresse',
    'founding date' => 'Gründungsdatum',
    'number of employees' => 'Anzahl der Mitarbeitenden',
    'price range' => 'Preisspanne',
    'area served' => 'Einzugsgebiet',
    'slogan' => 'Slogan',
    'award' => 'Auszeichnung',
    'languages' => 'Sprachen',
    'founder' => 'Gründer',
    'text' => 'Text',
    'number' => 'Zahl',
    'date' => 'Datum',
    'year' => 'Jahr',
    'phone' => 'Telefon',
    'Company name' => 'Firmenname',
    'Current year' => 'Aktuelles Jahr',
    'The fact is saved.' => 'Der Fakt ist gespeichert.',
    'The fact does not exist.' => 'Der Fakt existiert nicht.',
    'The fact is deleted.' => 'Der Fakt ist gelöscht.',
    'The fact is deleted – some content still uses it and shows nothing there now; the site audit lists it.' => 'Der Fakt ist gelöscht – einige Inhalte verwenden ihn noch und zeigen dort jetzt nichts; das Website-Audit listet sie auf.',
    'Write a fact once and use it everywhere: {{fact.key}} in a text, a button or a link (tel:{{fact.company_phone}}). The site fills in the value when a page is shown; change it here and every page says the new value.' => 'Schreiben Sie einen Fakt einmal und verwenden Sie ihn überall: {{fact.schluessel}} in einem Text, einer Schaltfläche oder einem Link (tel:{{fact.company_phone}}). Die Website setzt den Wert beim Anzeigen ein; ändern Sie ihn hier, und jede Seite nennt den neuen Wert.',
    'New fact' => 'Neuer Fakt',
    'Sentences with numbers that are not facts yet' => 'Sätze mit Zahlen, die noch keine Fakten sind',
    'No facts yet. Typical ones: the year the company was founded, the number of projects or clients, a price from, the warranty, the area you serve.' => 'Noch keine Fakten. Typisch sind: das Gründungsjahr, die Zahl der Projekte oder Kunden, ein Preis ab, die Garantie, das Gebiet, in dem Sie tätig sind.',
    'Fact' => 'Fakt',
    'Value' => 'Wert',
    'Token' => 'Platzhalter',
    'Used' => 'Verwendet',
    'Changed' => 'Geändert',
    'From the settings' => 'Aus den Einstellungen',
    'not filled in' => 'nicht ausgefüllt',
    'The company details are changed in Business details. Claude reads and changes facts with list_facts and save_fact.' => 'Die Firmendaten ändern Sie unter Firmendaten. Claude liest und ändert Fakten mit list_facts und save_fact.',
    'All facts' => 'Alle Fakten',
    'No text on the site states the old value “%s” any more.' => 'Kein Text auf der Website nennt den alten Wert „%s“ mehr.',
    'The old value “%s” is still written as plain text in %d places – replace it with the token so it changes by itself next time:' => 'Der alte Wert „%s“ steht noch an %d Stellen als reiner Text – ersetzen Sie ihn durch den Platzhalter, damit er sich nächstes Mal selbst ändert:',
    'e.g. Founded' => 'z. B. Gegründet',
    'Lowercase letters, digits and _. In content: {{fact.key}}. It cannot change later.' => 'Kleinbuchstaben, Ziffern und _. Im Inhalt: {{fact.schluessel}}. Später nicht mehr änderbar.',
    'Type' => 'Typ',
    'A number is shown with the thousands separator of the language, a date in its format, an amount as 1 500 CZK (enter 1500 CZK).' => 'Eine Zahl wird mit dem Tausendertrennzeichen der Sprache gezeigt, ein Datum in deren Format, ein Betrag als 1.500 EUR (Eingabe 1500 EUR).',
    'Empty = the same as the default value.' => 'Leer = derselbe Wert wie in der Standardsprache.',
    'For search engines' => 'Für Suchmaschinen',
    'Adds the fact to the company in the structured data (schema.org) search engines and AI assistants read.' => 'Fügt den Fakt der Firma in den strukturierten Daten (schema.org) hinzu, die Suchmaschinen und KI-Assistenten lesen.',
    'Where the number comes from – for you and your colleagues, not shown on the site.' => 'Woher die Zahl stammt – für Sie und Ihre Kollegen, nicht auf der Website sichtbar.',
    'Delete the fact? Content that uses it will show nothing in its place.' => 'Fakt löschen? Inhalte, die ihn verwenden, zeigen an seiner Stelle nichts.',
    'Delete' => 'Löschen',
    'Not used yet. Write {{fact.%s}} into a text, a button or a link.' => 'Noch nicht verwendet. Schreiben Sie {{fact.%s}} in einen Text, eine Schaltfläche oder einen Link.',
    'Changes' => 'Änderungen',
    'Sentences with numbers, years and amounts written as plain text. When one of them changes – a new year, another project – you have to find every place yourself. Make it a fact and write {{fact.key}} instead.' => 'Sätze mit Zahlen, Jahren und Beträgen als reiner Text. Wenn sich einer ändert – ein neues Jahr, ein weiteres Projekt –, müssen Sie jede Stelle selbst finden. Machen Sie daraus einen Fakt und schreiben Sie stattdessen {{fact.schluessel}}.',
    'No such sentences – the numbers on the site are facts already.' => 'Keine solchen Sätze – die Zahlen auf der Website sind bereits Fakten.',
    'Sentence' => 'Satz',
    'Facts' => 'Fakten',
    'The value does not fit the type of the fact (%s).' => 'Der Wert passt nicht zum Typ des Fakts (%s).',
    'The fact {{fact.%s}} does not exist – visitors see nothing in its place. Create it in Facts, or fix the key.' => 'Der Fakt {{fact.%s}} existiert nicht – Besucher sehen an seiner Stelle nichts. Legen Sie ihn unter Fakten an oder korrigieren Sie den Schlüssel.',
    'Open now (and until when)' => 'Jetzt geöffnet (und bis wann)',
    'Exceptions to the opening hours' => 'Abweichende Öffnungszeiten',
    'Holidays, a closed day, shorter hours. The site shows them under the opening hours, knows whether it is open now, and shows a notice bar a few days ahead until the exception ends.' => 'Feiertage, ein geschlossener Tag, kürzere Öffnungszeiten. Die Website zeigt sie unter den Öffnungszeiten, weiß, ob gerade geöffnet ist, und zeigt einige Tage vorher bis zum Ende einen Hinweisbalken.',
    'notice %d days ahead' => 'Hinweis %d Tage vorher',
    'no notice' => 'kein Hinweis',
    'From' => 'Von',
    'One day: fill in only the first date.' => 'Ein Tag: nur das erste Datum ausfüllen.',
    'Closed' => 'Geschlossen',
    'Closed all day' => 'Ganztägig geschlossen',
    'Or open' => 'Oder geöffnet',
    'When it is open with different hours: uncheck Closed and enter the hours, more ranges with a comma.' => 'Wenn zu anderen Zeiten geöffnet ist: Geschlossen abwählen und die Zeiten eingeben, mehrere Bereiche mit Komma.',
    'e.g. Christmas' => 'z. B. Weihnachten',
    'Notice bar' => 'Hinweisbalken',
    'days ahead' => 'Tage vorher',
    '0 = no notice bar.' => '0 = kein Hinweisbalken.',
    'Add the exception' => 'Ausnahme hinzufügen',
    'The exception is saved.' => 'Die Ausnahme ist gespeichert.',
    'The exception is deleted.' => 'Die Ausnahme ist gelöscht.',
    'Enter the dates as YYYY-MM-DD; the last day must not be before the first one.' => 'Geben Sie die Daten als JJJJ-MM-TT ein; der letzte Tag darf nicht vor dem ersten liegen.',
    'Enter the hours of the exception, e.g. 9:00-12:00 (more ranges with a comma), or mark the days as closed.' => 'Geben Sie die Zeiten der Ausnahme ein, z. B. 9:00-12:00 (mehrere Bereiche mit Komma), oder markieren Sie die Tage als geschlossen.',
    'closed' => 'geschlossen',
    'Open now, until %s' => 'Jetzt geöffnet, bis %s',
    'Closed now' => 'Jetzt geschlossen',
    'Closed now, opens today at %s' => 'Jetzt geschlossen, öffnet heute um %s',
    'Closed now, opens tomorrow at %s' => 'Jetzt geschlossen, öffnet morgen um %s',
    'Closed now, opens on %s at %s' => 'Jetzt geschlossen, öffnet am %s um %s',
    'item of another collection' => 'Eintrag einer anderen Sammlung',
    'Linked collection' => 'Verknüpfte Sammlung',
    'An item of another collection links two collections – a person to a branch, a reference to a service: choose the type and the linked collection. {{key}} shows the linked item\'s name, {{key_url}} its page. On the page of the linked item, a Collection list filtered by the field with the value {{seo}} lists everything linked to it.' => 'Ein Eintrag einer anderen Sammlung verknüpft zwei Sammlungen – eine Person mit einer Filiale, eine Referenz mit einer Leistung: Wählen Sie den Typ und die verknüpfte Sammlung. {{schluessel}} zeigt den Namen des verknüpften Eintrags, {{schluessel_url}} seine Seite. Auf der Seite des verknüpften Eintrags listet eine Sammlungsliste, gefiltert nach dem Feld mit dem Wert {{seo}}, alles, was mit ihm verknüpft ist.',
    'Hidden items redirect to' => 'Ausgeblendete Einträge weiterleiten auf',
    'When an item is hidden or deleted – a person who left, a product no longer sold – its page leads here (301) instead of “page not found”. Empty = page not found.' => 'Wenn ein Eintrag ausgeblendet oder gelöscht ist – eine Person, die gegangen ist, ein Produkt, das nicht mehr verkauft wird –, führt seine Seite hierher (301) statt zu „Seite nicht gefunden“. Leer = Seite nicht gefunden.',
    'The redirect of hidden items must be an address on the site (/team) or https://…' => 'Die Weiterleitung ausgeblendeter Einträge muss eine Adresse auf der Website (/team) oder https://… sein',
    'Unknown template.' => 'Unbekannte Vorlage.',
    'The collection was created – add the first items.' => 'Die Sammlung ist angelegt – fügen Sie die ersten Einträge hinzu.',
    'New team (people)' => 'Neues Team (Personen)',
    'Photo, role, languages, phone, e-mail, absence and a page for each person; the page of someone who left leads to the team page.' => 'Foto, Funktion, Sprachen, Telefon, E-Mail, Abwesenheit und eine Seite für jede Person; die Seite von jemandem, der gegangen ist, führt zur Teamseite.',
    'Languages' => 'Sprachen',
    'On leave' => 'Abwesend',
    'About' => 'Über mich',
    'The token {{%s}} cannot be computed – visitors see nothing in its place. years_since takes a year, a date (YYYY-MM-DD) or a fact with one; count takes the address of a collection, or news.' => 'Der Platzhalter {{%s}} lässt sich nicht berechnen – Besucher sehen an seiner Stelle nichts. years_since nimmt ein Jahr, ein Datum (JJJJ-MM-TT) oder einen Fakt damit; count nimmt die Adresse einer Sammlung oder news.',
    'The number %s is typed in – make it a fact ({{fact.key}}) or a count, so it stays true.' => 'Die Zahl %s ist von Hand eingetragen – machen Sie daraus einen Fakt ({{fact.schluessel}}) oder eine Zählung, damit sie wahr bleibt.',
    'A big number with a label that counts up when shown (years of experience, customers, projects). The number may be a fact or a computed token, so it stays true.' => 'Eine große Zahl mit Beschriftung, die beim Erscheinen hochzählt (Jahre Erfahrung, Kunden, Projekte). Die Zahl kann ein Fakt oder ein berechneter Platzhalter sein, damit sie wahr bleibt.',
    'Number – or a fact or count token ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})' => 'Zahl – oder ein Fakt- bzw. Zähl-Platzhalter ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})',
    'Computed' => 'Berechnet',
    'Numbers the site works out when a page is shown, so they never go stale – years since a date and counts of what is on the site. Write the token into a text, or into the number of a counter.' => 'Zahlen, die die Website beim Anzeigen einer Seite berechnet, damit sie nie veralten – Jahre seit einem Datum und Anzahlen dessen, was auf der Website ist. Schreiben Sie den Platzhalter in einen Text oder in die Zahl eines Zählers.',
    'Shows now' => 'Zeigt jetzt',
    'What it counts' => 'Was gezählt wird',
    'nothing – the site has no such collection or fact yet' => 'nichts – die Website hat noch keine solche Sammlung und keinen solchen Fakt',
    'Full years since a year or a date (2004 or 2004-05-01).' => 'Volle Jahre seit einem Jahr oder Datum (2004 oder 2004-05-01).',
    'The same from a fact whose value is a year or a date.' => 'Dasselbe aus einem Fakt, dessen Wert ein Jahr oder ein Datum ist.',
    'The number of visible items of a collection (by its address).' => 'Die Anzahl der sichtbaren Einträge einer Sammlung (nach ihrer Adresse).',
    'The number of published news items.' => 'Die Anzahl der veröffentlichten Neuigkeiten.',
    'Door sign' => 'Türschild',
    'The exception no longer exists.' => 'Die Ausnahme existiert nicht mehr.',
    'True until' => 'Gültig bis',
    'Review by' => 'Prüfen bis',
    'After this day the page hides itself. Empty = always.' => 'Nach diesem Tag verbirgt sich die Seite von selbst. Leer = immer gültig.',
    'After this day the news item hides itself. Empty = always.' => 'Nach diesem Tag verbirgt sich der News-Beitrag von selbst. Leer = immer gültig.',
    'After this day the item hides itself. Empty = always.' => 'Nach diesem Tag verbirgt sich der Eintrag von selbst. Leer = immer gültig.',
    'After this day the pop-up switches itself off. Empty = always.' => 'Nach diesem Tag schaltet sich das Pop-up von selbst aus. Leer = immer gültig.',
    'On this day the site audit and the alert e-mail remind you to check it.' => 'An diesem Tag erinnern Sie der Website-Audit und die Warn-E-Mail daran, den Inhalt zu prüfen.',
    'Hides itself the day after.' => 'Verbirgt sich am Tag danach von selbst.',
    'Asks for a review on this day.' => 'Bittet an diesem Tag um eine Prüfung.',
    'true until %s' => 'gültig bis %s',
    'review by %s' => 'prüfen bis %s',
    '“%s” was true until %s and hid itself.' => '„%s“ war gültig bis %s und hat sich von selbst verborgen.',
    '“%s” asks for a review by %s.' => '„%s“ bittet um eine Prüfung bis %s.',
    'Asked for a review by %s.' => 'Bittet um eine Prüfung bis %s.',
    'Content that expires or asks for review' => 'Inhalte, die ablaufen oder eine Prüfung verlangen',
    'A page, news item, collection item or pop-up was true until a past day and hid itself.' => 'Eine Seite, ein News-Beitrag, ein Sammlungseintrag oder ein Pop-up war bis zu einem vergangenen Tag gültig und hat sich von selbst verborgen.',
    'A page, news item, collection item or pop-up asks for a review (its review-by day has come).' => 'Eine Seite, ein News-Beitrag, ein Sammlungseintrag oder ein Pop-up bittet um eine Prüfung (der Tag „prüfen bis“ ist gekommen).',
    'E-mail signature: %s' => 'E-Mail-Signatur: %s',
    'Made from the record of %s in the look of your site. When the record or the site changes, open this page again and copy the signature anew.' => 'Erstellt aus dem Eintrag von %s im Erscheinungsbild Ihrer Website. Wenn sich der Eintrag oder die Website ändert, öffnen Sie diese Seite erneut und kopieren Sie die Signatur neu.',
    'Copy signature' => 'Signatur kopieren',
    'Back to the item' => 'Zurück zum Eintrag',
    'Plain-text version' => 'Nur-Text-Version',
    'For mail clients and places that take no formatting – the Copy button puts it on the clipboard together with the formatted signature.' => 'Für Mailprogramme und Stellen ohne Formatierung – die Schaltfläche Kopieren legt sie zusammen mit der formatierten Signatur in die Zwischenablage.',
    'Where to paste it' => 'Wo Sie sie einfügen',
    'Settings (the gear) → See all settings → General → Signature → Create new, paste the signature into the box (Ctrl+V, on a Mac ⌘V) and click Save Changes at the bottom.' => 'Einstellungen (Zahnrad) → Alle Einstellungen aufrufen → Allgemein → Signatur → Neu erstellen, die Signatur in das Feld einfügen (Strg+V, auf dem Mac ⌘V) und unten auf Änderungen speichern klicken.',
    'New message → Signature → Signatures… (Outlook on the web: Settings → Mail → Compose and reply), paste the signature and save.' => 'Neue Nachricht → Signatur → Signaturen… (Outlook im Web: Einstellungen → E-Mail → Verfassen und Antworten), die Signatur einfügen und speichern.',
    'Mail → Settings → Signatures, choose the account, click +, paste the signature and untick “Always match my default message font”.' => 'Mail → Einstellungen → Signaturen, das Konto wählen, auf + klicken, die Signatur einfügen und „Immer meine Standardschrift für Nachrichten verwenden“ abwählen.',
    'The photo and the logo load from your website, so they show as long as they stay there.' => 'Foto und Logo werden von Ihrer Website geladen und erscheinen, solange sie dort bleiben.',
    'E-mail signature' => 'E-Mail-Signatur',
    'The system has been updated to version %s.' => 'Das System wurde auf Version %s aktualisiert.',
    'date and time' => 'Datum und Uhrzeit',
    'location (latitude, longitude)' => 'Standort (Breitengrad, Längengrad)',
    'Start from a ready-made collection' => 'Mit einer fertigen Sammlung beginnen',
    '00:00 = the whole day' => '00:00 = ganzer Tag',
    'Branch' => 'Filiale',
    'By date' => 'Nach Datum',
    'all items' => 'alle Einträge',
    'upcoming – not ended yet' => 'bevorstehend – noch nicht vorbei',
    'current – started and not ended' => 'laufend – begonnen und nicht beendet',
    'past – ended' => 'vergangen – beendet',
    'Start date field (key, e.g. start)' => 'Feld mit dem Beginn (Schlüssel, z. B. start)',
    'End date field (key, optional)' => 'Feld mit dem Ende (Schlüssel, optional)',
    'The collection was created with a hidden page that lists it – add the first items, then publish the page.' => 'Die Sammlung ist angelegt, mit einer ausgeblendeten Seite, die sie auflistet – fügen Sie die ersten Einträge hinzu und veröffentlichen Sie dann die Seite.',
    'daily' => 'täglich',
    'weekly' => 'wöchentlich',
    'every 2 weeks' => 'alle 2 Wochen',
    'monthly' => 'monatlich',
    'yearly' => 'jährlich',
    'Add to calendar' => 'Zum Kalender hinzufügen',
    'Registration' => 'Anmeldung',
    'Register' => 'Anmelden',
