    'Your enquiry' => 'Ihre Anfrage',
    'Thank you, we have received your enquiry. We will get back to you with prices and availability.' => 'Vielen Dank, wir haben Ihre Anfrage erhalten. Wir melden uns mit Preisen und Verfügbarkeit.',
    'Add to enquiry – shows on the pages and cards of a products collection.' => 'Zur Anfrage hinzufügen – erscheint auf den Seiten und Karten einer Produktsammlung.',
    'Code' => 'Artikelnummer',
    'Industry blueprint' => 'Branchenvorlage',
    'A blueprint sets the site up for a kind of business: the ready-made collections it needs, the facts to fill in, questions for the owner, checks in the site audit and instructions for Claude.' => 'Eine Branchenvorlage richtet die Website für eine Art von Unternehmen ein: die nötigen fertigen Sammlungen, Fakten zum Ausfüllen, Fragen an den Inhaber, Prüfungen im Website-Audit und Anweisungen für Claude.',
    'Applied' => 'Angewendet',
    'Questions for the owner' => 'Fragen an den Inhaber',
    'Save answers' => 'Antworten speichern',
    'Everything the blueprint checks is in place.' => 'Alles, was die Vorlage prüft, ist vorhanden.',
    'Apply a blueprint' => 'Branchenvorlage anwenden',
    'No other blueprints are available. Upload a blueprint file below.' => 'Keine weiteren Vorlagen verfügbar. Laden Sie unten eine Vorlagendatei hoch.',
    'Blueprint file (.json)' => 'Vorlagendatei (.json)',
    'Apply' => 'Anwenden',
    'Export this site as a blueprint' => 'Diese Website als Branchenvorlage exportieren',
    'The presets your collections come from, your facts without their values, and the questions, checks and instructions of the applied blueprints.' => 'Die Vorlagen, aus denen Ihre Sammlungen stammen, Ihre Fakten ohne Werte sowie Fragen, Prüfungen und Anweisungen der angewendeten Vorlagen.',
    'Blueprint' => 'Vorlage',
    'The file is not a valid blueprint: %s' => 'Die Datei ist keine gültige Branchenvorlage: %s',
    'Choose a blueprint or a file.' => 'Wählen Sie eine Vorlage oder eine Datei.',
    'The blueprint is applied: %d new collections (with hidden list pages) and %d facts. Answer its questions below.' => 'Die Vorlage ist angewendet: %d neue Sammlungen (mit ausgeblendeten Listenseiten) und %d Fakten. Beantworten Sie unten ihre Fragen.',
    'The blueprint is removed – its collections and facts stay.' => 'Die Vorlage ist entfernt – ihre Sammlungen und Fakten bleiben.',
    'The answers are saved – the site states them as facts.' => 'Die Antworten sind gespeichert – die Website nennt sie als Fakten.',
    'The key may contain lowercase letters, digits and _ (2–40 characters).' => 'Der Schlüssel darf Kleinbuchstaben, Ziffern und _ enthalten (2–40 Zeichen).',
    'Industry checks' => 'Branchenprüfungen',
    'Job openings' => 'Stellenangebote',
    'New job openings' => 'Neue Stellenangebote',
    'Location, employment type, salary, description, requirements and an application form with a CV on each job page; a job hides itself after its closing date.' => 'Ort, Beschäftigungsart, Gehalt, Beschreibung, Anforderungen und ein Bewerbungsformular mit Lebenslauf auf jeder Stellenseite; nach dem Bewerbungsschluss blendet sich die Stelle selbst aus.',
    'Employment type' => 'Beschäftigungsart',
    'Salary from' => 'Gehalt von',
    'Salary to' => 'Gehalt bis',
    'Salary unit' => 'Gehaltseinheit',
    'Requirements' => 'Anforderungen',
    'We offer' => 'Wir bieten',
    'Start date' => 'Eintrittsdatum',
    'Salary' => 'Gehalt',
    'Apply for this job' => 'Auf diese Stelle bewerben',
    'Job application' => 'Bewerbung',
    'Send application' => 'Bewerbung absenden',
    'Thank you for your application. We will get back to you.' => 'Vielen Dank für Ihre Bewerbung. Wir melden uns bei Ihnen.',
    'CV' => 'Lebenslauf',
    'A few words about you' => 'Ein paar Worte über Sie',
    'I agree to the processing of my personal data for the purpose of this selection procedure.' => 'Ich stimme der Verarbeitung meiner personenbezogenen Daten für dieses Auswahlverfahren zu.',
    'Job opening' => 'Stellenangebot',
    'Location (town)' => 'Ort (Stadt)',
    'Salary unit (per month / per hour)' => 'Gehaltseinheit (pro Monat / pro Stunde)',
    'Job opening without a closing date – set “true until” to the application deadline: the job then hides itself and search engines get validThrough, which they need to tell an open job from an expired one.' => 'Stellenangebot ohne Bewerbungsschluss – setzen Sie „gültig bis“ auf die Bewerbungsfrist: die Stelle blendet sich dann selbst aus und Suchmaschinen erhalten validThrough, woran sie eine offene von einer abgelaufenen Stelle unterscheiden.',
    '%d job applications older than %d months were deleted, including the CVs.' => '%d Bewerbungen, die älter als %d Monate waren, wurden samt Lebensläufen gelöscht.',
    'Delete job applications after' => 'Bewerbungen löschen nach',
    'Applications sent from the pages of a Job openings collection carry CVs and are usually kept only for a limited time after the selection. 0 = like other enquiries.' => 'Bewerbungen, die von den Seiten einer Stellenangebote-Sammlung gesendet wurden, enthalten Lebensläufe und werden üblicherweise nur begrenzt nach dem Auswahlverfahren aufbewahrt. 0 = wie andere Anfragen.',
    'Usual practice in %s: %d months – check with your lawyer.' => 'Übliche Praxis in %s: %d Monate – klären Sie das mit Ihrem Anwalt.',
    'Documents' => 'Dokumente',
    'New document library' => 'Neue Dokumentenbibliothek',
    'Price lists, terms, manuals and forms: a file with its version, summary and date of issue, a stable download address that survives a new edition, download counts and an expiry date; the previous versions stay on the document’s page.' => 'Preislisten, Geschäftsbedingungen, Anleitungen und Formulare: eine Datei mit Version, Zusammenfassung und Ausgabedatum, eine feste Download-Adresse, die eine neue Ausgabe überdauert, Abrufzahlen und ein Ablaufdatum; die früheren Versionen bleiben auf der Seite des Dokuments.',
    'Category' => 'Kategorie',
    'Summary' => 'Zusammenfassung',
    'Issued' => 'Ausgestellt',
    'Downloads (30 days / total)' => 'Abrufe (30 Tage / gesamt)',
    'Downloads of the stable address /…/latest: the last 30 days / total. Bots are not counted.' => 'Abrufe über die feste Adresse /…/latest: die letzten 30 Tage / gesamt. Bots werden nicht gezählt.',
    'The stable address of the current file – it stays the same when a new version replaces the file.' => 'Die feste Adresse der aktuellen Datei – sie bleibt gleich, wenn eine neue Version die Datei ersetzt.',
    'Document expires soon' => 'Dokument läuft bald ab',
    'The document is true until %s – upload the new edition or move the date; the day after, it hides itself and its download address stops working.' => 'Das Dokument gilt bis %s – laden Sie die neue Ausgabe hoch oder verschieben Sie das Datum; am Tag danach blendet es sich selbst aus und seine Download-Adresse funktioniert nicht mehr.',
    'After sending, e-mail this file to the visitor (a file from Media; the form needs an e-mail field). A file in Media stays reachable by its own address – this stops casual sharing, not a determined person.' => 'Nach dem Absenden diese Datei per E-Mail an den Besucher senden (eine Datei aus den Medien; das Formular braucht ein E-Mail-Feld). Eine Datei in den Medien bleibt unter ihrer eigenen Adresse erreichbar – das verhindert beiläufiges Weitergeben, nicht eine entschlossene Person.',
    'Store locator' => 'Filialfinder',
    'Branches or stores from a collection: a list with directions, a search box, “Nearest to me” and a map that loads after a click.' => 'Filialen oder Geschäfte aus einer Kollektion: Liste mit Anfahrt, Suchfeld, „In meiner Nähe“ und eine Karte, die nach einem Klick lädt.',
    'Collection (empty = the first Branches collection)' => 'Kollektion (leer = die erste Kollektion Filialen)',
    'Location field (key)' => 'Feld mit dem Standort (Schlüssel)',
    'Search box' => 'Suchfeld',
    '“Nearest to me” button' => 'Schaltfläche „In meiner Nähe“',
    'Map (loads after a click)' => 'Karte (lädt nach einem Klick)',
    'Create a Branches collection first (Collections → New branches), or choose a collection in the Content panel.' => 'Legen Sie zuerst eine Kollektion Filialen an (Kollektionen → Neue Filialen) oder wählen Sie eine Kollektion im Bereich Inhalt.',
    'The collection has no visible items yet.' => 'Die Kollektion hat noch keine sichtbaren Einträge.',
    'New branches (store locator)' => 'Neue Filialen (Filialfinder)',
    'Address, location, phone, e-mail, opening hours, photo and a page for each branch or store; the Store locator element lists them with search, the nearest one and a map.' => 'Adresse, Standort, Telefon, E-Mail, Öffnungszeiten, Foto und eine Seite für jede Filiale oder jedes Geschäft; das Element Filialfinder listet sie mit Suche, der nächsten Filiale und einer Karte.',
    'Local business (branch, store)' => 'Lokales Unternehmen (Filiale, Geschäft)',
    'Location (latitude, longitude)' => 'Standort (Breite, Länge)',
    'New services' => 'Neue Dienstleistungen',
    'A page for each service with a summary, an image, a description and a price from; the list shows cards with the summary.' => 'Eine Seite für jede Leistung mit Zusammenfassung, Bild, Beschreibung und Preis ab; die Liste zeigt Karten mit der Zusammenfassung.',
    'Summary' => 'Zusammenfassung',
    'Price from' => 'Preis ab',
    'Price note' => 'Preishinweis',
    'References' => 'Referenzen',
    'New references (case studies)' => 'Neue Referenzen (Fallstudien)',
    'Case studies with the client, an image, a quote, the result, a link and the year, each with its own page; a reference can point to the service it was for.' => 'Fallstudien mit Kunde, Bild, Zitat, Ergebnis, Link und Jahr, jede mit eigener Seite; eine Referenz kann auf die Leistung verweisen, um die es ging.',
    'Year' => 'Jahr',
    'Price list' => 'Preisliste',
    'New price list' => 'Neue Preisliste',
    'Rows with a price, a unit and a note, grouped by category with filter buttons for visitors; the rows have no pages of their own.' => 'Zeilen mit Preis, Einheit und Hinweis, nach Kategorie gruppiert mit Filterschaltflächen für Besucher; die Zeilen haben keine eigenen Seiten.',
    'Category' => 'Kategorie',
    'Unit' => 'Einheit',
    'New questions and answers' => 'Neue Fragen und Antworten',
    'Questions with a formatted answer, grouped by category with filter buttons; the answers are kept in one place for the FAQ page and the pages that need them.' => 'Fragen mit formatierter Antwort, nach Kategorie gruppiert mit Filterschaltflächen; die Antworten liegen an einem Ort für die FAQ-Seite und die Seiten, die sie brauchen.',
    'Machines and equipment' => 'Maschinen und Ausrüstung',
    'New machines and equipment' => 'Neue Maschinen und Ausrüstung',
    'A page for each machine with a photo, the model, a table of parameters, the year, a datasheet to download and its availability.' => 'Eine Seite für jede Maschine mit Foto, Modell, Parametertabelle, Baujahr, Datenblatt zum Herunterladen und Verfügbarkeit.',
    'Model' => 'Modell',
    'Parameters' => 'Parameter',
    'Datasheet' => 'Datenblatt',
    'Availability' => 'Verfügbarkeit',
    'Courses and training' => 'Kurse und Schulungen',
    'New courses and training' => 'Neue Kurse und Schulungen',
    'A page for each course with its start and end, the place, the price, the capacity and a description; the list shows only the courses still to come, the nearest first.' => 'Eine Seite für jeden Kurs mit Beginn und Ende, Ort, Preis, Kapazität und Beschreibung; die Liste zeigt nur die kommenden Kurse, den nächsten zuerst.',
    'Capacity' => 'Kapazität',
    'Screen mode' => 'Bildschirmmodus',
    'Screen mode on' => 'Bildschirmmodus eingeschaltet',
    'A TV or a tablet in the reception, showroom or waiting room opens the address below and rotates slides by itself: the latest news, items of the chosen collections and today\'s opening hours. The address has a secret part, so nobody finds the screen by guessing; it is not indexed and sets no cookies.' => 'Ein Fernseher oder Tablet im Empfang, Showroom oder Wartezimmer öffnet die Adresse unten und wechselt die Folien von selbst: die neuesten Nachrichten, Einträge der gewählten Sammlungen und die heutigen Öffnungszeiten. Die Adresse hat einen geheimen Teil, sodass niemand den Bildschirm durch Raten findet; sie wird nicht indexiert und setzt keine Cookies.',
    'Seconds per slide' => 'Sekunden pro Folie',
    'Collections to show' => 'Angezeigte Sammlungen',
    'The site has no collections yet.' => 'Die Website hat noch keine Sammlungen.',
    'A collection with a date field (events, courses) shows only the upcoming items.' => 'Eine Sammlung mit einem Terminfeld (Veranstaltungen, Kurse) zeigt nur die kommenden Einträge.',
    'Show the latest news' => 'Neueste Nachrichten zeigen',
    'Up to five, with their images.' => 'Höchstens fünf, mit ihren Bildern.',
    'Show today\'s opening hours' => 'Heutige Öffnungszeiten zeigen',
    'From Business details, with the exceptions: “Open now, until 17:00”.' => 'Aus Firmendaten, mit den Ausnahmen: „Jetzt geöffnet, bis 17:00“.',
    'Show a clock' => 'Uhr zeigen',
    'Screen address' => 'Bildschirmadresse',
    'Copy address' => 'Adresse kopieren',
    'Open it on the screen in full-screen (kiosk) mode. Anyone with the address sees the screen – do not publish it.' => 'Öffnen Sie sie auf dem Bildschirm im Vollbildmodus (Kiosk). Jeder, der die Adresse kennt, sieht den Bildschirm – veröffentlichen Sie sie nicht.',
    'Save the settings with the screen mode on – the address is created then.' => 'Speichern Sie die Einstellungen mit eingeschaltetem Bildschirmmodus – die Adresse entsteht dabei.',
    'Official notice board' => 'Amtliche Bekanntmachungen',
    'New notice board' => 'Neue Bekanntmachungstafel',
    'Posting and takedown dates, reference number, issuer, category, document and summary; the board shows what is posted now, the archive what was taken down. Notices are never deleted and every change is logged.' => 'Aushang- und Abnahmedatum, Aktenzeichen, Herausgeber, Kategorie, Dokument und Zusammenfassung; die Tafel zeigt, was gerade ausgehängt ist, das Archiv, was abgenommen wurde. Bekanntmachungen werden nie gelöscht und jede Änderung wird protokolliert.',
    'Posted on' => 'Ausgehängt am',
    'Taken down on' => 'Abgenommen am',
    'Reference number' => 'Aktenzeichen',
    'Issuer' => 'Herausgeber',
    'Category' => 'Kategorie',
    'Summary' => 'Zusammenfassung',
    '%s – archive' => '%s – Archiv',
    'Official notice board: postings and takedowns' => 'Amtliche Bekanntmachungen: Aushang und Abnahme',
    'Notice status' => 'Status der Bekanntmachung',
    'Notices stay in the archive – change the takedown date instead.' => 'Bekanntmachungen bleiben im Archiv – ändern Sie stattdessen das Abnahmedatum.',
    'A notice that is or was posted cannot be hidden – it stays on the board until its takedown date and then in the archive. Change the dates instead.' => 'Eine Bekanntmachung, die ausgehängt ist oder war, kann nicht ausgeblendet werden – sie bleibt bis zum Abnahmedatum auf der Tafel und danach im Archiv. Ändern Sie stattdessen die Daten.',
    'The notice board has %s notices – they stay in the archive, so the collection cannot be deleted.' => 'Die Bekanntmachungstafel hat %s Bekanntmachungen – sie bleiben im Archiv, die Sammlung kann daher nicht gelöscht werden.',
    'The collection is not an official notice board.' => 'Die Sammlung ist keine Bekanntmachungstafel.',
    'Notice log (%s)' => 'Protokoll der Bekanntmachung (%s)',
    'Every creation and change of the notice and the day it was posted and taken down. The log is append-only – nothing in it can be edited or deleted.' => 'Jede Anlage und Änderung der Bekanntmachung und der Tag, an dem sie ausgehängt und abgenommen wurde. Das Protokoll wird nur ergänzt – nichts darin kann bearbeitet oder gelöscht werden.',
    'Download the whole log as CSV' => 'Das ganze Protokoll als CSV herunterladen',
    'Action' => 'Aktion',
    'By' => 'Von',
    'Notice' => 'Bekanntmachung',
    'Created' => 'Angelegt',
    'Posted' => 'Ausgehängt',
    'Taken down' => 'Abgenommen',
    'kept in the archive' => 'bleibt im Archiv',
    'Kind' => 'Art',
    'All kinds' => 'Alle Arten',
    'Not sorted' => 'Nicht sortiert',
    'Sales' => 'Vertrieb',
    'Supplier or offer' => 'Lieferant oder Angebot',
    'Other' => 'Sonstiges',
    'urgent' => 'dringend',
    'can wait' => 'kann warten',
    'Priority' => 'Priorität',
    'Triage' => 'Sortierung',
    'Sorted by %s' => 'Sortiert von %s',
    'the writing assistant' => 'dem Schreibassistenten',
    'a rule' => 'einer Regel',
    'Drafted reply' => 'Antwortentwurf',
    'Never sent by itself – check it, then reply by e-mail.' => 'Wird nie von selbst gesendet – prüfen Sie ihn und antworten Sie dann per E-Mail.',
    'Save triage' => 'Sortierung speichern',
    'Reply by email with the draft' => 'Mit dem Entwurf per E-Mail antworten',
    'Sort new enquiries with the writing assistant' => 'Neue Anfragen mit dem Schreibassistenten sortieren',
    'The assistant suggests the kind, the priority and a reply; the text of each enquiry is then sent to the AI provider chosen in Features – mention it in your privacy policy. Claude can sort enquiries over its connection without this.' => 'Der Assistent schlägt Art, Priorität und eine Antwort vor; der Text jeder Anfrage geht dann an den unter Funktionen gewählten KI-Anbieter – erwähnen Sie das in Ihrer Datenschutzerklärung. Claude kann Anfragen auch ohne dies über seine Verbindung sortieren.',
    'Sorting new enquiries with the writing assistant' => 'Sortieren neuer Anfragen mit dem Schreibassistenten',
    'normal' => 'gewöhnlich',
    'new step (a multi-step form – the label is the step title)' => 'neuer Schritt (mehrstufiges Formular – die Bezeichnung ist der Titel des Schritts)',
    'price estimate (adds up the prices of the answers)' => 'Preisschätzung (summiert die Preise der Antworten)',
    'Price per unit for the estimate (the number × this price)' => 'Preis pro Einheit für die Schätzung (die Zahl × dieser Preis)',
    'Base price of the estimate' => 'Grundpreis der Schätzung',
    'Currency of the estimate (e.g. EUR, Kč)' => 'Währung der Schätzung (z. B. EUR, Kč)',
    'Show only when the field labelled…' => 'Nur anzeigen, wenn das Feld mit der Bezeichnung…',
    '…has this value (for options to tick: this one is ticked)' => '…diesen Wert hat (bei Optionen zum Ankreuzen: diese ist angekreuzt)',
    'An estimate from your answers – the final price follows in our reply.' => 'Eine Schätzung nach Ihren Antworten – den endgültigen Preis nennen wir in unserer Antwort.',
    'Step %d' => 'Schritt %d',
    'Testimonial' => 'Referenz',
    'Answered' => 'Beantwortet',
    'the draft reference' => 'den Referenzentwurf',
    'Expired' => 'Abgelaufen',
    'Waiting for the answer' => 'Wartet auf Antwort',
    'Ask for a testimonial by e-mail' => 'Per E-Mail um eine Referenz bitten',
    'Only create the link' => 'Nur den Link erstellen',
    'The customer gets a personal link for 30 days; what they write arrives as a hidden draft in References, with the consent they gave.' => 'Der Kunde erhält einen persönlichen Link für 30 Tage; was er schreibt, kommt als ausgeblendeter Entwurf in die Referenzen, mit der erteilten Einwilligung.',
    'The request was sent. The link: %s' => 'Die Anfrage ist gesendet. Der Link: %s',
    'The link to send yourself: %s' => 'Der Link zum Weitergeben: %s',
    'The enquiry has no e-mail address to send the request to.' => 'Die Anfrage hat keine E-Mail-Adresse für die Bitte.',
    'A customer sent a testimonial (a hidden draft reference).' => 'Ein Kunde hat eine Referenz gesendet (ausgeblendeter Entwurf).',
    'Contact clicks (calls, e-mails, WhatsApp)' => 'Kontaktklicks (Anrufe, E-Mails, WhatsApp)',
    'Calls / e-mails / WhatsApp' => 'Anrufe / E-Mails / WhatsApp',
    'Contact clicks: a click on a phone number, an e-mail address or a WhatsApp link counts as a lead once per visitor, page and day – without cookies.' => 'Kontaktklicks: ein Klick auf eine Telefonnummer, eine E-Mail-Adresse oder einen WhatsApp-Link zählt als Lead einmal je Besucher, Seite und Tag – ohne Cookies.',
    'Calls – clicks on a phone number' => 'Anrufe – Klicks auf eine Telefonnummer',
    'E-mails – clicks on an e-mail address' => 'E-Mails – Klicks auf eine E-Mail-Adresse',
    'WhatsApp – clicks on a WhatsApp link' => 'WhatsApp – Klicks auf einen WhatsApp-Link',
    'Generate share images when a page has none' => 'Teilen-Bilder erzeugen, wenn eine Seite keines hat',
    'A 1200×630 picture with the title in the site colours, the site name and the logo – so social networks show something instead of nothing.' => 'Ein Bild 1200×630 mit dem Titel in den Farben der Website, dem Namen der Website und dem Logo – soziale Netzwerke zeigen dann etwas statt nichts.',
    'This server cannot draw pictures (the PHP GD extension is missing), so nothing is generated.' => 'Dieser Server kann keine Bilder zeichnen (die PHP-Erweiterung GD fehlt), daher wird nichts erzeugt.',
    'What happens next (one step per line, shown with the thank-you)' => 'Wie es weitergeht (ein Schritt pro Zeile, erscheint mit dem Dank)',
    'We reply within (working hours by the opening hours in Business details; 0 = not shown)' => 'Wir antworten innerhalb von (Arbeitsstunden nach den Öffnungszeiten in Firmendaten; 0 = nicht angezeigt)',
    'Who replies (e.g. “Jana from the office”)' => 'Wer antwortet (z. B. „Jana aus dem Büro“)',
    'Pricing table' => 'Preistabelle',
    'Before and after' => 'Vorher und nachher',
    'Hotspots' => 'Bildpunkte',
    'Timeline' => 'Zeitleiste',
    'Plans side by side – name, price, features and a button; one plan can be highlighted.' => 'Pakete nebeneinander – Name, Preis, Leistungen und Button; ein Paket kann hervorgehoben werden.',
    'Two photos with a draggable divider – a renovation, a cleaning, a makeover.' => 'Zwei Fotos mit verschiebbarem Trenner – Renovierung, Reinigung, Verwandlung.',
    'An image with numbered points – a tap on a point shows its label and text (a product, a floor plan, a map of premises).' => 'Ein Bild mit nummerierten Punkten – ein Tipp auf einen Punkt zeigt Bezeichnung und Text (Produkt, Grundriss, Lageplan).',
    'Milestones one after another – the company history, project steps, how a service proceeds.' => 'Meilensteine nacheinander – Firmengeschichte, Projektschritte, Ablauf einer Leistung.',
    'Plans' => 'Pakete',
    'Plan name' => 'Name des Pakets',
    'Period (e.g. / month)' => 'Zeitraum (z. B. / Monat)',
    'Short description' => 'Kurzbeschreibung',
    'Features – one per line; a line starting with "-" is not included' => 'Leistungen – eine pro Zeile; eine Zeile mit „-“ am Anfang ist nicht enthalten',
    'Highlighted plan' => 'Hervorgehobenes Paket',
    'Highlight label' => 'Beschriftung der Hervorhebung',
    'Image before' => 'Bild vorher',
    'Description of the before image (alt)' => 'Beschreibung des Vorher-Bildes (alt)',
    'Label of the before image' => 'Beschriftung des Vorher-Bildes',
    'Image after' => 'Bild nachher',
    'Description of the after image (alt)' => 'Beschreibung des Nachher-Bildes (alt)',
    'Label of the after image' => 'Beschriftung des Nachher-Bildes',
    'Divider position (%)' => 'Position des Trenners (%)',
    'Points' => 'Punkte',
    'From the left (%)' => 'Von links (%)',
    'From the top (%)' => 'Von oben (%)',
    'Milestones' => 'Meilensteine',
    'Date or year' => 'Datum oder Jahr',
    'Title' => 'Titel',
    'Image (optional)' => 'Bild (optional)',
    'The site talks only to the services listed here, only after you connect them. Sign-ins and keys are stored encrypted and never shown again – not here, not to Claude, not in the site export.' => 'Die Website spricht nur mit den hier genannten Diensten und erst, wenn Sie sie verbinden. Anmeldungen und Schlüssel werden verschlüsselt gespeichert und nie wieder angezeigt – weder hier noch Claude noch im Website-Export.',
    'Connected' => 'Verbunden',
    'Not connected' => 'Nicht verbunden',
    'since %s' => 'seit %s',
    'Create an OAuth app (a web application) with %s and enter its client ID and secret. The redirect address to enter there:' => 'Erstellen Sie bei %s eine OAuth-App (Webanwendung) und geben Sie deren Client-ID und Geheimnis ein. Die dort einzutragende Weiterleitungsadresse:',
    'Where to get it' => 'Wo Sie es bekommen',
    'Client ID' => 'Client-ID',
    'Client secret' => 'Client-Geheimnis',
    'stored – type to replace' => 'gespeichert – zum Ersetzen neu eingeben',
    'Where to get the key' => 'Wo Sie den Schlüssel bekommen',
    'Connect %s' => '%s verbinden',
    'Disconnect %s? The stored sign-in is deleted; what was already sent stays there.' => '%s trennen? Die gespeicherte Anmeldung wird gelöscht; bereits Gesendetes bleibt dort.',
    'Last calls' => 'Letzte Aufrufe',
    '%d deliveries are waiting or being retried.' => '%d Zustellungen warten oder werden wiederholt.',
    'No calls yet.' => 'Noch keine Aufrufe.',
    'The sign-in was cancelled: %s' => 'Die Anmeldung wurde abgebrochen: %s',
    '%s is connected.' => '%s ist verbunden.',
    'Disconnected – the stored sign-in was deleted.' => 'Getrennt – die gespeicherte Anmeldung wurde gelöscht.',
    'Enter the client ID and secret of your OAuth app first.' => 'Geben Sie zuerst Client-ID und Geheimnis Ihrer OAuth-App ein.',
    'The sign-in could not be verified. Try connecting again.' => 'Die Anmeldung konnte nicht geprüft werden. Verbinden Sie erneut.',
    '%s did not accept the sign-in: %s' => '%s hat die Anmeldung nicht akzeptiert: %s',
    '%s was connected.' => '%s wurde verbunden.',
    'The sign-in expired – connect %s again.' => 'Die Anmeldung ist abgelaufen – verbinden Sie %s erneut.',
    '%s is not connected.' => '%s ist nicht verbunden.',
    'Too many calls to %s this minute – it will be tried again.' => 'Zu viele Aufrufe an %s in dieser Minute – es wird erneut versucht.',
    'A delivery to an outside service failed: %s' => 'Eine Zustellung an einen externen Dienst ist fehlgeschlagen: %s',
    'Deliveries to connected services' => 'Zustellungen an verbundene Dienste',
    'An outside service was connected.' => 'Ein externer Dienst wurde verbunden.',
    'A delivery to an outside service failed after all retries.' => 'Eine Zustellung an einen externen Dienst ist auch nach allen Wiederholungen fehlgeschlagen.',
    'Links to /%s now lead to %s (%d places).' => 'Links zu /%s führen jetzt zu %s (%d Stellen).',
    'Personal data of one address were erased on request.' => 'Personenbezogene Daten einer Adresse wurden auf Anfrage gelöscht.',
    'Only an administrator can handle personal data requests.' => 'Anfragen zu personenbezogenen Daten bearbeitet nur ein Administrator.',
    'Tick that you want to erase the data.' => 'Bestätigen Sie, dass Sie die Daten löschen möchten.',
    'Erased: %d enquiries, %d subscriptions, %d e-mails in the queue, %d testimonial requests.' => 'Gelöscht: Anfragen %d, Abonnements %d, E-Mails in der Warteschlange %d, Referenzanfragen %d.',
    'A testimonial the person sent stays in References (items %s) – remove it there if they ask.' => 'Eine Referenz der Person bleibt in den Referenzen (Einträge %s) – entfernen Sie sie dort, wenn sie darum bittet.',
    'Personal data request' => 'Auskunfts- oder Löschanfrage',
    'find, export or erase everything about one e-mail address' => 'alles zu einer E-Mail-Adresse finden, exportieren oder löschen',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent and testimonial requests.' => 'Wenn jemand fragt, was die Website über ihn speichert, oder um Löschung bittet: Geben Sie seine E-Mail-Adresse ein. Durchsucht werden Anfragen (Absender und alle Felder), das Newsletter-Abonnement, wartende E-Mails und Referenzanfragen.',
    'E-mail address' => 'E-Mail-Adresse',
    'Find' => 'Suchen',
    'What the site keeps about %s' => 'Was die Website über %s speichert',
    'Nothing – the site keeps no data about this address.' => 'Nichts – die Website speichert keine Daten zu dieser Adresse.',
    'Enquiries: %d' => 'Anfragen: %d',
    'Newsletter subscription since %s' => 'Newsletter-Abonnement seit %s',
    'not confirmed' => 'unbestätigt',
    'E-mails in the outgoing queue: %d' => 'E-Mails in der Versandwarteschlange: %d',
    'Testimonial requests: %d' => 'Referenzanfragen: %d',
    'An account of the administration (%s) – change or remove it in Users; it is not erased here.' => 'Ein Konto der Verwaltung (%s) – ändern oder entfernen Sie es unter Benutzer; hier wird es nicht gelöscht.',
    'Download as a file for the person (JSON)' => 'Als Datei für die Person herunterladen (JSON)',
    'Erase everything listed above for good? This cannot be undone.' => 'Alles oben Aufgeführte endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'I want to erase this data for good' => 'Ich möchte diese Daten endgültig löschen',
    'Erase' => 'Löschen',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails and testimonial requests are deleted. Backups keep older copies until they expire.' => 'Gelöscht werden Anfragen mit Anhängen, das Abonnement (auch im verbundenen Mailing-Dienst), wartende E-Mails und Referenzanfragen. Sicherungen behalten ältere Kopien, bis sie ablaufen.',
    'The page password must have at least %d characters.' => 'Das Seitenpasswort muss mindestens %d Zeichen haben.',
    'Page password' => 'Seitenpasswort',
    'protected – type a new password to change it' => 'geschützt – zum Ändern ein neues Passwort eingeben',
    'none – the page is public' => 'keines – die Seite ist öffentlich',
    'Remove the password' => 'Passwort entfernen',
    'Visitors see the page only after entering the password – e.g. a price list for partners. It is not an account: whoever knows the password reads the page. A protected page is never in search engines, the sitemap or the site search.' => 'Besucher sehen die Seite erst nach Eingabe des Passworts – z. B. eine Preisliste für Partner. Es ist kein Konto: Wer das Passwort kennt, liest die Seite. Eine geschützte Seite erscheint nie in Suchmaschinen, in der Sitemap oder in der Websuche.',
    '%d files in Media. The site found what can be cleaned up – nothing changes until you decide.' => '%d Dateien in den Medien. Die Website hat gefunden, was aufgeräumt werden kann – nichts ändert sich, bis Sie entscheiden.',
    '%d images have no description for blind visitors (alt).' => '%d Bilder haben keine Beschreibung für blinde Besucher (Alt).',
    'Add language versions in Settings → General; this screen then shows which translations are missing.' => 'Sprachversionen fügen Sie unter Einstellungen → Allgemein hinzu; diese Seite zeigt dann, welche Übersetzungen fehlen.',
    'Apply the action to the selected items?' => 'Die Aktion auf die ausgewählten Einträge anwenden?',
    'Back to draft' => 'Zurück zum Entwurf',
    'Back to media' => 'Zurück zu den Medien',
    'Category…' => 'Kategorie…',
    'Clean-up' => 'Aufräumen',
    'Content check' => 'Inhaltsprüfung',
    'Delete %s' => '%s löschen',
    'Delete selected files' => 'Ausgewählte Dateien löschen',
    'Delete the selected files for good? Media has no trash. Files the site still uses are skipped.' => 'Die ausgewählten Dateien endgültig löschen? Die Medien haben keinen Papierkorb. Dateien, die die Website noch verwendet, werden übersprungen.',
    'Describe what each image shows – screen readers and search engines read it. Empty fields are skipped; the rest is saved together.' => 'Beschreiben Sie, was jedes Bild zeigt – Screenreader und Suchmaschinen lesen es. Leere Felder werden übersprungen, der Rest wird zusammen gespeichert.',
    'Duplicates' => 'Duplikate',
    'Every file is used somewhere on the site.' => 'Jede Datei wird irgendwo auf der Website verwendet.',
    'Every image has a description (alt).' => 'Jedes Bild hat eine Beschreibung (Alt).',
    'Every image has a description for blind visitors (alt).' => 'Jedes Bild hat eine Beschreibung für blinde Besucher (Alt).',
    'Headings do not skip a level.' => 'Die Überschriften überspringen keine Ebene.',
    'Headings skip a level (%s) – screen readers and search engines read the outline.' => 'Die Überschriften überspringen eine Ebene (%s) – Screenreader und Suchmaschinen lesen die Gliederung.',
    'Image descriptions saved: %d.' => 'Gespeicherte Bildbeschreibungen: %d.',
    'Images over %s or wider than %d px slow pages down. “Make smaller” re-encodes the image to %d px in place – its address and every page that shows it stay.' => 'Bilder über %s oder breiter als %d px verlangsamen die Seiten. „Verkleinern“ kodiert das Bild an Ort und Stelle auf %d px um – seine Adresse und jede Seite, die es zeigt, bleiben.',
    'Images without a description' => 'Bilder ohne Beschreibung',
    'Items hidden: %d.' => 'Ausgeblendete Einträge: %d.',
    'Items moved to the language version: %d.' => 'In die Sprachversion verschobene Einträge: %d.',
    'Items moved to the trash: %d.' => 'In den Papierkorb verschobene Einträge: %d.',
    'Items published: %d.' => 'Veröffentlichte Einträge: %d.',
    'Language version…' => 'Sprachversion…',
    'Make smaller' => 'Verkleinern',
    'Missing translations: %d, older than the original: %d.' => 'Fehlende Übersetzungen: %d, älter als das Original: %d.',
    'Move to trash' => 'In den Papierkorb',
    'News items back as drafts: %d.' => 'Zu Entwürfen zurückgesetzte Neuigkeiten: %d.',
    'News items moved to the category: %d.' => 'In die Kategorie verschobene Neuigkeiten: %d.',
    'News items published: %d.' => 'Veröffentlichte Neuigkeiten: %d.',
    'No description for search engines – they make one up from the text.' => 'Keine Beschreibung für Suchmaschinen – sie erfinden eine aus dem Text.',
    'No file is uploaded twice.' => 'Keine Datei ist doppelt hochgeladen.',
    'No image is larger than %s or wider than %d px.' => 'Kein Bild ist größer als %s oder breiter als %d px.',
    'Nothing on the site points at these files: no page, build, news item, collection item, component, pop-up, newsletter or setting. Media has no trash – deleted files cannot be restored.' => 'Nichts auf der Website verweist auf diese Dateien: keine Seite, kein Aufbau, keine Neuigkeit, kein Sammlungseintrag, keine Komponente, kein Pop-up, kein Newsletter und keine Einstellung. Die Medien haben keinen Papierkorb – gelöschte Dateien lassen sich nicht wiederherstellen.',
    'Of the saved version. Search engines show about 60 characters of a title and 160 of a description.' => 'Der gespeicherten Version. Suchmaschinen zeigen etwa 60 Zeichen eines Titels und 160 einer Beschreibung.',
    'One H1 heading.' => 'Eine H1-Überschrift.',
    'Only the owner of an image or an administrator can describe it.' => 'Nur der Besitzer eines Bildes oder ein Administrator kann es beschreiben.',
    'Oversized images' => 'Zu große Bilder',
    'Pages hidden: %d.' => 'Ausgeblendete Seiten: %d.',
