    'Pages moved to the trash: %d.' => 'In den Papierkorb verschobene Seiten: %d.',
    'Pages published: %d.' => 'Veröffentlichte Seiten: %d.',
    'Save descriptions' => 'Beschreibungen speichern',
    'Save first – the check looks at the saved version.' => 'Zuerst speichern – die Prüfung betrachtet die gespeicherte Version.',
    'Select %s' => '%s auswählen',
    'Select all' => 'Alle auswählen',
    'Settings' => 'Einstellungen',
    'Showing the first %d of %d.' => 'Die ersten %d von %d werden angezeigt.',
    'Skipped: %d (no permission).' => 'Übersprungen: %d (keine Berechtigung).',
    'Skipped: %d (no permission, or the home page).' => 'Übersprungen: %d (keine Berechtigung oder die Startseite).',
    'Skipped: %d (the address is taken in that language).' => 'Übersprungen: %d (die Adresse ist in dieser Sprache vergeben).',
    'The description has %d characters – %d to %d is best.' => 'Die Beschreibung hat %d Zeichen – %d bis %d sind am besten.',
    'The description has %d characters – search engines cut it after about %d.' => 'Die Beschreibung hat %d Zeichen – Suchmaschinen kürzen sie nach etwa %d.',
    'The description has %d characters.' => 'Die Beschreibung hat %d Zeichen.',
    'The focus keyword “%s” is in the title, the description and the first paragraph.' => 'Das Fokus-Schlüsselwort „%s“ steht im Titel, in der Beschreibung und im ersten Absatz.',
    'The focus keyword “%s” is missing from %s.' => 'Das Fokus-Schlüsselwort „%s“ fehlt in: %s.',
    'The image is now %s px wide and takes %s.' => 'Das Bild ist jetzt %s px breit und belegt %s.',
    'The original changed after this translation was saved.' => 'Das Original hat sich geändert, nachdem diese Übersetzung gespeichert wurde.',
    'The page has %d H1 headings – only the main one should be an H1, the others H2.' => 'Die Seite hat %d H1-Überschriften – nur die Hauptüberschrift sollte eine H1 sein, die anderen H2.',
    'The page has no H1 heading – the main heading tells readers and search engines what the page is about.' => 'Die Seite hat keine H1-Überschrift – die Hauptüberschrift sagt Lesern und Suchmaschinen, worum es geht.',
    'The page has no title.' => 'Die Seite hat keinen Titel.',
    'The same file uploaded more than once. Keep the one the site uses; an unused copy can be ticked and deleted below.' => 'Dieselbe Datei mehrfach hochgeladen. Behalten Sie die, die die Website verwendet; eine unbenutzte Kopie können Sie ankreuzen und unten löschen.',
    'The site has a single language.' => 'Die Website hat eine einzige Sprache.',
    'The title has %d characters – %d to %d is best for search results.' => 'Der Titel hat %d Zeichen – %d bis %d sind für Suchergebnisse am besten.',
    'The title has %d characters – search engines cut it after about %d.' => 'Der Titel hat %d Zeichen – Suchmaschinen kürzen ihn nach etwa %d.',
    'The title has %d characters.' => 'Der Titel hat %d Zeichen.',
    'Translate' => 'Übersetzen',
    'Translations' => 'Übersetzungen',
    'Unused files' => 'Unbenutzte Dateien',
    'cannot be made smaller here' => 'kann hier nicht verkleinert werden',
    'missing' => 'fehlt',
    'newsletter' => 'Newsletter',
