    'the description' => 'der Beschreibung',
    'the first paragraph' => 'dem ersten Absatz',
    'the title' => 'dem Titel',
    'translated' => 'übersetzt',
    '“Older” means the original changed after the translation was last saved.' => '„Älter“ heißt, das Original hat sich nach dem letzten Speichern der Übersetzung geändert.',
    'Accessibility options' => 'Optionen zur Barrierefreiheit',
    'Larger text' => 'Größere Schrift',
    'High contrast' => 'Hoher Kontrast',
    'Underline links' => 'Links unterstreichen',
    'Reduce motion' => 'Bewegung reduzieren',
