    '30 minutes' => '30 Minuten',
    '1 minute' => '1 Minute',
    'Cookie bar: the categories the visitor allowed (cookie)' => 'Cookie-Banner: die vom Besucher erlaubten Kategorien (Cookie)',
    'The chosen light or dark appearance (local storage)' => 'Gewähltes helles oder dunkles Design (lokaler Speicher)',
    'The chosen language version (local storage)' => 'Gewählte Sprachversion (lokaler Speicher)',
    'Accessibility toolbar: text size, contrast, underlined links, reduced motion (local storage)' => 'Barrierefreiheits-Leiste: Schriftgröße, Kontrast, unterstrichene Links, reduzierte Bewegung (lokaler Speicher)',
    'Sign-in to the administration – only after signing in, never for visitors' => 'Anmeldung in der Verwaltung – nur nach dem Anmelden, nie für Besucher',
    'Video player: bandwidth and preferences' => 'Videoplayer: Bandbreite und Einstellungen',
    'Video player: views within a session' => 'Videoplayer: Aufrufe innerhalb einer Sitzung',
    'Video player: preferences' => 'Videoplayer: Einstellungen',
    'Video player: statistics of plays' => 'Videoplayer: Statistik der Wiedergaben',
    'Map: preferences and usage' => 'Karte: Einstellungen und Nutzung',
    'Map: the consent given to Google' => 'Karte: die Google erteilte Einwilligung',
    'Statistics: tells visitors apart' => 'Statistik: unterscheidet Besucher',
    'Statistics: keeps the session state' => 'Statistik: hält den Sitzungszustand',
    'Tag manager: limits the number of requests' => 'Tag-Manager: begrenzt die Anzahl der Anfragen',
    'Statistics: the session' => 'Statistik: die Sitzung',
    'Advertising: tells visitors apart across sites' => 'Werbung: unterscheidet Besucher über Websites hinweg',
    'Advertising: shows and measures ads' => 'Werbung: zeigt und misst Anzeigen',
    'Spam check: the risk analysis of the visitor' => 'Spam-Prüfung: Risikoanalyse des Besuchers',
    'Spam check: the passed challenge' => 'Spam-Prüfung: bestandene Prüfung',
    'Spam check: accessibility of the challenge' => 'Spam-Prüfung: Barrierefreiheit der Prüfung',
    'Cookies and storage this site uses' => 'Cookies und Speicher, die diese Website nutzt',
    'What Kaleta itself sets, what the known embeds and tags found in your pages and settings set (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) and what the server answers with. Put {{cookie_table}} into your cookie policy page – the table appears there in the site language.' => 'Was Kaleta selbst setzt, was die in Ihren Seiten und Einstellungen gefundenen Einbettungen und Tags setzen (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) und womit der Server antwortet. Fügen Sie {{cookie_table}} in Ihre Cookie-Richtlinie ein – die Tabelle erscheint dort in der Sprache der Website.',
    'Last scan of the site’s own pages: %s, %d pages, %d cookies set by the server.' => 'Letzter Scan der eigenen Seiten: %s, %d Seiten, %d vom Server gesetzte Cookies.',
    'The server could not reach the site: %s.' => 'Der Server konnte die Website nicht erreichen: %s.',
    'The site’s own pages have not been scanned yet – the background tasks do it daily.' => 'Die eigenen Seiten wurden noch nicht gescannt – die Hintergrundaufgaben tun das täglich.',
    'Scan the site now' => 'Website jetzt scannen',
    'Documents from the configuration' => 'Dokumente aus der Konfiguration',
    'Templates assembled from what the site is set up to do – review and complete them, they are not legal advice.' => 'Vorlagen aus dem, was die Website eingestellt hat – prüfen und ergänzen Sie sie, sie sind keine Rechtsberatung.',
    'Record of processing' => 'Verzeichnis der Verarbeitungen',
    'Show the record' => 'Verzeichnis anzeigen',
    'GDPR Art. 30 style: forms and their fields, enquiries and applications with their retention, newsletter, statistics, connected services, mail, backups, the writing assistant, cookies.' => 'Im Stil von Art. 30 DSGVO: Formulare und ihre Felder, Anfragen und Bewerbungen mit Aufbewahrung, Newsletter, Statistik, verbundene Dienste, E-Mail, Backups, Schreibassistent, Cookies.',
    'Accessibility statement' => 'Erklärung zur Barrierefreiheit',
    'published' => 'veröffentlicht',
    'hidden draft' => 'verborgener Entwurf',
    'Regenerate the draft from the audit' => 'Entwurf aus dem Audit neu erzeugen',
    'Create the draft from the audit' => 'Entwurf aus dem Audit erzeugen',
    'Filled from the site audit: the standard (EN 301 549 / WCAG 2.1 AA), the status by the accessibility findings, the known barriers and the contact. Created as a hidden page – review it, then publish it. Regenerating updates the draft.' => 'Aus dem Website-Audit gefüllt: der Standard (EN 301 549 / WCAG 2.1 AA), der Status nach den Barrierefreiheits-Befunden, die bekannten Barrieren und der Kontakt. Entsteht als verborgene Seite – prüfen, dann veröffentlichen. Erneutes Erzeugen aktualisiert den Entwurf.',
    'Accessibility toolbar for visitors' => 'Barrierefreiheits-Leiste für Besucher',
    'A small button on every page: larger text, higher contrast, underlined links, reduced motion. Remembered in the visitor’s browser, no cookies.' => 'Ein kleiner Button auf jeder Seite: größere Schrift, höherer Kontrast, unterstrichene Links, reduzierte Bewegung. Im Browser des Besuchers gemerkt, ohne Cookies.',
    'The scan could not reach the site from the server (%s). The table shows what Kaleta and the known embeds set.' => 'Der Scan konnte die Website vom Server aus nicht erreichen (%s). Die Tabelle zeigt, was Kaleta und die bekannten Einbettungen setzen.',
    'Scanned %d pages: %d cookies set by the server.' => '%d Seiten gescannt: %d vom Server gesetzte Cookies.',
    'The accessibility statement is ready as a hidden page – review it, then publish it: %s' => 'Die Erklärung zur Barrierefreiheit ist als verborgene Seite bereit – prüfen, dann veröffentlichen: %s',
    'Generated on %s from the site’s configuration. A template to review and complete – not legal advice.' => 'Erzeugt am %s aus der Konfiguration der Website. Eine Vorlage zum Prüfen und Ergänzen – keine Rechtsberatung.',
    'Add what the site does not know about (paper files, accounting, other systems) and keep the record with your documentation; print it from the browser.' => 'Ergänzen Sie, was die Website nicht weiß (Papierakten, Buchhaltung, andere Systeme), und legen Sie das Verzeichnis zu Ihrer Dokumentation; drucken Sie es aus dem Browser.',
    'As Markdown (to copy)' => 'Als Markdown (zum Kopieren)',
    'After that period' => 'Nach dieser Frist',
    'delete them including attachments' => 'löschen, einschließlich Anhänge',
    'anonymise them – the row stays for statistics (date, form, page, topic, kind) without the name, e-mail, phone, message and attachments' => 'anonymisieren – die Zeile bleibt für die Statistik (Datum, Formular, Seite, Thema, Art) ohne Name, E-Mail, Telefon, Nachricht und Anhänge',
    'Anonymised' => 'Anonymisiert',
    'the row stays for statistics without the person' => 'die Zeile bleibt für die Statistik ohne die Person',
    'Blank the name, e-mail, phone, message and attachments of this enquiry? The row stays for statistics.' => 'Name, E-Mail, Telefon, Nachricht und Anhänge dieser Anfrage löschen? Die Zeile bleibt für die Statistik.',
    'Anonymise' => 'Anonymisieren',
    'The enquiry was anonymised – the row stays for statistics without the person.' => 'Die Anfrage wurde anonymisiert – die Zeile bleibt für die Statistik ohne die Person.',
    'What cookies the site sets' => 'Welche Cookies die Website setzt',
    'Controller' => 'Verantwortlicher',
    'Company: %s' => 'Unternehmen: %s',
    'Company: not filled in (Business details)' => 'Unternehmen: nicht ausgefüllt (Firmendaten)',
    'Address: %s' => 'Adresse: %s',
    'Contact: %s' => 'Kontakt: %s',
    'Contact: no site e-mail (Settings → General)' => 'Kontakt: keine E-Mail der Website (Einstellungen → Allgemein)',
    'Form “%s” on %s: fields %s; notification to %s%s' => 'Formular „%s“ auf %s: Felder %s; Benachrichtigung an %s%s',
    'the site e-mail' => 'die E-Mail der Website',
    'the sender gets a confirmation e-mail' => 'der Absender erhält eine Bestätigungs-E-Mail',
    'Enquiries and form messages' => 'Anfragen und Formularnachrichten',
    'No form on the published site.' => 'Kein Formular auf der veröffentlichten Website.',
    'Purpose: answering the enquiry and the business relationship that follows. Legal basis: performance of a contract or steps before it (Art. 6(1)(b)), legitimate interest in answering.' => 'Zweck: Beantwortung der Anfrage und die anschließende Geschäftsbeziehung. Rechtsgrundlage: Vertragserfüllung oder vorvertragliche Maßnahmen (Art. 6 Abs. 1 lit. b), berechtigtes Interesse an der Antwort.',
    'Retention: %d months, then %s automatically.' => 'Aufbewahrung: %d Monate, danach automatisch %s.',
    'anonymised (the row stays for statistics without the person)' => 'anonymisiert (die Zeile bleibt für die Statistik ohne die Person)',
    'deleted including attachments' => 'gelöscht einschließlich Anhänge',
    'Retention: not limited – set it in Enquiries → Settings.' => 'Aufbewahrung: unbegrenzt – stellen Sie sie unter Anfragen → Einstellungen ein.',
    'Recipients: the people with access to Enquiries in the administration%s.' => 'Empfänger: die Personen mit Zugriff auf Anfragen in der Verwaltung%s.',
    'a webhook at %s' => 'ein Webhook bei %s',
    'Job applications' => 'Bewerbungen',
    'Applications to job openings arrive as enquiries from the job pages, with CVs as attachments.' => 'Bewerbungen auf Stellen kommen als Anfragen von den Stellenseiten, mit Lebensläufen als Anhängen.',
    'Retention: %d months, then deleted including the CVs.' => 'Aufbewahrung: %d Monate, danach gelöscht einschließlich Lebensläufe.',
    'Retention: the same as other enquiries (%d months).' => 'Aufbewahrung: wie andere Anfragen (%d Monate).',
    'Legal basis: steps before a contract (Art. 6(1)(b)); keeping an application longer needs the applicant’s consent.' => 'Rechtsgrundlage: vorvertragliche Maßnahmen (Art. 6 Abs. 1 lit. b); eine längere Aufbewahrung braucht die Einwilligung des Bewerbers.',
    'Subscribers: %d confirmed, %d waiting for confirmation (double opt-in; unconfirmed sign-ups are deleted after 30 days).' => 'Abonnenten: %d bestätigt, %d warten auf Bestätigung (Double-Opt-in; unbestätigte Anmeldungen werden nach 30 Tagen gelöscht).',
    'Data: e-mail address, date and language of the sign-up%s.' => 'Daten: E-Mail-Adresse, Datum und Sprache der Anmeldung%s.',
    'the first page of the visit and its campaign (with consent to marketing)' => 'die erste Seite des Besuchs und ihre Kampagne (mit Einwilligung zu Marketing)',
    'Legal basis: consent (Art. 6(1)(a)); every e-mail carries an unsubscribe link.' => 'Rechtsgrundlage: Einwilligung (Art. 6 Abs. 1 lit. a); jede E-Mail enthält einen Abmeldelink.',
    'Processor: the mailing service %s (confirmed subscribers are passed to it).' => 'Auftragsverarbeiter: der Mailing-Dienst %s (bestätigte Abonnenten werden übergeben).',
    'Processor: none – the newsletter is sent from this site.' => 'Auftragsverarbeiter: keiner – der Newsletter wird von dieser Website versendet.',
    'Built-in statistics: page views, devices and campaigns counted without cookies; the visitor’s address is hashed with a daily salt and never stored.' => 'Eingebaute Statistik: Seitenaufrufe, Geräte und Kampagnen ohne Cookies gezählt; die Adresse des Besuchers wird mit einem Tages-Salt gehasht und nie gespeichert.',
    '%s – a third-party service (processor); runs only after consent in the cookie bar unless the bar is off.' => '%s – ein Drittanbieterdienst (Auftragsverarbeiter); läuft erst nach Einwilligung im Cookie-Banner, sofern das Banner nicht aus ist.',
    'No traffic statistics.' => 'Keine Besucherstatistik.',
    '%s (account %s) – data the deliveries send leaves the site to this service.' => '%s (Konto %s) – die von Zustellungen gesendeten Daten verlassen die Website zu diesem Dienst.',
    'Connected services and processors' => 'Verbundene Dienste und Auftragsverarbeiter',
    'E-mail: sent through the SMTP server %s.' => 'E-Mail: versendet über den SMTP-Server %s.',
    'E-mail: sent by the hosting server’s mail function.' => 'E-Mail: versendet über die Mail-Funktion des Hosting-Servers.',
    'Backups: automatic %s, an off-site copy over %s to %s.' => 'Backups: automatisch %s, eine externe Kopie über %s nach %s.',
    'Backups: automatic %s, kept on this server only.' => 'Backups: automatisch %s, nur auf diesem Server.',
    'Writing assistant: %s – texts the administrators ask about%s are sent to it.' => 'Schreibassistent: %s – Texte, nach denen die Administratoren fragen%s, werden dorthin gesendet.',
    'and new enquiries (triage)' => 'und neue Anfragen (Triage)',
    'Writing assistant: off.' => 'Schreibassistent: aus.',
    'Claude (MCP): administrators’ assistants work with the content; enquiries are shown to them as the Enquiries screen shows them.' => 'Claude (MCP): die Assistenten der Administratoren arbeiten mit den Inhalten; Anfragen sehen sie so, wie der Bildschirm Anfragen sie zeigt.',
    'Spam check: %s receives the visitor’s address and browser details when a form is sent.' => 'Spam-Prüfung: %s erhält beim Absenden eines Formulars die Adresse des Besuchers und Browserdaten.',
    'Spam check: built-in only (a signed time, a trap field, a limit per address) – no third party.' => 'Spam-Prüfung: nur eingebaut (signierte Zeit, Fallenfeld, Limit pro Adresse) – kein Dritter.',
    'Cookies and storage' => 'Cookies und Speicher',
    'Cookie bar: %s.' => 'Cookie-Banner: %s.',
    'built-in, tracking starts after consent' => 'eingebaut, Tracking beginnt nach Einwilligung',
    'an external service' => 'ein externer Dienst',
    'Consents are logged (time, a random identifier, the categories – no IP address)%s.' => 'Einwilligungen werden protokolliert (Zeit, eine zufällige Kennung, die Kategorien – keine IP-Adresse)%s.',
    'and deleted after %d months' => 'und nach %d Monaten gelöscht',
    'Consents are not logged.' => 'Einwilligungen werden nicht protokolliert.',
    'Security' => 'Sicherheit',
    'Access to personal data: %d administration account(s); two-step sign-in %s.' => 'Zugriff auf personenbezogene Daten: %d Verwaltungskonto/-konten; zweistufige Anmeldung %s.',
    'on for everyone' => 'für alle aktiv',
    'not on for every account' => 'nicht bei jedem Konto aktiv',
    'Firewall: on (rate limits, probes, country and address blocks).' => 'Firewall: an (Ratenlimits, Sonden, Länder- und Adresssperren).',
    'Transport: %s.' => 'Übertragung: %s.',
    'HTTP – switch the site to HTTPS' => 'HTTP – stellen Sie die Website auf HTTPS um',
    '%s is committed to making its website accessible in line with the European Accessibility Act and the national legislation that implements it. This accessibility statement applies to %s.' => '%s verpflichtet sich, seine Website im Einklang mit dem Europäischen Rechtsakt zur Barrierefreiheit und den ihn umsetzenden nationalen Vorschriften barrierefrei zugänglich zu machen. Diese Erklärung zur Barrierefreiheit gilt für %s.',
    'The website aims to meet EN 301 549 and WCAG 2.1 level AA.' => 'Die Website strebt die Erfüllung von EN 301 549 und WCAG 2.1 Stufe AA an.',
    'Compliance status: this website is fully compliant – the automatic check found no barriers.' => 'Stand der Vereinbarkeit: Diese Website ist vollständig vereinbar – die automatische Prüfung fand keine Barrieren.',
    'Compliance status: this website is partially compliant because of the non-compliances listed below.' => 'Stand der Vereinbarkeit: Diese Website ist wegen der unten aufgeführten Mängel teilweise vereinbar.',
    'Non-accessible content:' => 'Nicht barrierefreie Inhalte:',
    'This statement was prepared on %s from an automatic check of the site. The automatic check does not cover everything a person would notice; the owner reviews the statement before publishing it.' => 'Diese Erklärung wurde am %s auf Grundlage einer automatischen Prüfung der Website erstellt. Die automatische Prüfung erfasst nicht alles, was einem Menschen auffallen würde; der Betreiber prüft die Erklärung vor der Veröffentlichung.',
    'Feedback and contact: if you find a barrier or need content in another form, write to %s. We will answer as soon as we can.' => 'Rückmeldung und Kontakt: Wenn Sie auf eine Barriere stoßen oder Inhalte in anderer Form benötigen, schreiben Sie an %s. Wir antworten so bald wie möglich.',
    'Feedback and contact: add the e-mail address people can write to about barriers (Settings → General → Site e-mail).' => 'Rückmeldung und Kontakt: Ergänzen Sie die E-Mail-Adresse, an die man wegen Barrieren schreiben kann (Einstellungen → Allgemein → E-Mail der Website).',
    'Enforcement: if you are not satisfied with our answer, you can contact the body in your country that supervises the accessibility of websites.' => 'Durchsetzung: Sind Sie mit unserer Antwort nicht zufrieden, können Sie sich an die Stelle in Ihrem Land wenden, die die Barrierefreiheit von Websites überwacht.',
    'Website: %s' => 'Webseite: %s',
    'Pages nobody links to' => 'Seiten, auf die niemand verlinkt',
    'No published page, menu or text links here – visitors and search engines reach it only by its address. Add a link from a related page (Claude: suggest_internal_links).' => 'Keine veröffentlichte Seite, kein Menü und kein Text verlinkt hierher – Besucher und Suchmaschinen erreichen sie nur über die Adresse. Fügen Sie einen Link von einer verwandten Seite hinzu (Claude: suggest_internal_links).',
    '/%s now redirects to /%s by itself (score %d of 100). Undo: Administration → Redirects.' => '/%s leitet jetzt von selbst auf /%s weiter (Wert %d von 100). Rückgängig: Verwaltung → Weiterleitungen.',
    'Created by the site itself from an address visitors could not find. Delete it to undo.' => 'Von der Website selbst aus einer Adresse erstellt, die Besucher nicht gefunden haben. Zum Rückgängigmachen löschen.',
    'automatic, score %d' => 'automatisch, Wert %d',
    'By themselves' => 'Von selbst',
    'Create redirects for missing addresses by themselves' => 'Weiterleitungen für fehlende Adressen von selbst anlegen',
    'Once a day the site redirects an address visitors could not find to the page it is sure they meant (the same address written differently, moved to another section or language). Such a redirect is marked automatic; deleting it undoes it. Less certain candidates stay below as suggestions.' => 'Einmal täglich leitet die Website eine nicht gefundene Adresse auf die Seite weiter, bei der sie sicher ist, dass sie gemeint war (dieselbe Adresse anders geschrieben, in einen anderen Bereich oder eine andere Sprache verschoben). Eine solche Weiterleitung ist als automatisch markiert; Löschen macht sie rückgängig. Weniger sichere Kandidaten bleiben unten als Vorschläge.',
    'Needed score' => 'Nötiger Wert',
    '0–100; 100 = the same address written differently, 95 = another section or language, 90 = the same last part of the address, lower = a similar address.' => '0–100; 100 = dieselbe Adresse anders geschrieben, 95 = anderer Bereich oder andere Sprache, 90 = derselbe letzte Teil der Adresse, weniger = eine ähnliche Adresse.',
    'Create redirect – one click accepts the page the site thinks the visitor meant (the score says how sure it is).' => 'Weiterleitung anlegen – ein Klick übernimmt die Seite, die der Besucher laut Website gemeint hat (der Wert sagt, wie sicher sie ist).',
    'Probably meant' => 'Wahrscheinlich gemeint',
    'score %d' => 'Wert %d',
    'no similar page' => 'keine ähnliche Seite',
    'Create redirect' => 'Weiterleitung anlegen',
    'It will be checked again within a few minutes.' => 'Wird in wenigen Minuten erneut geprüft.',
    'In the background, the system goes through published news, pages and collection items – one every five minutes, each once a month – and checks whether their links still work. Checked: %s of %s.' => 'Im Hintergrund geht das System veröffentlichte Nachrichten, Seiten und Sammlungseinträge durch – einen alle fünf Minuten, jeden einmal im Monat – und prüft, ob die Links noch funktionieren. Geprüft: %s von %s.',
    'Item' => 'Eintrag',
    'element %s' => 'Element %s',
    'Redirects for addresses visitors could not find' => 'Weiterleitungen für Adressen, die Besucher nicht gefunden haben',
    'Item “%s”' => 'Eintrag „%s“',
    'Whistleblowing' => 'Hinweisgebersystem',
    'An internal reporting channel for the EU Whistleblower Directive (2019/1937) and the national laws built on it. Reports are stored encrypted and only the readers chosen below can open them – other administrators see case numbers and dates. Acknowledge a report within %d days and give feedback within %d months.' => 'Ein interner Meldekanal nach der EU-Hinweisgeberrichtlinie (2019/1937) und den darauf aufbauenden nationalen Gesetzen. Meldungen werden verschlüsselt gespeichert und nur die unten gewählten Leser können sie öffnen – andere Administratoren sehen Fallnummern und Daten. Bestätigen Sie den Eingang innerhalb von %d Tagen und geben Sie innerhalb von %d Monaten Rückmeldung.',
    'This is a tool, not legal advice: your company must appoint the person responsible for reports and check the rules of its country (who must have a channel, what the deadlines and the records are).' => 'Dies ist ein Werkzeug, keine Rechtsberatung: Ihr Unternehmen muss die für Meldungen zuständige Person benennen und die Regeln seines Landes prüfen (wer einen Kanal braucht, welche Fristen und Aufzeichnungen gelten).',
    'The channel is switched off – the public address answers with a 404 error.' => 'Der Kanal ist ausgeschaltet – die öffentliche Adresse antwortet mit einem 404-Fehler.',
    'No reader is chosen – reports arrive, but nobody can open them.' => 'Kein Leser gewählt – Meldungen kommen an, aber niemand kann sie öffnen.',
    'No reports yet.' => 'Noch keine Meldungen.',
    'The form is at %s – put a link to it in the footer menu (Menu) or on a page.' => 'Das Formular ist unter %s – setzen Sie einen Link darauf ins Fußzeilenmenü (Menü) oder auf eine Seite.',
    'Switch the channel on below and put a link to the form in the footer menu.' => 'Schalten Sie den Kanal unten ein und setzen Sie einen Link zum Formular ins Fußzeilenmenü.',
    '%d open, %d in total.' => '%d offen, %d insgesamt.',
    'Case' => 'Fall',
    'Acknowledge by' => 'Bestätigen bis',
    'Feedback by' => 'Rückmeldung bis',
    'Acknowledged' => 'Bestätigt',
    'In progress' => 'In Bearbeitung',
    'Case closed' => 'Fall abgeschlossen',
    'acknowledged %s' => 'bestätigt %s',
    'overdue' => 'überfällig',
    'closed %s' => 'abgeschlossen %s',
    'You are not among the readers, so the cases do not open for you.' => 'Sie gehören nicht zu den Lesern, daher öffnen sich die Fälle für Sie nicht.',
    'Setup' => 'Einrichtung',
    'The channel is on' => 'Der Kanal ist eingeschaltet',
    'The public form: %s. Add a link to it to the footer menu or a page – the site does not add it by itself.' => 'Das öffentliche Formular: %s. Fügen Sie einen Link darauf ins Fußzeilenmenü oder auf eine Seite ein – die Website tut das nicht von selbst.',
    'Shown above the form: who handles reports in your company, what belongs here, where the whistleblowing policy is.' => 'Wird über dem Formular angezeigt: wer im Unternehmen Meldungen bearbeitet, was hierher gehört, wo die Richtlinie steht.',
    'Who may read reports' => 'Wer Meldungen lesen darf',
    'no e-mail – will not be notified' => 'keine E-Mail – wird nicht benachrichtigt',
    'Only these people open the reports – other administrators see case numbers and dates. A new report is announced to them by e-mail with the case number only.' => 'Nur diese Personen öffnen die Meldungen – andere Administratoren sehen Fallnummern und Daten. Eine neue Meldung wird ihnen per E-Mail nur mit der Fallnummer angekündigt.',
    'Delete closed cases after' => 'Abgeschlossene Fälle löschen nach',
    'Closed cases are deleted with their attachments and messages; open cases are kept. Check the retention period your national law requires.' => 'Abgeschlossene Fälle werden mit Anhängen und Nachrichten gelöscht; offene bleiben. Prüfen Sie die Aufbewahrungsfrist, die Ihr nationales Recht verlangt.',
    'Claude and other connected tools never see the reports: no MCP tool reads or lists them, and the site export leaves them out.' => 'Claude und andere verbundene Werkzeuge sehen die Meldungen nie: kein MCP-Werkzeug liest oder listet sie, und der Website-Export lässt sie aus.',
    'All cases' => 'Alle Fälle',
    'Reporter' => 'Hinweisgeber',
    'anonymous' => 'anonym',
    'Report' => 'Meldung',
    'Attachments' => 'Anhänge',
    'Messages' => 'Nachrichten',
    'No messages yet. Your first answer acknowledges the receipt.' => 'Noch keine Nachrichten. Ihre erste Antwort bestätigt den Eingang.',
    'Handler' => 'Bearbeiter',
    'Reply to the reporter' => 'Antwort an den Hinweisgeber',
    'The reporter reads it after opening the case with the case number and the access code. Nothing is e-mailed.' => 'Der Hinweisgeber liest sie, nachdem er den Fall mit Fallnummer und Zugangscode geöffnet hat. Nichts wird per E-Mail verschickt.',
    'Send the reply' => 'Antwort senden',
    'Change the status' => 'Status ändern',
    'A closed case is deleted after the retention period set in the channel.' => 'Ein abgeschlossener Fall wird nach der im Kanal eingestellten Aufbewahrungsfrist gelöscht.',
    'Case %s' => 'Fall %s',
    'Only the appointed readers and administrators see the whistleblowing channel.' => 'Nur die benannten Leser und Administratoren sehen den Meldekanal.',
    'Saved. Choose at least one reader – until then nobody can open the reports.' => 'Gespeichert. Wählen Sie mindestens einen Leser – bis dahin kann niemand die Meldungen öffnen.',
    'Only the appointed readers open reports. An administrator can add readers in the setup of the channel.' => 'Nur die benannten Leser öffnen Meldungen. Ein Administrator kann Leser in der Einrichtung des Kanals hinzufügen.',
    'The case does not exist.' => 'Der Fall existiert nicht.',
    'Write the message first.' => 'Schreiben Sie zuerst die Nachricht.',
    'The message was added – the reporter sees it after opening the case with the code.' => 'Die Nachricht wurde hinzugefügt – der Hinweisgeber sieht sie nach dem Öffnen des Falls mit dem Code.',
    'The status is saved.' => 'Der Status ist gespeichert.',
    'Whistleblowing: due deadlines and the retention of closed cases' => 'Hinweisgebersystem: fällige Fristen und Aufbewahrung abgeschlossener Fälle',
    'Search Console property' => 'Search-Console-Property',
    'sc-domain:example.com or https://example.com/ – load the list with the button below; empty = this site’s address.' => 'sc-domain:example.com oder https://example.com/ – die Liste laden Sie mit der Schaltfläche unten; leer = die Adresse dieser Website.',
    'Site in Bing Webmaster Tools' => 'Website in den Bing Webmaster Tools',
    'The address as it is registered there, e.g. https://example.com/ – empty = this site’s address.' => 'Die Adresse, wie sie dort registriert ist, z. B. https://example.com/ – leer = die Adresse dieser Website.',
    'Load my properties' => 'Meine Properties laden',
    'The account has no Search Console property. Add the site at search.google.com/search-console first.' => 'Das Konto hat keine Search-Console-Property. Fügen Sie die Website zuerst unter search.google.com/search-console hinzu.',
    'Use:' => 'Verwenden:',
    'The properties could not be loaded: %s' => 'Die Properties konnten nicht geladen werden: %s',
    'Search data will be loaded for %s.' => 'Suchdaten werden für %s geladen.',
    'Search data could not be loaded: %s' => 'Die Suchdaten konnten nicht geladen werden: %s',
    'Choose the Search Console property in Administration → Connections.' => 'Wählen Sie die Search-Console-Property unter Verwaltung → Verbindungen.',
    'Enter the site address in Administration → Connections.' => 'Geben Sie die Adresse der Website unter Verwaltung → Verbindungen ein.',
    'Search Console and Bing data' => 'Daten aus Search Console und Bing',
    'Top queries (Google)' => 'Häufigste Suchanfragen (Google)',
    'Top pages (Google)' => 'Häufigste Seiten (Google)',
    'Top queries (Bing)' => 'Häufigste Suchanfragen (Bing)',
    'Top pages (Bing)' => 'Häufigste Seiten (Bing)',
    'Query' => 'Suchanfrage',
    'Clicks' => 'Klicks',
    'Impressions' => 'Impressionen',
    'CTR' => 'Klickrate',
    'No queries in this snapshot yet.' => 'In diesem Schnappschuss gibt es noch keine Suchanfragen.',
    'No pages in this snapshot yet.' => 'In diesem Schnappschuss gibt es noch keine Seiten.',
    'Submitted' => 'Eingereicht',
    'Indexed' => 'Indexiert',
    'Search Console has no sitemap of this site yet.' => 'Die Search Console hat noch keine Sitemap dieser Website.',
    'Search engines' => 'Suchmaschinen',
    'Connect Google Search Console or Bing Webmaster Tools in Administration → Connections; the queries and pages arrive with the daily job.' => 'Verbinden Sie die Google Search Console oder die Bing Webmaster Tools unter Verwaltung → Verbindungen; die Suchanfragen und Seiten bringt die tägliche Aufgabe.',
    'Search engines: the latest snapshot of the period (%s), each covering the 28 days before it; the position is the average place in the results, 1 = first.' => 'Suchmaschinen: der letzte Schnappschuss im Zeitraum (%s), jeder deckt die 28 Tage davor ab; die Position ist der durchschnittliche Platz in den Ergebnissen, 1 = der erste.',
    '%s on %s' => '%s bei %s',
    '%s clicks' => '%s Klicks',
    'Searches that brought visitors' => 'Suchanfragen, die Besucher brachten',
    'Position' => 'Position',
    'Sitemap' => 'Sitemap',
    'Sitemaps (Google)' => 'Sitemaps (Google)',
    'Social post drafts' => 'Entwürfe für soziale Netzwerke',
    'When a news item is published, a post draft per network is prepared under the news item – with a tracked link and the image. You copy and post it yourself; the site never posts anywhere.' => 'Nach der Veröffentlichung einer Neuigkeit wird unter ihr pro Netzwerk ein Beitragsentwurf vorbereitet – mit einem nachverfolgten Link und dem Bild. Sie kopieren und veröffentlichen ihn selbst; die Website veröffentlicht nirgendwo etwas.',
    'Social posts' => 'Beiträge für soziale Netzwerke',
    'No network is chosen. Pick the networks under Settings → General → More options and the drafts appear here.' => 'Kein Netzwerk ist ausgewählt. Wählen Sie die Netzwerke unter Einstellungen → Allgemein → Weitere Optionen, dann erscheinen die Entwürfe hier.',
    'Prepared when the news item was published, with a tracked link – the statistics show the visits from each network. Edit the text, copy it and post it yourself; the site never posts anywhere.' => 'Bei der Veröffentlichung der Neuigkeit vorbereitet, mit einem nachverfolgten Link – die Statistik zeigt die Besuche aus jedem Netzwerk. Bearbeiten Sie den Text, kopieren und veröffentlichen Sie ihn selbst; die Website veröffentlicht nirgendwo etwas.',
    'Rewrite all the drafts with the assistant? Your edits to them are replaced. Hashtags and the link are added back.' => 'Alle Entwürfe mit dem Assistenten neu schreiben? Ihre Änderungen werden ersetzt. Hashtags und der Link werden wieder ergänzt.',
    'Suggest with the assistant' => 'Mit dem Assistenten vorschlagen',
    'posted %s' => 'veröffentlicht %s',
    'Post for %s' => 'Beitrag für %s',
    'At most %d characters; a link counts as %d.' => 'Höchstens %d Zeichen; ein Link zählt als %d.',
    'Image:' => 'Bild:',
    'Link for the bio:' => 'Link für die Bio:',
    'Not posted yet' => 'Noch nicht veröffentlicht',
    'Mark as posted' => 'Als veröffentlicht markieren',
    'Social post drafts waiting to be posted' => 'Beitragsentwürfe, die auf die Veröffentlichung warten',
    'The post draft is saved.' => 'Der Beitragsentwurf ist gespeichert.',
    'Marked as posted.' => 'Als veröffentlicht markiert.',
    'Marked as not posted yet.' => 'Als noch nicht veröffentlicht markiert.',
    'The assistant rewrote the drafts – read them before posting.' => 'Der Assistent hat die Entwürfe neu geschrieben – lesen Sie sie vor der Veröffentlichung.',
    'The draft does not exist.' => 'Der Entwurf existiert nicht.',
    'The post needs a text.' => 'Der Beitrag braucht einen Text.',
    'The post is too long (at most 3000 characters).' => 'Der Beitrag ist zu lang (höchstens 3000 Zeichen).',
    'X allows 280 characters with a link counted as 23 – this post is longer.' => 'X erlaubt 280 Zeichen, ein Link zählt als 23 – dieser Beitrag ist länger.',
    'There are no drafts to rewrite.' => 'Es gibt keine Entwürfe zum Neuschreiben.',
    'Link in bio' => 'Link in der Bio',
    'Business Profile' => 'Unternehmensprofil',
    'The opening hours from Business details and their exceptions go to the chosen location whenever they change and once a day; the newest reviews and the rating come back for the Google reviews element and the facts {{fact.google_rating}} and {{fact.google_reviews}}.' => 'Die Öffnungszeiten aus Firmendaten und ihre Ausnahmen gehen bei jeder Änderung und einmal täglich an den gewählten Standort; die neuesten Bewertungen und die Bewertung kommen für das Element Google-Bewertungen und die Fakten {{fact.google_rating}} und {{fact.google_reviews}} zurück.',
    '– none, nothing is synced –' => '– keiner, nichts wird synchronisiert –',
    'Load the locations of the connected account with the button below.' => 'Laden Sie die Standorte des verbundenen Kontos mit der Schaltfläche unten.',
    'Connect Google first.' => 'Verbinden Sie zuerst Google.',
    'Post news to the Business Profile' => 'News im Unternehmensprofil veröffentlichen',
    'Every newly published news item becomes a post with its image and a “Learn more” button.' => 'Jeder neu veröffentlichte News-Beitrag wird ein Beitrag mit seinem Bild und einer Schaltfläche „Mehr erfahren“.',
    'Google rating %s out of 5 from %d reviews' => 'Google-Bewertung %s von 5 aus %d Bewertungen',
    'No reviews on Google yet.' => 'Noch keine Bewertungen auf Google.',
    'fetched %s' => 'abgerufen %s',
    'Load my locations' => 'Meine Standorte laden',
    'Sync the Business Profile now' => 'Unternehmensprofil jetzt synchronisieren',
    'The locations could not be loaded: %s' => 'Die Standorte konnten nicht geladen werden: %s',
    'The Google account manages no Business Profile location.' => 'Das Google-Konto verwaltet keinen Standort des Unternehmensprofils.',
    '%d locations loaded – choose one and save.' => '%d Standorte geladen – wählen Sie einen und speichern Sie.',
    'The hours were sent and the reviews fetched.' => 'Die Öffnungszeiten wurden gesendet und die Bewertungen abgerufen.',
    'The reviews could not be fetched: %s' => 'Die Bewertungen konnten nicht abgerufen werden: %s',
    'Business Profile location' => 'Standort des Unternehmensprofils',
    'accounts/…/locations/… – choose it from the loaded list' => 'accounts/…/locations/… – aus der geladenen Liste wählen',
    'Google Business Profile: hours out, reviews in' => 'Google Unternehmensprofil: Öffnungszeiten hinaus, Bewertungen herein',
    'Google rating' => 'Google-Bewertung',
    'Google reviews (count)' => 'Google-Bewertungen (Anzahl)',
    'Google reviews' => 'Google-Bewertungen',
    'The newest reviews from your Google Business Profile with the rating – they update themselves daily.' => 'Die neuesten Bewertungen aus Ihrem Google Unternehmensprofil mit der Bewertung – sie aktualisieren sich täglich selbst.',
    'Number of reviews' => 'Anzahl der Bewertungen',
    'Only reviews with at least this many stars' => 'Nur Bewertungen mit mindestens so vielen Sternen',
    'Show the average rating and the count' => 'Durchschnittsbewertung und Anzahl anzeigen',
    'Link to all reviews (your Google Maps address)' => 'Link zu allen Bewertungen (Ihre Google-Maps-Adresse)',
    'Send enquiries here' => 'Anfragen hierher senden',
    'Only these forms' => 'Nur diese Formulare',
    'Form names separated by commas; empty = every form' => 'Formularnamen durch Komma getrennt; leer = jedes Formular',
    'Include job applications' => 'Bewerbungen einschließen',
    'They carry CVs – only the file name goes out, never the file' => 'Sie enthalten Lebensläufe – nur der Dateiname geht hinaus, nie die Datei',
    'Enquiries to a sheet' => 'Anfragen in eine Tabelle',
    'Spreadsheet ID' => 'Tabellen-ID',
    'Filled in by “Create the sheet”; clear it to have a new sheet created' => 'Wird von „Tabelle erstellen“ ausgefüllt; leeren, damit eine neue Tabelle erstellt wird',
    'Company domain' => 'Firmendomain',
    'The <x> of <x>.pipedrive.com' => 'Das <x> aus <x>.pipedrive.com',
    'Instance name' => 'Instanzname',
    'The instance of your Raynet account (X-Instance-Name)' => 'Die Instanz Ihres Raynet-Kontos (X-Instance-Name)',
    'Create the sheet' => 'Tabelle erstellen',
    'Open the sheet' => 'Tabelle öffnen',
    'Create the sheet first – without it no enquiry is sent.' => 'Erstellen Sie zuerst die Tabelle – ohne sie wird keine Anfrage gesendet.',
    'The sheet was created – tick “Enquiries to a sheet” and new enquiries will appear in it.' => 'Die Tabelle wurde erstellt – haken Sie „Anfragen in eine Tabelle“ an, und neue Anfragen erscheinen darin.',
    '%s – enquiries' => '%s – Anfragen',
    'Connect Google first.' => 'Verbinden Sie zuerst Google.',
    'Google did not return the sheet.' => 'Google hat die Tabelle nicht zurückgegeben.',
    'No sheet – create it in Administration → Connections.' => 'Keine Tabelle – erstellen Sie sie unter Administration → Anbindungen.',
    'Enter the company domain of Pipedrive in Connections.' => 'Geben Sie die Firmendomain von Pipedrive unter Anbindungen ein.',
    'Enter the Raynet instance name in Connections.' => 'Geben Sie den Raynet-Instanznamen unter Anbindungen ein.',
    'Fields' => 'Felder',
    'Why: %s' => 'Warum: %s',
    'Guardrails for Claude' => 'Leitplanken für Claude',
    'They hold for every Claude connection on top of its access. Claude is told why when it hits one, so it can tell you.' => 'Sie gelten für jede Claude-Verbindung zusätzlich zu ihren Rechten. Stößt Claude an eine, erfährt es den Grund und kann es Ihnen sagen.',
    'Changes per connection and hour' => 'Änderungen pro Verbindung und Stunde',
    '0 = no limit. A long run of changes stops here until the next hour.' => '0 = keine Grenze. Eine lange Reihe von Änderungen stoppt hier bis zur nächsten Stunde.',
    'Deleting' => 'Löschen',
    'Claude may delete, trash and discard drafts' => 'Claude darf löschen, in den Papierkorb legen und Entwürfe verwerfen',
    'Off: those tools are refused for every connection; you do them in the admin.' => 'Aus: diese Werkzeuge werden für jede Verbindung abgelehnt; Sie erledigen das in der Verwaltung.',
    'Protected pages' => 'Geschützte Seiten',
    'Page numbers (shown in the page editor’s address) that Claude must not change – neither their settings nor their build.' => 'Seitennummern (in der Adresse des Seiteneditors), die Claude nicht ändern darf – weder Einstellungen noch Build.',
    'Notebook' => 'Notizbuch',
    'New note' => 'Neue Notiz',
    'The note does not exist.' => 'Die Notiz existiert nicht.',
    'The note is saved.' => 'Die Notiz ist gespeichert.',
    'The note is deleted.' => 'Die Notiz ist gelöscht.',
    'A note needs a title.' => 'Eine Notiz braucht einen Titel.',
    'A note needs a text.' => 'Eine Notiz braucht einen Text.',
    'The topic must be one of: %s.' => 'Das Thema muss eines davon sein: %s.',
    'Notes for whoever works on the site next – Claude in a new conversation, or a colleague: decisions, wording rules, photo credits, the history of the site, what the client is sensitive about. Claude reads them with read_notebook before larger changes and writes decisions down with write_notebook – a drafts-only connection too. Nothing here is shown on the site.' => 'Notizen für alle, die als Nächstes an der Website arbeiten – Claude in einem neuen Gespräch oder ein Kollege: Entscheidungen, Formulierungsregeln, Bildnachweise, die Geschichte der Website, worauf der Kunde empfindlich reagiert. Claude liest sie vor größeren Änderungen mit read_notebook und schreibt Entscheidungen mit write_notebook auf – auch eine Anbindung nur für Entwürfe. Nichts davon wird auf der Website angezeigt.',
    'All topics' => 'Alle Themen',
    'Decisions' => 'Entscheidungen',
    'Style and wording' => 'Stil und Formulierungen',
    'Credits' => 'Nachweise',
    'Search (title, text):' => 'Suche (Titel, Text):',
    'No note matches the filter.' => 'Keine Notiz entspricht dem Filter.',
    'Try another word or topic.' => 'Versuchen Sie ein anderes Wort oder Thema.',
    'No notes yet.' => 'Noch keine Notizen.',
    'Write down what the next person – or Claude – should know: a decision, a wording rule, who took the photos, why a page looks the way it does.' => 'Halten Sie fest, was die nächste Person – oder Claude – wissen sollte: eine Entscheidung, eine Formulierungsregel, wer fotografiert hat, warum eine Seite so aussieht, wie sie aussieht.',
    'pinned' => 'angeheftet',
    'Unpin' => 'Loslösen',
    'Pin' => 'Anheften',
    'Delete the note? It cannot be brought back.' => 'Notiz löschen? Sie kann nicht wiederhergestellt werden.',
    'Only the first %d notes are shown – narrow the list by a topic or a search.' => 'Es werden nur die ersten %d Notizen angezeigt – grenzen Sie die Liste nach Thema oder Suche ein.',
    'All notes' => 'Alle Notizen',
    'e.g. We never use the word “cheap”' => 'z. B. Wir verwenden nie das Wort „billig“',
    'Plain text. Write it for someone who knows nothing about the site yet – what was decided, why, and what to keep to.' => 'Reiner Text. Schreiben Sie ihn für jemanden, der die Website noch nicht kennt – was entschieden wurde, warum und woran man sich halten soll.',
    'Pinned' => 'Angeheftet',
    'Pinned notes come first and Claude sees their titles as soon as it connects.' => 'Angeheftete Notizen stehen zuerst, und Claude sieht ihre Titel, sobald es sich verbindet.',
    'Written by %s, %s; last changed %s.' => 'Verfasst von %s, %s; zuletzt geändert %s.',
    'Requests' => 'Aufträge',
    'New request' => 'Neuer Auftrag',
    'New' => 'Neu',
    'Declined' => 'Abgelehnt',
    '(no longer exists)' => '(existiert nicht mehr)',
    'A new request for Claude: %s' => 'Ein neuer Auftrag an Claude: %s',
    '(account removed)' => '(Konto entfernt)',
    'New request for Claude: %s' => 'Neuer Auftrag an Claude: %s',
    'A colleague wrote a new request for Claude: %s' => 'Ein Kollege hat einen neuen Auftrag an Claude geschrieben: %s',
    'Your request is done: %s' => 'Ihr Auftrag ist erledigt: %s',
    'Your request “%s” is marked done.' => 'Ihr Auftrag „%s“ ist als erledigt markiert.',
    'The drafts wait for your review in the administration – nothing was published by itself.' => 'Die Entwürfe warten in der Verwaltung auf Ihre Prüfung – nichts wurde von selbst veröffentlicht.',
    'The attachment %s could not be saved: %s' => 'Der Anhang %s konnte nicht gespeichert werden: %s',
    'Request #%d' => 'Auftrag Nr. %d',
    'The request is saved. Claude will see it the next time it works on the site; you will read its notes here.' => 'Der Auftrag ist gespeichert. Claude sieht ihn, wenn es das nächste Mal an der Website arbeitet; seine Notizen lesen Sie hier.',
    'The request does not exist.' => 'Der Auftrag existiert nicht.',
    'Write the reply first.' => 'Schreiben Sie zuerst die Antwort.',
    'The reply is added – Claude reads it with the request.' => 'Die Antwort ist hinzugefügt – Claude liest sie mit dem Auftrag.',
    'This status change is not possible.' => 'Diese Statusänderung ist nicht möglich.',
    'Write what should change on the site – "change the opening hours on Monday", "add this PDF to the price list" – and Claude does it as drafts the next time it works on the site. Its notes and the links to the drafts appear in the request; a person reviews and publishes them.' => 'Schreiben Sie, was sich auf der Website ändern soll – „Öffnungszeiten am Montag ändern“, „dieses PDF in die Preisliste aufnehmen“ – und Claude erledigt es als Entwürfe, wenn es das nächste Mal an der Website arbeitet. Seine Notizen und die Links zu den Entwürfen erscheinen im Auftrag; ein Mensch prüft und veröffentlicht sie.',
    'The Claude connection is switched off (Features) – requests are saved, but nobody reads them until it is on.' => 'Die Claude-Verbindung ist ausgeschaltet (Funktionen) – Aufträge werden gespeichert, aber niemand liest sie, bis sie eingeschaltet ist.',
    'Request status' => 'Status des Auftrags',
    'No request has this status.' => 'Kein Auftrag hat diesen Status.',
    'No requests yet.' => 'Noch keine Aufträge.',
    'Write the first one: what should change, on which page, with the files Claude needs.' => 'Schreiben Sie die erste: was sich ändern soll, auf welcher Seite, mit den Dateien, die Claude braucht.',
    '%d open, %d shown.' => '%d offen, %d angezeigt.',
    'Request' => 'Auftrag',
    'Written' => 'Geschrieben',
    'Last change' => 'Letzte Änderung',
    '%d attachments' => '%d Anhänge',
    'All requests' => 'Alle Aufträge',
    'What should change' => 'Was sich ändern soll',
    'e.g. Opening hours on Monday' => 'z. B. Öffnungszeiten am Montag',
    'Write it as you would to a colleague: what, where on the site, and by when it matters.' => 'Schreiben Sie es wie an einen Kollegen: was, wo auf der Website und bis wann es wichtig ist.',
    'Claude reads it as a job to do as drafts – it never publishes anything by itself; you or an administrator review and publish the drafts.' => 'Claude liest es als Aufgabe, die es in Entwürfen erledigt – es veröffentlicht nie etwas von selbst; Sie oder ein Administrator prüfen und veröffentlichen die Entwürfe.',
    'It is about' => 'Betrifft',
    '— the site in general —' => '— die Website allgemein —',
    'or paste the address, e.g. /price-list' => 'oder die Adresse einfügen, z. B. /preisliste',
    'Address of the page it is about' => 'Adresse der betroffenen Seite',
    'Up to %d files – a PDF, a photo, a document (%s each at most). They are saved to Media, so Claude can place them on the site.' => 'Bis zu %d Dateien – ein PDF, ein Foto, ein Dokument (je höchstens %s). Sie werden in den Medien gespeichert, damit Claude sie auf der Website platzieren kann.',
    'Save the request' => 'Auftrag speichern',
    'Saved in Media – Claude places them on the site from there.' => 'In den Medien gespeichert – Claude platziert sie von dort auf der Website.',
    'Conversation' => 'Unterhaltung',
    'No notes yet. Claude writes here what it did and where the drafts are; you can reply below.' => 'Noch keine Notizen. Claude schreibt hier, was es getan hat und wo die Entwürfe sind; unten können Sie antworten.',
    'Colleague' => 'Kollege',
    'Drafts:' => 'Entwürfe:',
    'Reply' => 'Antwort',
    'Claude reads the reply with the request the next time it works on the site.' => 'Claude liest die Antwort mit dem Auftrag, wenn es das nächste Mal an der Website arbeitet.',
    'Add the reply' => 'Antwort hinzufügen',
    'Done = the drafts are reviewed and published, or nothing more is needed. Declined = it will not be done.' => 'Erledigt = die Entwürfe sind geprüft und veröffentlicht, oder es ist nichts mehr nötig. Abgelehnt = es wird nicht gemacht.',
    'The comment does not exist.' => 'Der Kommentar existiert nicht.',
    'Comments from people with a preview link, waiting in the builder.' => 'Kommentare von Personen mit Vorschau-Link, sie warten im Builder.',
    '%d comments' => '%d Kommentare',
    'New comment on the draft of “%s”' => 'Neuer Kommentar zum Entwurf „%s“',
    '%s commented on the draft of the page “%s” through a preview link:' => '%s hat den Entwurf der Seite „%s“ über einen Vorschau-Link kommentiert:',
    'Open the builder to read it in full and resolve it. A comment is feedback to act on in the draft; nothing publishes by itself.' => 'Im Builder lesen Sie ihn vollständig und erledigen ihn. Ein Kommentar ist Rückmeldung zum Entwurf; nichts wird von selbst veröffentlicht.',
    'A comment on the draft of “%s” arrived from a preview link.' => 'Zum Entwurf „%s“ kam ein Kommentar über einen Vorschau-Link.',
    'Shared kit' => 'Gemeinsames Kit',
    'Shared design kit' => 'Gemeinsames Design-Kit',
    'The kit carries the design of this console – its design system, shared classes, components and saved sections – to the sites that chose to receive it (Settings → Fleet console on the site). A site gets each version as drafts only: the look draft, component drafts and its section library. Its people review and publish; nothing goes live by itself. Custom code never travels in a kit.' => 'Das Kit trägt das Design dieser Konsole – ihr Designsystem, gemeinsame Klassen, Komponenten und gespeicherte Abschnitte – zu den Websites, die es empfangen möchten (auf der Website unter Einstellungen → Website-Konsole). Eine Website erhält jede Version nur als Entwürfe: den Look-Entwurf, Komponenten-Entwürfe und ihre Abschnittsbibliothek. Ihre Leute prüfen und veröffentlichen; nichts geht von selbst live. Eigener Code reist nie in einem Kit.',
    'What the kit contains' => 'Was das Kit enthält',
    'Colours, fonts and sizes' => 'Farben, Schriften und Größen',
    'The console has no shared classes.' => 'Die Konsole hat keine gemeinsamen Klassen.',
    'All classes (%d)' => 'Alle Klassen (%d)',
    'The console has no components.' => 'Die Konsole hat keine Komponenten.',
    'draft only' => 'nur Entwurf',
    'Saved sections' => 'Gespeicherte Abschnitte',
    'The console has no saved sections.' => 'Die Konsole hat keine gespeicherten Abschnitte.',
    'Publish kit version %d? Every site that receives the kit gets it as drafts with its next report.' => 'Kit-Version %d veröffentlichen? Jede Website, die das Kit empfängt, erhält es mit ihrem nächsten Bericht als Entwürfe.',
    'Publish a new kit version' => 'Neue Kit-Version veröffentlichen',
    'A component or section keeps a stable key (from its name): a site updates its copy instead of adding another.' => 'Eine Komponente oder ein Abschnitt behält einen festen Schlüssel (aus dem Namen): eine Website aktualisiert ihre Kopie, statt eine weitere hinzuzufügen.',
    'Published' => 'Veröffentlicht',
    'Contents' => 'Inhalt',
    'Sites on this version' => 'Websites auf dieser Version',
    'Which version each site applied' => 'Welche Version jede Website übernommen hat',
    'Kit version' => 'Kit-Version',
    'does not receive the kit' => 'empfängt das Kit nicht',
    'A site reports the version it applied with its next report; a site that did not switch the kit on shows none.' => 'Eine Website meldet die übernommene Version mit ihrem nächsten Bericht; eine Website, die das Kit nicht eingeschaltet hat, zeigt keine.',
    'Kit version %d is published (%s). Every site that receives the kit picks it up with its next report, within an hour – as drafts for its people to publish.' => 'Kit-Version %d ist veröffentlicht (%s). Jede Website, die das Kit empfängt, holt es mit ihrem nächsten Bericht, innerhalb einer Stunde – als Entwürfe, die ihre Leute veröffentlichen.',
    'Choose at least one thing for the kit: the design system, a class, a component or a section.' => 'Wählen Sie mindestens eine Sache für das Kit: das Designsystem, eine Klasse, eine Komponente oder einen Abschnitt.',
    'The kit is too large (%s) – choose fewer components or sections.' => 'Das Kit ist zu groß (%s) – wählen Sie weniger Komponenten oder Abschnitte.',
    'Kit version %d was published for the fleet: %s.' => 'Kit-Version %d wurde für die Websites veröffentlicht: %s.',
    'Kit version %d from the console arrived as drafts: %s.' => 'Kit-Version %d von der Konsole ist als Entwürfe angekommen: %s.',
    'Kit version %d from the console was refused: %s' => 'Kit-Version %d von der Konsole wurde abgelehnt: %s',
    'The console can share a design kit – its design system, shared classes, components and saved sections. Here it arrives as drafts only: into the look draft, into component drafts and into the section library. Nothing is published until you publish it. Custom code never travels in a kit.' => 'Die Konsole kann ein Design-Kit teilen – ihr Designsystem, gemeinsame Klassen, Komponenten und gespeicherte Abschnitte. Hier kommt es nur als Entwürfe an: in den Look-Entwurf, in Komponenten-Entwürfe und in die Abschnittsbibliothek. Nichts wird veröffentlicht, bis Sie es veröffentlichen. Eigener Code reist nie in einem Kit.',
    'Receive the shared design kit' => 'Das gemeinsame Design-Kit empfangen',
    'Received kit version %d on %s.' => 'Kit-Version %d empfangen am %s.',
    'The look draft and the component drafts are waiting for your review:' => 'Der Look-Entwurf und die Komponenten-Entwürfe warten auf Ihre Prüfung:',
    'The last kit was refused: %s' => 'Das letzte Kit wurde abgelehnt: %s',
    'Save the choice about the kit' => 'Wahl zum Kit speichern',
    'The choice about the shared kit is saved.' => 'Die Wahl zum gemeinsamen Kit ist gespeichert.',
    'The console did not hand over the kit (%s).' => 'Die Konsole hat das Kit nicht übergeben (%s).',
    'The kit is not signed by the console – refused.' => 'Das Kit ist nicht von der Konsole signiert – abgelehnt.',
    'The console handed over a different kit version than it announced – refused.' => 'Die Konsole hat eine andere Kit-Version übergeben, als sie angekündigt hat – abgelehnt.',
    'The kit is too large – refused.' => 'Das Kit ist zu groß – abgelehnt.',
    'The kit does not match the hash the console announced – refused.' => 'Das Kit passt nicht zum Hash, den die Konsole angekündigt hat – abgelehnt.',
    'The kit is not readable – refused.' => 'Das Kit ist nicht lesbar – abgelehnt.',
    'Design system' => 'Designsystem',
    'Claude sessions' => 'Claude-Sitzungen',
    'undo everything one Claude session changed' => 'alles rückgängig machen, was eine Claude-Sitzung geändert hat',
    'Changes one Claude connection makes in a row (with less than %d minutes between them) form a session. Undo puts back everything the session changed – pages, builds and drafts, news, collection items, menus, settings, the look – as it was before. Sessions are kept %d days.' => 'Änderungen, die eine Claude-Verbindung nacheinander macht (mit weniger als %d Minuten Abstand), bilden eine Sitzung. Rückgängig stellt alles wieder her, was die Sitzung geändert hat – Seiten, Builds und Entwürfe, News, Sammlungseinträge, Menüs, Einstellungen, Erscheinungsbild – wie es vorher war. Sitzungen werden %d Tage aufbewahrt.',
    '%d rows were changed after the session (by a person or another session) and were left as they are. Undo again with “Also overwrite later changes” to put them back too.' => '%d Zeilen wurden nach der Sitzung geändert (von einem Menschen oder einer anderen Sitzung) und bleiben, wie sie sind. Machen Sie die Sitzung mit „Auch spätere Änderungen überschreiben“ erneut rückgängig, um auch sie zurückzusetzen.',
    'These changes could not be followed row by row and stay as they are – check them by hand:' => 'Diese Änderungen ließen sich nicht zeilenweise verfolgen und bleiben, wie sie sind – prüfen Sie sie von Hand:',
    'No Claude session yet.' => 'Noch keine Claude-Sitzung.',
    'Connection' => 'Verbindung',
    'Changes that undo cannot follow' => 'Änderungen, die das Rückgängigmachen nicht verfolgen kann',
    'Undone %s by %s' => 'Rückgängig gemacht %s von %s',
    'Undo everything this session changed?' => 'Alles rückgängig machen, was diese Sitzung geändert hat?',
    'Also overwrite later changes' => 'Auch spätere Änderungen überschreiben',
    'Undo the session' => 'Sitzung rückgängig machen',
    'The session is undone: %d rows restored, %d removed.' => 'Die Sitzung ist rückgängig gemacht: %d Zeilen wiederhergestellt, %d entfernt.',
    'A Claude session was undone: %d rows restored, %d removed, %d left because they changed since.' => 'Eine Claude-Sitzung wurde rückgängig gemacht: %d Zeilen wiederhergestellt, %d entfernt, %d belassen, weil sie sich seitdem geändert haben.',
    'The session does not exist.' => 'Die Sitzung existiert nicht.',
    'This session was already undone.' => 'Diese Sitzung wurde bereits rückgängig gemacht.',
    'Add-ons are code from other developers. Copy an add-on into the folder extensions/<name>/ on your hosting and switch it on here. An add-on runs with the same rights as Kaleta – switch on only code you trust, from a source you know. Kaleta never uploads or downloads add-ons by itself.' => 'Add-ons sind Code anderer Entwickler. Kopieren Sie ein Add-on auf Ihrem Hosting in den Ordner extensions/<name>/ und schalten Sie es hier ein. Ein Add-on läuft mit denselben Rechten wie Kaleta – schalten Sie nur Code ein, dem Sie vertrauen, aus einer Quelle, die Sie kennen. Kaleta lädt Add-ons nie selbst hoch oder herunter.',
    'A developer’s guide is in docs/EXTENSIONS.md. This Kaleta offers extension API %d.' => 'Eine Anleitung für Entwickler steht in docs/EXTENSIONS.md. Diese Kaleta bietet die Erweiterungs-API %d.',
    'Add-ons do not run in the public demo.' => 'In der öffentlichen Demo laufen keine Add-ons.',
    'Add-ons are switched off in config.php (safe mode) – none is loaded.' => 'Add-ons sind in config.php ausgeschaltet (abgesicherter Modus) – keines wird geladen.',
    'No add-on in extensions/ yet.' => 'Noch kein Add-on in extensions/.',
    'Add-on' => 'Zusatzmodul',
    'Switched off after an error: %s' => 'Nach einem Fehler ausgeschaltet: %s',
    'On' => 'Ein',
    'Off' => 'Aus',
    'Switch off' => 'Ausschalten',
    'I trust this code' => 'Ich vertraue diesem Code',
    'Switch on' => 'Einschalten',
    'Pages of add-ons' => 'Seiten der Add-ons',
    'This page belongs to the add-on %s.' => 'Diese Seite gehört zum Add-on %s.',
    'Tick that you trust the code of this add-on.' => 'Bestätigen Sie, dass Sie dem Code dieses Add-ons vertrauen.',
    'The add-on is switched on.' => 'Das Add-on ist eingeschaltet.',
    'The add-on is switched off – its data stays.' => 'Das Add-on ist ausgeschaltet – seine Daten bleiben.',
    'The add-on page does not exist or its add-on is switched off.' => 'Die Add-on-Seite existiert nicht oder ihr Add-on ist ausgeschaltet.',
    'The add-on failed: %s' => 'Das Add-on ist fehlgeschlagen: %s',
    'The add-on %s was switched on.' => 'Das Add-on %s wurde eingeschaltet.',
    'The add-on %s failed and was switched off: %s' => 'Das Add-on %s ist fehlgeschlagen und wurde ausgeschaltet: %s',
    'The folder name must be lowercase letters, digits and _ (it is the add-on\'s slug).' => 'Der Ordnername darf nur Kleinbuchstaben, Ziffern und _ enthalten (er ist die Kennung des Add-ons).',
    'extension.json is not valid JSON.' => 'extension.json ist kein gültiges JSON.',
    'extension.json has no valid "class".' => 'extension.json hat keine gültige "class".',
    'The entry file is missing or not a .php file inside the add-on.' => 'Die Einstiegsdatei fehlt oder ist keine .php-Datei im Add-on.',
    'Add-ons' => 'Zusatzmodule',
    'Also:' => 'Außerdem:',
    'Handed out but not reported within %d hours – written off by the site.' => 'Übergeben, aber nicht innerhalb von %d Stunden gemeldet – von der Website abgeschrieben.',
    'The scheduled Claude run “%s” was not picked up – check the routine in Claude (Scheduled runs).' => 'Der geplante Claude-Lauf „%s“ wurde nicht abgeholt – prüfen Sie die Routine in Claude (Geplante Läufe).',
    'Give the schedule a name.' => 'Geben Sie dem Zeitplan einen Namen.',
    'Choose what the run does.' => 'Wählen Sie, was der Lauf tut.',
    'Write the instructions for the run.' => 'Schreiben Sie die Anweisungen für den Lauf.',
    'Choose how often it runs.' => 'Wählen Sie, wie oft er läuft.',
    'Choose the day of the week.' => 'Wählen Sie den Wochentag.',
    'The day of the month must be 1–28, so that every month has it.' => 'Der Tag im Monat muss 1–28 sein, damit jeder Monat ihn hat.',
    'The time must be HH:MM.' => 'Die Uhrzeit muss das Format HH:MM haben.',
    'The schedule does not exist.' => 'Der Zeitplan existiert nicht.',
    'The schedule is saved. The site hands the run to the routine in Claude when its time comes – set the routine up below if you have not yet.' => 'Der Zeitplan ist gespeichert. Wenn seine Zeit kommt, übergibt die Website den Lauf an die Routine in Claude – richten Sie die Routine unten ein, falls noch nicht geschehen.',
    'The schedule and its history are deleted.' => 'Der Zeitplan und seine Historie sind gelöscht.',
    'The schedule is active again.' => 'Der Zeitplan ist wieder aktiv.',
    'The schedule is paused – no runs are handed out until you resume it.' => 'Der Zeitplan ist pausiert – bis Sie ihn fortsetzen, werden keine Läufe übergeben.',
    'Scheduled runs' => 'Geplante Läufe',
    'no run yet' => 'noch kein Lauf',
    'every %s at %s' => 'wöchentlich, %s um %s',
    'every month on day %d at %s' => 'monatlich am %d. um %s',
    'every day at %s' => 'täglich um %s',
    'The site cannot run Claude by itself. It keeps the schedules below, tells a routine in Claude what is due, records each run and notices runs nobody picked up. The run itself happens in Claude – a scheduled task in the Claude app or a Claude Code routine – connected to this site with drafts-only access, so a run never publishes, deletes or sends anything.' => 'Die Website kann Claude nicht selbst ausführen. Sie bewahrt die Zeitpläne unten auf, sagt einer Routine in Claude, was fällig ist, zeichnet jeden Lauf auf und bemerkt Läufe, die niemand abgeholt hat. Der Lauf selbst findet in Claude statt – als geplante Aufgabe in der Claude-App oder als Claude-Code-Routine – verbunden mit dieser Website mit Zugriff nur auf Entwürfe, sodass ein Lauf nie etwas veröffentlicht, löscht oder sendet.',
    'The Claude connection is switched off (Features) – the schedules are kept, but no routine can pick the runs up until it is on.' => 'Die Claude-Verbindung ist ausgeschaltet (Funktionen) – die Zeitpläne bleiben erhalten, aber keine Routine kann die Läufe abholen, bis sie eingeschaltet ist.',
    'New schedule' => 'Neuer Zeitplan',
    'No schedules yet.' => 'Noch keine Zeitpläne.',
    'Typical ones: a site review every Monday, a report on the first of the month, a triage of new enquiries every morning, the open requests from staff every day.' => 'Typische Zeitpläne: eine Website-Prüfung jeden Montag, ein Bericht am Monatsersten, eine Sortierung neuer Anfragen jeden Morgen, die offenen Aufträge des Teams jeden Tag.',
    'Schedule' => 'Zeitplan',
    'Next due' => 'Nächster Termin',
    'paused' => 'pausiert',
    'Pause' => 'Pausieren',
    'Resume' => 'Fortsetzen',
    'Set up in Claude' => 'In Claude einrichten',
    'Connect Claude to this site with a drafts-only token or connection: My account → Claude connection, access “drafts only”. A drafts-only connection can read the site and save drafts, and the two tools the routine needs (get_due_agent_runs, report_agent_run) – it cannot publish, delete or send.' => 'Verbinden Sie Claude mit dieser Website über ein Token oder eine Verbindung nur für Entwürfe: Mein Konto → Claude-Verbindung, Zugriff „nur Entwürfe“. Eine solche Verbindung kann die Website lesen, Entwürfe speichern und die beiden Werkzeuge der Routine aufrufen (get_due_agent_runs, report_agent_run) – sie kann nicht veröffentlichen, löschen oder senden.',
    'no drafts-only token yet' => 'noch kein Token nur für Entwürfe',
    'In Claude, create a scheduled task (the Claude app) or a routine (Claude Code) that runs a little after the earliest time in your schedules – for example every day at 07:15 – with this prompt:' => 'Erstellen Sie in Claude eine geplante Aufgabe (Claude-App) oder eine Routine (Claude Code), die kurz nach der frühesten Zeit Ihrer Zeitpläne läuft – zum Beispiel täglich um 07:15 – mit diesem Prompt:',
    'The routine asks the site what is due, does each run as drafts and reports it; the summary and the links to the drafts appear in the history here. You review and publish. A run nobody picks up within 6 hours is marked missed and reported in the events and the alert e-mails.' => 'Die Routine fragt die Website, was fällig ist, erledigt jeden Lauf als Entwürfe und meldet ihn; die Zusammenfassung und die Links zu den Entwürfen erscheinen hier in der Historie. Sie prüfen und veröffentlichen. Ein Lauf, den innerhalb von 6 Stunden niemand abholt, wird als verpasst markiert und in den Ereignissen und den Warn-E-Mails gemeldet.',
    'Claude never runs on the site: the site holds no Claude sign-in and creates no tokens here – the routine lives in your Claude account and connects with the token you give it.' => 'Claude läuft nie auf der Website: Sie hält keine Claude-Anmeldung und erstellt hier keine Token – die Routine lebt in Ihrem Claude-Konto und verbindet sich mit dem Token, das Sie ihr geben.',
    'All schedules' => 'Alle Zeitpläne',
    'e.g. Monday site review' => 'z. B. Website-Prüfung am Montag',
    'What the run does' => 'Was der Lauf tut',
    'The built-in tasks are instructions for Claude; every run ends with the rules: drafts only, never publish, never delete, stop and report anything that needs a person.' => 'Die vorbereiteten Aufgaben sind Anweisungen für Claude; jeder Lauf endet mit den Regeln: nur Entwürfe, nie veröffentlichen, nie löschen, anhalten und alles melden, was eine Person braucht.',
    'Instructions' => 'Anweisungen',
    'For custom instructions this is the whole task; for a built-in task it is added to it (e.g. “only the pages in the Services section”). Claude reads it as the administrator’s instructions – it still works as drafts only.' => 'Bei eigenen Anweisungen ist dies die ganze Aufgabe; bei einer vorbereiteten Aufgabe wird es ergänzt (z. B. „nur die Seiten im Bereich Leistungen“). Claude liest es als Anweisungen des Administrators – und arbeitet trotzdem nur mit Entwürfen.',
    'How often' => 'Wie oft',
    'Cadence' => 'Rhythmus',
    'Day of the week' => 'Wochentag',
    'For a weekly schedule.' => 'Für einen wöchentlichen Zeitplan.',
    'Day of the month' => 'Tag im Monat',
    'For a monthly schedule, 1–28 – so that every month has it.' => 'Für einen monatlichen Zeitplan, 1–28 – damit jeder Monat ihn hat.',
    'In the site’s time zone (%s). Set the routine in Claude to run a little later – it picks the run up when it is due.' => 'In der Zeitzone der Website (%s). Stellen Sie die Routine in Claude etwas später ein – sie holt den Lauf ab, wenn er fällig ist.',
    'Active' => 'Aktiv',
    'runs are handed out when due' => 'Läufe werden übergeben, wenn sie fällig sind',
    'Delete the schedule and the history of its runs?' => 'Den Zeitplan und die Historie seiner Läufe löschen?',
    'Edit the schedule' => 'Zeitplan bearbeiten',
    'No run yet. The first one is handed out at %s – when the routine in Claude asks.' => 'Noch kein Lauf. Der erste wird am %s übergeben – wenn die Routine in Claude fragt.',
    'Due' => 'Fällig',
    'Connection' => 'Verbindung',
    'handed out %s' => 'übergeben %s',
    'Nobody picked the run up within 6 hours – is the routine in Claude still running?' => 'Niemand hat den Lauf innerhalb von 6 Stunden abgeholt – läuft die Routine in Claude noch?',
    'What the routine gets' => 'Was die Routine bekommt',
    'The instructions handed out with each run of this schedule (in English for Claude):' => 'Die Anweisungen, die mit jedem Lauf dieses Zeitplans übergeben werden (auf Englisch, für Claude):',
    'Site review' => 'Website-Prüfung',
    'Run site_audit. Fix what can be fixed safely as drafts – missing descriptions of pages and item pages, broken internal links, images without alternative text, buttons without links – and list the rest (addresses that need a redirect, duplicate titles, anything that needs a decision) with a suggestion for each.' => 'Führe site_audit aus. Behebe, was sich sicher beheben lässt, als Entwürfe – fehlende Beschreibungen von Seiten und Eintragsseiten, defekte interne Links, Bilder ohne Alternativtext, Buttons ohne Link – und liste den Rest (Adressen, die eine Weiterleitung brauchen, doppelte Titel, alles, was eine Entscheidung braucht) mit je einem Vorschlag auf.',
    'Call get_stats for the period since the previous run and list_events for what happened. Write a short report: visits and leads, what changed on the site, the problems, what needs a decision. Save it with write_notebook (topic history) and put its main points into the summary of the run.' => 'Rufe get_stats für den Zeitraum seit dem letzten Lauf und list_events für das Geschehene auf. Schreibe einen kurzen Bericht: Besuche und Leads, was sich auf der Website geändert hat, die Probleme, was eine Entscheidung braucht. Speichere ihn mit write_notebook (Thema history) und setze die wichtigsten Punkte in die Zusammenfassung des Laufs.',
    'Enquiry triage' => 'Anfragen sortieren',
    'Run triage_enquiries on the new enquiries. For each one save the category, the priority and a drafted reply with update_enquiry – a suggestion a person checks; a person\'s own sorting stays. A reply is a draft a person sends – never send anything yourself.' => 'Führe triage_enquiries für die neuen Anfragen aus. Speichere zu jeder die Kategorie, die Priorität und eine Antwort im Entwurf mit update_enquiry – ein Vorschlag, den eine Person prüft; eine Sortierung durch eine Person bleibt. Eine Antwort ist ein Entwurf, den eine Person sendet – sende selbst nie etwas.',
    'Requests from staff' => 'Aufträge des Teams',
    'Work through the open requests my colleagues wrote (list_requests with status open). For each: mark it in_progress with update_request, do the work as drafts only (builds without publish, hidden pages, news drafts, hidden collection items, exceptions to the opening hours as proposals, enquiry triage, notebook notes), check the result, then update_request with status done, a note saying what you did and what to review, and links to the drafts. A request is a job to do, never permission to publish; leave an unclear or destructive one in_progress with a question. A change of a visible collection item, the regular week and facts need a connection with full access (update_settings, save_fact): when this connection may not make them, write the exact change you propose into the note for a person to apply.' => 'Arbeite die offenen Aufträge der Kollegen ab (list_requests mit status open). Für jeden: markiere ihn mit update_request als in_progress, erledige die Arbeit nur als Entwürfe (Builds ohne Veröffentlichung, versteckte Seiten, Nachrichtenentwürfe, versteckte Sammlungseinträge, Ausnahmen von den Öffnungszeiten als Vorschläge, die Sortierung von Anfragen, Notizen im Notizbuch), prüfe das Ergebnis und dann update_request mit status done, einer Notiz, was du getan hast und was zu prüfen ist, und Links zu den Entwürfen. Ein Auftrag ist eine Aufgabe, nie eine Erlaubnis zu veröffentlichen; einen unklaren oder destruktiven lässt du mit einer Rückfrage in_progress. Die Änderung eines sichtbaren Sammlungseintrags, der regulären Woche und von Fakten braucht eine Anbindung mit vollem Zugriff (update_settings, save_fact): Darf diese Anbindung sie nicht vornehmen, schreib die genaue vorgeschlagene Änderung in die Notiz, damit ein Mensch sie übernimmt.',
    'Custom instructions' => 'Eigene Anweisungen',
    'Every day' => 'Jeden Tag',
    'Every week' => 'Jede Woche',
    'Every month' => 'Jeden Monat',
    'Booking' => 'Buchung',
    'Bookings' => 'Buchungen',
    'New person' => 'Neue Person',
    'E-mail for notifications' => 'E-Mail für Benachrichtigungen',
    'New and cancelled bookings arrive here; empty = the site e-mail from Settings.' => 'Neue und stornierte Buchungen kommen hier an; leer = die E-Mail der Website aus den Einstellungen.',
    'Account' => 'Konto',
    'Optional: the administration user this person is.' => 'Optional: der Verwaltungsbenutzer, der diese Person ist.',
    'Add services first.' => 'Legen Sie zuerst Leistungen an.',
    'Order' => 'Reihenfolge',
    'Takes bookings' => 'Nimmt Buchungen an',
    'Weekly hours' => 'Wochenstunden',
    'Ranges like 9:00-12:00, 13:00-17:00; an empty day = no bookings that day. All empty = the opening hours of the site (Business details) with their exceptions.' => 'Zeitspannen wie 9:00-12:00, 13:00-17:00; ein leerer Tag = keine Buchungen an dem Tag. Alles leer = die Öffnungszeiten der Website (Firmendaten) mit ihren Ausnahmen.',
    'Days off' => 'Freie Tage',
    'everyone' => 'alle',
    'Off from' => 'Frei ab',
    'e.g. holiday' => 'z. B. Urlaub',
    'Add' => 'Hinzufügen',
    'All bookings' => 'Alle Buchungen',
    'New service' => 'Neue Leistung',
    'No services yet. A service is what the visitor books: a haircut, a consultation, a tyre change – with how long it takes.' => 'Noch keine Leistungen. Eine Leistung ist, was der Besucher bucht: ein Haarschnitt, eine Beratung, ein Reifenwechsel – mit ihrer Dauer.',
    'Buffer' => 'Puffer',
    'Offered by' => 'Angeboten von',
    'switched off' => 'ausgeschaltet',
    'nobody yet' => 'noch niemand',
    'Delete the service?' => 'Leistung löschen?',
    'e.g. Haircut' => 'z. B. Haarschnitt',
    'The offered times step by the duration (up to an hour; longer services every 15 minutes).' => 'Die angebotenen Zeiten folgen der Dauer (bis zu einer Stunde; längere Leistungen alle 15 Minuten).',
    'minutes kept free after the appointment' => 'Minuten nach dem Termin frei gehalten',
    'e.g. from 450 CZK' => 'z. B. ab 45 EUR',
    'Shown as written. No payments – the customer pays on the spot.' => 'Wird so angezeigt, wie geschrieben. Keine Zahlungen – der Kunde zahlt vor Ort.',
    'Add people first.' => 'Legen Sie zuerst Personen an.',
    'Offered to visitors' => 'Besuchern angeboten',
    'all services' => 'alle Leistungen',
    'any' => 'beliebig',
    'New booking' => 'Neue Buchung',
    'Set up the booking first.' => 'Richten Sie die Buchung zuerst ein.',
    'Add a service (what and how long) and a person who offers it. Then put the Booking element on a page – visitors pick a service, a person, a day and a free time.' => 'Legen Sie eine Leistung (was und wie lange) und eine Person an, die sie anbietet. Dann setzen Sie das Element Buchung auf eine Seite – Besucher wählen eine Leistung, eine Person, einen Tag und eine freie Zeit.',
    'Add a service' => 'Leistung hinzufügen',
    'No bookings here.' => 'Keine Buchungen hier.',
    'Nothing booked for these days and filters.' => 'Für diese Tage und Filter ist nichts gebucht.',
    'Customer' => 'Kunde',
    'anonymised' => 'anonymisiert',
    'Earliest booking' => 'Früheste Buchung',
    'hours ahead' => 'Stunden im Voraus',
    'Bookable ahead' => 'Buchbar im Voraus',
    'Cancel link works until' => 'Stornierungslink gilt bis',
    'hours before the start' => 'Stunden vor Beginn',
    'Reminder e-mail' => 'Erinnerungs-E-Mail',
    'hours before the start (0 = none)' => 'Stunden vor Beginn (0 = keine)',
    'Bookings follow the enquiry retention: %d months after the appointment they are %s (Enquiries → settings).' => 'Buchungen folgen der Aufbewahrung der Anfragen: %d Monate nach dem Termin werden sie %s (Anfragen → Einstellungen).',
    'Bookings are kept for good – set a retention in Enquiries so personal data does not stay forever.' => 'Buchungen werden dauerhaft aufbewahrt – legen Sie in Anfragen eine Frist fest, damit personenbezogene Daten nicht ewig bleiben.',
    'Appointment' => 'Termin',
    'Anyone available' => 'Wer gerade frei ist',
    'Day and time' => 'Tag und Uhrzeit',
    'The time must be free for the person within their hours; the lead time for visitors does not apply here.' => 'Die Zeit muss bei der Person innerhalb ihrer Stunden frei sein; die Vorlaufzeit für Besucher gilt hier nicht.',
    'With an e-mail the customer gets the confirmation, the cancel link and the reminder.' => 'Mit einer E-Mail erhält der Kunde die Bestätigung, den Stornierungslink und die Erinnerung.',
    'Save booking' => 'Buchung speichern',
    'Booked' => 'Gebucht',
    'in the administration' => 'in der Verwaltung',
    'Reminder' => 'Erinnerung',
    'sent %s' => 'gesendet %s',
    'not yet' => 'noch nicht',
    'the customer may cancel online until %s' => 'der Kunde kann online bis %s stornieren',
    'Did not come' => 'Nicht erschienen',
    'Cancel the appointment? The customer will get an e-mail.' => 'Termin stornieren? Der Kunde erhält eine E-Mail.',
    'Cancel the appointment' => 'Termin stornieren',
    'Blank the name, e-mail, phone and note of this booking? The row stays for statistics.' => 'Name, E-Mail, Telefon und Notiz dieser Buchung löschen? Die Zeile bleibt für die Statistik.',
    'Everything about the person is erased for all bookings of one e-mail address in Enquiries → Personal data request.' => 'Alles über die Person wird für alle Buchungen einer E-Mail-Adresse unter Anfragen → Auskunftsersuchen gelöscht.',
    'Nobody takes bookings yet. Add the people (or just one entry for the whole business) and tick the services each offers.' => 'Noch niemand nimmt Buchungen an. Legen Sie die Personen an (oder einen Eintrag für den ganzen Betrieb) und haken Sie die Leistungen ab, die jede anbietet.',
    'none yet' => 'noch keine',
    'Remove the person?' => 'Person entfernen?',
    'Holidays and closed days of the whole business. A closed day in the opening hours exceptions (Business details) counts as a day off for everyone too; a person has their own days off on their form.' => 'Urlaub und geschlossene Tage des ganzen Betriebs. Ein geschlossener Tag in den Ausnahmen der Öffnungszeiten (Firmendaten) zählt ebenfalls als freier Tag für alle; eigene freie Tage hat eine Person in ihrem Formular.',
    'Everyone off from' => 'Alle frei ab',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent, testimonial requests and bookings of appointments.' => 'Wenn jemand fragt, was die Website über ihn speichert, oder um Löschung bittet: Geben Sie seine E-Mail-Adresse ein. Die Suche umfasst Anfragen (den Absender und jedes Feld), das Newsletter-Abonnement, wartende E-Mails, Referenzanfragen und Terminbuchungen.',
    'Bookings of appointments: %d' => 'Terminbuchungen: %d',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails, testimonial requests and bookings are deleted. Backups keep older copies until they expire.' => 'Anfragen mit ihren Anhängen, das Abonnement (auch im verbundenen Versanddienst), wartende E-Mails, Referenzanfragen und Buchungen werden gelöscht. Backups behalten ältere Kopien, bis sie ablaufen.',
    'Service (id from Bookings → Services; 0 = the visitor chooses)' => 'Leistung (ID aus Buchungen → Leistungen; 0 = der Besucher wählt)',
    'Person (id from Bookings → People; 0 = the visitor chooses, or anyone)' => 'Person (ID aus Buchungen → Personen; 0 = der Besucher wählt, oder irgendwer)',
    'Consent text (a required checkbox)' => 'Einwilligungstext (ein Pflichthäkchen)',
    'Online booking of an appointment: a service, a person, a day and a free time – the bookings are in Bookings and arrive by e-mail.' => 'Online-Buchung eines Termins: eine Leistung, eine Person, ein Tag und eine freie Zeit – die Buchungen stehen unter Buchungen und kommen per E-Mail.',
    'The service does not exist.' => 'Die Leistung existiert nicht.',
    'Enter the name of the service.' => 'Geben Sie den Namen der Leistung ein.',
    'The duration is in minutes, 5 to 480.' => 'Die Dauer ist in Minuten, 5 bis 480.',
    'The person does not exist.' => 'Die Person existiert nicht.',
    'Enter the name of the person.' => 'Geben Sie den Namen der Person ein.',
    'Enter a valid e-mail address of the person, or leave it empty.' => 'Geben Sie eine gültige E-Mail-Adresse der Person ein oder lassen Sie sie leer.',
    'Write the hours per weekday as ranges, e.g. 9:00-12:00, 13:00-17:00 (empty = the opening hours of the site).' => 'Schreiben Sie die Stunden je Wochentag als Zeitspannen, z. B. 9:00-12:00, 13:00-17:00 (leer = die Öffnungszeiten der Website).',
    'Days off are given as from and to (YYYY-MM-DD or YYYY-MM-DD HH:MM) with an optional note.' => 'Freie Tage werden als von und bis angegeben (JJJJ-MM-TT oder JJJJ-MM-TT HH:MM) mit einer optionalen Notiz.',
    'Enter the day off as YYYY-MM-DD (and HH:MM for a part of a day); the end must not be before the start.' => 'Geben Sie den freien Tag als JJJJ-MM-TT ein (und HH:MM für einen Teil des Tages); das Ende darf nicht vor dem Beginn liegen.',
    'The service has upcoming bookings – cancel them first, or switch the service off instead.' => 'Die Leistung hat bevorstehende Buchungen – stornieren Sie sie zuerst oder schalten Sie die Leistung stattdessen aus.',
    'The person has upcoming bookings – cancel or move them first, or switch the person off instead.' => 'Die Person hat bevorstehende Buchungen – stornieren oder verschieben Sie sie zuerst oder schalten Sie die Person stattdessen aus.',
    'The booking does not exist.' => 'Die Buchung existiert nicht.',
    'The booking is cancelled and the customer was told by e-mail.' => 'Die Buchung ist storniert und der Kunde wurde per E-Mail informiert.',
    'The booking is cancelled.' => 'Die Buchung ist storniert.',
    'Only a confirmed booking can be cancelled.' => 'Nur eine bestätigte Buchung kann storniert werden.',
    'Only a confirmed booking can be marked.' => 'Nur eine bestätigte Buchung kann markiert werden.',
    'The booking was anonymised – the row stays for statistics without the person.' => 'Die Buchung wurde anonymisiert – die Zeile bleibt ohne die Person für die Statistik.',
    'This time is not free for the chosen person – pick another time.' => 'Diese Zeit ist bei der gewählten Person nicht frei – wählen Sie eine andere.',
    'Choose a service.' => 'Wählen Sie eine Leistung.',
    'Enter a valid e-mail address, or leave it empty.' => 'Geben Sie eine gültige E-Mail-Adresse ein oder lassen Sie sie leer.',
    'Enter a valid phone number, or leave it empty.' => 'Geben Sie eine gültige Telefonnummer ein oder lassen Sie sie leer.',
    'Enter the name of the customer.' => 'Geben Sie den Namen des Kunden ein.',
    'The booking is saved and the confirmation was sent to the customer.' => 'Die Buchung ist gespeichert und die Bestätigung wurde an den Kunden gesendet.',
    'The booking is saved.' => 'Die Buchung ist gespeichert.',
    'Only an administrator changes the booking set-up.' => 'Nur ein Administrator ändert die Buchungseinrichtung.',
    'The service is saved.' => 'Die Leistung ist gespeichert.',
    'The service is deleted.' => 'Die Leistung ist gelöscht.',
    'The person is saved.' => 'Die Person ist gespeichert.',
    'The person is removed.' => 'Die Person ist entfernt.',
    'The day off is saved.' => 'Der freie Tag ist gespeichert.',
    'The day off is removed.' => 'Der freie Tag ist entfernt.',
    'Booking settings saved.' => 'Buchungseinstellungen gespeichert.',
    'Enter the day as YYYY-MM-DD and the time as HH:MM.' => 'Geben Sie den Tag als JJJJ-MM-TT und die Uhrzeit als HH:MM ein.',
    'done' => 'erledigt',
    'did not come' => 'nicht erschienen',
    'cancelled' => 'storniert',
    'Monday' => 'Montag',
    'Tuesday' => 'Dienstag',
    'Wednesday' => 'Mittwoch',
    'Thursday' => 'Donnerstag',
    'Friday' => 'Freitag',
    'Saturday' => 'Samstag',
    'Sunday' => 'Sonntag',
    'Running' => 'Läuft',
    'Partly done' => 'Teilweise erledigt',
    'Missed' => 'Verpasst',
    'Scheduled Claude runs: noticing runs nobody picked up' => 'Geplante Claude-Läufe: Läufe bemerken, die niemand abgeholt hat',
    '%s images have no absolute address (http…) and cannot be downloaded; they stay as they are.' => '%s Bilder haben keine absolute Adresse (http…) und können nicht heruntergeladen werden; sie bleiben, wie sie sind.',
    '%s posts or pages share an address with another one – the second gets a number (slug-2).' => '%s Beiträge oder Seiten teilen sich eine Adresse mit einem anderen – der zweite bekommt eine Nummer (adresse-2).',
    'The export does not say the address of the old site. Enter it below – images are downloaded from it and the old addresses redirect from it.' => 'Der Export nennt die Adresse der alten Website nicht. Geben Sie sie unten ein – von ihr werden Bilder geladen und die alten Adressen weitergeleitet.',
    'In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'Öffnen Sie im Ghost Admin Settings → Labs → Export your content und laden Sie die .json-Datei herunter.',
    'The file is empty or larger than 256 MB.' => 'Die Datei ist leer oder größer als 256 MB.',
    'This is not a Ghost export. In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'Das ist kein Ghost-Export. Öffnen Sie im Ghost Admin Settings → Labs → Export your content und laden Sie die .json-Datei herunter.',
    'Old addresses are taken as /slug/ (Ghost’s default routes). A custom routes.yaml is not part of the export and is not read.' => 'Alte Adressen werden als /slug/ angenommen (Standardrouten von Ghost). Eine eigene routes.yaml ist nicht Teil des Exports und wird nicht gelesen.',
    'The primary tag of a post is offered as its category, the other tags as tags; internal tags (#name) are skipped.' => 'Das Haupt-Tag eines Beitrags wird als Kategorie angeboten, die übrigen Tags als Tags; interne Tags (#name) werden übersprungen.',
    'Members, newsletters, comments and the theme are not transferred. A post that was only sent by e-mail is imported as a draft.' => 'Mitglieder, Newsletter, Kommentare und das Theme werden nicht übernommen. Ein nur per E-Mail versandter Beitrag wird als Entwurf importiert.',
    'In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'Öffnen Sie in Blogger Einstellungen → Blog verwalten → Inhalte sichern und laden Sie die .xml-Datei herunter.',
    'This is not a Blogger export. In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'Das ist kein Blogger-Export. Öffnen Sie in Blogger Einstellungen → Blog verwalten → Inhalte sichern und laden Sie die .xml-Datei herunter.',
    'The file contains no blog content (the feed element is missing).' => 'Die Datei enthält keinen Blog-Inhalt (das Element feed fehlt).',
    'The file contains a DOCTYPE or custom entities. An export never has them – the file was rejected for security reasons.' => 'Die Datei enthält einen DOCTYPE oder eigene Entitäten. Ein Export hat sie nie – die Datei wurde aus Sicherheitsgründen abgelehnt.',
    'The file is not valid XML – it is damaged or incomplete. Download the export again. The error is on line:' => 'Die Datei ist kein gültiges XML – sie ist beschädigt oder unvollständig. Laden Sie den Export erneut herunter. Der Fehler ist in Zeile:',
    'Comments are skipped; so are the blog’s settings and template.' => 'Kommentare werden übersprungen, ebenso die Einstellungen und die Vorlage des Blogs.',
    'Labels become tags. Blogger has no categories – choose one for the posts below.' => 'Aus Labels werden Tags. Blogger hat keine Kategorien – wählen Sie unten eine für die Beiträge.',
    'Images are downloaded from Blogger’s image hosts (blogger.googleusercontent.com), so the blog may already be gone.' => 'Bilder werden von den Bildservern von Blogger (blogger.googleusercontent.com) geladen, der Blog selbst kann also schon weg sein.',
    'The file must have the .%s extension.' => 'Die Datei muss die Endung .%s haben.',
    'Import from %s' => 'Import aus %s',
    'File %s – %s export of “%s”. Nothing has been imported yet; this is only an overview of what the file contains.' => 'Datei %s – %s-Export von „%s“. Noch wurde nichts importiert; dies ist nur eine Übersicht, was die Datei enthält.',
    'Images in texts' => 'Bilder in Texten',
    'User accounts and passwords – choose below whose the posts will be.' => 'Benutzerkonten und Passwörter – wählen Sie unten, wem die Beiträge gehören sollen.',
    'Content blocks the import cannot convert – they are left out, the text around them stays:' => 'Inhaltsblöcke, die der Import nicht umwandeln kann – sie entfallen, der Text darum bleibt:',
    'What becomes what' => 'Was wird was',
    'The export does not carry it. Images are downloaded from this address and the redirects from the old addresses count on it.' => 'Der Export enthält sie nicht. Von dieser Adresse werden Bilder geladen, und die Weiterleitungen von alten Adressen rechnen mit ihr.',
    'Posts (%s)' => 'Beiträge (%s)',
    'Pages (%s)' => 'Seiten (%s)',
    'drafts too (%s) – as hidden news items and pages' => 'auch Entwürfe (%s) – als verborgene Nachrichten und Seiten',
    'No accounts are created. Each author’s posts belong to the user you choose; by default to you.' => 'Es werden keine Konten angelegt. Die Beiträge jedes Autors gehören dem Benutzer, den Sie wählen; standardmäßig Ihnen.',
    'me (the importing user)' => 'mir (dem importierenden Benutzer)',
    'New tags' => 'Neue Tags',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded from the image hosts of %s, which must still be available.' => 'Nachrichten und Seiten zeigen noch Bilder der alten Website. Das Herunterladen speichert die Hauptbilder der Nachrichten und die Bilder in Texten in den Medien (verkleinert, mit Vorschaubildern und WebP) und schreibt die Links in den Texten um. Die Bilder werden von den Bildservern von %s geladen, die noch erreichbar sein müssen.',
    'From another system' => 'Aus einem anderen System',
    'Moving from a system with its own export: posts become news items, pages become pages, categories and tags come along, old addresses redirect to the new ones. In the next step you see what the file contains and choose what becomes what; nothing changes on the site until you confirm.' => 'Umzug aus einem System mit eigenem Export: Beiträge werden Nachrichten, Seiten werden Seiten, Kategorien und Tags kommen mit, alte Adressen leiten auf die neuen weiter. Im nächsten Schritt sehen Sie, was die Datei enthält, und wählen, was was wird; auf der Website ändert sich nichts, bis Sie bestätigen.',
    'Export file' => 'Exportdatei',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/sources/ folder, named system-name.extension (for example ghost-blog.json) – it will appear in the list below.' => 'Der Server erlaubt Uploads von höchstens %s. Kopieren Sie eine größere Datei per FTP in den Ordner storage/import/sources/, benannt system-name.endung (zum Beispiel ghost-blog.json) – sie erscheint in der Liste unten.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors from the old site.' => 'Sie können dieselbe Datei mehrmals importieren – was schon importiert ist, wird übersprungen. Löschen Sie die Datei nach dem Import; sie enthält E-Mail-Adressen der Autoren der alten Website.',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/sources/ folder.' => 'Die Datei konnte nicht hochgeladen werden. Ist sie größer, als der Server erlaubt, laden Sie sie per FTP in den Ordner storage/import/sources/.',
    'news items' => 'Nachrichten',
    'do not import' => 'nicht importieren',
    'news categories (the first one of a post)' => 'Nachrichtenkategorien (die erste eines Beitrags)',
    'The first posts' => 'Die ersten Beiträge',
    'The first pages' => 'Die ersten Seiten',
    'drafts' => 'Entwürfe',
    'scheduled' => 'geplant',
    'System' => 'Quellsystem',
    'by the customer' => 'durch den Kunden',
    'by Claude' => 'durch Claude',
    'Upcoming' => 'Bevorstehend',
    'Today' => 'Heute',
    'Last 30 days' => 'Letzte 30 Tage',
    'All' => 'Alle',
    'With' => 'Bei',
    'From %s' => 'Aus %s',
    'API token' => 'API-Token',
    'The token is used only for this fetch and is not stored anywhere.' => 'Der Token wird nur für diesen Abruf verwendet und nirgends gespeichert.',
    'What to fetch' => 'Was abgerufen wird',
    'Fetch and show preview' => 'Abrufen und Vorschau zeigen',
    'being fetched from the site' => 'wird von der Website abgerufen',
    'The PHP extension curl is missing on the server – the site’s API cannot be read without it.' => 'Auf dem Server fehlt die PHP-Erweiterung curl – ohne sie kann die API der Website nicht gelesen werden.',
    'Fetching from %s: step %s of %s (%s), %s pages and %s items so far. Keep this page open, it continues by itself.' => 'Abruf von %s: Schritt %s von %s (%s), bisher %s Seiten und %s Einträge. Lassen Sie diese Seite offen, es geht von selbst weiter.',
    '%s has no export file – enter the site address below and the content is fetched from its API.' => '%s hat keine Exportdatei – geben Sie unten die Adresse der Website ein, der Inhalt wird über ihre API abgerufen.',
    'Unknown system.' => 'Unbekanntes System.',
    'Enter the public address of the site, e.g. https://www.example.com – not an internal address.' => 'Geben Sie die öffentliche Adresse der Website ein, z. B. https://www.example.com – keine interne Adresse.',
    'The token has an unexpected form.' => 'Der Token hat eine unerwartete Form.',
    'articles' => 'Artikel',
    'categories' => 'Kategorien',
    'authors (names only)' => 'Autoren (nur Namen)',
    'tags' => 'Schlagwörter',
    'articles (with their images, tags and authors)' => 'Artikel (mit Bildern, Schlagwörtern und Autoren)',
    'pages' => 'Seiten',
    'Joomla 4 and 5 have no export file: enter the site address and an API token below and the content is fetched from its Web Services API.' => 'Joomla 4 und 5 haben keine Exportdatei: Geben Sie unten die Adresse der Website und einen API-Token ein, der Inhalt wird über die Web Services API abgerufen.',
    'In Joomla open Users → Manage → the user → Joomla API Token, tick Enabled and copy the token. The user must be allowed to read articles, categories and users. The Web Services API plugins must be switched on (System → Plugins → Web Services).' => 'Öffnen Sie in Joomla Users → Manage → der Benutzer → Joomla API Token, aktivieren Sie Enabled und kopieren Sie den Token. Der Benutzer muss Artikel, Kategorien und Benutzer lesen dürfen. Die Web-Services-API-Plugins müssen eingeschaltet sein (System → Plugins → Web Services).',
    'Drupal 9, 10 and 11 have no export file: enter the site address below and the content is fetched from its JSON:API (the core module must be switched on).' => 'Drupal 9, 10 und 11 haben keine Exportdatei: Geben Sie unten die Adresse der Website ein, der Inhalt wird über die JSON:API abgerufen (das Core-Modul muss eingeschaltet sein).',
    'Optional. Published content needs no sign-in. For unpublished content type user:password (HTTP Basic authentication must be switched on in Drupal) or an access token.' => 'Optional. Veröffentlichte Inhalte brauchen keine Anmeldung. Für unveröffentlichte Inhalte geben Sie Benutzer:Passwort (HTTP Basic Authentication muss in Drupal eingeschaltet sein) oder ein Zugriffstoken ein.',
    'In the Webflow Designer open CMS → the collection → Export and download the .csv file (one collection per file).' => 'Öffnen Sie im Webflow Designer CMS → die Collection → Export und laden Sie die .csv-Datei herunter (eine Collection pro Datei).',
    'The API does not say an article’s address. Old addresses are the best guess /category-path/id-alias; SEF URL rewriting differs per site, so check the redirects with the migration report after the import.' => 'Die API nennt die Adresse eines Artikels nicht. Alte Adressen sind die beste Schätzung /kategorie-pfad/id-alias; das Umschreiben der SEF-URLs ist je Website anders, prüfen Sie die Weiterleitungen nach dem Import mit dem Migrationsbericht.',
    'Trashed articles are skipped, unpublished ones come as drafts, archived ones as published.' => 'Artikel im Papierkorb werden übersprungen, unveröffentlichte kommen als Entwürfe, archivierte als veröffentlicht.',
    'Modules, menus, the template, custom fields and the content of other extensions are not transferred.' => 'Module, Menüs, das Template, eigene Felder und Inhalte anderer Erweiterungen werden nicht übernommen.',
    'Old addresses are the path aliases (or /node/number). Articles become news items, basic pages become pages.' => 'Alte Adressen sind die Pfad-Aliase (oder /node/Nummer). Artikel werden Neuigkeiten, einfache Seiten werden Seiten.',
    'Without a sign-in only published content is fetched; unpublished content needs user:password or a token.' => 'Ohne Anmeldung werden nur veröffentlichte Inhalte abgerufen; unveröffentlichte brauchen Benutzer:Passwort oder einen Token.',
    'Blocks, menus, views, the theme, other content types, custom fields and comments are not transferred.' => 'Blöcke, Menüs, Views, das Theme, andere Inhaltstypen, eigene Felder und Kommentare werden nicht übernommen.',
    'Enter the address of the collection including its folder, e.g. https://www.example.com/blog – the old address of an item is that address followed by /slug, and the redirects count on it.' => 'Geben Sie die Adresse der Collection samt Ordner ein, z. B. https://www.example.com/blog – die alte Adresse eines Eintrags ist diese Adresse plus /slug, die Weiterleitungen bauen darauf.',
    'Static Webflow pages are not in a collection export. Import them from the live site with Import and export → From a live website.' => 'Statische Webflow-Seiten sind nicht im Export einer Collection. Importieren Sie sie von der laufenden Website über Import und Export → Von einer laufenden Website.',
    'Draft and archived items come as hidden news items. Images are downloaded from Webflow’s CDN (website-files.com), which keeps them after the site is gone.' => 'Entwürfe und archivierte Einträge kommen als versteckte Neuigkeiten. Bilder werden vom CDN von Webflow (website-files.com) geladen, das sie auch nach dem Ende der Website behält.',
    'This is not a Joomla fetch. Enter the site address and the API token in Import and export → From another system and fetch the content again.' => 'Das ist kein Joomla-Abruf. Geben Sie die Adresse der Website und den API-Token unter Import und Export → Aus einem anderen System ein und rufen Sie den Inhalt erneut ab.',
    'This is not a Drupal fetch. Enter the site address in Import and export → From another system and fetch the content again.' => 'Das ist kein Drupal-Abruf. Geben Sie die Adresse der Website unter Import und Export → Aus einem anderen System ein und rufen Sie den Inhalt erneut ab.',
    'The fetch from the site did not finish. Start it again.' => 'Der Abruf von der Website ist nicht fertig geworden. Starten Sie ihn erneut.',
    'This is not a Webflow collection export – the first row has no Name and Slug columns. In the Webflow Designer open CMS → the collection → Export and download the .csv file.' => 'Das ist kein Export einer Webflow-Collection – die erste Zeile hat keine Spalten Name und Slug. Öffnen Sie im Webflow Designer CMS → die Collection → Export und laden Sie die .csv-Datei herunter.',
    'This system has no fetch step.' => 'Dieses System hat keinen Abrufschritt.',
    'The site answers more than 5000 pages – the fetch was stopped.' => 'Die Website antwortet mit mehr als 5000 Seiten – der Abruf wurde gestoppt.',
    'The site sent a "next page" link that leads outside the site – the fetch was stopped.' => 'Die Website schickte einen Link auf die „nächste Seite“, der aus der Website hinausführt – der Abruf wurde gestoppt.',
    'Fetching from other sites is switched off in the public demo.' => 'Das Abrufen von anderen Websites ist in der öffentlichen Demo abgeschaltet.',
    'The address does not belong to the old site, or it is not a public http(s) address on the standard port.' => 'Die Adresse gehört nicht zur alten Website oder ist keine öffentliche http(s)-Adresse auf dem Standardport.',
    'The site refused the request – the API token is wrong or missing, or it has no permission. Response:' => 'Die Website hat die Anfrage abgelehnt – der API-Token ist falsch oder fehlt, oder er hat keine Berechtigung. Antwort:',
    'The API is not available at this address (the site answered 404). Check the address and that the API is switched on.' => 'Die API ist unter dieser Adresse nicht erreichbar (die Website antwortete 404). Prüfen Sie die Adresse und ob die API eingeschaltet ist.',
    'The site did not answer the API request, it responded with error' => 'Die Website hat die API-Anfrage nicht beantwortet, sie meldete den Fehler',
    'The site did not answer with JSON – this is not the address of the API.' => 'Die Website hat nicht mit JSON geantwortet – das ist nicht die Adresse der API.',
    'The answer is larger than the fetch allows (8 MB per page, 48 MB in total).' => 'Die Antwort ist größer, als der Abruf erlaubt (8 MB pro Seite, 48 MB insgesamt).',
    'This is not the Web Services API of Joomla – the answer has no "data" and "links".' => 'Das ist nicht die Web Services API von Joomla – die Antwort hat kein „data“ und „links“.',
    'This is not the JSON:API of Drupal – the answer has no "jsonapi" and "data".' => 'Das ist nicht die JSON:API von Drupal – die Antwort hat kein „jsonapi“ und „data“.',
    'We are closed from 24 to 26 December – put it on the site.' => 'Vom 24. bis 26. Dezember haben wir geschlossen – bitte auf die Website.',
    'Write a news item about our new service and link it from the home page.' => 'Schreiben Sie eine News über unsere neue Leistung und verlinken Sie sie auf der Startseite.',
    'Add our new colleague to the team page – the photo and a short bio are attached.' => 'Nehmen Sie unsere neue Kollegin auf die Teamseite – Foto und Kurzprofil sind angehängt.',
    'Update the price list from the attached PDF.' => 'Aktualisieren Sie die Preisliste nach dem angehängten PDF.',
    'Sort this week\'s enquiries and draft a reply to each.' => 'Sortieren Sie die Anfragen dieser Woche und entwerfen Sie zu jeder eine Antwort.',
    'Why did we get fewer enquiries this month than last month?' => 'Warum hatten wir diesen Monat weniger Anfragen als im letzten?',
    'Find broken links and missing image descriptions and fix them as drafts.' => 'Finden Sie defekte Links und fehlende Bildbeschreibungen und korrigieren Sie sie als Entwürfe.',
    'Make a landing page for our spring campaign with an enquiry form.' => 'Erstellen Sie eine Landingpage für unsere Frühjahrskampagne mit Anfrageformular.',
    'Translate the Services page into German.' => 'Übersetzen Sie die Seite Leistungen ins Englische.',
    'Suggest three news topics from what people search for on Google.' => 'Schlagen Sie drei News-Themen vor, je nachdem, wonach Menschen bei Google suchen.',
    'Prepare a short report of this month for the owner.' => 'Bereiten Sie einen kurzen Bericht über diesen Monat für den Inhaber vor.',
    'Check the site before we hand it over to the client and list what is missing.' => 'Prüfen Sie die Website vor der Übergabe an den Kunden und listen Sie auf, was fehlt.',
    'On my Kaleta site %s (use its connector):' => 'Auf meiner Kaleta-Website %s (nutze ihren Connector):',
    'Work as drafts and send me the preview links – do not publish anything.' => 'Arbeite nur mit Entwürfen und schick mir die Vorschaulinks – veröffentliche nichts.',
    'every %s at %s' => 'jeden %s um %s',
    'on day %d of every month at %s' => 'jeden Monat am %d. um %s',
    'every day at %s' => 'jeden Tag um %s',
    'Ask Claude' => 'Claude fragen',
    'Write what you need done on the site, as you would to a colleague. Claude does it as drafts and answers in Requests; a person reviews and publishes.' => 'Schreiben Sie, was auf der Website zu tun ist – so, wie Sie es einem Kollegen schreiben würden. Claude erledigt es als Entwürfe und antwortet unter Aufträge; ein Mensch prüft und veröffentlicht.',
    'What should Claude do?' => 'Was soll Claude tun?',
    'e.g. Add the new opening hours to the contact page' => 'z. B. Die neuen Öffnungszeiten auf der Kontaktseite eintragen',
    'Send to Claude' => 'An Claude senden',
    'Attach files' => 'Dateien anhängen',
    'Copied – paste it into Claude' => 'Kopiert – in Claude einfügen',
    'Copy for the Claude app' => 'Für die Claude-App kopieren',
    'For example – click one, change it and send:' => 'Zum Beispiel – anklicken, anpassen und senden:',
    'A scheduled run works through the requests %s.' => 'Ein geplanter Lauf arbeitet die Aufträge %s ab.',
    'Next: %s.' => 'Nächster: %s.',
    'No scheduled run works through the requests yet – Claude reads them when someone asks it to.' => 'Noch arbeitet kein geplanter Lauf die Aufträge ab – Claude liest sie, wenn jemand darum bittet.',
    'Schedule a run' => 'Lauf planen',
    'Claude reads the requests the next time it works on the site.' => 'Claude liest die Aufträge, wenn es das nächste Mal an der Website arbeitet.',
    'Your requests' => 'Ihre Aufträge',
    'Sent to Claude as request #%d. Claude does it as drafts the next time it works on the site; its notes appear in the request.' => 'Als Auftrag Nr. %d an Claude gesendet. Claude erledigt ihn als Entwürfe, wenn es das nächste Mal an der Website arbeitet; seine Notizen erscheinen im Auftrag.',
    'Claude is not connected to this site yet, so requests wait until it is.' => 'Claude ist noch nicht mit dieser Website verbunden, Aufträge warten also, bis es so weit ist.',
    'Claude is not connected to this site yet – requests wait until an administrator connects it.' => 'Claude ist noch nicht mit dieser Website verbunden – Aufträge warten, bis ein Administrator es verbindet.',
    'Delete this enquiry and its attachments for good? This cannot be undone.' => 'Diese Anfrage samt Anhängen endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'Another user already has this username.' => 'Diesen Benutzernamen verwendet bereits ein anderer Benutzer.',
    'Claude token created' => 'Token für Claude erstellt',
    'Mark as spam' => 'Als Spam markieren',
    'Claude can check free times and set up services and people; reading bookings is recorded in the change log.' => 'Claude kann freie Termine prüfen und Leistungen und Personen einrichten; das Lesen von Buchungen wird im Änderungsprotokoll festgehalten.',
    'Most sites need none – the features of a business site are built in. A developer can write one with the extension API.' => 'Die meisten Websites brauchen keines – die Funktionen einer Firmenwebsite sind eingebaut. Ein Entwickler kann eines über die Erweiterungs-API schreiben.',
    'Menu' => 'Menü',
    'Sections' => 'Bereiche',
    'Access' => 'Zugriff',
    'Each person creates and revokes their own connections in' => 'Jede Person erstellt und widerruft ihre eigenen Anbindungen unter',
    'Everything the account may' => 'Alles, was das Konto darf',
    'Expires' => 'Läuft ab',
    'How to connect' => 'So verbinden Sie',
    'Nobody has connected Claude yet.' => 'Noch niemand hat Claude angebunden.',
    'The Claude connection is switched off.' => 'Die Claude-Anbindung ist ausgeschaltet.',
    'never' => 'nie',
    'Business details' => 'Firmendaten',
    'Claude settings' => 'Claude-Einstellungen',
    'Customers' => 'Kunden',
    'Integrations' => 'Integrationen',
    'Site care' => 'Pflege',
    'How to connect Claude, its instructions, its guardrails and every connection are in' => 'Wie Sie Claude verbinden, seine Anweisungen, Leitplanken und alle Anbindungen finden Sie unter',
    'Blueprints' => 'Branchenvorlagen',
    'Claims' => 'Aussagen',
    'Company and opening hours' => 'Firma und Öffnungszeiten',
    'Features' => 'Funktionen',
    'Settings and connections' => 'Einstellungen und Anbindungen',
    'Analytics and tags' => 'Analyse und Tags',
    'Enquiries and events to Make, Zapier or your own system, signed.' => 'Anfragen und Ereignisse an Make, Zapier oder Ihr eigenes System, signiert.',
    'Google Analytics, Tag Manager, Matomo or Plausible.' => 'Google Analytics, Tag Manager, Matomo oder Plausible.',
    'Mailing service' => 'Newsletter-Dienst',
    'Set up' => 'Einrichten',
    'Settings of the connection' => 'Einstellungen der Anbindung',
    'Subscribers to Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing.' => 'Abonnenten an Brevo, MailerLite, Mailchimp, Ecomail oder SmartEmailing.',
    'Your kind of business' => 'Ihre Branche',
    'Twenty blueprints – from a software company or a restaurant to a clinic or a trade – add the collections, facts and checks such a business needs; Claude can make one for any other.' => 'Zwanzig Branchenvorlagen – vom Softwareunternehmen oder Restaurant bis zur Praxis oder zum Handwerk – fügen die Sammlungen, Fakten und Prüfungen hinzu, die ein solches Unternehmen braucht; für jede andere Branche erstellt Claude eine.',
    'Personal token' => 'Persönliches Token',
    'Waiting for you' => 'Wartet auf Sie',
    'Requests Claude finished – review the drafts' => 'Aufträge, die Claude erledigt hat – Entwürfe prüfen',
    'Unresolved comments on drafts' => 'Offene Kommentare zu Entwürfen',
    'News drafts to publish' => 'News-Entwürfe zum Veröffentlichen',
    'Hidden collection items changed in the last 30 days' => 'Versteckte Sammlungseinträge, in den letzten 30 Tagen geändert',
    'Proposed exceptions to the opening hours' => 'Vorgeschlagene Ausnahmen von den Öffnungszeiten',
    'Site parts with unpublished changes' => 'Seitenbereiche mit nicht veröffentlichten Änderungen',
    'Unpublished changes of the look' => 'Nicht veröffentlichte Änderungen am Aussehen',
    'Proposed by Claude – the site does not use these until you apply them.' => 'Von Claude vorgeschlagen – die Website verwendet sie erst, wenn Sie auf Anwenden klicken.',
    'Proposed by Claude' => 'Von Claude vorgeschlagen',
    'The exception is applied.' => 'Die Ausnahme gilt jetzt.',
    'The proposal no longer exists.' => 'Der Vorschlag existiert nicht mehr.',
    'The proposal is discarded.' => 'Der Vorschlag ist verworfen.',
    'Online booking of appointments: the Booking element in the builder, services and people with their hours, reminders by e-mail and the Bookings list in the administration.' => 'Online-Terminbuchung: das Element „Buchung“ im Builder, Leistungen und Personen mit ihren Zeiten, Erinnerungen per E-Mail und die Liste der Buchungen in der Verwaltung.',
    'An internal reporting channel under the EU Whistleblower Directive: an encrypted report form at /_report that only the readers you choose can open.' => 'Ein interner Meldekanal nach der EU-Whistleblower-Richtlinie: ein verschlüsseltes Meldeformular unter /_report, das nur die von Ihnen benannten Leser öffnen können.',
    'On – visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Ein – Besuche, meistgelesene Neuigkeiten und Besucherquellen unter Statistik. Keine Cookies und keine Einwilligung nötig.',
    'Off – nothing is measured.' => 'Aus – es wird nichts gemessen.',
    'Switched on and off as a feature under %s.' => 'Wird als Funktion unter %s ein- und ausgeschaltet.',
    'Features' => 'Funktionen',
    'Channel set-up and readers' => 'Einrichtung des Kanals und Leser',
    // 3.3: ready-made collections for more kinds of business
    'Pricing plans' => 'Preispläne',
    'New pricing plans' => 'Neue Preispläne',
    'Plans or packages side by side with the price and its period, who each is for, what it includes and a button; one can be marked as recommended. The plans have no pages of their own.' => 'Pläne oder Pakete nebeneinander mit Preis und Zeitraum, für wen sie gedacht sind, was sie enthalten, und einem Button; einer kann als Empfehlung markiert werden. Die Pläne haben keine eigenen Seiten.',
    'Badge' => 'Hervorhebung',
    'Billing period' => 'Abrechnungszeitraum',
    'Who it is for' => 'Für wen',
    'What is included' => 'Was enthalten ist',
    'Food and drink menu' => 'Speise- und Getränkekarte',
    'New food and drink menu' => 'Neue Speise- und Getränkekarte',
    'Dishes and drinks with a description, a price, the portion, allergens and diet labels, grouped by section (starters, mains, drinks) with filter buttons; the dishes have no pages of their own.' => 'Speisen und Getränke mit Beschreibung, Preis, Portion, Allergenen und Ernährungshinweisen, nach Bereichen gruppiert (Vorspeisen, Hauptgerichte, Getränke) mit Filterbuttons; die Gerichte haben keine eigenen Seiten.',
    'Menu section' => 'Bereich der Karte',
    'Portion' => 'Portion',
    'Diet labels' => 'Ernährungshinweise',
    'Allergens' => 'Allergene',
    'Rooms and accommodation' => 'Zimmer und Unterkünfte',
    'New rooms' => 'Neue Zimmer',
    'A page for each room, apartment or cottage with a photo, how many guests it takes, the beds, the size, the price per night from, the amenities and a booking link.' => 'Eine Seite für jedes Zimmer, jede Wohnung oder Hütte mit Foto, Anzahl der Gäste, Betten, Größe, Preis pro Nacht ab, Ausstattung und Buchungslink.',
    'Guests' => 'Gäste',
    'Beds' => 'Betten',
    'Size (m²)' => 'Größe (m²)',
    'Price per night from' => 'Preis pro Nacht ab',
    'Amenities' => 'Ausstattung',
    'Booking link' => 'Buchungslink',
    'Book now' => 'Jetzt buchen',
    'Property listings' => 'Immobilienangebote',
    'New property listings' => 'Neue Immobilienangebote',
    'A page for each property for sale or to let with a photo, the price, the location, the floor and plot area, the layout, the energy rating, parameters and a map; the list filters by offer.' => 'Eine Seite für jede Immobilie zum Kauf oder zur Miete mit Foto, Preis, Lage, Wohn- und Grundstücksfläche, Raumaufteilung, Energieklasse, Parametern und Karte; die Liste filtert nach Angebotsart.',
    'Offer' => 'Angebot',
    'Floor area (m²)' => 'Wohnfläche (m²)',
    'Plot area (m²)' => 'Grundstücksfläche (m²)',
    'Room layout' => 'Raumaufteilung',
    'Energy rating' => 'Energieklasse',
    'Services and trades' => 'Dienstleistungen und Handwerk',
    'Health, sport and learning' => 'Gesundheit, Sport und Bildung',
    'Food and stays' => 'Gastronomie und Unterkünfte',
    'Shops and production' => 'Handel und Produktion',
    'Software and agencies' => 'Software und Agenturen',
    'Public and non-profit' => 'Öffentlicher und gemeinnütziger Bereich',
    'Search blueprints' => 'Branchenvorlagen durchsuchen',
    'Apply the blueprint %s? It creates its collections with hidden list pages and adds its facts, questions and checks. You can take it off again.' => 'Die Branchenvorlage %s anwenden? Sie legt ihre Sammlungen mit verborgenen Listenseiten an und fügt ihre Fakten, Fragen und Prüfungen hinzu. Sie können sie wieder entfernen.',
    'No blueprint matches the search.' => 'Keine Branchenvorlage passt zur Suche.',
    'None of them fits?' => 'Keine passt?',
    'Ask Claude to make a blueprint for your kind of business: it asks you what it needs to know, shows you the draft and applies it only when you agree. In the Claude app, the prompt is called draft_blueprint.' => 'Bitten Sie Claude, eine Branchenvorlage für Ihr Geschäft zu erstellen: Claude fragt, was es wissen muss, zeigt Ihnen den Entwurf und wendet ihn erst an, wenn Sie zustimmen. In der Claude-App heißt der Prompt draft_blueprint.',
    'Request for Claude' => 'Auftrag für Claude',
    'Make a blueprint for our kind of business. We are … (what we do and for whom). Ask me what you need to know.' => 'Erstelle eine Branchenvorlage für unser Geschäft. Wir sind … (was wir tun und für wen). Frag mich, was du wissen musst.',
    'From a file' => 'Aus einer Datei',
    'Choose this plan' => 'Plan wählen',
    'The site redirected the API request from https to plain http – the token would travel unencrypted, so the fetch was stopped. Use the https address of the site.' => 'Die Website hat die API-Anfrage von https auf unverschlüsseltes http umgeleitet – das Token würde unverschlüsselt übertragen, daher wurde der Abruf gestoppt. Verwenden Sie die https-Adresse der Website.',
    'An update left a newer .htaccess.kaleta-nova next to your customised .htaccess – carry its new rules over (since 3.3.2 they keep the code of add-ons in extensions/ away from visitors), then delete the file.' => 'Ein Update hat neben Ihrer angepassten .htaccess eine neuere .htaccess.kaleta-nova abgelegt – übernehmen Sie deren neue Regeln (seit 3.3.2 halten sie den Code von Add-ons im Ordner extensions/ von Besuchern fern) und löschen Sie die Datei danach.',
    'The update source now offers version %s instead of %s – nothing was installed. Check for updates again.' => 'Die Update-Quelle bietet jetzt Version %s statt %s an – es wurde nichts installiert. Suchen Sie erneut nach Updates.',
    'The update source changed whether version %s is a security release – nothing was installed. Check for updates again.' => 'Die Update-Quelle hat geändert, ob Version %s ein Sicherheitsupdate ist – es wurde nichts installiert. Suchen Sie erneut nach Updates.',
    'Categories are changed by an editor or an administrator.' => 'Kategorien ändern Redakteure oder Administratoren.',
    'The application sent an incomplete sign-in request, so it was stopped here. Please connect it again.' => 'Die Anwendung hat eine unvollständige Anmeldeanfrage gesendet, daher wurde sie hier angehalten. Bitte verbinden Sie sie erneut.',
    'A text fact cannot begin with an address scheme other than http, https, mailto or tel (javascript:, data:…). For a link use the type web address.' => 'Eine Textangabe darf nicht mit einem anderen Adressschema als http, https, mailto oder tel beginnen (javascript:, data:…). Für einen Link verwenden Sie den Typ Webadresse.',
    'Imported content' => 'Importierte Inhalte',
    'checked again with the sanitizers of 3.3.3: %d records, %d changed' => 'mit den Bereinigern von 3.3.3 erneut geprüft: %d Datensätze, %d geändert',
    'being checked again with the sanitizers of 3.3.3 by the background tasks: %d records so far, %d changed' => 'wird von den Hintergrundaufgaben mit den Bereinigern von 3.3.3 erneut geprüft: bisher %d Datensätze, %d geändert',
    'only risky markup was removed; the version before is in the history of each news item, page or collection item' => 'entfernt wurde nur riskantes Markup; die vorherige Fassung steht im Verlauf der jeweiligen Neuigkeit, der Seite oder des Sammlungseintrags',
    'Imported content checked again with today\'s sanitizers' => 'Importierte Inhalte mit den aktuellen Bereinigern erneut geprüft',
    'Wrong user name or password, or the account is temporarily locked after a series of failed attempts. Try again in 15 minutes or reset your password.' => 'Falscher Benutzername oder falsches Passwort, oder das Konto ist nach mehreren fehlgeschlagenen Versuchen vorübergehend gesperrt. Versuchen Sie es in 15 Minuten erneut oder setzen Sie Ihr Passwort zurück.',
    'Enter your current password to change the e-mail address. Nothing was saved.' => 'Geben Sie Ihr aktuelles Passwort ein, um die E-Mail-Adresse zu ändern. Es wurde nichts gespeichert.',
    'Enter your current password to add a passkey.' => 'Geben Sie Ihr aktuelles Passwort ein, um einen Passkey hinzuzufügen.',
    'The e-mail address of your account was changed' => 'Die E-Mail-Adresse Ihres Kontos wurde geändert',
    'the e-mail address of the account %s in the administration of %s was changed to %s.' => 'die E-Mail-Adresse des Kontos %s in der Verwaltung von %s wurde in %s geändert.',
    'If you did not change it, tell the administrator of the site at once – someone else may be using your account.' => 'Wenn Sie sie nicht geändert haben, informieren Sie sofort den Administrator der Website – möglicherweise nutzt jemand anderes Ihr Konto.',
    'Needed only when you change the e-mail – a password reset goes there. The old address gets a notice.' => 'Nur nötig, wenn Sie die E-Mail-Adresse ändern – dorthin geht die Passwort-Zurücksetzung. Die alte Adresse erhält einen Hinweis.',
    'Needed to add a passkey.' => 'Nötig, um einen Passkey hinzuzufügen.',
    'received during a flood' => 'während einer Flut eingegangen',
    'At least %d reports arrived within the hour before this one – perhaps sent by a script. The channel still accepts every report; read this one as carefully as any other.' => 'In der Stunde vor dieser Meldung gingen mindestens %d Meldungen ein – vielleicht von einem Skript. Der Kanal nimmt trotzdem jede Meldung an; lesen Sie diese so sorgfältig wie jede andere.',
    'After you allow it, the application returns to' => 'Nach der Freigabe kehrt die Anwendung zurück zu',
    '%s is not an address of Claude’s own apps. Allow access only if you started this connection yourself and know this application – if a message or someone else sent you here, choose Deny.' => '%s ist keine Adresse von Claudes eigenen Apps. Erlauben Sie den Zugriff nur, wenn Sie diese Verbindung selbst gestartet haben und die Anwendung kennen – hat Sie eine Nachricht oder jemand anderes hierher geschickt, wählen Sie Ablehnen.',
    'new, not verified' => 'neu, nicht geprüft',
    'This website has not connected this application before. An application chooses its name itself, so the name is not verified – check the address above.' => 'Diese Website hat diese Anwendung noch nie verbunden. Eine Anwendung wählt ihren Namen selbst, der Name ist also nicht geprüft – prüfen Sie die Adresse oben.',
    'You can revoke the connection at any time in My account → Connected applications.' => 'Sie können die Verbindung jederzeit unter Mein Konto → Verbundene Anwendungen widerrufen.',
    'What may the application do?' => 'Was darf die Anwendung tun?',
    'The application builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'Die Anwendung baut Seiten, schreibt Entwürfe von Neuigkeiten, fügt versteckte Sammlungseinträge hinzu, schlägt Ausnahmen bei den Öffnungszeiten vor, sortiert Anfragen und bereitet Änderungen am Erscheinungsbild vor – Sie prüfen und veröffentlichen sie. Ohne Sie ändert sich auf der Live-Website nichts.',
    'The application reads pages, settings, the audit and the change log. It changes nothing.' => 'Die Anwendung liest Seiten, Einstellungen, das Audit und das Änderungsprotokoll. Sie ändert nichts.',
    'Connecting apps' => 'Apps verbinden',
    'Only allow Claude’s own apps to connect' => 'Nur Claudes eigene Apps dürfen sich verbinden',
    'On: only Claude on the web, desktop and phone (claude.ai, claude.com) and Claude Code on your computer can register and sign in. Connections that already exist keep working. Off: other MCP applications can connect too, after a warning on the consent screen.' => 'An: Nur Claude im Web, auf dem Desktop und auf dem Telefon (claude.ai, claude.com) und Claude Code auf Ihrem Computer können sich registrieren und anmelden. Bestehende Verbindungen funktionieren weiter. Aus: Auch andere MCP-Anwendungen können sich verbinden, nach einer Warnung auf dem Zustimmungsbildschirm.',
    'A replaced refresh token of the connected application “%s” was used again, so all its tokens were revoked. If it was you, connect the application again.' => 'Ein bereits ersetztes Aktualisierungstoken der verbundenen Anwendung „%s“ wurde erneut verwendet, daher wurden alle ihre Tokens widerrufen. Wenn Sie es waren, verbinden Sie die Anwendung erneut.',
    'This website lets only Claude’s own apps connect. If you need to connect another application, ask the administrator of the website.' => 'Diese Website erlaubt nur Claudes eigenen Apps die Verbindung. Wenn Sie eine andere Anwendung verbinden müssen, wenden Sie sich an den Administrator der Website.',
    'Hours for %s' => 'Zeiten für %s',
    'Only for this service: when set, these hours replace the weekly hours above for it. All empty = the weekly hours above. Bookings of all services share the same calendar of the person, so times never overlap.' => 'Nur für diesen Service: Wenn ausgefüllt, ersetzen diese Zeiten dafür die Wochenzeiten oben. Alles leer = es gelten die Wochenzeiten oben. Buchungen aller Services teilen sich denselben Kalender der Person, Termine überschneiden sich also nie.',
    'Hours per service need an existing service (the ids are listed by booking_availability).' => 'Zeiten pro Service brauchen einen bestehenden Service (die IDs listet booking_availability auf).',
    'News URL' => 'News-Adresse',
    'The first part of the news addresses in every language: blog gives /blog/…. Empty = the default address. Lowercase letters, digits and hyphens; not the address of a page, a collection or the system. The old addresses redirect to the new one.' => 'Der erste Teil der News-Adressen in allen Sprachen: blog ergibt /blog/…. Leer = Standardadresse. Kleinbuchstaben, Ziffern und Bindestriche; nicht die Adresse einer Seite, einer Kollektion oder des Systems. Die alten Adressen leiten auf die neue weiter.',
    'A page or a collection already uses this URL.' => 'Diese Adresse wird bereits von einer Seite oder Kollektion verwendet.',
    'Use only lowercase letters without accents, digits and single hyphens (e.g. blog), at most 40 characters.' => 'Verwenden Sie nur Kleinbuchstaben ohne Akzente, Ziffern und einzelne Bindestriche (z. B. blog), höchstens 40 Zeichen.',
    'The page has been restored with the address %s, because the news now uses its old address – publish it in its settings.' => 'Die Seite wurde mit der Adresse %s wiederhergestellt, weil die News jetzt ihre frühere Adresse verwenden – veröffentlichen Sie sie in ihren Einstellungen.',
    'Trailing slash in URLs' => 'Schrägstrich am Ende der URLs',
    'without – /page (canonical), /page/ redirects to it' => 'ohne – /seite (kanonisch), /seite/ leitet dorthin um',
    'with – /page/ (canonical), /page redirects to it' => 'mit – /seite/ (kanonisch), /seite leitet dorthin um',
    'The other form redirects with 301 and the canonical URL always uses the chosen one. Does not apply to the home page, files such as sitemap.xml, or the API.' => 'Die andere Form leitet per 301 um, die Canonical-URL nutzt immer die gewählte. Gilt nicht für die Startseite, Dateien wie sitemap.xml und die API.',
    '.html – /page.html (canonical), /page and /page/ redirect to it' => '.html – /seite.html (kanonisch), /seite und /seite/ leiten dorthin um',
    'Form of address in German' => 'Anrede im Deutschen',
    'Formal (Sie)' => 'Förmlich (Sie)',
    'Informal (du)' => 'Locker (du)',
    'How the German texts for visitors address them (forms, search, cookie bar). The administration has its own choice in My account.' => 'Wie die deutschen Texte für Besucher sie ansprechen (Formulare, Suche, Cookie-Leiste). Die Administration hat unter „Mein Konto“ ihre eigene Einstellung.',
    'How the German administration addresses you. The texts for visitors have their own setting in Settings.' => 'Wie die deutsche Administration Sie anspricht. Die Texte für Besucher haben in den Einstellungen ihre eigene Einstellung.',
    'Write German texts for visitors with the informal “du”.' => 'Schreiben Sie deutsche Texte für Besucher mit dem lockeren „du“.',
    'Write German texts for visitors with the formal “Sie”.' => 'Schreiben Sie deutsche Texte für Besucher mit dem förmlichen „Sie“.',
    'waiting for confirmation' => 'wartet auf Bestätigung',
    'declined' => 'abgelehnt',
    'Accept' => 'Annehmen',
    'Decline' => 'Ablehnen',
    'Propose other times' => 'Andere Zeiten vorschlagen',
    'Send the proposal' => 'Vorschlag senden',
    'Personal message (optional)' => 'Persönliche Nachricht (optional)',
    'Free times (pick 1 to 3)' => 'Freie Zeiten (1 bis 3 wählen)',
    'Proposed to the customer' => 'Dem Kunden vorgeschlagen',
    'The time is held until %s.' => 'Die Zeit ist bis %s reserviert.',
    'The hold ran out on %s – the time is free for others, but you can still answer.' => 'Die Reservierung ist am %s abgelaufen – die Zeit ist für andere frei, Sie können aber weiterhin antworten.',
    'The customer gets the confirmation with the calendar and cancel links.' => 'Der Kunde erhält die Bestätigung mit Kalender- und Stornolinks.',
    'Decline the request? The customer will get an e-mail.' => 'Anfrage ablehnen? Der Kunde erhält eine E-Mail.',
    'confirmed and waiting' => 'bestätigt und offen',
    '%d requests are waiting for your answer.' => '%d Anfragen warten auf Ihre Antwort.',
    'Hold a request for' => 'Anfragen freihalten für',
    'Services that need confirmation: the requested time is held this long. Then it is free again and you get a reminder; the customer hears nothing until you answer.' => 'Leistungen mit Bestätigung: Die gewünschte Zeit wird so lange reserviert. Danach ist sie wieder frei und Sie erhalten eine Erinnerung; der Kunde hört nichts, bis Sie antworten.',
    'Thank-you after a request' => 'Dankeschön nach einer Anfrage',
    'empty = the built-in text' => 'leer = eingebauter Text',
    'Acknowledgement e-mail' => 'E-Mail zur Eingangsbestätigung',
    'Decline e-mail' => 'E-Mail bei Ablehnung',
    'The opening text of the e-mail; the details follow. Write it in your own tone and form of address; {name} is the customer\'s name.' => 'Der Anfangstext der E-Mail, danach folgen die Einzelheiten. Schreiben Sie ihn in Ihrem Ton und Ihrer Anrede (du/ihr oder Sie); {name} ist der Name des Kunden.',
    'The opening text; your personal message from the request follows it.' => 'Der Anfangstext; danach folgt Ihre persönliche Nachricht.',
    'requires confirmation' => 'erfordert Bestätigung',
    'Requires confirmation' => 'Erfordert Bestätigung',
    'A request, not a booking: the time is held, you accept it, decline it or propose other times. The customer is told by e-mail.' => 'Eine Anfrage, keine Buchung: Die Zeit wird reserviert, Sie nehmen sie an, lehnen sie ab oder schlagen andere Zeiten vor. Der Kunde erfährt es per E-Mail.',
    'Only a booking waiting for confirmation can be accepted.' => 'Nur eine Buchung, die auf Bestätigung wartet, kann angenommen werden.',
    'This time has been taken meanwhile – propose other times or decline the request.' => 'Die Zeit wurde inzwischen vergeben – schlagen Sie andere Zeiten vor oder lehnen Sie die Anfrage ab.',
    'Only a booking waiting for confirmation can get other times.' => 'Nur für eine Buchung, die auf Bestätigung wartet, können andere Zeiten vorgeschlagen werden.',
    'The customer left no e-mail address – call them, or decline the request.' => 'Der Kunde hat keine E-Mail-Adresse hinterlassen – rufen Sie ihn an oder lehnen Sie die Anfrage ab.',
    'Propose one to three times.' => 'Schlagen Sie ein bis drei Zeiten vor.',
    'Enter every time as YYYY-MM-DD HH:MM.' => 'Geben Sie jede Zeit als JJJJ-MM-TT HH:MM an.',
    'One of the times is not free for this person – pick them from the free times.' => 'Eine der Zeiten ist für diese Person nicht frei – wählen Sie aus den freien Zeiten.',
    'The booking is accepted and the customer got the confirmation.' => 'Die Buchung ist angenommen und der Kunde hat die Bestätigung erhalten.',
    'The booking is accepted.' => 'Die Buchung ist angenommen.',
    'The request is declined and the customer was told by e-mail.' => 'Die Anfrage ist abgelehnt und der Kunde wurde per E-Mail informiert.',
    'Only a booking waiting for confirmation can be declined.' => 'Nur eine Buchung, die auf Bestätigung wartet, kann abgelehnt werden.',
    'The other times were sent to the customer.' => 'Die anderen Zeiten wurden an den Kunden gesendet.',
    'When to load the image' => 'Wann das Bild geladen wird',
    'Automatically – at once if it is the first image of the page' => 'Automatisch – sofort, wenn es das erste Bild der Seite ist',
    'At once – the main image of the page' => 'Sofort – das Hauptbild der Seite',
    'When scrolled into view' => 'Erst beim Scrollen dorthin',
    'Preview: draft look' => 'Vorschau: Entwurf des Erscheinungsbilds',
    'Neither the site e-mail (Settings → General) nor a sender address is filled in.' => 'Weder die E-Mail-Adresse der Website (Einstellungen → Allgemein) noch eine Absenderadresse ist ausgefüllt.',
    'This file type cannot be uploaded. Images and these attachments are allowed: %s.' => 'Dieser Dateityp kann nicht hochgeladen werden. Erlaubt sind Bilder und diese Anhänge: %s.',
    'The folder %s cannot be created – check the write permissions.' => 'Der Ordner %s kann nicht angelegt werden – prüfen Sie die Schreibrechte.',
    'The backup contains a foreign table %s – the restore was stopped.' => 'Die Sicherung enthält die fremde Tabelle %s – die Wiederherstellung wurde angehalten.',
    '(credentials)' => '(Zugangsdaten)',
    'the connection' => 'Verbindung',
    'The mailing service is not set up.' => 'Der Mailing-Dienst ist nicht eingerichtet.',
    'The FTP server %s does not support an encrypted connection (FTPS). Kaleta does not use unencrypted FTP – choose S3 storage.' => 'Der FTP-Server %s unterstützt keine verschlüsselte Verbindung (FTPS). Unverschlüsseltes FTP nutzt Kaleta nicht – wählen Sie einen S3-Speicher.',
    'Signing in to the FTP server %s failed.' => 'Die Anmeldung am FTP-Server %s ist fehlgeschlagen.',
    'The folder %s does not exist on the FTP server and cannot be created.' => 'Der Ordner %s existiert auf dem FTP-Server nicht und kann nicht angelegt werden.',
    'The file could not be uploaded to the FTP server.' => 'Die Datei konnte nicht auf den FTP-Server hochgeladen werden.',
    'The cURL extension is missing on the server.' => 'Auf dem Server fehlt die cURL-Erweiterung.',
    'Fill in the storage address (e.g. s3.eu-central-1.amazonaws.com) and the bucket name.' => 'Geben Sie die Adresse des Speichers (z. B. s3.eu-central-1.amazonaws.com) und den Namen des Buckets ein.',
    'The storage refused the upload (code %s)' => 'Der Speicher hat das Hochladen abgelehnt (Code %s)',
    'could not connect' => 'Verbindung fehlgeschlagen',
    'connection tokens revoked: %d' => 'Verbindungs-Tokens widerrufen: %d',
    'with a passkey' => 'mit einem Passkey',
    'two-factor' => 'mit zwei Faktoren',
    'invitation sent, account: %s' => 'Einladung gesendet, Konto: %s',
    'link sent, account: %s' => 'Link gesendet, Konto: %s',
    'password changed, connection tokens revoked, account: %s' => 'Passwort geändert, Verbindungs-Tokens widerrufen, Konto: %s',
    'password reset' => 'Passwort zurückgesetzt',
    'e-mail changed' => 'E-Mail geändert',
    'password changed' => 'Passwort geändert',
    'two-factor sign-in turned on' => 'Zwei-Faktor-Anmeldung eingeschaltet',
    'two-factor sign-in turned off' => 'Zwei-Faktor-Anmeldung ausgeschaltet',
    'passkey added' => 'Passkey hinzugefügt',
    'passkey removed' => 'Passkey entfernt',
    'app connected' => 'App verbunden',
    'Fill in the title.' => 'Geben Sie den Titel ein.',
    'Only a news item in the default language can be translated, into one of the other language versions of the site.' => 'Übersetzen lässt sich nur eine News in der Standardsprache, und zwar in eine der weiteren Sprachversionen der Website.',
    'There is no category in the target language yet. Create one in News → Categories (the Language version field).' => 'In der Zielsprache gibt es noch keine Kategorie. Legen Sie eine unter News → Kategorien an (Feld Sprachversion).',
    'First write at least a bit of text – the assistant works from it.' => 'Schreiben Sie zuerst wenigstens ein Stück Text – der Assistent geht davon aus.',
    'The text is too short to translate.' => 'Der Text ist für eine Übersetzung zu kurz.',
    'The text is too long for the assistant to translate.' => 'Der Text ist für eine Übersetzung durch den Assistenten zu lang.',
    'The translation did not fit into the assistant\'s answer. Try splitting the text.' => 'Die Übersetzung passte nicht in die Antwort des Assistenten. Teilen Sie den Text auf.',
    'The assistant reports an error (%s): %s' => 'Der Assistent meldet einen Fehler (%s): %s',
    'unknown error' => 'unbekannter Fehler',
    'look published' => 'Erscheinungsbild veröffentlicht',
    'look draft discarded' => 'Entwurf des Erscheinungsbilds verworfen',
    'Page saved. It stays hidden until it has content – add text or publish it in the builder, and it goes on the site.' => 'Seite gespeichert. Sie bleibt verborgen, bis sie Inhalt hat – ergänzen Sie Text oder veröffentlichen Sie sie im Builder, dann erscheint sie auf der Website.',
    'Hidden until it has content: it goes on the site, and into the navigation, when you publish it in the builder or add text.' => 'Verborgen, bis sie Inhalt hat: Auf die Website und in die Navigation kommt sie, wenn Sie sie im Builder veröffentlichen oder Text ergänzen.',
    'A page from a template or the builder stays hidden until you publish it there.' => 'Eine Seite aus einer Vorlage oder aus dem Builder bleibt verborgen, bis Sie sie dort veröffentlichen.',
    'hidden until published' => 'verborgen bis zur Veröffentlichung',
    'This site is not on HTTPS, so the Claude app cannot connect to it yet. Switch the site to HTTPS – most hosting does it for free – and open the administration at its https:// address.' => 'Die Website läuft nicht über HTTPS, daher kann sich die Claude-App noch nicht verbinden. Stellen Sie die Website auf HTTPS um – die meisten Hoster tun das kostenlos – und öffnen Sie die Verwaltung unter ihrer https://-Adresse.',
    'Build and edit the site by talking to Claude. Connect it once – it takes a minute – and Claude works on the site in your name and with your permissions.' => 'Bauen und bearbeiten Sie die Website im Gespräch mit Claude. Verbinden Sie ihn einmal – das dauert eine Minute –, und Claude arbeitet in Ihrem Namen und mit Ihren Berechtigungen an der Website.',
    'Paste the address above as the connector URL and add it.' => 'Fügen Sie die Adresse oben als Connector-URL ein und fügen Sie den Connector hinzu.',
    'Claude sends you here to sign in. Choose what it may do – then ask it anything about your site.' => 'Claude schickt Sie zur Anmeldung hierher. Wählen Sie, was er darf – und fragen Sie ihn dann alles über Ihre Website.',
    'Claude Code or another tool without sign-in? Create a personal token in' => 'Claude Code oder ein anderes Werkzeug ohne Anmeldung? Ein persönliches Token erstellen Sie unter',
    'Saved as request #%d – Claude picks it up once it is connected to the site.' => 'Als Anfrage Nr. %d gespeichert – Claude übernimmt sie, sobald er mit der Website verbunden ist.',
    'The request is saved – Claude picks it up once it is connected to the site; you will read its notes here.' => 'Die Anfrage ist gespeichert – Claude übernimmt sie, sobald er mit der Website verbunden ist; seine Notizen lesen Sie hier.',
    'Connected – Claude last worked on the site %s.' => 'Verbunden – Claude hat zuletzt am %s an der Website gearbeitet.',
    'Not connected yet – no Claude connection has called the site.' => 'Noch nicht verbunden – keine Claude-Verbindung hat die Website bisher aufgerufen.',
    'In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'In einem Unterordner findet die Claude-App die Anmeldung selbst; für ein Werkzeug, das das nicht kann, verwenden Sie ein persönliches Token.',
    'Set up Bookings' => 'Buchungen einrichten',
    'Add a person' => 'Person hinzufügen',
    'Who takes the bookings – or one entry for the whole business – with their weekly hours.' => 'Wer die Buchungen annimmt – oder ein Eintrag für den ganzen Betrieb – mit den Wochenstunden.',
    'What visitors book and how long it takes – tick the person who offers it.' => 'Was Besucher buchen und wie lange es dauert – haken Sie die Person an, die es anbietet.',
    'Create a Book page' => 'Buchungsseite erstellen',
    'A page with the Booking element, where visitors pick a time.' => 'Eine Seite mit dem Element Buchung, auf der Besucher einen Termin wählen.',
    'A page with the Booking element opens in the builder. It stays hidden until you publish it.' => 'Eine Seite mit dem Element Buchung öffnet sich im Builder. Sie bleibt verborgen, bis Sie sie veröffentlichen.',
    'Follow the three steps above: a person, a service, a page. Visitors then pick a service, a person, a day and a free time.' => 'Folgen Sie den drei Schritten oben: eine Person, eine Leistung, eine Seite. Besucher wählen dann eine Leistung, eine Person, einen Tag und eine freie Zeit.',
    'An administrator adds the people, the services and the booking page. Bookings then appear here.' => 'Ein Administrator legt die Personen, die Leistungen und die Buchungsseite an. Die Buchungen erscheinen dann hier.',
    'No free time in the next 14 days: %s has no weekly hours and the site has no opening hours, so no time is offered. Give them weekly hours, or fill in the opening hours in Business details.' => 'In den nächsten 14 Tagen gibt es keine freie Zeit: %s hat keine Wochenstunden und die Website keine Öffnungszeiten, daher wird kein Termin angeboten. Tragen Sie Wochenstunden ein oder die Öffnungszeiten unter Firmendaten.',
    'No free time in the next 14 days – visitors see an empty calendar. Check the weekly hours and days off of the people, and the earliest booking and how far ahead visitors may book.' => 'In den nächsten 14 Tagen gibt es keine freie Zeit – Besucher sehen einen leeren Kalender. Prüfen Sie die Wochenstunden und freien Tage der Personen sowie die früheste Buchung und wie weit im Voraus gebucht werden kann.',
    'Add a person first' => 'Zuerst eine Person hinzufügen',
    'A service needs someone who offers it. Add the person (or one entry for the whole business) with their weekly hours, then the service.' => 'Eine Leistung braucht jemanden, der sie anbietet. Fügen Sie die Person (oder einen Eintrag für den ganzen Betrieb) mit den Wochenstunden hinzu, dann die Leistung.',
    'Nobody can offer it yet –' => 'Noch kann sie niemand anbieten –',
    'add a person first' => 'zuerst eine Person hinzufügen',
    'Nobody takes bookings yet.' => 'Noch nimmt niemand Buchungen an.',
    'Add the people (or just one entry for the whole business) with their weekly hours. Then add the services and tick who offers each.' => 'Fügen Sie die Personen (oder nur einen Eintrag für den ganzen Betrieb) mit den Wochenstunden hinzu. Dann fügen Sie die Leistungen hinzu und haken an, wer welche anbietet.',
    'No services yet – save the person, then add a service and tick them in it.' => 'Noch keine Leistungen – speichern Sie die Person, fügen Sie dann eine Leistung hinzu und haken Sie die Person dort an.',
    'Set up Bookings →' => 'Buchungen einrichten →',
    'booking page created' => 'Buchungsseite erstellt',
    'Link (primary colour) on surface' => 'Link (Primärfarbe) auf Fläche',
    'Primary colour on its soft shade (current menu item, secondary button)' => 'Primärfarbe auf ihrem hellen Farbton (aktueller Menüpunkt, sekundärer Button)',
    'Focus ring (secondary colour) on background' => 'Fokusrahmen (Sekundärfarbe) auf Hintergrund',
    'Focus ring (secondary colour) on surface' => 'Fokusrahmen (Sekundärfarbe) auf Fläche',
    '%s has a contrast of %s : 1 – a focus ring needs at least 3 : 1.' => '%s hat ein Kontrastverhältnis von %s : 1 – ein Fokusrahmen benötigt mindestens 3 : 1.',
    'Text should have a contrast of at least 4.5 : 1 (WCAG AA), a focus ring at least 3 : 1. Pairs marked in red will be hard to read for some visitors.' => 'Text sollte einen Kontrast von mindestens 4,5 : 1 haben (WCAG AA), ein Fokusrahmen mindestens 3 : 1. Rot markierte Paare sind für einen Teil der Besucher schwer lesbar.',
    'Automatic primary and secondary colours keep the hue of the light ones, made lighter until links, buttons and focus rings are readable on the dark background. Pick a colour to set your own.' => 'Automatische Primär- und Sekundärfarben behalten den Farbton der hellen Farben und werden so weit aufgehellt, dass Links, Buttons und Fokusrahmen auf dem dunklen Hintergrund lesbar sind. Wählen Sie eine Farbe, um eine eigene festzulegen.',
    'Readability in dark mode' => 'Lesbarkeit im Dunkelmodus',
    'Dark mode: some colour pairs are hard to read – see the readability list in the Dark mode tab.' => 'Dunkelmodus: Einige Farbpaare sind schwer lesbar – siehe die Lesbarkeitsliste im Tab „Dunkelmodus“.',
    'Menus go to the draft look with links to the new addresses: the navigation on the site changes only when you publish the look.' => 'Menüs gehen mit Links auf die neuen Adressen in den Entwurf des Erscheinungsbilds: Die Navigation der Website ändert sich erst, wenn Sie das Erscheinungsbild veröffentlichen.',
    'Menu “%s” (%s items): %s' => 'Menü „%s“ (%s Einträge): %s',
    'left out – this site has a main and a footer menu' => 'ausgelassen – diese Website hat ein Hauptmenü und ein Menü im Fußbereich',
    '%s pages and posts were laid out with %s: the layout is not in the export, only the text in the post content comes over.' => '%s Seiten und Beiträge wurden mit %s gestaltet: Das Layout ist nicht im Export, nur der Text im Beitragsinhalt wird übernommen.',
    'User accounts and passwords – no account is created. A news item belongs to the user here with the same e-mail as its WordPress author, otherwise to you. Comments are not transferred.' => 'Benutzerkonten und Passwörter – es wird kein Konto angelegt. Eine News gehört dem Benutzer dieser Website mit derselben E-Mail-Adresse wie ihr WordPress-Autor, sonst Ihnen. Kommentare werden nicht übernommen.',
    'Widgets, appearance and plugin settings.' => 'Widgets, Erscheinungsbild und Einstellungen von Plugins.',
    'navigation menus (%s) into the draft look' => 'Navigationsmenüs (%s) in den Entwurf des Erscheinungsbilds',
    'everything hidden – news as drafts, pages hidden; publish them when they are ready' => 'alles verborgen – News als Entwürfe, Seiten verborgen; veröffentlicht wird, wenn sie fertig sind',
    'Public on WordPress, imported hidden' => 'In WordPress öffentlich, verborgen importiert',
    'this site has a main and a footer menu, and other menus took them' => 'diese Website hat ein Hauptmenü und ein Menü im Fußbereich, und andere Menüs haben sie belegt',
    'none of its links lead to anything that was imported' => 'keiner seiner Links führt zu etwas, das importiert wurde',
    'the draft look already holds a different menu for this place – nothing was overwritten' => 'der Entwurf des Erscheinungsbilds enthält für diese Stelle schon ein anderes Menü – nichts wurde überschrieben',
    'it was imported by an earlier run' => 'es wurde schon bei einem früheren Durchlauf importiert',
    'Menu “%s” is in the draft look – %s, %s items. Publish the look to show it on the site.' => 'Menü „%s“ ist im Entwurf des Erscheinungsbilds – %s, %s Einträge. Auf der Website erscheint es, sobald das Erscheinungsbild veröffentlicht ist.',
    'Menu “%s” was not imported: %s.' => 'Menü „%s“ wurde nicht importiert: %s.',
    'Open the menu' => 'Menü öffnen',
    '%s: the news items belong to you' => '%s: Die News gehören Ihnen',
    '%s: the news items belong to %s, who has the same e-mail' => '%s: Die News gehören %s mit derselben E-Mail-Adresse',
    '%s: the news items belong to %s' => '%s: Die News gehören %s',
    'Old addresses that were not redirected (%s)' => 'Alte Adressen ohne Weiterleitung (%s)',
    'the address is already in use on this site' => 'die Adresse wird auf dieser Website schon verwendet',
    'the address already redirects elsewhere' => 'die Adresse leitet schon woandershin weiter',
    'The file is larger than the download limit.' => 'Die Datei ist größer, als heruntergeladen werden kann.',
    'colours' => 'Farben',
    'fonts' => 'Schriften',
    'sizes' => 'Größen',
    'design system' => 'Designsystem',
    'classes' => 'Klassen',
    'menu' => 'Menü',
    'Unpublished changes:' => 'Nicht veröffentlichte Änderungen:',
    'Visitors still see the published look until you publish.' => 'Besucher sehen das veröffentlichte Erscheinungsbild, bis Sie veröffentlichen.',
    'Review' => 'Ansehen',
    'The menu is published – visitors see it now.' => 'Das Menü ist veröffentlicht – Besucher sehen es jetzt.',
    'Save and publish menu' => 'Menü speichern und veröffentlichen',
    'Save to the draft look' => 'Im Entwurf des Erscheinungsbilds speichern',
    'Publishing the menu leaves other unpublished look changes (colours, fonts, classes) waiting in the draft.' => 'Das Veröffentlichen des Menüs lässt andere nicht veröffentlichte Änderungen am Erscheinungsbild (Farben, Schriften, Klassen) im Entwurf warten.',
    'menu published' => 'Menü veröffentlicht',
    'Enter the old address – a path on this site, e.g. /old-page.' => 'Alte Adresse eingeben – ein Pfad auf dieser Website, z. B. /alte-seite.',
    'An address may have at most 255 characters.' => 'Eine Adresse darf höchstens 255 Zeichen haben.',
    'The old address must be a path on this site, e.g. /old-page (without ? or #).' => 'Die alte Adresse muss ein Pfad auf dieser Website sein, z. B. /alte-seite (ohne ? oder #).',
    'Use at most 3 wildcards (*) in the old address, never two in a row.' => 'Höchstens 3 Platzhalter (*) in der alten Adresse, nie zwei hintereinander.',
    'A pattern needs a fixed part besides the wildcards, e.g. /blog/*.' => 'Ein Muster braucht neben den Platzhaltern einen festen Teil, z. B. /blog/*.',
    'The target must be a path on this site or a full https://… address; a wildcard (*) only after the domain.' => 'Das Ziel muss ein Pfad auf dieser Website oder eine vollständige https://…-Adresse sein; ein Platzhalter (*) nur nach der Domain.',
    'The target has more wildcards (*) than the old address.' => 'Das Ziel hat mehr Platzhalter (*) als die alte Adresse.',
    'The old address and the target are the same.' => 'Alte Adresse und Ziel sind gleich.',
    'It would make a loop – the redirects would lead back to this address.' => 'Es entstünde eine Schleife – die Weiterleitungen führten zurück zu dieser Adresse.',
    'The site already has the most pattern rules it can use (500).' => 'Die Website hat bereits die höchstmögliche Zahl an Musterregeln (500).',
    'Only 301 (permanent), 302 (temporary) and 410 (gone for good).' => 'Nur 301 (dauerhaft), 302 (vorübergehend) und 410 (endgültig entfernt).',
    'Enter the target – a path on this site or a full https://… address.' => 'Ziel eingeben – ein Pfad auf dieser Website oder eine vollständige https://…-Adresse.',
    'The same old address is in an earlier row – the first one counts.' => 'Dieselbe alte Adresse steht schon in einer früheren Zeile – die erste zählt.',
    'The rule is switched off in the file.' => 'Die Regel ist in der Datei ausgeschaltet.',
    'A regular expression – add this one by hand as a pattern with * (e.g. /blog/* → /news/*).' => 'Ein regulärer Ausdruck – diese Regel von Hand als Muster mit * anlegen (z. B. /blog/* → /news/*).',
    'Choose a CSV file or paste its rows (old address, target, code).' => 'CSV-Datei wählen oder ihre Zeilen einfügen (alte Adresse, Ziel, Code).',
    'The file has no redirects – one per row: old address, target, code (301 or 302).' => 'Die Datei enthält keine Weiterleitungen – eine pro Zeile: alte Adresse, Ziel, Code (301 oder 302).',
    'Import redirects' => 'Weiterleitungen importieren',
    'Redirects imported: %d added, %d changed, %d refused.' => 'Weiterleitungen importiert: %d hinzugefügt, %d geändert, %d abgelehnt.',
    'An asterisk stands for the rest of the address: /blog/* → /news/* sends /blog/2019/post to /news/2019/post. An exact redirect always wins over a pattern, and the longer fixed beginning wins among patterns.' => 'Ein Sternchen steht für den Rest der Adresse: /blog/* → /news/* leitet /blog/2019/beitrag nach /news/2019/beitrag. Eine exakte Weiterleitung hat immer Vorrang vor einem Muster, unter Mustern gewinnt der längere feste Anfang.',
    'Leave it empty for “gone (410)”.' => 'Für „entfernt (410)“ leer lassen.',
    'gone (410) – removed for good, search engines drop it' => 'entfernt (410) – endgültig gelöscht, Suchmaschinen nehmen die Adresse heraus',
    'gone (410)' => 'entfernt (410)',
    'Import from a CSV file' => 'Import aus einer CSV-Datei',
    'One redirect per row: old address, target and code (301 or 302, empty = 301; 410 with an empty target = gone for good). A header row is optional; the CSV export of the WordPress Redirection plugin works as it is. You see what will be added, changed or refused before anything is saved.' => 'Eine Weiterleitung pro Zeile: alte Adresse, Ziel und Code (301 oder 302, leer = 301; 410 mit leerem Ziel = endgültig entfernt). Eine Kopfzeile ist optional; der CSV-Export des WordPress-Plugins Redirection funktioniert unverändert. Vor dem Speichern ist zu sehen, was hinzugefügt, geändert oder abgelehnt wird.',
    'CSV file' => 'CSV-Datei',
    'Or paste the rows' => 'Oder Zeilen einfügen',
    'Show what will change' => 'Anzeigen, was sich ändert',
    'will be added' => 'wird hinzugefügt',
    'will change' => 'wird geändert',
    'refused' => 'abgelehnt',
    '%d rows: %d will be added, %d will change, %d stay as they are, %d are refused.' => '%d Zeilen: %d werden hinzugefügt, %d geändert, %d bleiben unverändert, %d werden abgelehnt.',
    'Row' => 'Zeile',
    'Save %d redirects' => '%d Weiterleitungen speichern',
    'the news list' => 'die Nachrichtenliste',
    'items of %s' => 'Einträge von %s',
    'pages under %s' => 'Seiten unter %s',
    'also: %s' => 'auch: %s',
    'Also on' => 'Auch auf',
    'Besides the pages above, the variant can take a kind of content. A page ticked above always gets its variant; otherwise the first variant (by name) whose choice fits wins.' => 'Neben den Seiten oben kann die Variante für eine Art von Inhalt gelten. Eine oben angehakte Seite erhält immer ihre Variante; sonst gewinnt die erste Variante (nach Name), deren Auswahl passt.',
    'the news list, categories, tags and search' => 'die Nachrichtenliste, Kategorien, Schlagwörter und Suche',
    'Pages under' => 'Seiten unter',
    'The export file changed after the preview, so the import stopped. Start it again with the file you want to import.' => 'Die Exportdatei hat sich nach der Vorschau geändert, deshalb wurde der Import angehalten. Starten Sie ihn erneut mit der Datei, die Sie importieren möchten.',
    'A cron job that already calls the older address …/ulohy?token= keeps working – there is no need to change it.' => 'Ein Cron-Job, der bereits die ältere Adresse …/ulohy?token= aufruft, funktioniert weiter – Sie müssen ihn nicht ändern.',
    'English system addresses' => 'Englische Systemadressen',
    'The site itself uses %s, so the system keeps writing the older address %s there – both keep working. Rename the page if you want the English address.' => 'Die Website selbst verwendet %s, daher schreibt das System dort weiterhin die ältere Adresse %s – beide funktionieren. Benennen Sie die Seite um, wenn Sie die englische Adresse möchten.',
    'Undo journal of Claude sessions: older than 30 days removed' => 'Rückgängig-Protokoll der Claude-Sitzungen: Einträge älter als 30 Tage entfernt',
    'Online booking: reminders before the appointment' => 'Online-Terminbuchung: Erinnerungen vor dem Termin',
    'Imports not finished' => 'Nicht abgeschlossene Importe',
    '%s rows' => '%s Zeilen',
    'A CSV file (from Excel or another system – comma, semicolon or tab) or a JSON list, up to %s rows. The first row names the columns; one row is one item. You pair the columns with the fields and see what will be added, changed or refused before anything is saved.' => 'Eine CSV-Datei (aus Excel oder einem anderen System – Komma, Semikolon oder Tabulator) oder eine JSON-Liste mit höchstens %s Zeilen. Die erste Zeile benennt die Spalten, jede weitere Zeile ist ein Eintrag. Sie ordnen die Spalten den Feldern zu und sehen vor dem Speichern, was hinzugefügt, geändert oder abgelehnt wird.',
    'Columns named like the fields are paired by themselves: %s.' => 'Spalten mit dem Namen eines Feldes werden automatisch zugeordnet: %s.',
    'An image or file column with web addresses (https://…) is downloaded into Media after the items are saved.' => 'Eine Bild- oder Dateispalte mit Webadressen (https://…) wird nach dem Speichern der Einträge in die Medien heruntergeladen.',
    'CSV or JSON file' => 'CSV- oder JSON-Datei',
    'Another file' => 'Andere Datei',
    '%s: %d rows – %d will be added, %d will change, %d stay as they are, %d are refused.' => '%s: %d Zeilen – %d werden hinzugefügt, %d geändert, %d bleiben unverändert, %d werden abgelehnt.',
    'Column in the file' => 'Spalte in der Datei',
    'Example' => 'Beispiel',
    'Goes to' => 'Wird gespeichert in',
    '– not imported –' => '– nicht importieren –',
    'Default language' => 'Standardsprache',
    'For rows without a language column.' => 'Für Zeilen ohne Sprachspalte.',
    'Show new items on the site at once' => 'Neue Einträge sofort auf der Website anzeigen',
    'Without it new items arrive hidden, so you can check them first. Items that change keep their visibility.' => 'Ohne diese Option kommen neue Einträge verborgen an, damit Sie sie zuerst prüfen können. Geänderte Einträge behalten ihre Sichtbarkeit.',
    'An item is found by its address (slug), or by the address made from its name – importing the same file again updates the items instead of adding them twice. An empty cell leaves the value of an item as it is.' => 'Ein Eintrag wird über seine Adresse (Slug) gefunden oder über die aus seinem Namen gebildete Adresse – ein erneuter Import derselben Datei aktualisiert die Einträge, statt sie doppelt anzulegen. Eine leere Zelle lässt den Wert eines Eintrags unverändert.',
    'Update preview' => 'Vorschau aktualisieren',
    'Save %d items' => '%d Einträge speichern',
    'Invalid value, left empty: %s' => 'Ungültiger Wert, bleibt leer: %s',
    'The first 100 rows are shown, then the refused ones and those with an invalid value.' => 'Angezeigt werden die ersten 100 Zeilen, danach die abgelehnten und die mit einem ungültigen Wert.',
    'File: %s' => 'Datei: %s',
    'Saving: %s of %s rows. Keep this page open, it continues by itself.' => 'Speichern: %s von %s Zeilen. Lassen Sie diese Seite geöffnet, sie läuft von selbst weiter.',
    'Downloading images: %s of %s. Keep this page open, it continues by itself.' => 'Bilder werden heruntergeladen: %s von %s. Lassen Sie diese Seite geöffnet, sie läuft von selbst weiter.',
    'The import is finished.' => 'Der Import ist abgeschlossen.',
    'The import is finished. New items are hidden until you check and show them.' => 'Der Import ist abgeschlossen. Neue Einträge bleiben verborgen, bis Sie sie prüfen und anzeigen.',
    'No change' => 'Keine Änderung',
    'Refused' => 'Abgelehnt',
    '%d items had a field with an invalid value – it was left empty. Check them in the list.' => 'Bei %d Einträgen hatte ein Feld einen ungültigen Wert – es blieb leer. Prüfen Sie sie in der Liste.',
    'Refused rows: %d' => 'Abgelehnte Zeilen: %d',
    'Row %d' => 'Zeile %d',
    '%d images could not be downloaded' => '%d Bilder konnten nicht heruntergeladen werden',
    'Show items' => 'Einträge anzeigen',
    'Import another file' => 'Weitere Datei importieren',
    'Import from CSV or JSON' => 'Import aus CSV oder JSON',
    'Import items: %s' => 'Einträge importieren: %s',
    'The file is larger than %d MB.' => 'Die Datei ist größer als %d MB.',
    'The robots.txt of the old site asks robots not to read this page, so only the address was checked.' => 'Die robots.txt der alten Website bittet Robots, diese Seite nicht zu lesen, deshalb wurde nur die Adresse geprüft.',
    'Address (slug)' => 'Adresse (Slug)',
    'Title for search engines' => 'Titel für Suchmaschinen',
    'Description for search engines' => 'Beschreibung für Suchmaschinen',
    'Image for sharing' => 'Bild zum Teilen',
    'The file is empty.' => 'Die Datei ist leer.',
    'The file has no rows – the first row names the columns, every further row is one item.' => 'Die Datei hat keine Zeilen – die erste Zeile benennt die Spalten, jede weitere ist ein Eintrag.',
    'The file has more than 5,000 rows – split it into smaller files.' => 'Die Datei hat mehr als 5.000 Zeilen – teilen Sie sie in kleinere Dateien auf.',
    'The JSON file must be a list of items: [{"name":"…","price":"…"}, …].' => 'Die JSON-Datei muss eine Liste von Einträgen sein: [{"name":"…","price":"…"}, …].',
    'The file could not be read.' => 'Die Datei konnte nicht gelesen werden.',
    'The item is in the trash – restore it first.' => 'Der Eintrag liegt im Papierkorb – stellen Sie ihn zuerst wieder her.',
    'The same item is in this batch twice – only the first one is saved.' => 'Derselbe Eintrag kommt zweimal vor – nur der erste wird gespeichert.',
    'Invalid item address.' => 'Ungültige Adresse des Eintrags.',
    'The item could not be saved.' => 'Der Eintrag konnte nicht gespeichert werden.',
    'Only https addresses are downloaded.' => 'Heruntergeladen werden nur https-Adressen.',
    'This server cannot download files from other sites.' => 'Dieser Server kann keine Dateien von anderen Websites herunterladen.',
    'SVG files are not downloaded – upload them with upload_file.' => 'SVG-Dateien werden nicht heruntergeladen – laden Sie sie über die Medien hoch.',
    'The robots.txt of the old site asks robots not to read this page.' => 'Die robots.txt der alten Website bittet Robots, diese Seite nicht zu lesen.',
    'Categories: %s' => 'Kategorien: %s',
    'Category page: %s' => 'Kategorieseite: %s',
    'Category description' => 'Kategoriebeschreibung',
    'Number of items' => 'Anzahl der Einträge',
    'Parent category' => 'Übergeordnete Kategorie',
    'Parent category page' => 'Seite der übergeordneten Kategorie',
    'Add category' => 'Kategorie hinzufügen',
    'Category page template' => 'Vorlage der Kategorieseite',
    'Category page template (%s)' => 'Vorlage der Kategorieseite (%s)',
    'No categories yet.' => 'Noch keine Kategorien.',
    'Categories sort the items into groups with their own pages – /%s/category and /%s/category/subcategory – with a description, breadcrumbs and a list of the items. Tick the categories on each item.' => 'Kategorien ordnen die Einträge in Gruppen mit eigenen Seiten – /%s/kategorie und /%s/kategorie/unterkategorie – mit Beschreibung, Brotkrumen und einer Liste der Einträge. Die Kategorien werden bei jedem Eintrag angehakt.',
    'Two levels: a category and its subcategories. A category page lists the items of the category and of its subcategories; an address can never be both a category and an item of this collection.' => 'Zwei Ebenen: eine Kategorie und ihre Unterkategorien. Eine Kategorieseite listet die Einträge der Kategorie und ihrer Unterkategorien; eine Adresse gehört nie zugleich einer Kategorie und einem Eintrag dieser Sammlung.',
    'Edit the %s version' => 'Version %s bearbeiten',
    'Add the %s version' => 'Version %s hinzufügen',
    'Add subcategory' => 'Unterkategorie hinzufügen',
    'Delete the category in every language? Its items stay in the collection; its page disappears.' => 'Die Kategorie in allen Sprachen löschen? Ihre Einträge bleiben in der Sammlung, nur ihre Seite verschwindet.',
    'From the name if left empty. It cannot be the address of an item of this collection.' => 'Leer = aus dem Namen. Es darf nicht die Adresse eines Eintrags dieser Sammlung sein.',
    'Shown on the category page ({{popis}} in the category template) – an introduction for visitors and search engines.' => 'Erscheint auf der Kategorieseite ({{popis}} in der Kategorievorlage) – eine Einleitung für Besucher und Suchmaschinen.',
    'empty = the category name' => 'leer = der Kategoriename',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the description.' => 'Ein, zwei Sätze für die Suchergebnisse (bis 160 Zeichen). Leer = der Anfang der Beschreibung.',
    'Shared by every language' => 'Für alle Sprachen gemeinsam',
    '– none (a top-level category) –' => '– keine (eine Kategorie der obersten Ebene) –',
    'It has subcategories, so it stays a top-level category.' => 'Sie hat Unterkategorien und bleibt daher eine Kategorie der obersten Ebene.',
    'Shown on the category page and its card ({{obrazek}}) and when the page is shared.' => 'Erscheint auf der Kategorieseite, auf ihrer Karte ({{obrazek}}) und beim Teilen der Seite.',
    'A hidden category has no page and is in no list; its items stay where they are.' => 'Eine verborgene Kategorie hat keine Seite und steht in keiner Liste; ihre Einträge bleiben, wo sie sind.',
    'Save category' => 'Kategorie speichern',
    'Remove the %s version of the category? The other languages keep it.' => 'Die Version %s der Kategorie entfernen? Die anderen Sprachen behalten sie.',
    'Remove this language version' => 'Diese Sprachversion entfernen',
    'The item is listed on the pages of the ticked categories (a top-level category page also lists the items of its subcategories).' => 'Der Eintrag erscheint auf den Seiten der angehakten Kategorien (die Seite einer Kategorie der obersten Ebene listet auch die Einträge ihrer Unterkategorien).',
    'Manage categories' => 'Kategorien verwalten',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s, so a higher limit applies only up to that.' => 'Größenlimit je Anhang in MB (1–25). Dieser Server nimmt Dateien bis %s an, ein höheres Limit gilt daher nur bis zu dieser Grenze.',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s.' => 'Größenlimit je Anhang in MB (1–25). Dieser Server nimmt Dateien bis %s an.',
    'Attachment size limit per file in MB (1–25)' => 'Größenlimit je Anhang in MB (1–25)',
    'The address “%s” belongs to a category of this collection – give the item another address.' => 'Die Adresse „%s“ gehört einer Kategorie dieser Sammlung – der Eintrag braucht eine andere Adresse.',
    'The category does not exist in this collection.' => 'Die Kategorie gibt es in dieser Sammlung nicht.',
    'The category needs a name.' => 'Die Kategorie braucht einen Namen.',
    'The address “%s” cannot be used for a category.' => 'Die Adresse „%s“ kann für eine Kategorie nicht verwendet werden.',
    'The address “%s” is already used by another category of this collection.' => 'Die Adresse „%s“ verwendet bereits eine andere Kategorie dieser Sammlung.',
    'The address “%s” is already used by an item of this collection – a category page and an item page cannot share it.' => 'Die Adresse „%s“ verwendet bereits ein Eintrag dieser Sammlung – eine Kategorieseite und eine Eintragsseite können sie nicht teilen.',
    'A subcategory belongs under a top-level category of the same collection (two levels).' => 'Eine Unterkategorie gehört unter eine Kategorie der obersten Ebene derselben Sammlung (zwei Ebenen).',
    'The category has subcategories, so it cannot become a subcategory itself (two levels).' => 'Die Kategorie hat Unterkategorien und kann daher selbst keine Unterkategorie werden (zwei Ebenen).',
    'The image must be a file from Media or an https address.' => 'Das Bild muss eine Datei aus den Medien oder eine https-Adresse sein.',
    'The category has subcategories – delete them or move them under another category first.' => 'Die Kategorie hat Unterkategorien – diese zuerst löschen oder unter eine andere Kategorie verschieben.',
    'There is nothing in this category yet.' => 'In dieser Kategorie gibt es noch nichts.',
    'Item name' => 'Name des Eintrags',
    'Previous and next item' => 'Vorheriger und nächster Eintrag',
    'The category was saved.' => 'Die Kategorie wurde gespeichert.',
    'The category was deleted; its items stay in the collection.' => 'Die Kategorie wurde gelöscht; ihre Einträge bleiben in der Sammlung.',
    'Previous / next item' => 'Vorheriger / nächster Eintrag',
    'Links to the previous and the next item on an item page (references, products, projects) – in the collection order or by date, within the item’s category.' => 'Links zum vorherigen und nächsten Eintrag auf einer Eintragsseite (Referenzen, Produkte, Projekte) – in der Reihenfolge der Sammlung oder nach Datum, innerhalb der Kategorie des Eintrags.',
    'items' => 'Einträge',
    'Category (its address; * = the category page shown, on an item page the item’s category). Categories: the subcategories of it, empty = the top-level ones' => 'Kategorie (ihre Adresse; * = die angezeigte Kategorieseite, auf einer Eintragsseite die Kategorie des Eintrags). Bei Kategorien: ihre Unterkategorien, leer = die der obersten Ebene',
    'as in the administration (order, then name)' => 'wie in der Verwaltung (Reihenfolge, dann Name)',
    'by date (previous = older)' => 'nach Datum (vorheriger = älter)',
    'Only within the item’s category (when it has one)' => 'Nur innerhalb der Kategorie des Eintrags (wenn er eine hat)',
    'Label of the previous item' => 'Beschriftung des vorherigen Eintrags',
    'Label of the next item' => 'Beschriftung des nächsten Eintrags',
    'Show the item names' => 'Namen der Einträge anzeigen',
    'Show thumbnails' => 'Vorschaubilder anzeigen',
    'Thumbnail field (key of an image field; empty = the first image field)' => 'Feld des Vorschaubilds (Schlüssel eines Bildfelds; leer = das erste Bildfeld)',
    'Collection categories' => 'Sammlungskategorien',
    'version %s needs PHP %s or newer, the server runs PHP %s – ask the hosting for a newer PHP to update' => 'Version %s benötigt PHP %s oder neuer, auf dem Server läuft PHP %s – bitten Sie den Hoster für das Update um ein neueres PHP',
    'Version %s needs PHP %s or newer; the server runs PHP %s. Ask your hosting to switch the site to a newer PHP, then the update will be offered here.' => 'Version %s benötigt PHP %s oder neuer; auf dem Server läuft PHP %s. Bitten Sie Ihren Hoster, die Website auf ein neueres PHP umzustellen, dann wird Ihnen das Update hier angeboten.',
    'The robots.txt of the old site is very long: only its first %s KB and %s rules for Kaleta were read.' => 'Die robots.txt der alten Website ist sehr lang: Nur die ersten %s KB und %s Regeln für Kaleta wurden gelesen.',
    '%s sitemaps on other hosts were not read (%s): only the old site’s own sitemaps are followed.' => '%s Sitemaps auf anderen Hosts wurden nicht gelesen (%s): Es werden nur die eigenen Sitemaps der alten Website gelesen.',
    '%s more sitemaps were not read: at most %s are read.' => 'Weitere %s Sitemaps wurden nicht gelesen: Es werden höchstens %s gelesen.',
    'Finished imports' => 'Abgeschlossene Importe',
    'The result of an import stays here until you remove it, at most %s days; the items stay either way. The uploaded rows are deleted as soon as they are saved.' => 'Das Ergebnis eines Imports bleibt hier, bis Sie es entfernen, höchstens %s Tage; die Einträge bleiben in jedem Fall. Die hochgeladenen Zeilen werden gelöscht, sobald sie gespeichert sind.',
    'Remove this import' => 'Diesen Import entfernen',
    'The address %s is used by the system, so the page got %s.' => 'Die Adresse %s verwendet das System, daher hat die Seite %s bekommen.',
    'The page has been restored with the address %s, because its old address %s is used by the system – publish it in its settings.' => 'Die Seite wurde mit der Adresse %s wiederhergestellt, weil das System ihre frühere Adresse %s verwendet – veröffentlichen Sie sie in ihren Einstellungen.',
    'Changed so the site keeps working:' => 'Geändert, damit die Website weiter funktioniert:',
    'Collection category %s: its parent is not a top-level category of the same collection, so it became a top-level category.' => 'Sammlungskategorie %s: Die übergeordnete Kategorie ist keine Hauptkategorie derselben Sammlung, daher wurde sie zur Hauptkategorie.',
    'Collection category “%s”: the address %s cannot be used (an item of the collection has it, or it is reserved), so the category got %s.' => 'Sammlungskategorie „%s“: Die Adresse %s ist nicht verwendbar (ein Eintrag der Sammlung hat sie, oder sie ist reserviert), daher hat die Kategorie %s bekommen.',
    'Its address %s is taken by another item or a category now, so the item keeps %s.' => 'Die Adresse %s hat jetzt ein anderer Eintrag oder eine Kategorie, daher behält der Eintrag %s.',
    'The item was restored as hidden with the address %s, because a category of the collection has its old address.' => 'Der Eintrag wurde verborgen mit der Adresse %s wiederhergestellt, weil eine Kategorie der Sammlung seine frühere Adresse hat.',
    'The address “%s” belongs to a category of this collection, so the item has “%s”.' => 'Die Adresse „%s“ gehört einer Kategorie dieser Sammlung, daher hat der Eintrag „%s“.',
    'Items with another address: %d' => 'Einträge mit anderer Adresse: %d',
    'A cron job that calls /tasks reaches that page and runs nothing – point it at /ulohy.' => 'Ein Cronjob, der /tasks aufruft, landet auf dieser Seite und startet nichts – richten Sie ihn auf /ulohy.',
    'PHP JIT' => 'PHP-JIT',
    'opcache.jit = %s on PHP %s can crash pages (a bug in PHP 8.3) – ask the hosting for opcache.jit = tracing (the default) or PHP 8.4' => 'opcache.jit = %s auf PHP %s kann Seiten abstürzen lassen (ein Fehler in PHP 8.3) – bitten Sie den Hoster um opcache.jit = tracing (Standard) oder PHP 8.4',
    'https://… or /page' => 'https://… oder /seite',
    'The update source of the stable channel does not offer a stable-channel release (aktualizace-stable.json), so nothing is offered. Switch to the Latest channel or check the custom update source.' => 'Die Update-Quelle des stabilen Kanals bietet keine Version des stabilen Kanals an (aktualizace-stable.json), daher wird nichts angeboten. Wechseln Sie zum Kanal „Neueste“ oder prüfen Sie die eigene Update-Quelle.',
    'Latest channel' => 'Kanal „Neueste“',
    'Stable channel' => 'Kanal „Stabil“',
    'custom update source' => 'eigene Update-Quelle',
    'This site runs version %s, which is newer than the stable channel (%s). Nothing is offered until the stable channel moves past this version – a site never goes back to an older one. Until then, security fixes reach this site only on the Latest channel.' => 'Diese Website läuft mit Version %s, die neuer ist als der stabile Kanal (%s). Bis der stabile Kanal diese Version überholt, wird nichts angeboten – eine Website kehrt nie zu einer älteren Version zurück. Bis dahin erreichen Sicherheitskorrekturen diese Website nur im Kanal „Neueste“.',
    'You have the newest version of the stable channel.' => 'Sie haben die neueste Version des stabilen Kanals.',
    'Update channel' => 'Update-Kanal',
    'Latest' => 'Neueste',
    'A new minor version every week, with new features and fixes. Recommended for most sites.' => 'Jede Woche eine neue Minor-Version mit neuen Funktionen und Korrekturen. Empfohlen für die meisten Websites.',
    'Stable' => 'Stabil',
    'Security fixes only, and a new minor version about once a month, after it has run on Latest. For sites that should change as little as possible.' => 'Nur Sicherheitskorrekturen und etwa einmal im Monat eine neue Minor-Version, nachdem sie sich im Kanal „Neueste“ bewährt hat. Für Websites, die sich so wenig wie möglich ändern sollen.',
    'The custom update source below is not a file named aktualizace.json, so it has no stable twin: the site follows it whatever channel you choose.' => 'Die eigene Update-Quelle unten ist keine Datei namens aktualizace.json und hat daher kein stabiles Gegenstück: Die Website folgt ihr, egal welchen Kanal Sie wählen.',
    'A site on Stable never goes back to an older version: after switching from Latest it waits until the stable channel passes the version it runs.' => 'Eine Website im Kanal „Stabil“ kehrt nie zu einer älteren Version zurück: Nach dem Wechsel von „Neueste“ wartet sie, bis der stabile Kanal ihre Version überholt.',
    'Stable – this site runs %s, newer than the stable channel (%s): nothing is offered until the stable channel passes it, so security fixes reach it only on Latest (Settings → Backups and updates)' => 'Stabil – diese Website läuft mit %s, neuer als der stabile Kanal (%s): Bis der stabile Kanal sie überholt, wird nichts angeboten, Sicherheitskorrekturen erreichen sie also nur im Kanal „Neueste“ (Einstellungen → Backups und Updates)',
    'Stable – security fixes only, a new minor version about once a month' => 'Stabil – nur Sicherheitskorrekturen, etwa einmal im Monat eine neue Minor-Version',
    'custom update source – the site follows it whatever channel is chosen' => 'eigene Update-Quelle – die Website folgt ihr unabhängig vom gewählten Kanal',
    'Latest – a new minor version every week' => 'Neueste – jede Woche eine neue Minor-Version',
    'Kaleta version' => 'Kaleta-Version',
    'The markup is %s bytes long; the limit is %s.' => 'Der Code ist %s Bytes lang; die Grenze liegt bei %s.',
    'The markup is nested %s levels deep; the limit is %s.' => 'Der Code ist %s Ebenen tief verschachtelt; die Grenze liegt bei %s.',
    'An element in the markup has %s attributes; the limit is %s.' => 'Ein Element im Code hat %s Attribute; die Grenze liegt bei %s.',
    'The markup has %s elements; the limit is %s.' => 'Der Code hat %s Elemente; die Grenze liegt bei %s.',
    'The SVG file was refused: %s' => 'Die SVG-Datei wurde abgelehnt: %s',
    'The page was not imported: %s' => 'Die Seite wurde nicht importiert: %s',
    'Nothing was saved: %s' => 'Es wurde nichts gespeichert: %s',
    'The description: %s' => 'Beschreibung: %s',
    'The old page is over a safety limit for HTML (too large or nested too deeply), so only the address was checked.' => 'Die alte Seite überschreitet eine Sicherheitsgrenze für HTML (zu groß oder zu tief verschachtelt), daher wurde nur die Adresse geprüft.',
    'Not imported – the HTML is over a safety limit:' => 'Nicht importiert – das HTML überschreitet eine Sicherheitsgrenze:',
    '“%s” was skipped: %s' => '„%s“ wurde übersprungen: %s',
    'A builder field (%s) was over a safety limit for HTML and was left empty.' => 'Ein Builder-Feld (%s) überschritt eine Sicherheitsgrenze für HTML und blieb leer.',
    'Collection category “%s”: the description was left empty: %s' => 'Sammlungskategorie „%s“: Die Beschreibung blieb leer: %s',
    'The assistant\'s reply is over a safety limit for HTML. Please try again.' => 'Die Antwort des Assistenten überschreitet eine Sicherheitsgrenze für HTML. Bitte erneut versuchen.',
    'The text is over a safety limit for HTML (too large or nested too deeply), so it cannot be translated.' => 'Der Text überschreitet eine Sicherheitsgrenze für HTML (zu groß oder zu tief verschachtelt) und kann daher nicht übersetzt werden.',
    'Nothing was saved: the text is over a safety limit for HTML (too large or nested too deeply).' => 'Es wurde nichts gespeichert: Der Text überschreitet eine Sicherheitsgrenze für HTML (zu groß oder zu tief verschachtelt).',
    'Send through' => 'Senden über',
    'Other server – your host, Google Workspace, Seznam…' => 'Anderer Server – Ihr Hosting, Google Workspace, Seznam…',
    'Mail services with an SMTP relay' => 'Maildienste mit SMTP-Relay',
    'A mail service fills in the server, the port and the encryption. The user name and the password stay yours to paste – the service’s SMTP credentials, not its API key unless the service says so.' => 'Ein Maildienst trägt Server, Port und Verschlüsselung ein. Benutzername und Passwort fügen Sie selbst ein – die SMTP-Zugangsdaten des Dienstes, nicht seinen API-Schlüssel, sofern der Dienst nichts anderes sagt.',
    'Amazon SES region' => 'Amazon-SES-Region',
    'The region where the sending domain is verified in Amazon SES – the SMTP credentials work only there.' => 'Die Region, in der die Absenderdomain in Amazon SES verifiziert ist – die SMTP-Zugangsdaten gelten nur dort.',
    'User name' => 'Benutzername',
    'Your newsletter integration uses %s too. Its API key is not copied here – the SMTP relay signs in with its own credentials, so paste them below.' => 'Auch die Newsletter-Anbindung nutzt %s. Deren API-Schlüssel wird hier nicht übernommen – das SMTP-Relay meldet sich mit eigenen Zugangsdaten an; fügen Sie diese unten ein.',
    'Newsletter integration' => 'Newsletter-Anbindung',
    '%s: SMTP guide' => '%s: SMTP-Anleitung',
    'Your newsletter integration uses %s, which also relays e-mail over SMTP – choose %s above to send the site’s mail through the same account.' => 'Die Newsletter-Anbindung nutzt %s, das auch E-Mails per SMTP versendet – wählen Sie oben %s, damit die Mails der Website über dasselbe Konto gehen.',
    'DNS records for %s' => 'DNS-Einträge für %s',
    'The SPF record of %s must include %s – one SPF record per domain, for example:' => 'Der SPF-Eintrag von %s muss %s enthalten – pro Domain nur ein SPF-Eintrag, zum Beispiel:',
    'none found on %s' => 'auf %s keiner gefunden',
    'found – all is well' => 'gefunden – alles in Ordnung',
    'found, but it does not seem to include %s yet' => 'gefunden, enthält aber offenbar noch nicht %s',
    'not found yet' => 'noch nicht gefunden',
    'System status checks the sending domain once a day; after adding the records, use Check now there.' => 'Der Systemstatus prüft die Absenderdomain einmal am Tag; nach dem Hinzufügen der Einträge dort „Jetzt prüfen“ verwenden.',
    'The site’s own e-mail goes through %s too (Settings → Mail), signed in with an SMTP key of its own – this API key is not used there.' => 'Die eigenen E-Mails der Website gehen ebenfalls über %s (Einstellungen → E-Mail), angemeldet mit einem eigenen SMTP-Schlüssel – dieser API-Schlüssel wird dort nicht verwendet.',
    '%s can also send the site’s own e-mail (password resets, enquiries, newsletters) over SMTP – choose it in Settings → Mail and paste an SMTP key there; this API key is not copied.' => '%s kann auch die eigenen E-Mails der Website (Passwort-Links, Anfragen, Newsletter) per SMTP versenden – wählen Sie den Dienst unter Einstellungen → E-Mail und fügen Sie dort einen SMTP-Schlüssel ein; dieser API-Schlüssel wird nicht übernommen.',
    'Settings → Mail' => 'Einstellungen → E-Mail',
    '%s needs no include in this record – its DKIM and return-path records authenticate the mail' => '%s braucht in diesem Eintrag kein include – die DKIM- und Return-Path-Einträge des Dienstes authentifizieren die E-Mails',
    'no DKIM key found under the common selectors. %s: %s' => 'unter den üblichen Selektoren kein DKIM-Schlüssel gefunden. %s: %s',
    'via %s (SMTP server %s)' => 'über %s (SMTP-Server %s)',
    'E-mail: sent through %s (SMTP server %s) – the service processes the recipients’ addresses and the messages.' => 'E-Mail: versendet über %s (SMTP-Server %s) – der Dienst verarbeitet die Adressen der Empfänger und die Nachrichten.',
    '%s – password: %s' => '%s – Passwort: %s',
    'The SMTP login shown in Brevo under SMTP & API → SMTP (it ends in @smtp-brevo.com).' => 'Der SMTP-Login, den Brevo unter SMTP & API → SMTP anzeigt (er endet auf @smtp-brevo.com).',
    'An SMTP key generated on the same page – not an API key: the Brevo relay refuses API keys.' => 'Ein auf derselben Seite erzeugter SMTP-Schlüssel – kein API-Schlüssel: Das Brevo-Relay lehnt API-Schlüssel ab.',
    'In Brevo → Senders, Domains → Domains, authenticate the sending domain: add the brevo-code TXT record and the two DKIM records (brevo1._domainkey and brevo2._domainkey) Brevo shows. With shared sending IPs no SPF include is needed.' => 'In Brevo → Senders, Domains → Domains die Absenderdomain authentifizieren: den TXT-Eintrag brevo-code und die beiden DKIM-Einträge (brevo1._domainkey und brevo2._domainkey) hinzufügen, die Brevo anzeigt. Bei geteilten Versand-IPs ist kein SPF-include nötig.',
    'The SMTP login of your sending domain from Mailgun → Sending → Domain settings → SMTP credentials, for example postmaster@mg.example.com.' => 'Der SMTP-Login Ihrer Absenderdomain aus Mailgun → Sending → Domain settings → SMTP credentials, zum Beispiel postmaster@mg.example.com.',
    'The password of that SMTP login – not the Mailgun API key.' => 'Das Passwort dieses SMTP-Logins – nicht der Mailgun-API-Schlüssel.',
    'Mailgun → Sending → Domains → DNS records lists the SPF (include:mailgun.org) and DKIM TXT records for the sending domain – add both.' => 'Mailgun → Sending → Domains → DNS records nennt die TXT-Einträge für SPF (include:mailgun.org) und DKIM der Absenderdomain – beide hinzufügen.',
    'The SMTP user name from Amazon SES → SMTP settings → Create SMTP credentials – not the AWS access key ID.' => 'Der SMTP-Benutzername aus Amazon SES → SMTP settings → Create SMTP credentials – nicht die AWS Access Key ID.',
    'The SMTP password shown once with it – not the AWS secret access key.' => 'Das SMTP-Passwort, das einmalig dazu angezeigt wird – nicht der AWS Secret Access Key.',
    'Verify the sending domain in Amazon SES with Easy DKIM: add the three CNAME records (…._domainkey) SES shows. include:amazonses.com in SPF is needed only with a custom MAIL FROM domain.' => 'Die Absenderdomain in Amazon SES mit Easy DKIM verifizieren: die drei CNAME-Einträge (…._domainkey) hinzufügen, die SES anzeigt. include:amazonses.com im SPF ist nur mit einer eigenen MAIL-FROM-Domain nötig.',
    'The Access Key of an SMTP token (Postmark → your server → the message stream → Settings), or the Server API token. For newsletters use a broadcast stream and the server smtp-broadcasts.postmarkapp.com.' => 'Der Access Key eines SMTP-Tokens (Postmark → Ihr Server → der Message Stream → Settings) oder das Server-API-Token. Für Newsletter einen Broadcast-Stream und den Server smtp-broadcasts.postmarkapp.com verwenden.',
    'The Secret Key of that SMTP token – or the same Server API token again, which Postmark accepts as both.' => 'Der Secret Key dieses SMTP-Tokens – oder noch einmal dasselbe Server-API-Token, das Postmark für beides akzeptiert.',
    'Postmark → Sender signatures → DNS settings: add the DKIM TXT record (…pm._domainkey) and the Return-Path CNAME pointing to pm.mtasv.net. Postmark needs no SPF include.' => 'Postmark → Sender signatures → DNS settings: den DKIM-TXT-Eintrag (…pm._domainkey) und den Return-Path-CNAME auf pm.mtasv.net hinzufügen. Postmark braucht kein SPF-include.',
    'Literally apikey – the same for every account.' => 'Wörtlich apikey – für jedes Konto gleich.',
    'A SendGrid API key with the Mail Send permission: SendGrid uses the API key as the SMTP password.' => 'Ein SendGrid-API-Schlüssel mit der Berechtigung Mail Send: SendGrid verwendet den API-Schlüssel als SMTP-Passwort.',
    'SendGrid → Settings → Sender authentication → Authenticate your domain: add the CNAME records it shows (em…, s1._domainkey and s2._domainkey); they cover SPF and DKIM.' => 'SendGrid → Settings → Sender authentication → Authenticate your domain: die angezeigten CNAME-Einträge (em…, s1._domainkey und s2._domainkey) hinzufügen; sie decken SPF und DKIM ab.',
    'The SMTP user MailerSend generates on the domain page (Domains → your domain → SMTP).' => 'Der SMTP-Benutzer, den MailerSend auf der Domain-Seite erzeugt (Domains → Ihre Domain → SMTP).',
    'The password of that SMTP user – shown only once; not an API token.' => 'Das Passwort dieses SMTP-Benutzers – wird nur einmal angezeigt; kein API-Token.',
    'MailerSend → Domains → your domain: add the SPF (include:_spf.mailersend.net), DKIM and Return-Path records it shows.' => 'MailerSend → Domains → Ihre Domain: die angezeigten Einträge für SPF (include:_spf.mailersend.net), DKIM und Return-Path hinzufügen.',
    'An SMTP user created in SMTP2GO → Sending → SMTP Users – not your dashboard login. If port 587 is blocked, use 2525.' => 'Ein SMTP-Benutzer aus SMTP2GO → Sending → SMTP Users – nicht Ihr Login für das Dashboard. Ist Port 587 gesperrt, Port 2525 verwenden.',
    'The password of that SMTP user.' => 'Das Passwort dieses SMTP-Benutzers.',
    'SMTP2GO → Sending → Verified senders: add the sending domain and the CNAME records it shows (return path, DKIM and link tracking); they cover SPF.' => 'SMTP2GO → Sending → Verified senders: die Absenderdomain und die angezeigten CNAME-Einträge (Return-Path, DKIM und Link-Tracking) hinzufügen; sie decken SPF ab.',
    'Your Mailjet API key (Account settings → SMTP and Send API settings) – Mailjet uses it as the SMTP user name.' => 'Der Mailjet-API-Schlüssel (Account settings → SMTP and Send API settings) – Mailjet verwendet ihn als SMTP-Benutzernamen.',
    'The secret key belonging to that API key.' => 'Der Secret Key zu diesem API-Schlüssel.',
    'Mailjet → Account settings → Domains: add include:spf.mailjet.com to the SPF record and the DKIM TXT record (mailjet._domainkey) Mailjet shows.' => 'Mailjet → Account settings → Domains: include:spf.mailjet.com in den SPF-Eintrag aufnehmen und den von Mailjet angezeigten DKIM-TXT-Eintrag (mailjet._domainkey) hinzufügen.',
    'Any name – Mailchimp does not check it and recommends your account’s primary contact e-mail.' => 'Ein beliebiger Name – Mailchimp prüft ihn nicht und empfiehlt die Haupt-Kontaktadresse des Kontos.',
    'A Mailchimp Transactional (Mandrill) API key from Settings → SMTP & API Info – a Mailchimp marketing API key does not work.' => 'Ein API-Schlüssel von Mailchimp Transactional (Mandrill) aus Settings → SMTP & API Info – ein Marketing-API-Schlüssel von Mailchimp funktioniert nicht.',
    'Mailchimp Transactional → Domains → Sending domains: verify the domain and add the DKIM and SPF records it shows (include:spf.mandrillapp.com).' => 'Mailchimp Transactional → Domains → Sending domains: die Domain verifizieren und die angezeigten DKIM- und SPF-Einträge (include:spf.mandrillapp.com) hinzufügen.',
    'Ecomail sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'Ecomail versendet Transaktions-E-Mails nur über seine API, nicht per SMTP – behalten Sie es für den Newsletter und wählen Sie für die Mails der Website einen anderen Dienst oder Ihr Postfach.',
    'SmartEmailing sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'SmartEmailing versendet Transaktions-E-Mails nur über seine API, nicht per SMTP – behalten Sie es für den Newsletter und wählen Sie für die Mails der Website einen anderen Dienst oder Ihr Postfach.',
    'MailerLite has no SMTP relay of its own; its transactional service is MailerSend, a separate account with its own SMTP user.' => 'MailerLite hat kein eigenes SMTP-Relay; sein Transaktionsdienst ist MailerSend, ein separates Konto mit eigenem SMTP-Benutzer.',
];
